function sketch(p) {
  let particles = [];
  let time = 0;
  let breathePhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Create quantum foam particles
    for (let i = 0; i < 800; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(0.5, 3),
        hue: p.random(240, 280),
        alpha: p.random(0.1, 0.4),
        speed: p.random(0.2, 0.8),
        phase: p.random(p.TWO_PI),
        orbit: p.random(10, 30)
      });
    }
  };

  p.draw = function() {
    time += 0.01;
    breathePhase += 0.008;

    // Create deep space gradient that breathes
    let breathe = p.sin(breathePhase) * 0.1 + 0.9;

    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(260, 80 * breathe, 5 * breathe);
      let c2 = p.color(280, 60 * breathe, 15 * breathe);
      let c3 = p.color(240, 40 * breathe, 8 * breathe);

      let gradient;
      if (inter < 0.5) {
        gradient = p.lerpColor(c1, c2, inter * 2);
      } else {
        gradient = p.lerpColor(c2, c3, (inter - 0.5) * 2);
      }

      p.stroke(gradient);
      p.line(0, y, p.width, y);
    }

    // Mouse influence creates ripples of potential
    let mouseForce = p.dist(p.mouseX, p.mouseY, p.width/2, p.height/2) / 200;
    let mouseAngle = p.atan2(p.mouseY - p.height/2, p.mouseX - p.width/2);

    // Draw quantum foam particles
    p.noStroke();
    for (let particle of particles) {
      // Subtle orbital motion around invisible attractors
      let attractor1X = p.width * 0.3 + p.cos(time * 0.5) * 20;
      let attractor1Y = p.height * 0.4 + p.sin(time * 0.3) * 15;
      let attractor2X = p.width * 0.7 + p.cos(time * 0.7) * 25;
      let attractor2Y = p.height * 0.6 + p.sin(time * 0.4) * 20;

      let force1 = p5.Vector.sub(p.createVector(attractor1X, attractor1Y), 
                                 p.createVector(particle.x, particle.y));
      let force2 = p5.Vector.sub(p.createVector(attractor2X, attractor2Y), 
                                 p.createVector(particle.x, particle.y));

      force1.mult(0.0001);
      force2.mult(0.0001);

      particle.x += force1.x + p.cos(particle.phase + time) * 0.1;
      particle.y += force1.y + p.sin(particle.phase + time * 0.7) * 0.1;

      // Mouse interaction creates quantum fluctuations
      let mouseInfluence = 1 + p.sin(time * 3 + mouseForce * 5) * 0.3 * mouseForce;

      // Boundary wrapping with fade
      if (particle.x < -10) particle.x = p.width + 10;
      if (particle.x > p.width + 10) particle.x = -10;
      if (particle.y < -10) particle.y = p.height + 10;
      if (particle.y > p.height + 10) particle.y = -10;

      // Dynamic coloring based on position and time
      let dynamicHue = (particle.hue + time * 10 + 
                       p.sin(particle.x * 0.01) * 20 + 
                       p.cos(particle.y * 0.01) * 15) % 360;

      let distFromCenter = p.dist(particle.x, particle.y, p.width/2, p.height/2);
      let centerInfluence = p.map(distFromCenter, 0, p.width/2, 1, 0.3);

      let alpha = particle.alpha * centerInfluence * mouseInfluence * breathe;
      let size = particle.size * mouseInfluence * (0.8 + breathe * 0.4);

      p.fill(dynamicHue, 70, 80, alpha);

      // Soft circular particles with slight variation
      p.circle(particle.x, particle.y, size);

      // Occasionally add tiny sparkles
      if (p.random() < 0.001) {
        p.fill(dynamicHue, 30, 95, alpha * 2);
        p.circle(particle.x + p.random(-2, 2), particle.y + p.random(-2, 2), size * 0.3);
      }
    }

    // Subtle vortex suggestion in center
    p.push();
    p.translate(p.width/2, p.height/2);
    p.rotate(time * 0.1);
    p.noFill();

    for (let r = 5; r < 150; r += 8) {
      let alpha = p.map(r, 5, 150, 0.3, 0.05) * breathe;
      let hue = (260 + r * 0.5 + time * 20) % 360;
      p.stroke(hue, 60, 60, alpha);
      p.strokeWeight(0.5);

      let points = Math.floor(r / 3);
      p.beginShape(p.POINTS);
      for (let i = 0; i < points; i++) {
        let angle = (i / points) * p.TWO_PI + time * 0.05;
        let x = p.cos(angle) * r * (1 + p.sin(time * 2 + r * 0.1) * 0.1);
        let y = p.sin(angle) * r * (1 + p.cos(time * 1.5 + r * 0.1) * 0.1);
        p.vertex(x, y);
      }
      p.endShape();
    }
    p.pop();

    // Click interaction - burst of potential
    if (p.mouseIsPressed) {
      let burstParticles = 30;
      for (let i = 0; i < burstParticles; i++) {
        let angle = (i / burstParticles) * p.TWO_PI;
        let distance = p.random(20, 80);
        let x = p.mouseX + p.cos(angle) * distance;
        let y = p.mouseY + p.sin(angle) * distance;

        if (x > 0 && x < p.width && y > 0 && y < p.height) {
          let hue = (280 + p.random(-40, 40)) % 360;
          p.fill(hue, 80, 90, 0.6);
          p.noStroke();
          p.circle(x, y, p.random(1, 4));
        }
      }
    }
  };
}

function sketch(p) {
  let word = "";
  let targetWord = "BEING";
  let letterIndex = 0;
  let particles = [];
  let divisions = [];
  let mouth = { x: 200, y: 150, speaking: false };
  let soundWaves = [];
  let splitProgress = 0;
  let colorShift = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize background divisions
    for (let i = 0; i < 8; i++) {
      divisions.push({
        x: p.random(p.width),
        y: p.random(200, p.height),
        angle: p.random(p.TWO_PI),
        growth: 0,
        active: false
      });
    }
  };

  p.draw = function() {
    // Gradient background that shifts as naming progresses
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(240 + colorShift, 80, 20);
      let c2 = p.color(280 + colorShift * 2, 60, 80);
      let col = p.lerpColor(c1, c2, inter);
      p.stroke(col);
      p.line(0, y, p.width, y);
    }

    // Animate word appearance
    if (p.frameCount % 60 === 0 && letterIndex < targetWord.length) {
      word += targetWord[letterIndex];
      letterIndex++;
      mouth.speaking = true;

      // Create sound wave
      soundWaves.push({
        x: mouth.x,
        y: mouth.y,
        radius: 0,
        life: 100
      });

      // Activate division
      if (letterIndex - 1 < divisions.length) {
        divisions[letterIndex - 1].active = true;
      }

      // Create particles
      for (let i = 0; i < 5; i++) {
        particles.push({
          x: mouth.x + p.random(-20, 20),
          y: mouth.y + p.random(-10, 10),
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 255,
          hue: 60 + letterIndex * 40
        });
      }
    }

    // Draw and update sound waves
    for (let i = soundWaves.length - 1; i >= 0; i--) {
      let wave = soundWaves[i];
      wave.radius += 3;
      wave.life -= 2;

      p.noFill();
      p.stroke(50 + wave.life, 70, 90, wave.life);
      p.strokeWeight(2);
      p.circle(wave.x, wave.y, wave.radius);

      if (wave.life <= 0) {
        soundWaves.splice(i, 1);
      }
    }

    // Draw mouth
    p.fill(20, 80, 80);
    p.noStroke();
    p.ellipse(mouth.x, mouth.y - 20, 40, 30);

    // Mouth opening
    let openness = mouth.speaking ? p.sin(p.frameCount * 0.3) * 8 + 8 : 4;
    p.fill(0, 0, 0);
    p.ellipse(mouth.x, mouth.y, 25, openness);

    mouth.speaking = false;

    // Draw the word being spoken
    p.fill(60, 100, 100);
    p.textAlign(p.CENTER);
    p.textSize(32);
    p.text(word, mouth.x, mouth.y + 80);

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;
      particle.vy += 0.1; // gravity

      p.fill(particle.hue, 80, 90, particle.life);
      p.noStroke();
      p.circle(particle.x, particle.y, 6);

      if (particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Draw reality divisions
    for (let i = 0; i < divisions.length; i++) {
      let div = divisions[i];
      if (div.active) {
        div.growth = p.min(div.growth + 2, 100);

        p.stroke(180 + i * 30, 70, 80, 60);
        p.strokeWeight(3);

        let length = p.map(div.growth, 0, 100, 0, 150);
        let x1 = div.x - p.cos(div.angle) * length;
        let y1 = div.y - p.sin(div.angle) * length;
        let x2 = div.x + p.cos(div.angle) * length;
        let y2 = div.y + p.sin(div.angle) * length;

        p.line(x1, y1, x2, y2);

        // Create separated regions
        if (div.growth > 50) {
          p.fill(180 + i * 30, 30, 95, 20);
          p.noStroke();
          p.circle(x1, y1, 40);
          p.circle(x2, y2, 40);
        }
      }
    }

    // Mouse interaction - disturb the unity
    if (p.mouseIsPressed) {
      for (let i = 0; i < 3; i++) {
        particles.push({
          x: p.mouseX + p.random(-10, 10),
          y: p.mouseY + p.random(-10, 10),
          vx: p.random(-3, 3),
          vy: p.random(-2, 2),
          life: 150,
          hue: p.random(0, 360)
        });
      }

      colorShift += 0.5;
    }

    // Reset animation
    if (letterIndex >= targetWord.length && particles.length === 0 && p.frameCount % 300 === 0) {
      word = "";
      letterIndex = 0;
      divisions.forEach(div => {
        div.active = false;
        div.growth = 0;
      });
      colorShift = 0;
    }

    splitProgress = p.map(word.length, 0, targetWord.length, 0, 1);
  };
}

function sketch(p) {
  let keys = [];
  let keyholes = [];
  let shadowObjects = [];
  let breathingOffset = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create floating keyholes that define absent keys
    for(let i = 0; i < 5; i++) {
      keyholes.push({
        x: p.random(80, 320),
        y: p.random(100, 500),
        size: p.random(30, 60),
        rotation: p.random(p.TWO_PI),
        driftSpeed: p.random(0.5, 1.5),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create shadow-casting objects that exist only as negative space
    for(let i = 0; i < 8; i++) {
      shadowObjects.push({
        x: p.random(-50, 450),
        y: p.random(-50, 650),
        size: p.random(20, 80),
        opacity: p.random(0.1, 0.3),
        speed: p.random(0.3, 0.8),
        direction: p.random(p.TWO_PI)
      });
    }

    // Potential keys that might fill the holes
    for(let i = 0; i < 3; i++) {
      keys.push({
        targetHole: i,
        progress: 0,
        active: false,
        x: 0,
        y: 0
      });
    }
  };

  p.draw = function() {
    // Deep void background with subtle breathing
    breathingOffset += 0.02;
    let breathe = p.sin(breathingOffset) * 10 + 15;
    p.background(12 + breathe, 8 + breathe, 25 + breathe);

    // Mouse creates ripples in the void
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 300, 0.05);

    // Draw shadow projections first (what casts the keyholes)
    p.push();
    p.blendMode(p.MULTIPLY);
    for(let shadow of shadowObjects) {
      shadow.x += p.cos(shadow.direction) * shadow.speed;
      shadow.y += p.sin(shadow.direction) * shadow.speed;

      // Wrap around canvas
      if(shadow.x > 450) shadow.x = -50;
      if(shadow.x < -50) shadow.x = 450;
      if(shadow.y > 650) shadow.y = -50;
      if(shadow.y < -50) shadow.y = 650;

      p.fill(0, 0, 0, shadow.opacity * 255);
      p.noStroke();
      p.ellipse(shadow.x, shadow.y, shadow.size);
    }
    p.pop();

    // Create the main void structure - hemoglobin-like form
    p.push();
    p.translate(200, 300);
    p.rotate(p.sin(breathingOffset * 0.7) * 0.1);

    // The binding site - a structured absence
    let bindingPulse = p.sin(breathingOffset * 1.5) * 8 + 25;
    p.strokeWeight(4);
    p.stroke(120, 80, 200, 150 + bindingPulse);
    p.noFill();

    // Main hemoglobin-like structure with the crucial void
    p.beginShape();
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = 80 + p.sin(angle * 3 + breathingOffset) * 15;
      let x = p.cos(angle) * radius;
      let y = p.sin(angle) * radius * 0.7;
      p.curveVertex(x, y);
    }
    p.endShape(p.CLOSE);

    // The binding void - where oxygen would go
    p.fill(8, 5, 15);
    p.stroke(180, 120, 255, 100);
    p.strokeWeight(2);
    let voidSize = 40 + p.sin(breathingOffset * 2) * 8;
    p.ellipse(0, -20, voidSize, voidSize * 0.6);

    // Intention lines - showing the pull of absence
    p.stroke(255, 150, 180, 60 + mouseInfluence * 40);
    p.strokeWeight(1);
    for(let i = 0; i < 12; i++) {
      let angle = (i / 12) * p.TWO_PI + breathingOffset;
      let inner = voidSize * 0.3;
      let outer = voidSize * 0.8;
      p.line(
        p.cos(angle) * inner, -20 + p.sin(angle) * inner * 0.6,
        p.cos(angle) * outer, -20 + p.sin(angle) * outer * 0.6
      );
    }
    p.pop();

    // Draw the keyholes - absences that define presence
    for(let i = 0; i < keyholes.length; i++) {
      let hole = keyholes[i];

      // Drift motion
      hole.x += p.sin(p.millis() * 0.001 * hole.driftSpeed + hole.phase) * 0.5;
      hole.y += p.cos(p.millis() * 0.0008 * hole.driftSpeed + hole.phase) * 0.3;

      // Keep in bounds
      hole.x = p.constrain(hole.x, 50, 350);
      hole.y = p.constrain(hole.y, 80, 520);

      p.push();
      p.translate(hole.x, hole.y);
      p.rotate(hole.rotation + breathingOffset * 0.3);

      // The keyhole void
      p.fill(5, 3, 12);
      p.stroke(150, 100, 220, 80 + p.sin(breathingOffset + i) * 30);
      p.strokeWeight(2);

      // Keyhole shape - absence that defines the key
      p.ellipse(0, -hole.size * 0.2, hole.size * 0.4, hole.size * 0.4);
      p.rect(-hole.size * 0.1, -hole.size * 0.1, hole.size * 0.2, hole.size * 0.6);

      // Glow around the absence
      p.noFill();
      p.stroke(200, 120, 255, 20);
      p.strokeWeight(8);
      p.ellipse(0, 0, hole.size * 1.2, hole.size * 1.2);

      p.pop();

      // Mouse interaction - potential keys appear
      let dist = p.dist(p.mouseX, p.mouseY, hole.x, hole.y);
      if(dist < hole.size && i < keys.length) {
        keys[i].active = true;
        keys[i].x = p.lerp(keys[i].x, hole.x, 0.05);
        keys[i].y = p.lerp(keys[i].y, hole.y, 0.05);
        keys[i].progress = p.min(keys[i].progress + 0.02, 1);

        // Draw the potential key - what could fill the absence
        p.push();
        p.translate(keys[i].x, keys[i].y);
        p.rotate(hole.rotation + breathingOffset * 0.3);
        p.fill(255, 200, 120, keys[i].progress * 100);
        p.noStroke();
        p.ellipse(0, -hole.size * 0.2, hole.size * 0.35, hole.size * 0.35);
        p.rect(-hole.size * 0.08, -hole.size * 0.1, hole.size * 0.16, hole.size * 0.55);
        p.pop();
      } else if(i < keys.length) {
        keys[i].progress = p.max(keys[i].progress - 0.03, 0);
        if(keys[i].progress <= 0) keys[i].active = false;
      }
    }

    // Particle system for the active void
    if(p.frameCount % 15 === 0) {
      for(let i = 0; i < 3; i++) {
        let angle = p.random(p.TWO_PI);
        let radius = p.random(60, 120);
        let particle = {
          x: 200 + p.cos(angle) * radius,
          y: 280 + p.sin(angle) * radius,
          targetX: 200,
          targetY: 280,
          life: 1,
          size: p.random(2, 6)
        };

        // Particles get pulled into the void
        let dx = particle.targetX - particle.x;
        let dy = particle.targetY - particle.y;
        particle.vx = dx * 0.01;
        particle.vy = dy * 0.01;

        setTimeout(() => {
          drawParticle(particle);
        }, i * 50);
      }
    }
  };

  function drawParticle(particle) {
    if(particle.life > 0) {
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vx *= 1.02; // Acceleration toward void
      particle.vy *= 1.02;
      particle.life -= 0.02;

      p.push();
      p.fill(180, 120, 255, particle.life * 100);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * particle.life);
      p.pop();

      if(particle.life > 0) {
        setTimeout(() => drawParticle(particle), 16);
      }
    }
  }

  p.mousePressed = function() {
    // Click creates ripples in the void space
    for(let i = 0; i < 8; i++) {
      setTimeout(() => {
        let ripple = {
          x: p.mouseX,
          y: p.mouseY,
          radius: 0,
          life: 1
        };
        drawRipple(ripple);
      }, i * 100);
    }
  };

  function drawRipple(ripple) {
    if(ripple.life > 0) {
      ripple.radius += 5;
      ripple.life -= 0.05;

      p.push();
      p.noFill();
      p.stroke(200, 150, 255, ripple.life * 60);
      p.strokeWeight(2);
      p.ellipse(ripple.x, ripple.y, ripple.radius);
      p.pop();

      if(ripple.life > 0 && ripple.radius < 200) {
        setTimeout(() => drawRipple(ripple), 16);
      }
    }
  }
}

function sketch(p) {
  let membrane;
  let realityParticles = [];
  let interfaceIcons = [];
  let eyeX, eyeY;
  let membraneOffset = 0;
  let filterLayers = [];
  let codeStream = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize membrane position
    membrane = p.height * 0.5;

    // Create reality particles (complex, chaotic)
    for (let i = 0; i < 150; i++) {
      realityParticles.push({
        x: p.random(p.width),
        y: p.random(membrane, p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(2, 8),
        color: p.color(p.random(255), p.random(255), p.random(255), 150),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create interface icons (simplified, clean)
    for (let i = 0; i < 6; i++) {
      interfaceIcons.push({
        x: 50 + i * 60,
        y: p.random(50, membrane - 50),
        type: p.floor(p.random(4)), // different icon types
        float: p.random(p.TWO_PI),
        baseY: p.random(50, membrane - 50)
      });
    }

    // Create code stream
    for (let i = 0; i < 200; i++) {
      codeStream.push({
        x: p.random(p.width),
        y: p.random(membrane + 50, p.height),
        char: String.fromCharCode(33 + p.floor(p.random(94))),
        speed: p.random(0.5, 2),
        alpha: p.random(50, 200)
      });
    }

    eyeX = p.width * 0.5;
    eyeY = 80;
  };

  p.draw = function() {
    p.background(15, 15, 25);

    // Update membrane with gentle wave
    membraneOffset += 0.02;

    // Draw the complex reality layer (bottom)
    p.push();
    p.fill(20, 20, 40, 100);
    p.rect(0, membrane, p.width, p.height - membrane);

    // Draw chaotic code stream
    p.fill(0, 255, 100, 80);
    p.textSize(8);
    for (let code of codeStream) {
      p.text(code.char, code.x, code.y);
      code.y -= code.speed;
      if (code.y < membrane + 10) {
        code.y = p.height;
        code.x = p.random(p.width);
      }
      code.alpha = p.map(code.y, membrane + 10, p.height, 30, 150);
      p.fill(0, 255, 100, code.alpha);
    }

    // Draw reality particles with chaotic movement
    for (let particle of realityParticles) {
      particle.phase += 0.05;
      particle.x += particle.vx + p.sin(particle.phase) * 0.5;
      particle.y += particle.vy + p.cos(particle.phase * 0.7) * 0.3;

      if (particle.x < 0 || particle.x > p.width) particle.vx *= -1;
      if (particle.y < membrane || particle.y > p.height) particle.vy *= -1;

      p.fill(particle.color);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    }
    p.pop();

    // Draw the membrane/interface barrier
    for (let i = 0; i < p.width; i += 2) {
      let wave = p.sin(i * 0.02 + membraneOffset) * 8;
      let alpha = p.map(p.sin(i * 0.01 + membraneOffset), -1, 1, 100, 200);
      p.stroke(100, 200, 255, alpha);
      p.strokeWeight(3);
      p.line(i, membrane + wave, i + 2, membrane + wave);
    }

    // Draw the simplified interface layer (top)
    p.push();
    p.fill(240, 245, 255, 20);
    p.rect(0, 0, p.width, membrane);

    // Draw clean interface icons
    for (let icon of interfaceIcons) {
      icon.float += 0.03;
      icon.y = icon.baseY + p.sin(icon.float) * 5;

      p.push();
      p.translate(icon.x, icon.y);
      p.fill(120, 200, 255, 200);
      p.stroke(255);
      p.strokeWeight(2);

      // Different icon types
      switch(icon.type) {
        case 0: // Circle
          p.ellipse(0, 0, 30);
          break;
        case 1: // Square
          p.rect(-15, -15, 30, 30);
          break;
        case 2: // Triangle
          p.triangle(-15, 15, 15, 15, 0, -15);
          break;
        case 3: // Diamond
          p.quad(0, -15, 15, 0, 0, 15, -15, 0);
          break;
      }
      p.pop();
    }
    p.pop();

    // Draw the observing eye
    eyeX = p.lerp(eyeX, p.mouseX, 0.05);
    eyeY = p.lerp(eyeY, p.constrain(p.mouseY, 40, 150), 0.05);

    // Eye socket
    p.fill(50, 50, 80);
    p.stroke(100, 150, 200);
    p.strokeWeight(2);
    p.ellipse(eyeX, eyeY, 60, 40);

    // Iris
    p.fill(80, 150, 220);
    p.ellipse(eyeX, eyeY, 35, 30);

    // Pupil
    p.fill(20);
    p.ellipse(eyeX, eyeY, 15, 15);

    // Eye reflection
    p.fill(255, 200);
    p.noStroke();
    p.ellipse(eyeX - 3, eyeY - 2, 4, 4);

    // Draw filter rays from eye to membrane
    p.stroke(150, 200, 255, 80);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      let angle = p.map(i, 0, 4, -0.3, 0.3);
      let endX = eyeX + p.sin(angle) * 200;
      let endY = membrane + p.sin(endX * 0.02 + membraneOffset) * 8;
      p.line(eyeX, eyeY + 15, endX, endY);
    }

    // Interactive effect - mouse proximity creates visual disturbance
    if (p.dist(p.mouseX, p.mouseY, eyeX, eyeY) < 60) {
      p.push();
      p.fill(255, 100, 150, 50);
      p.noStroke();
      let ripple = p.sin(p.frameCount * 0.3) * 20 + 30;
      p.ellipse(eyeX, eyeY, ripple, ripple);
      p.pop();

      // Distort membrane when eye is activated
      p.stroke(255, 150, 100, 100);
      p.strokeWeight(2);
      for (let i = 0; i < p.width; i += 5) {
        let disturbance = p.map(p.dist(i, membrane, eyeX, eyeY), 0, 200, 20, 0);
        disturbance = p.max(0, disturbance);
        let wave = p.sin(i * 0.05 + p.frameCount * 0.1) * disturbance;
        p.point(i, membrane + wave);
      }
    }
  };
}

function sketch(p) {
  let shapes = [];
  let identifiedShapes = [];
  let scanLine = 0;
  let eyeX, eyeY;
  let blinkTimer = 0;
  let isBlinking = false;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create a field of ambiguous shapes
    for (let i = 0; i < 120; i++) {
      shapes.push({
        x: p.random(50, 350),
        y: p.random(150, 550),
        size: p.random(8, 25),
        type: p.floor(p.random(4)),
        opacity: p.random(30, 80),
        identified: false,
        identifyTime: 0,
        originalColor: p.color(p.random(100, 200), p.random(100, 200), p.random(100, 200))
      });
    }

    eyeX = 200;
    eyeY = 80;
  };

  p.draw = function() {
    // Gradient background suggesting depth of observation
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(45, 35, 65), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Draw the observing eye
    p.push();
    p.translate(eyeX, eyeY);

    // Eye follows mouse subtly
    let targetX = p.lerp(200, p.mouseX, 0.1);
    let targetY = p.lerp(80, p.mouseY * 0.3 + 60, 0.1);
    eyeX = p.lerp(eyeX, targetX, 0.02);
    eyeY = p.lerp(eyeY, targetY, 0.02);

    // Blink animation
    blinkTimer++;
    if (blinkTimer > 180 && p.random() < 0.02) {
      isBlinking = true;
      blinkTimer = 0;
    }
    if (isBlinking && blinkTimer > 8) {
      isBlinking = false;
    }

    // Draw eye
    p.fill(255, 255, 240);
    p.noStroke();
    if (!isBlinking) {
      p.ellipse(0, 0, 60, 35);
      // Iris
      p.fill(80, 120, 160);
      p.ellipse(0, 0, 25, 25);
      // Pupil
      p.fill(20, 20, 30);
      p.ellipse(0, 0, 12, 12);
      // Highlight
      p.fill(255, 255, 255, 200);
      p.ellipse(-3, -3, 4, 4);
    } else {
      p.fill(255, 255, 240);
      p.ellipse(0, 0, 60, 3);
    }
    p.pop();

    // Scanning beam from eye
    scanLine = (scanLine + 1.5) % p.height;
    let beamY = 120 + scanLine;

    p.stroke(255, 255, 200, 60);
    p.strokeWeight(2);
    p.line(eyeX - 30, eyeY + 15, 0, beamY);
    p.line(eyeX + 30, eyeY + 15, p.width, beamY);

    // Scanning highlight
    p.stroke(255, 255, 150, 30);
    p.strokeWeight(40);
    p.line(0, beamY, p.width, beamY);

    // Draw and identify shapes
    for (let i = 0; i < shapes.length; i++) {
      let shape = shapes[i];

      // Check if shape is in scanning area or near mouse
      let distToScan = p.abs(shape.y - beamY);
      let distToMouse = p.dist(shape.x, shape.y, p.mouseX, p.mouseY);

      if ((distToScan < 20 || distToMouse < 30) && !shape.identified) {
        shape.identified = true;
        shape.identifyTime = p.millis();
      }

      p.push();
      p.translate(shape.x, shape.y);

      if (shape.identified) {
        // Identified shapes become clear and distinct
        let timeSinceId = p.millis() - shape.identifyTime;
        let clarity = p.constrain(p.map(timeSinceId, 0, 1000, 0, 1), 0, 1);

        // Bright, clear colors
        p.fill(p.red(shape.originalColor) + 100 * clarity, 
               p.green(shape.originalColor) + 80 * clarity, 
               p.blue(shape.originalColor) + 60 * clarity, 
               255);
        p.stroke(255, 255, 255, 150 * clarity);
        p.strokeWeight(1 + clarity);

        // Draw distinct shape based on type
        if (shape.type === 0) {
          p.circle(0, 0, shape.size * (1 + clarity * 0.2));
        } else if (shape.type === 1) {
          p.rectMode(p.CENTER);
          p.rect(0, 0, shape.size * (1 + clarity * 0.2), shape.size * (1 + clarity * 0.2));
        } else if (shape.type === 2) {
          p.triangle(-shape.size/2, shape.size/2, 
                    shape.size/2, shape.size/2, 
                    0, -shape.size/2);
        } else {
          // Diamond
          p.rotate(p.PI/4);
          p.rect(0, 0, shape.size * 0.8, shape.size * 0.8);
        }

        // Identification glow
        if (timeSinceId < 500) {
          p.fill(255, 255, 100, 100 * (1 - timeSinceId/500));
          p.noStroke();
          p.circle(0, 0, shape.size * 2);
        }

      } else {
        // Unidentified shapes are vague and ambiguous
        p.fill(p.red(shape.originalColor), p.green(shape.originalColor), p.blue(shape.originalColor), shape.opacity);
        p.noStroke();

        // Vague, shifting blob
        p.beginShape();
        for (let a = 0; a < p.TWO_PI; a += p.PI/6) {
          let r = shape.size/2 + p.sin(a * 3 + p.millis() * 0.01 + i) * 3;
          let x = p.cos(a) * r;
          let y = p.sin(a) * r;
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
      }
      p.pop();
    }

    // Classification lines connecting similar identified shapes
    p.stroke(100, 255, 150, 30);
    p.strokeWeight(1);
    for (let i = 0; i < shapes.length; i++) {
      if (shapes[i].identified) {
        for (let j = i + 1; j < shapes.length; j++) {
          if (shapes[j].identified && shapes[i].type === shapes[j].type) {
            let dist = p.dist(shapes[i].x, shapes[i].y, shapes[j].x, shapes[j].y);
            if (dist < 80) {
              p.line(shapes[i].x, shapes[i].y, shapes[j].x, shapes[j].y);
            }
          }
        }
      }
    }

    // Reset some shapes occasionally to maintain the identification process
    if (p.frameCount % 300 === 0) {
      for (let i = 0; i < 5; i++) {
        let shape = shapes[p.floor(p.random(shapes.length))];
        shape.identified = false;
      }
    }
  };

  p.mousePressed = function() {
    // Mouse click creates a burst of identification
    for (let shape of shapes) {
      let dist = p.dist(shape.x, shape.y, p.mouseX, p.mouseY);
      if (dist < 60 && !shape.identified) {
        shape.identified = true;
        shape.identifyTime = p.millis() + p.random(-200, 200);
      }
    }
  };
}

function sketch(p) {
  let blueprint = [];
  let structures = [];
  let particles = [];
  let time = 0;
  let constructionPhase = 0;

  class BlueprintLine {
    constructor(x1, y1, x2, y2, delay) {
      this.x1 = x1;
      this.y1 = y1;
      this.x2 = x2;
      this.y2 = y2;
      this.progress = 0;
      this.delay = delay;
      this.active = false;
    }

    update() {
      if (time > this.delay) {
        this.active = true;
        this.progress = p.min(1, this.progress + 0.02);
      }
    }

    display() {
      if (this.active) {
        p.stroke(100, 150, 255, 180);
        p.strokeWeight(1);
        let currentX = p.lerp(this.x1, this.x2, this.progress);
        let currentY = p.lerp(this.y1, this.y2, this.progress);
        p.line(this.x1, this.y1, currentX, currentY);

        if (this.progress > 0.8) {
          p.fill(150, 200, 255, 100);
          p.noStroke();
          p.circle(currentX, currentY, 4);
        }
      }
    }
  }

  class Structure {
    constructor(x, y, w, h, delay) {
      this.x = x;
      this.y = y;
      this.w = w;
      this.h = h;
      this.progress = 0;
      this.delay = delay;
      this.active = false;
      this.opacity = 0;
    }

    update() {
      if (time > this.delay) {
        this.active = true;
        this.progress = p.min(1, this.progress + 0.015);
        this.opacity = p.min(255, this.opacity + 3);
      }
    }

    display() {
      if (this.active && this.progress > 0) {
        p.push();
        p.translate(this.x, this.y);

        let currentH = this.h * this.progress;

        // Building structure
        p.fill(255, 200, 100, this.opacity * 0.8);
        p.stroke(200, 150, 50);
        p.strokeWeight(2);
        p.rect(0, this.h - currentH, this.w, currentH);

        // Construction scaffolding
        if (this.progress < 0.9) {
          p.stroke(100, 100, 100, this.opacity * 0.6);
          p.strokeWeight(1);
          for (let i = 0; i < 3; i++) {
            let scaffoldY = this.h - currentH - 20;
            p.line(-5, scaffoldY, this.w + 5, scaffoldY);
            p.line(-5, scaffoldY, -5, scaffoldY + 40);
            p.line(this.w + 5, scaffoldY, this.w + 5, scaffoldY + 40);
          }
        }

        // Windows appearing
        if (this.progress > 0.6) {
          p.fill(50, 100, 200, this.opacity * 0.7);
          p.noStroke();
          for (let i = 0; i < 2; i++) {
            for (let j = 0; j < 3; j++) {
              let winX = 15 + i * 25;
              let winY = this.h - 30 - j * 25;
              if (winY > this.h - currentH) {
                p.rect(winX, winY, 12, 15);
              }
            }
          }
        }

        p.pop();
      }
    }
  }

  class ConstructionParticle {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      this.vx = p.random(-1, 1);
      this.vy = p.random(-2, -0.5);
      this.life = 255;
      this.size = p.random(2, 4);
    }

    update() {
      this.x += this.vx;
      this.y += this.vy;
      this.vy += 0.05;
      this.life -= 3;
    }

    display() {
      if (this.life > 0) {
        p.fill(200, 150, 100, this.life);
        p.noStroke();
        p.circle(this.x, this.y, this.size);
      }
    }

    isDead() {
      return this.life <= 0;
    }
  }

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create blueprint lines
    blueprint.push(new BlueprintLine(50, 450, 150, 450, 0));
    blueprint.push(new BlueprintLine(150, 450, 150, 350, 30));
    blueprint.push(new BlueprintLine(150, 350, 50, 350, 60));
    blueprint.push(new BlueprintLine(50, 350, 50, 450, 90));
    blueprint.push(new BlueprintLine(75, 425, 125, 425, 120));
    blueprint.push(new BlueprintLine(75, 400, 125, 400, 140));
    blueprint.push(new BlueprintLine(75, 375, 125, 375, 160));

    blueprint.push(new BlueprintLine(200, 400, 320, 400, 200));
    blueprint.push(new BlueprintLine(320, 400, 320, 280, 230));
    blueprint.push(new BlueprintLine(320, 280, 200, 280, 260));
    blueprint.push(new BlueprintLine(200, 280, 200, 400, 290));
    blueprint.push(new BlueprintLine(220, 380, 300, 380, 320));
    blueprint.push(new BlueprintLine(220, 360, 300, 360, 340));
    blueprint.push(new BlueprintLine(220, 340, 300, 340, 360));
    blueprint.push(new BlueprintLine(220, 320, 300, 320, 380));
    blueprint.push(new BlueprintLine(220, 300, 300, 300, 400));

    // Create structures that will be built
    structures.push(new Structure(50, 350, 100, 100, 500));
    structures.push(new Structure(200, 280, 120, 120, 700));
    structures.push(new Structure(120, 250, 80, 80, 900));
    structures.push(new Structure(250, 180, 90, 90, 1100));
  };

  p.draw = function() {
    p.background(15, 25, 45);
    time++;

    // Floating geometric construction guides
    p.push();
    p.translate(200, 100);
    p.rotate(time * 0.005);
    p.stroke(100, 150, 200, 100);
    p.strokeWeight(1);
    p.noFill();
    for (let i = 0; i < 6; i++) {
      p.rotate(p.PI / 3);
      p.line(0, 0, 40, 0);
      p.circle(40, 0, 8);
    }
    p.pop();

    // Update and display blueprint
    for (let line of blueprint) {
      line.update();
      line.display();
    }

    // Update and display structures
    for (let structure of structures) {
      structure.update();
      structure.display();
    }

    // Add construction particles
    if (p.frameCount % 10 === 0 && time > 400) {
      for (let structure of structures) {
        if (structure.active && structure.progress > 0.1 && structure.progress < 0.9) {
          particles.push(new ConstructionParticle(
            structure.x + p.random(structure.w),
            structure.y + structure.h - structure.h * structure.progress
          ));
        }
      }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
      particles[i].update();
      particles[i].display();
      if (particles[i].isDead()) {
        particles.splice(i, 1);
      }
    }

    // Mouse interaction - add construction sparks
    if (p.mouseIsPressed) {
      for (let i = 0; i < 3; i++) {
        particles.push(new ConstructionParticle(
          p.mouseX + p.random(-10, 10),
          p.mouseY + p.random(-10, 10)
        ));
      }
    }

    // Construction tools floating around cursor
    if (p.mouseX > 0 && p.mouseY > 0) {
      p.push();
      p.translate(p.mouseX, p.mouseY);
      p.rotate(time * 0.02);
      p.stroke(255, 200, 100, 150);
      p.strokeWeight(2);
      p.noFill();

      // Compass tool
      p.circle(0, 0, 30);
      p.line(-15, 0, 15, 0);
      p.line(0, -15, 0, 15);

      // Square tool
      p.rotate(p.PI / 4);
      p.rect(-8, -8, 16, 16);
      p.pop();
    }

    // Reset after full cycle
    if (time > 1500) {
      time = 0;
      for (let line of blueprint) {
        line.progress = 0;
        line.active = false;
      }
      for (let structure of structures) {
        structure.progress = 0;
        structure.active = false;
        structure.opacity = 0;
      }
      particles = [];
    }
  };
}

function sketch(p) {
  let strates = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 5 nested strates with different properties
    strates = [
      { y: 500, size: 350, pattern: 'material', color: [80, 40, 20], alpha: 120 },
      { y: 400, size: 280, pattern: 'organic', color: [60, 120, 80], alpha: 100 },
      { y: 320, size: 220, pattern: 'neural', color: [100, 80, 160], alpha: 80 },
      { y: 260, size: 170, pattern: 'linguistic', color: [180, 100, 60], alpha: 70 },
      { y: 220, size: 120, pattern: 'conceptual', color: [200, 180, 220], alpha: 60 }
    ];

    // Initialize floating particles for each strate
    for (let i = 0; i < 80; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        strate: p.floor(p.random(5)),
        size: p.random(2, 6),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    p.background(15, 10, 25);
    time += 0.02;

    // Draw connection lines between strates
    p.stroke(255, 40);
    p.strokeWeight(1);
    for (let i = 0; i < strates.length - 1; i++) {
      let current = strates[i];
      let next = strates[i + 1];

      for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 6) {
        let x1 = 200 + p.cos(angle + time * 0.3) * (current.size * 0.4);
        let y1 = current.y + p.sin(angle + time * 0.3) * 20;
        let x2 = 200 + p.cos(angle + time * 0.5) * (next.size * 0.4);
        let y2 = next.y + p.sin(angle + time * 0.5) * 15;

        p.line(x1, y1, x2, y2);
      }
    }

    // Draw each strate with its unique pattern
    for (let i = strates.length - 1; i >= 0; i--) {
      let strate = strates[i];
      let mouseInfluence = p.map(p.dist(p.mouseX, p.mouseY, 200, strate.y), 0, 200, 1.5, 0.8);
      mouseInfluence = p.constrain(mouseInfluence, 0.8, 1.5);

      p.push();
      p.translate(200, strate.y + p.sin(time + i) * 8);

      // Outer ring with pattern
      p.fill(strate.color[0], strate.color[1], strate.color[2], strate.alpha);
      p.stroke(strate.color[0] + 50, strate.color[1] + 50, strate.color[2] + 50, 100);
      p.strokeWeight(2);
      p.ellipse(0, 0, strate.size * mouseInfluence);

      // Pattern specific to each strate
      p.noFill();
      p.strokeWeight(1);

      if (strate.pattern === 'material') {
        // Crystalline structure
        for (let a = 0; a < p.TWO_PI; a += p.PI / 8) {
          let r = strate.size * 0.3 * mouseInfluence;
          p.line(0, 0, p.cos(a + time * 0.2) * r, p.sin(a + time * 0.2) * r);
        }
      } else if (strate.pattern === 'organic') {
        // Branching patterns
        for (let a = 0; a < p.TWO_PI; a += p.PI / 6) {
          let r1 = strate.size * 0.2 * mouseInfluence;
          let r2 = strate.size * 0.35 * mouseInfluence;
          let x1 = p.cos(a + time * 0.3) * r1;
          let y1 = p.sin(a + time * 0.3) * r1;
          let x2 = p.cos(a + time * 0.3) * r2;
          let y2 = p.sin(a + time * 0.3) * r2;
          p.line(x1, y1, x2, y2);

          // Sub-branches
          for (let j = 0; j < 3; j++) {
            let subAngle = a + p.random(-0.5, 0.5);
            let x3 = x2 + p.cos(subAngle) * 15;
            let y3 = y2 + p.sin(subAngle) * 15;
            p.line(x2, y2, x3, y3);
          }
        }
      } else if (strate.pattern === 'neural') {
        // Network nodes
        for (let j = 0; j < 12; j++) {
          let angle = (j / 12) * p.TWO_PI + time * 0.4;
          let r = strate.size * 0.25 * mouseInfluence;
          let x = p.cos(angle) * r;
          let y = p.sin(angle) * r;
          p.circle(x, y, 8);

          // Connections between nodes
          if (j < 11) {
            let nextAngle = ((j + 1) / 12) * p.TWO_PI + time * 0.4;
            let nextX = p.cos(nextAngle) * r;
            let nextY = p.sin(nextAngle) * r;
            p.line(x, y, nextX, nextY);
          }
        }
      } else if (strate.pattern === 'linguistic') {
        // Symbol-like patterns
        for (let j = 0; j < 8; j++) {
          let angle = (j / 8) * p.TWO_PI + time * 0.5;
          let r = strate.size * 0.2 * mouseInfluence;
          let x = p.cos(angle) * r;
          let y = p.sin(angle) * r;

          p.push();
          p.translate(x, y);
          p.rotate(angle + time);
          p.rect(-5, -2, 10, 4);
          p.rect(-2, -5, 4, 10);
          p.pop();
        }
      } else if (strate.pattern === 'conceptual') {
        // Abstract geometric forms
        for (let j = 0; j < 6; j++) {
          let angle = (j / 6) * p.TWO_PI + time * 0.6;
          let r = strate.size * 0.15 * mouseInfluence;
          let x = p.cos(angle) * r;
          let y = p.sin(angle) * r;

          p.push();
          p.translate(x, y);
          p.rotate(time + j);
          p.beginShape();
          for (let k = 0; k < 5; k++) {
            let a = (k / 5) * p.TWO_PI;
            p.vertex(p.cos(a) * 8, p.sin(a) * 8);
          }
          p.endShape(p.CLOSE);
          p.pop();
        }
      }

      p.pop();
    }

    // Update and draw particles
    for (let particle of particles) {
      let strate = strates[particle.strate];
      let targetY = strate.y + p.sin(time + particle.phase) * 30;
      let targetRadius = strate.size * 0.4;

      // Keep particles within their strate
      let distFromCenter = p.dist(particle.x, particle.y, 200, targetY);
      if (distFromCenter > targetRadius) {
        let angle = p.atan2(particle.y - targetY, particle.x - 200);
        particle.x = 200 + p.cos(angle) * targetRadius * 0.9;
        particle.y = targetY + p.sin(angle) * targetRadius * 0.9;
        particle.vx *= -0.5;
        particle.vy *= -0.5;
      }

      particle.x += particle.vx;
      particle.y += particle.vy;

      // Mouse interaction - particles are attracted to mouse when close
      if (p.dist(p.mouseX, p.mouseY, particle.x, particle.y) < 80) {
        let forceX = (p.mouseX - particle.x) * 0.002;
        let forceY = (p.mouseY - particle.y) * 0.002;
        particle.vx += forceX;
        particle.vy += forceY;
      }

      // Draw particle
      let alpha = p.map(p.sin(time * 2 + particle.phase), -1, 1, 50, 150);
      p.fill(strate.color[0] + 80, strate.color[1] + 80, strate.color[2] + 80, alpha);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size);
    }

    // Central emanation point
    p.fill(255, 255, 200, 100 + p.sin(time * 3) * 50);
    p.noStroke();
    p.circle(200, 300, 12 + p.sin(time * 2) * 4);
  };
}

function sketch(p) {
  let spiralEyes = [];
  let centerX, centerY;
  let ouroboros = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    centerX = p.width / 2;
    centerY = p.height / 2;

    // Create spiral eyes at different scales
    for (let i = 0; i < 3; i++) {
      spiralEyes.push({
        x: centerX + p.cos(i * p.TWO_PI / 3) * 80,
        y: centerY + p.sin(i * p.TWO_PI / 3) * 60,
        size: 60 + i * 20,
        rotation: i * p.PI / 3,
        spiralOffset: i * p.PI / 2
      });
    }

    // Create ouroboros circle points
    for (let i = 0; i < 100; i++) {
      let angle = i * p.TWO_PI / 100;
      ouroboros.push({
        angle: angle,
        radius: 150,
        originalRadius: 150
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 1.5);

    // Gradient background that shifts with mouse
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(15 + p.mouseX * 0.1, 25 + p.mouseY * 0.1, 45),
        p.color(45, 15, 35 + p.mouseX * 0.1),
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    p.translate(centerX, centerY);

    // Draw impossible recursive frame
    p.push();
    p.rotate(time * 0.3);
    drawRecursiveFrame(120 * mouseInfluence, 4);
    p.pop();

    // Draw ouroboros that breathes
    p.push();
    p.noFill();
    p.strokeWeight(3);

    for (let i = 0; i < ouroboros.length; i++) {
      let point = ouroboros[i];
      let nextI = (i + 1) % ouroboros.length;
      let nextPoint = ouroboros[nextI];

      // Breathing effect
      let breathe = p.sin(time * 2 + point.angle * 3) * 10;
      point.radius = point.originalRadius + breathe;

      let x1 = p.cos(point.angle + time * 0.5) * point.radius;
      let y1 = p.sin(point.angle + time * 0.5) * point.radius;
      let x2 = p.cos(nextPoint.angle + time * 0.5) * nextPoint.radius;
      let y2 = p.sin(nextPoint.angle + time * 0.5) * nextPoint.radius;

      // Color based on position and time
      let hue = (point.angle + time) % p.TWO_PI;
      p.stroke(
        p.map(p.sin(hue), -1, 1, 100, 255),
        p.map(p.cos(hue * 2), -1, 1, 50, 200),
        p.map(p.sin(hue * 3), -1, 1, 150, 255),
        150
      );

      p.line(x1, y1, x2, y2);
    }
    p.pop();

    // Draw spiral eyes that observe each other
    for (let eye of spiralEyes) {
      p.push();
      p.translate(eye.x, eye.y);
      p.rotate(eye.rotation + time * 0.2);

      drawSpiralEye(eye.size, eye.spiralOffset);
      p.pop();
    }

    // Central impossible knot
    p.push();
    p.rotate(time * -0.4);
    drawStrangeKnot(40 + p.sin(time * 3) * 10);
    p.pop();

    // Floating reflection particles
    drawReflectionParticles();
  };

  function drawRecursiveFrame(size, depth) {
    if (depth <= 0) return;

    p.stroke(255, 255 - depth * 30, 200, 100 + depth * 30);
    p.strokeWeight(2);
    p.noFill();

    // Draw impossible frame that folds into itself
    let offset = p.sin(time + depth) * 5;
    p.rect(-size/2 + offset, -size/2 + offset, size, size);

    // Recursive call with transformed space
    p.push();
    p.scale(0.7);
    p.rotate(p.PI / 8 + time * 0.1 * depth);
    drawRecursiveFrame(size, depth - 1);
    p.pop();
  }

  function drawSpiralEye(size, offset) {
    let numSpirals = 30;
    p.strokeWeight(1.5);
    p.noFill();

    for (let i = 0; i < numSpirals; i++) {
      let angle = i * 0.3 + time * 2 + offset;
      let radius = (i / numSpirals) * size/2;

      let x = p.cos(angle) * radius;
      let y = p.sin(angle) * radius;

      // Eye color that shifts
      p.stroke(
        p.map(p.sin(angle), -1, 1, 150, 255),
        p.map(p.cos(angle * 2), -1, 1, 100, 200),
        255,
        p.map(radius, 0, size/2, 255, 50)
      );

      if (i > 0) {
        let prevAngle = (i-1) * 0.3 + time * 2 + offset;
        let prevRadius = ((i-1) / numSpirals) * size/2;
        let prevX = p.cos(prevAngle) * prevRadius;
        let prevY = p.sin(prevAngle) * prevRadius;

        p.line(prevX, prevY, x, y);
      }

      // Central pupil that dilates
      if (i == numSpirals - 1) {
        p.fill(0, 100);
        p.noStroke();
        let pupilSize = 8 + p.sin(time * 4) * 3;
        p.ellipse(0, 0, pupilSize);
      }
    }
  }

  function drawStrangeKnot(size) {
    p.strokeWeight(2);
    p.noFill();

    let numPoints = 60;
    for (let i = 0; i < numPoints; i++) {
      let t = i / numPoints * p.TWO_PI * 3;
      let nextT = (i + 1) / numPoints * p.TWO_PI * 3;

      // Torus knot equations creating impossible loop
      let x1 = size * p.cos(t + time) * (2 + p.cos(3 * t));
      let y1 = size * p.sin(t + time) * (2 + p.cos(3 * t));
      let x2 = size * p.cos(nextT + time) * (2 + p.cos(3 * nextT));
      let y2 = size * p.sin(nextT + time) * (2 + p.cos(3 * nextT));

      // Scale everything down
      x1 *= 0.15;
      y1 *= 0.15;
      x2 *= 0.15;
      y2 *= 0.15;

      p.stroke(
        p.map(p.sin(t), -1, 1, 200, 255),
        p.map(p.cos(t * 2), -1, 1, 150, 255),
        p.map(p.sin(t * 3), -1, 1, 100, 255),
        180
      );

      p.line(x1, y1, x2, y2);
    }
  }

  function drawReflectionParticles() {
    let numParticles = 12;
    for (let i = 0; i < numParticles; i++) {
      let angle = i * p.TWO_PI / numParticles + time * 0.3;
      let radius = 180 + p.sin(time * 2 + i) * 30;

      let x = p.cos(angle) * radius;
      let y = p.sin(angle) * radius;

      p.fill(255, 255, 255, 100 + p.sin(time * 4 + i) * 50);
      p.noStroke();

      let particleSize = 3 + p.sin(time * 3 + i) * 2;
      p.ellipse(x, y, particleSize);

      // Each particle reflects mouse position subtly
      let mouseReflectionX = x + (p.mouseX - centerX) * 0.05;
      let mouseReflectionY = y + (p.mouseY - centerY) * 0.05;

      p.fill(255, 200, 255, 50);
      p.ellipse(mouseReflectionX, mouseReflectionY, particleSize * 0.7);
    }
  }
}

function sketch(p) {
  let time = 0;
  let mirrorPhase = 0;
  let particles = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize mirror particles
    for (let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(200),
        y: p.random(300, 600),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03),
        size: p.random(3, 8)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mirrorPhase = p.sin(time * 0.5) * 0.3;
    mouseInfluence = p.map(p.mouseX, 0, 400, -0.2, 0.2);

    // Deep purple-blue gradient background
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(280, 80, 15), p.color(260, 90, 5), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    p.push();
    p.translate(200, 300);

    // Central mirroring hands
    drawMirroredHands();

    // Chiasmic wave patterns
    drawChiasmaticWaves();

    // Palindromic particles
    drawMirrorParticles();

    // Central reflection axis
    drawReflectionAxis();

    p.pop();
  };

  function drawMirroredHands() {
    let handOffset = 80 + p.sin(time) * 10 + mouseInfluence * 20;
    let handRotation = p.sin(time * 0.7) * 0.3;

    p.strokeWeight(3);
    p.stroke(50, 90, 90, 80);
    p.fill(40, 70, 85, 60);

    // Left hand (original)
    p.push();
    p.translate(-handOffset, 0);
    p.rotate(handRotation);
    drawHand();
    p.pop();

    // Right hand (mirrored)
    p.push();
    p.translate(handOffset, 0);
    p.rotate(-handRotation);
    p.scale(-1, 1); // Mirror horizontally
    drawHand();
    p.pop();
  }

  function drawHand() {
    // Palm
    p.ellipse(0, 0, 40, 60);

    // Fingers
    for (let i = 0; i < 5; i++) {
      let angle = p.map(i, 0, 4, -0.6, 0.6);
      let length = 25 + i * 2;
      p.push();
      p.rotate(angle);
      p.line(0, -20, 0, -20 - length);
      p.ellipse(0, -20 - length, 8, 8);
      p.pop();
    }
  }

  function drawChiasmaticWaves() {
    p.strokeWeight(2);
    p.noFill();

    for (let layer = 0; layer < 3; layer++) {
      let hue = 300 + layer * 20;
      p.stroke(hue, 70, 70, 40);

      p.beginShape();
      for (let x = -200; x <= 200; x += 2) {
        let y1 = p.sin((x + time * 50) * 0.02 + layer) * 30;
        let y2 = p.sin((-x + time * 50) * 0.02 + layer) * 30; // Mirrored
        let y = (y1 + y2) * 0.5 + layer * 40 - 100;
        p.vertex(x, y);
      }
      p.endShape();
    }
  }

  function drawMirrorParticles() {
    for (let particle of particles) {
      let x1 = particle.x + p.sin(time + particle.phase) * 20;
      let y1 = particle.y + p.cos(time * 0.5 + particle.phase) * 15;

      // Original particle
      let alpha = p.sin(time + particle.phase) * 30 + 50;
      p.fill(320, 80, 90, alpha);
      p.noStroke();
      p.ellipse(x1 - 200, y1 - 300, particle.size, particle.size);

      // Mirrored particle
      p.fill(280, 80, 90, alpha);
      p.ellipse(-x1 + 200, y1 - 300, particle.size, particle.size);

      // Connection line showing the mirroring
      if (alpha > 60) {
        p.stroke(300, 60, 80, 20);
        p.strokeWeight(1);
        p.line(x1 - 200, y1 - 300, -x1 + 200, y1 - 300);
      }
    }
  }

  function drawReflectionAxis() {
    p.strokeWeight(1);
    p.stroke(60, 100, 100, 30 + p.sin(time * 2) * 20);

    // Vertical axis of reflection
    for (let y = -300; y < 300; y += 10) {
      let offset = p.sin(y * 0.05 + time) * 2;
      p.point(offset, y);
    }

    // Subtle X pattern suggesting chiasmus
    p.stroke(60, 80, 90, 15);
    p.strokeWeight(0.5);

    let crossSize = 150 + p.sin(time) * 20;
    p.line(-crossSize, -crossSize, crossSize, crossSize);
    p.line(-crossSize, crossSize, crossSize, -crossSize);
  }

  p.mousePressed = function() {
    // Regenerate particles on click
    particles = [];
    for (let i = 0; i < 40; i++) {
      particles.push({
        x: p.random(200),
        y: p.random(300, 600),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03),
        size: p.random(3, 8)
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let field = [];
  let gridSize = 20;
  let cols, rows;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    cols = p.width / gridSize;
    rows = p.height / gridSize;

    // Initialize vector field
    for (let i = 0; i < cols; i++) {
      field[i] = [];
      for (let j = 0; j < rows; j++) {
        field[i][j] = p.createVector(0, 0);
      }
    }

    // Create particles that will show the derivative
    for (let i = 0; i < 150; i++) {
      particles.push({
        pos: p.createVector(p.random(p.width), p.random(p.height)),
        vel: p.createVector(0, 0),
        trail: [],
        hue: p.random(200, 280),
        life: 1.0
      });
    }
  };

  p.draw = function() {
    p.background(15, 15, 5);
    time += 0.01;

    // Update vector field - this represents the underlying function
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 3);
    let mouseY = p.map(p.mouseY, 0, p.height, 0.1, 1);

    for (let i = 0; i < cols; i++) {
      for (let j = 0; j < rows; j++) {
        let x = i * gridSize;
        let y = j * gridSize;

        // Complex field that creates interesting derivatives
        let angle1 = p.noise(x * 0.01 + time, y * 0.01) * p.TWO_PI * 2;
        let angle2 = p.sin(x * 0.02 + time * mouseInfluence) + p.cos(y * 0.02 + time);
        let finalAngle = angle1 + angle2 * mouseY;

        let magnitude = p.noise(x * 0.008 + time * 0.5, y * 0.008) * 2;

        field[i][j] = p.createVector(
          p.cos(finalAngle) * magnitude,
          p.sin(finalAngle) * magnitude
        );
      }
    }

    // Draw the derivative field as subtle arrows
    p.stroke(240, 40, 25, 0.3);
    p.strokeWeight(1);
    for (let i = 1; i < cols - 1; i++) {
      for (let j = 1; j < rows - 1; j++) {
        let x = i * gridSize + gridSize/2;
        let y = j * gridSize + gridSize/2;

        // Calculate derivative (rate of change) of the field
        let dx = (field[i+1][j].mag() - field[i-1][j].mag()) / (2 * gridSize);
        let dy = (field[i][j+1].mag() - field[i][j-1].mag()) / (2 * gridSize);

        let derivMag = p.sqrt(dx*dx + dy*dy) * 50;
        if (derivMag > 0.5) {
          let derivAngle = p.atan2(dy, dx);
          p.line(x, y, 
                x + p.cos(derivAngle) * derivMag * 10,
                y + p.sin(derivAngle) * derivMag * 10);
        }
      }
    }

    // Update and draw particles following the field
    for (let particle of particles) {
      // Get field value at particle position
      let col = p.constrain(p.floor(particle.pos.x / gridSize), 0, cols-1);
      let row = p.constrain(p.floor(particle.pos.y / gridSize), 0, rows-1);
      let force = field[col][row].copy();

      // Apply force (this is like integration)
      particle.vel.add(force.mult(0.02));
      particle.vel.mult(0.98); // damping

      // Update position
      particle.pos.add(particle.vel);

      // Add to trail
      particle.trail.push(particle.pos.copy());
      if (particle.trail.length > 20) {
        particle.trail.splice(0, 1);
      }

      // Wrap around edges
      if (particle.pos.x < 0) particle.pos.x = p.width;
      if (particle.pos.x > p.width) particle.pos.x = 0;
      if (particle.pos.y < 0) particle.pos.y = p.height;
      if (particle.pos.y > p.height) particle.pos.y = 0;

      // Draw velocity vector (the derivative made visible!)
      let speed = particle.vel.mag();
      if (speed > 0.1) {
        p.stroke(particle.hue, 70, 90, p.map(speed, 0, 5, 0.1, 0.8));
        p.strokeWeight(p.map(speed, 0, 5, 1, 4));

        let arrowSize = speed * 8;
        let angle = particle.vel.heading();

        // Draw velocity arrow
        p.line(particle.pos.x, particle.pos.y,
              particle.pos.x + p.cos(angle) * arrowSize,
              particle.pos.y + p.sin(angle) * arrowSize);

        // Arrow head
        p.fill(particle.hue, 70, 90, p.map(speed, 0, 5, 0.3, 0.9));
        p.noStroke();
        p.push();
        p.translate(particle.pos.x + p.cos(angle) * arrowSize,
                   particle.pos.y + p.sin(angle) * arrowSize);
        p.rotate(angle);
        p.triangle(0, 0, -8, -3, -8, 3);
        p.pop();
      }

      // Draw trail showing path history
      p.noFill();
      if (particle.trail.length > 1) {
        for (let i = 1; i < particle.trail.length; i++) {
          let alpha = p.map(i, 0, particle.trail.length, 0, 0.4);
          p.stroke(particle.hue, 50, 60, alpha);
          p.strokeWeight(1);
          p.line(particle.trail[i-1].x, particle.trail[i-1].y,
                particle.trail[i].x, particle.trail[i].y);
        }
      }
    }

    // Draw gradient visualization at mouse position
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      let mouseCol = p.constrain(p.floor(p.mouseX / gridSize), 1, cols-2);
      let mouseRow = p.constrain(p.floor(p.mouseY / gridSize), 1, rows-2);

      // Show the derivative at mouse position as a bright indicator
      let dx = (field[mouseCol+1][mouseRow].mag() - field[mouseCol-1][mouseRow].mag()) / (2 * gridSize);
      let dy = (field[mouseCol][mouseRow+1].mag() - field[mouseCol][mouseRow-1].mag()) / (2 * gridSize);
      let derivMag = p.sqrt(dx*dx + dy*dy);

      p.fill(60, 90, 95, 0.8);
      p.noStroke();
      p.circle(p.mouseX, p.mouseY, derivMag * 100 + 5);

      p.fill(60, 100, 100, 0.9);
      p.circle(p.mouseX, p.mouseY, 3);
    }
  };
}

function sketch(p) {
  let layers = [];
  let particles = [];
  let time = 0;
  let threshold = 0.7;
  let emergenceActive = false;
  let emergenceTime = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize accumulating layers
    for (let i = 0; i < 12; i++) {
      layers.push({
        y: p.height - 50 - i * 35,
        elements: [],
        complexity: i + 1,
        alpha: 0,
        targetAlpha: 0
      });
    }

    // Initialize floating particles
    for (let i = 0; i < 80; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height + 200, p.height + 800),
        size: p.random(2, 6),
        speed: p.random(0.5, 2),
        color: p.color(p.random(180, 220), p.random(100, 255), p.random(200, 255), 180),
        assigned: false,
        targetLayer: -1
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Dynamic background gradient
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(15, 25, 45),
        p.color(45, 15, 75),
        inter + p.sin(time * 0.5) * 0.1
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Calculate accumulation progress
    let progress = (p.sin(time * 0.3) + 1) * 0.5;
    let currentLayer = p.floor(progress * layers.length);

    // Update layer visibility based on accumulation
    for (let i = 0; i < layers.length; i++) {
      if (i <= currentLayer) {
        layers[i].targetAlpha = p.map(i, 0, layers.length - 1, 255, 100);
      } else {
        layers[i].targetAlpha = 0;
      }
      layers[i].alpha = p.lerp(layers[i].alpha, layers[i].targetAlpha, 0.02);
    }

    // Check for emergence threshold
    if (progress > threshold && !emergenceActive) {
      emergenceActive = true;
      emergenceTime = time;
    }

    // Update and draw particles
    p.noStroke();
    for (let particle of particles) {
      // Particle movement and assignment
      if (!particle.assigned && particle.y > 0) {
        particle.y -= particle.speed;

        // Assign particle to layer when it reaches appropriate height
        for (let i = 0; i < layers.length; i++) {
          if (particle.y <= layers[i].y + 20 && particle.y >= layers[i].y - 20 && layers[i].alpha > 50) {
            if (layers[i].elements.length < layers[i].complexity * 3) {
              particle.assigned = true;
              particle.targetLayer = i;
              layers[i].elements.push({
                x: particle.x,
                y: layers[i].y,
                size: particle.size,
                color: particle.color,
                phase: p.random(p.TWO_PI)
              });
            }
          }
        }
      }

      // Draw unassigned particles
      if (!particle.assigned) {
        p.fill(particle.color);
        p.ellipse(particle.x, particle.y, particle.size);

        // Add subtle drift toward mouse
        let mouseInfluence = p.map(p.dist(p.mouseX, p.mouseY, particle.x, particle.y), 0, 200, 0.02, 0);
        particle.x = p.lerp(particle.x, p.mouseX, mouseInfluence);
      }

      // Reset particles that go off screen
      if (particle.y < -50) {
        particle.y = p.random(p.height + 50, p.height + 200);
        particle.x = p.random(p.width);
        particle.assigned = false;
        particle.targetLayer = -1;
      }
    }

    // Draw accumulated layers
    for (let i = 0; i < layers.length; i++) {
      let layer = layers[i];
      if (layer.alpha > 5) {
        // Draw connection lines between elements
        p.stroke(255, 100, 200, layer.alpha * 0.3);
        p.strokeWeight(1);

        for (let j = 0; j < layer.elements.length - 1; j++) {
          let elem1 = layer.elements[j];
          let elem2 = layer.elements[j + 1];
          p.line(elem1.x, elem1.y, elem2.x, elem2.y);
        }

        // Draw layer elements
        p.noStroke();
        for (let elem of layer.elements) {
          let breathing = p.sin(time * 2 + elem.phase) * 0.3 + 1;
          p.fill(p.red(elem.color), p.green(elem.color), p.blue(elem.color), layer.alpha);
          p.ellipse(elem.x, elem.y, elem.size * breathing);

          // Higher layers get more complex visual treatment
          if (i > 6) {
            p.fill(255, 255, 255, layer.alpha * 0.5);
            p.ellipse(elem.x, elem.y, elem.size * breathing * 0.3);
          }
        }

        // Draw layer substrate
        p.fill(100, 150, 255, layer.alpha * 0.1);
        p.rect(0, layer.y - 5, p.width, 10);
      }
    }

    // Draw emergence effect when threshold is crossed
    if (emergenceActive) {
      let emergenceDuration = time - emergenceTime;
      if (emergenceDuration < 3) {
        let intensity = p.sin(emergenceDuration * p.PI / 3);

        // Radial emergence burst
        p.push();
        p.translate(p.width / 2, p.height / 3);
        p.noFill();

        for (let r = 0; r < 8; r++) {
          p.stroke(255, 200, 100, intensity * 200 * (1 - r / 8));
          p.strokeWeight(2);
          p.ellipse(0, 0, r * 60 * intensity);
        }

        // Spiraling emergence pattern
        p.rotate(emergenceDuration * 2);
        for (let angle = 0; angle < p.TWO_PI * 3; angle += 0.1) {
          let radius = angle * 15 * intensity;
          let x = p.cos(angle) * radius;
          let y = p.sin(angle) * radius;
          let alpha = intensity * 255 * (1 - angle / (p.TWO_PI * 3));

          p.fill(255, 255, 150, alpha);
          p.noStroke();
          p.ellipse(x, y, 4);
        }
        p.pop();
      } else {
        emergenceActive = false;
      }
    }

    // Mouse interaction - influence particle flow
    if (p.mouseIsPressed) {
      p.push();
      p.translate(p.mouseX, p.mouseY);
      p.noFill();
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(1);
      for (let i = 0; i < 5; i++) {
        p.ellipse(0, 0, i * 20 + p.sin(time * 3) * 10);
      }
      p.pop();

      // Accelerate nearby particles
      for (let particle of particles) {
        if (!particle.assigned) {
          let dist = p.dist(p.mouseX, p.mouseY, particle.x, particle.y);
          if (dist < 100) {
            particle.speed *= 1.02;
          }
        }
      }
    }
  };
}

function sketch(p) {
  let structures = [];
  let particles = [];
  let time = 0;
  let captureLevel = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create initial structure layers
    for(let i = 0; i < 8; i++) {
      structures.push({
        level: i,
        boxes: [],
        opacity: p.map(i, 0, 7, 255, 80),
        drift: p.random(-0.5, 0.5),
        rotSpeed: p.random(0.001, 0.003)
      });

      // Generate boxes for each level
      let numBoxes = p.floor(p.random(3, 8));
      for(let j = 0; j < numBoxes; j++) {
        structures[i].boxes.push({
          x: p.random(50, 350),
          y: p.map(i, 0, 7, 550, 100) + p.random(-30, 30),
          size: p.random(15, 40),
          rotation: 0,
          connections: []
        });
      }
    }

    // Create connection particles
    for(let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: p.random(100, 300),
        maxLife: 300
      });
    }
  };

  p.draw = function() {
    p.background(15, 10, 25);
    time += 0.01;

    // Calculate capture level based on mouse interaction
    captureLevel = p.map(p.mouseY, 600, 0, 0, 1);
    captureLevel = p.constrain(captureLevel, 0, 1);

    // Draw foundation becoming invisible
    p.push();
    p.fill(40, 35, 30, 255 * (1 - captureLevel * 0.8));
    p.noStroke();
    p.rect(0, 550, 400, 50);

    // Foundation cracks
    p.stroke(60, 50, 40, 150 * captureLevel);
    p.strokeWeight(2);
    for(let i = 0; i < 10; i++) {
      let x = p.map(i, 0, 9, 50, 350);
      let crackHeight = captureLevel * p.random(20, 60);
      p.line(x, 600, x + p.random(-10, 10), 600 - crackHeight);
    }
    p.pop();

    // Draw structural levels
    for(let i = 0; i < structures.length; i++) {
      let struct = structures[i];
      let levelCapture = p.pow(captureLevel, 0.5 + i * 0.1);

      p.push();
      p.translate(0, struct.drift * p.sin(time + i) * levelCapture * 20);

      // Draw connections between boxes (becoming more chaotic)
      p.stroke(200, 100, 150, struct.opacity * 0.3);
      p.strokeWeight(1 + levelCapture * 2);

      for(let j = 0; j < struct.boxes.length; j++) {
        let box = struct.boxes[j];
        for(let k = j + 1; k < struct.boxes.length; k++) {
          let other = struct.boxes[k];
          let distance = p.dist(box.x, box.y, other.x, other.y);

          if(distance < 100 + levelCapture * 100) {
            // Connection becomes more erratic with capture
            let wobble = levelCapture * p.sin(time * 3 + j + k) * 10;
            p.line(
              box.x + wobble, box.y,
              other.x - wobble, other.y
            );

            // Self-referential loops
            if(levelCapture > 0.5 && p.random() < 0.1) {
              p.noFill();
              p.stroke(255, 80, 120, 100);
              p.ellipse(
                (box.x + other.x) / 2,
                (box.y + other.y) / 2,
                distance * 0.5,
                distance * 0.3
              );
            }
          }
        }
      }

      // Draw boxes
      for(let j = 0; j < struct.boxes.length; j++) {
        let box = struct.boxes[j];
        box.rotation += struct.rotSpeed * (1 + levelCapture * 3);

        p.push();
        p.translate(box.x, box.y);
        p.rotate(box.rotation);

        // Box becomes more fragmented and self-consuming
        let hue = p.map(i, 0, 7, 280, 320);
        let sat = 60 + levelCapture * 40;
        let bri = 40 + levelCapture * 30;

        p.fill(hue, sat, bri, struct.opacity);
        p.stroke(hue + 20, sat + 20, bri + 40, struct.opacity);
        p.strokeWeight(1 + levelCapture);

        // Main structure
        p.rect(-box.size/2, -box.size/2, box.size, box.size);

        // Fractal self-consumption
        if(levelCapture > 0.3) {
          let numFractals = p.floor(levelCapture * 4);
          for(let f = 0; f < numFractals; f++) {
            p.push();
            p.scale(0.6);
            p.rotate(f * p.PI/2 + time);
            p.fill(hue, sat + 20, bri + 20, struct.opacity * 0.7);
            p.rect(-box.size/4, -box.size/4, box.size/2, box.size/2);
            p.pop();
          }
        }

        p.pop();
      }
      p.pop();
    }

    // Parasitic particles
    p.stroke(255, 100, 150, 150);
    p.strokeWeight(1);
    p.noFill();

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Move toward structures (parasitic behavior)
      let nearestStruct = null;
      let minDist = Infinity;

      for(let s = 0; s < structures.length; s++) {
        for(let b = 0; b < structures[s].boxes.length; b++) {
          let box = structures[s].boxes[b];
          let d = p.dist(particle.x, particle.y, box.x, box.y);
          if(d < minDist) {
            minDist = d;
            nearestStruct = box;
          }
        }
      }

      if(nearestStruct && minDist < 100) {
        let pull = 0.02 * captureLevel;
        particle.vx += (nearestStruct.x - particle.x) * pull;
        particle.vy += (nearestStruct.y - particle.y) * pull;
      }

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      // Draw particle trail
      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 100);
      p.stroke(300, 80, 90, alpha);
      p.point(particle.x, particle.y);

      // Remove dead particles
      if(particle.life <= 0 || particle.x < 0 || particle.x > 400 || particle.y < 0 || particle.y > 600) {
        particles.splice(i, 1);
        // Replace with new particle
        particles.push({
          x: p.random(400),
          y: p.random(600),
          vx: p.random(-1, 1),
          vy: p.random(-1, 1),
          life: p.random(100, 300),
          maxLife: 300
        });
      }
    }

    // Warning signals when capture is detected
    if(captureLevel > 0.7) {
      p.stroke(255, 0, 0, p.sin(time * 10) * 100 + 155);
      p.strokeWeight(3);
      p.noFill();
      p.rect(10, 10, 380, 580, 10);

      // Pulsing danger indicators
      for(let i = 0; i < 4; i++) {
        let x = [20, 380, 380, 20][i];
        let y = [20, 20, 580, 580][i];
        p.fill(255, 0, 0, p.sin(time * 8 + i) * 100 + 155);
        p.noStroke();
        p.triangle(x, y, x+10, y+10, x-10, y+10);
      }
    }
  };

  p.mousePressed = function() {
    // Disturb the system
    for(let i = 0; i < structures.length; i++) {
      for(let j = 0; j < structures[i].boxes.length; j++) {
        let box = structures[i].boxes[j];
        let distance = p.dist(p.mouseX, p.mouseY, box.x, box.y);
        if(distance < 50) {
          box.x += p.random(-20, 20);
          box.y += p.random(-20, 20);
          structures[i].rotSpeed *= 1.5;
        }
      }
    }
  };
}

function sketch(p) {
  let deltas = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize delta particles
    for (let i = 0; i < 60; i++) {
      deltas.push({
        x: p.random(p.width),
        y: p.random(p.height),
        size: p.random(8, 25),
        hue: p.random(180, 280),
        brightness: p.random(70, 90),
        speed: p.random(0.5, 2),
        phase: p.random(p.TWO_PI),
        changeRate: p.random(0.02, 0.05),
        opacity: p.random(60, 90)
      });
    }
  };

  p.draw = function() {
    // Deep purple-blue gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(260, 80, 15), 
        p.color(280, 60, 5), 
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.01;
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseX, 0, p.width, 0, 1), 0.1);

    // Draw flowing delta stream in center
    p.push();
    p.translate(p.width/2, p.height/2);

    // Main delta cascade
    for (let i = 0; i < 8; i++) {
      let y = p.map(i, 0, 7, -250, 250);
      let offset = p.sin(time + i * 0.5) * 30 * mouseInfluence;
      let size = 25 + p.sin(time * 2 + i) * 8;

      // Delta triangle with glow
      p.fill(220 + i * 5, 80 - i * 5, 85 + p.sin(time + i) * 10, 80);
      p.noStroke();

      // Outer glow
      for (let glow = 3; glow > 0; glow--) {
        p.fill(220 + i * 5, 60, 90, 15 * glow);
        drawDelta(offset, y, size + glow * 6);
      }

      // Main delta
      p.fill(220 + i * 5, 90, 95, 90);
      drawDelta(offset, y, size);

      // Inner bright core
      p.fill(240, 70, 100, 60);
      drawDelta(offset, y, size * 0.6);
    }
    p.pop();

    // Floating change particles
    for (let delta of deltas) {
      // Update position with gentle drift
      delta.y -= delta.speed;
      delta.x += p.sin(time + delta.phase) * 0.3;

      // Wrap around screen
      if (delta.y < -20) {
        delta.y = p.height + 20;
        delta.x = p.random(p.width);
      }
      if (delta.x < -20) delta.x = p.width + 20;
      if (delta.x > p.width + 20) delta.x = -20;

      // Mouse interaction - deltas are drawn to mouse but maintain their flow
      let mouseForce = p.createVector(p.mouseX - delta.x, p.mouseY - delta.y);
      mouseForce.mult(0.002);
      delta.x += mouseForce.x * mouseInfluence;
      delta.y += mouseForce.y * mouseInfluence * 0.3; // Less vertical influence

      // Animate properties
      delta.hue += delta.changeRate;
      delta.brightness = 75 + p.sin(time + delta.phase) * 15;
      delta.size = delta.size + p.sin(time * 2 + delta.phase) * 2;

      // Draw delta with subtle glow
      p.push();
      p.translate(delta.x, delta.y);
      p.rotate(p.sin(time + delta.phase) * 0.1);

      // Glow
      p.fill(delta.hue, 50, delta.brightness, 25);
      p.noStroke();
      drawDelta(0, 0, delta.size + 8);

      // Main delta
      p.fill(delta.hue, 80, delta.brightness, delta.opacity);
      drawDelta(0, 0, delta.size);

      p.pop();
    }

    // Interactive ripples when mouse moves
    if (p.mouseX !== p.pmouseX || p.mouseY !== p.pmouseY) {
      let rippleSize = 30 + mouseInfluence * 50;
      p.push();
      p.translate(p.mouseX, p.mouseY);
      p.noFill();
      p.stroke(200, 70, 90, 40);
      p.strokeWeight(2);
      p.ellipse(0, 0, rippleSize);

      // Small delta at mouse position
      p.fill(200, 80, 95, 70);
      p.noStroke();
      drawDelta(0, 0, 15);
      p.pop();
    }
  };

  function drawDelta(x, y, size) {
    p.push();
    p.translate(x, y);
    p.beginShape();
    p.vertex(0, -size * 0.6);
    p.vertex(-size * 0.5, size * 0.4);
    p.vertex(size * 0.5, size * 0.4);
    p.endShape(p.CLOSE);
    p.pop();
  }

  p.mousePressed = function() {
    // Create burst of new deltas at mouse position
    for (let i = 0; i < 8; i++) {
      deltas.push({
        x: p.mouseX + p.random(-30, 30),
        y: p.mouseY + p.random(-30, 30),
        size: p.random(6, 20),
        hue: p.random(180, 280),
        brightness: p.random(80, 100),
        speed: p.random(1, 3),
        phase: p.random(p.TWO_PI),
        changeRate: p.random(0.03, 0.08),
        opacity: p.random(70, 95)
      });
    }

    // Remove oldest deltas to maintain performance
    if (deltas.length > 100) {
      deltas.splice(0, 8);
    }
  };
}

function sketch(p) {
  let references = [];
  let centralObject = null;
  let objectOpacity = 0;
  let accumulatedAttention = 0;
  let sparkles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize reference streams
    for (let i = 0; i < 12; i++) {
      references.push({
        angle: (i / 12) * p.TWO_PI,
        distance: 250,
        particles: [],
        color: p.color(p.random(180, 220), p.random(100, 180), p.random(200, 255), 120)
      });
    }

    // Initialize particles for each reference stream
    references.forEach(ref => {
      for (let j = 0; j < 8; j++) {
        ref.particles.push({
          progress: p.random(1),
          speed: p.random(0.005, 0.015),
          size: p.random(2, 6),
          pulse: p.random(p.TWO_PI)
        });
      }
    });
  };

  p.draw = function() {
    time += 0.02;
    p.background(15, 20, 35);

    let centerX = p.width / 2;
    let centerY = p.height / 2;

    // Mouse influence
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, centerX, centerY) < 100 ? 
                        p.map(p.dist(p.mouseX, p.mouseY, centerX, centerY), 0, 100, 2, 0.5) : 1;

    // Draw reference streams
    let totalReferences = 0;

    references.forEach((ref, i) => {
      let startX = centerX + p.cos(ref.angle + time * 0.3) * ref.distance;
      let startY = centerY + p.sin(ref.angle + time * 0.3) * ref.distance;

      // Draw connecting line
      p.stroke(ref.color);
      p.strokeWeight(1);
      p.line(startX, startY, centerX, centerY);

      // Animate particles along the reference line
      ref.particles.forEach(particle => {
        particle.progress += particle.speed * mouseInfluence;

        if (particle.progress >= 1) {
          particle.progress = 0;
          totalReferences += 0.1;

          // Create sparkle at center
          sparkles.push({
            x: centerX + p.random(-15, 15),
            y: centerY + p.random(-15, 15),
            life: 1,
            color: ref.color
          });
        }

        let x = p.lerp(startX, centerX, particle.progress);
        let y = p.lerp(startY, centerY, particle.progress);

        // Draw particle
        p.fill(ref.color);
        p.noStroke();
        let size = particle.size * (1 + 0.3 * p.sin(time * 3 + particle.pulse));
        p.circle(x, y, size);

        // Trail effect
        p.fill(p.red(ref.color), p.green(ref.color), p.blue(ref.color), 30);
        p.circle(x, y, size * 1.5);
      });
    });

    // Accumulate attention
    accumulatedAttention += totalReferences;
    objectOpacity = p.constrain(p.map(accumulatedAttention, 0, 500, 0, 255), 0, 255);

    // Draw emerging central object
    if (objectOpacity > 10) {
      p.push();
      p.translate(centerX, centerY);

      // Outer glow
      for (let r = 60; r > 0; r -= 10) {
        p.fill(120, 180, 255, objectOpacity * 0.1 * (60 - r) / 60);
        p.noStroke();
        p.circle(0, 0, r);
      }

      // Main object - crystalline form
      p.stroke(150, 200, 255, objectOpacity);
      p.strokeWeight(2);
      p.fill(80, 140, 220, objectOpacity * 0.3);

      let sides = 8;
      p.beginShape();
      for (let i = 0; i < sides; i++) {
        let angle = (i / sides) * p.TWO_PI;
        let radius = 25 + 8 * p.sin(time * 2 + i);
        let x = p.cos(angle) * radius;
        let y = p.sin(angle) * radius;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Inner core
      p.fill(200, 230, 255, objectOpacity * 0.8);
      p.noStroke();
      p.circle(0, 0, 8 + 3 * p.sin(time * 4));

      p.pop();
    }

    // Draw and update sparkles
    for (let i = sparkles.length - 1; i >= 0; i--) {
      let sparkle = sparkles[i];
      sparkle.life -= 0.02;

      if (sparkle.life <= 0) {
        sparkles.splice(i, 1);
        continue;
      }

      p.fill(p.red(sparkle.color), p.green(sparkle.color), p.blue(sparkle.color), 
             sparkle.life * 200);
      p.noStroke();
      p.circle(sparkle.x, sparkle.y, sparkle.life * 4);
    }

    // Attention field visualization
    p.push();
    p.translate(centerX, centerY);
    p.noFill();
    for (let i = 0; i < 3; i++) {
      p.stroke(100, 150, 200, 30 + objectOpacity * 0.2);
      p.strokeWeight(1);
      let radius = 80 + i * 20 + 10 * p.sin(time - i);
      p.circle(0, 0, radius);
    }
    p.pop();

    // Reset accumulation periodically for continuous animation
    if (accumulatedAttention > 800) {
      accumulatedAttention *= 0.95;
    }
  };

  p.mousePressed = function() {
    // Burst of new references
    accumulatedAttention += 50;
    for (let i = 0; i < 20; i++) {
      sparkles.push({
        x: p.mouseX + p.random(-30, 30),
        y: p.mouseY + p.random(-30, 30),
        life: 1,
        color: p.color(p.random(150, 255), p.random(150, 255), 255)
      });
    }
  };
}

function sketch(p) {
  let knots = [];
  let tensionField = [];
  let fieldWidth = 20;
  let fieldHeight = 30;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create central knot points
    for(let i = 0; i < 3; i++) {
      knots.push({
        x: 200 + p.random(-80, 80),
        y: 200 + p.random(-60, 60) + i * 120,
        intensity: p.random(0.8, 1.2),
        phase: p.random(p.TWO_PI)
      });
    }

    // Initialize tension field grid
    for(let i = 0; i <= fieldWidth; i++) {
      tensionField[i] = [];
      for(let j = 0; j <= fieldHeight; j++) {
        tensionField[i][j] = {
          x: i * (400 / fieldWidth),
          y: j * (600 / fieldHeight),
          originalX: i * (400 / fieldWidth),
          originalY: j * (600 / fieldHeight),
          tension: 0
        };
      }
    }
  };

  p.draw = function() {
    p.background(15, 12, 25);
    time += 0.01;

    // Calculate tension field distortions
    for(let i = 0; i <= fieldWidth; i++) {
      for(let j = 0; j <= fieldHeight; j++) {
        let point = tensionField[i][j];
        let totalForceX = 0;
        let totalForceY = 0;
        let totalTension = 0;

        // Each knot creates a distortion field
        for(let knot of knots) {
          let distance = p.dist(point.originalX, point.originalY, knot.x, knot.y);
          let force = (knot.intensity * 100) / (distance + 20);
          let angle = p.atan2(point.originalY - knot.y, point.originalX - knot.x);

          // Nonlinear attraction creates the "knot" effect
          let pullStrength = p.sin(time + knot.phase) * 0.3 + 0.7;
          totalForceX += p.cos(angle) * force * pullStrength;
          totalForceY += p.sin(angle) * force * pullStrength;
          totalTension += force;
        }

        point.x = point.originalX + totalForceX * 0.8;
        point.y = point.originalY + totalForceY * 0.8;
        point.tension = totalTension;
      }
    }

    // Draw tension field as distorted grid
    p.strokeWeight(0.8);
    for(let i = 0; i < fieldWidth; i++) {
      for(let j = 0; j < fieldHeight; j++) {
        let point = tensionField[i][j];
        let intensity = p.map(point.tension, 0, 15, 0, 1);

        // Color based on tension - deep purples and reds
        p.stroke(
          120 + intensity * 135,
          30 + intensity * 100,
          80 + intensity * 120,
          100 + intensity * 100
        );

        // Horizontal connections
        if(i < fieldWidth) {
          let nextPoint = tensionField[i + 1][j];
          p.line(point.x, point.y, nextPoint.x, nextPoint.y);
        }

        // Vertical connections
        if(j < fieldHeight) {
          let nextPoint = tensionField[i][j + 1];
          p.line(point.x, point.y, nextPoint.x, nextPoint.y);
        }
      }
    }

    // Draw knot centers as pulsing focal points
    for(let knot of knots) {
      let pulse = p.sin(time * 2 + knot.phase) * 0.3 + 0.7;
      let size = 15 + pulse * 10;

      // Outer glow
      for(let r = size * 2; r > 0; r -= 2) {
        let alpha = p.map(r, 0, size * 2, 200, 0);
        p.fill(255, 120, 180, alpha);
        p.noStroke();
        p.ellipse(knot.x, knot.y, r);
      }

      // Core knot
      p.fill(255, 200, 220);
      p.ellipse(knot.x, knot.y, size * 0.6);
    }

    // Interactive mouse influence
    if(p.mouseX > 0 && p.mouseX < 400 && p.mouseY > 0 && p.mouseY < 600) {
      let mouseInfluence = {
        x: p.mouseX,
        y: p.mouseY,
        intensity: 0.5
      };

      // Add temporary distortion around mouse
      p.stroke(255, 255, 255, 50);
      p.strokeWeight(1);
      p.noFill();
      for(let r = 10; r < 60; r += 8) {
        let wobble = p.sin(time * 4 + r * 0.1) * 3;
        p.ellipse(mouseInfluence.x, mouseInfluence.y, r + wobble);
      }
    }

    // Stress line particles that follow the distortion
    p.stroke(255, 180, 200, 150);
    p.strokeWeight(1);
    for(let i = 0; i < 8; i++) {
      let t = (time + i * 0.8) % 1;
      let pathX = p.lerp(50, 350, t);
      let pathY = 100 + p.sin(t * p.PI * 2 + i) * 50;

      // Find nearest tension field point for distortion
      let gridX = p.floor(pathX / (400 / fieldWidth));
      let gridY = p.floor(pathY / (600 / fieldHeight));

      if(gridX >= 0 && gridX < fieldWidth && gridY >= 0 && gridY < fieldHeight) {
        let fieldPoint = tensionField[gridX][gridY];
        let distortedX = pathX + (fieldPoint.x - fieldPoint.originalX) * 0.5;
        let distortedY = pathY + (fieldPoint.y - fieldPoint.originalY) * 0.5;

        p.point(distortedX, distortedY);

        // Trail effect
        let prevT = (time + i * 0.8 - 0.1) % 1;
        let prevX = p.lerp(50, 350, prevT);
        let prevY = 100 + p.sin(prevT * p.PI * 2 + i) * 50;
        p.line(distortedX, distortedY, prevX, prevY);
      }
    }
  };
}

function sketch(p) {
  let particles = [];
  let layers = [];
  let abstractShape = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create initial detailed particles at bottom
    for (let i = 0; i < 150; i++) {
      particles.push({
        x: p.random(50, 350),
        y: p.random(400, 550),
        size: p.random(2, 8),
        detail: p.random(0.5, 1),
        speed: p.random(0.3, 1.2),
        phase: p.random(p.TWO_PI),
        originalSize: p.random(2, 8)
      });
    }

    // Create abstraction layers
    for (let i = 0; i < 5; i++) {
      layers.push({
        y: 500 - i * 100,
        opacity: 50 + i * 30,
        thickness: 8 - i * 1.2
      });
    }

    // Create abstract form points
    for (let i = 0; i < 8; i++) {
      let angle = (p.TWO_PI / 8) * i;
      abstractShape.push({
        x: 200 + p.cos(angle) * 60,
        y: 120 + p.sin(angle) * 40,
        targetX: 200 + p.cos(angle) * 60,
        targetY: 120 + p.sin(angle) * 40
      });
    }
  };

  p.draw = function() {
    // Gradient background
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(85, 45, 85), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;

    // Draw abstraction layers with subtle shimmer
    p.noFill();
    for (let layer of layers) {
      let shimmer = p.sin(time * 2 + layer.y * 0.01) * 10;
      p.stroke(255, 255, 200, layer.opacity);
      p.strokeWeight(layer.thickness);
      p.line(50 + shimmer, layer.y, 350 - shimmer, layer.y);
    }

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Move upward with gentle drift
      particle.y -= particle.speed;
      particle.x += p.sin(time + particle.phase) * 0.5;

      // Simplify as particles rise
      let height_ratio = p.map(particle.y, 550, 50, 0, 1);
      height_ratio = p.constrain(height_ratio, 0, 1);

      particle.detail = p.lerp(1, 0.1, height_ratio);
      particle.size = p.lerp(particle.originalSize, particle.originalSize * 0.3, height_ratio);

      // Color transition from detailed blue-white to abstract golden
      let r = p.lerp(100, 255, height_ratio);
      let g = p.lerp(150, 220, height_ratio);
      let b = p.lerp(255, 120, height_ratio);
      let alpha = p.lerp(200, 100, height_ratio);

      // Mouse interaction - particles gently gravitate toward mouse when nearby
      let mouseDistance = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if (mouseDistance < 80) {
        let force = p.map(mouseDistance, 0, 80, 0.5, 0);
        particle.x += (p.mouseX - particle.x) * force * 0.02;
        particle.y += (p.mouseY - particle.y) * force * 0.01;
      }

      // Draw particle with decreasing detail
      p.fill(r, g, b, alpha);
      p.noStroke();

      if (particle.detail > 0.7) {
        // Detailed form - small complex shapes
        p.push();
        p.translate(particle.x, particle.y);
        p.rotate(time + particle.phase);
        p.beginShape();
        for (let j = 0; j < 6; j++) {
          let angle = (p.TWO_PI / 6) * j;
          let radius = particle.size;
          p.vertex(p.cos(angle) * radius, p.sin(angle) * radius);
        }
        p.endShape(p.CLOSE);
        p.pop();
      } else if (particle.detail > 0.3) {
        // Medium abstraction - simple circles with glow
        p.ellipse(particle.x, particle.y, particle.size * 2);
        p.fill(r, g, b, alpha * 0.3);
        p.ellipse(particle.x, particle.y, particle.size * 4);
      } else {
        // High abstraction - pure light points
        p.fill(255, 220, 120, alpha);
        p.ellipse(particle.x, particle.y, particle.size);
        p.fill(255, 255, 200, alpha * 0.2);
        p.ellipse(particle.x, particle.y, particle.size * 3);
      }

      // Remove particles that have fully ascended
      if (particle.y < 0) {
        particles.splice(i, 1);
      }
    }

    // Regenerate particles at bottom to maintain flow
    if (particles.length < 120) {
      particles.push({
        x: p.random(50, 350),
        y: p.random(500, 550),
        size: p.random(2, 8),
        detail: p.random(0.5, 1),
        speed: p.random(0.3, 1.2),
        phase: p.random(p.TWO_PI),
        originalSize: p.random(2, 8)
      });
    }

    // Draw the ultimate abstract form at top
    p.fill(255, 240, 150, 180);
    p.noStroke();

    // Update abstract shape with gentle breathing motion
    for (let point of abstractShape) {
      point.x += (point.targetX - point.x) * 0.1;
      point.y += (point.targetY - point.y) * 0.1;
    }

    // Draw abstract essence as flowing blob
    p.beginShape();
    for (let i = 0; i < abstractShape.length; i++) {
      let point = abstractShape[i];
      let breathing = p.sin(time * 1.5 + i * 0.5) * 8;
      p.curveVertex(point.x + breathing, point.y + p.sin(time + i) * 3);
    }
    // Close the shape by repeating first few points
    for (let i = 0; i < 3; i++) {
      let point = abstractShape[i];
      let breathing = p.sin(time * 1.5 + i * 0.5) * 8;
      p.curveVertex(point.x + breathing, point.y + p.sin(time + i) * 3);
    }
    p.endShape();

    // Draw subtle glow around abstract form
    p.fill(255, 255, 200, 30);
    p.beginShape();
    for (let i = 0; i < abstractShape.length; i++) {
      let point = abstractShape[i];
      let breathing = p.sin(time * 1.5 + i * 0.5) * 12;
      p.curveVertex(point.x + breathing, point.y + p.sin(time + i) * 4);
    }
    for (let i = 0; i < 3; i++) {
      let point = abstractShape[i];
      let breathing = p.sin(time * 1.5 + i * 0.5) * 12;
      p.curveVertex(point.x + breathing, point.y + p.sin(time + i) * 4);
    }
    p.endShape();
  };

  p.mousePressed = function() {
    // Create burst of particles from mouse position that will rise and abstract
    for (let i = 0; i < 15; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-10, 10),
        size: p.random(3, 10),
        detail: 1,
        speed: p.random(0.8, 2),
        phase: p.random(p.TWO_PI),
        originalSize: p.random(3, 10)
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let numParticles = 120;
  let time = 0;
  let lensY = 200;
  let targetLensY = 200;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize particles as abstract forms at the top
    for (let i = 0; i < numParticles; i++) {
      particles.push({
        id: i,
        originalX: p.random(50, 350),
        originalY: p.random(20, 80),
        x: p.random(50, 350),
        y: p.random(20, 80),
        targetX: 0,
        targetY: 0,
        size: p.random(2, 8),
        targetSize: 0,
        hue: p.random(200, 280),
        brightness: p.random(60, 90),
        alpha: p.random(40, 80),
        speed: p.random(0.008, 0.02),
        phase: p.random(0, p.TWO_PI),
        concrete: false,
        concreteTime: 0
      });
    }

    updateTargets();
  };

  function updateTargets() {
    // Create focused projection points below the lens
    let focusY = lensY + 150;
    let spreadFactor = p.map(p.mouseY, 0, 600, 0.2, 2.0);

    for (let i = 0; i < particles.length; i++) {
      let particle = particles[i];
      let angle = (i / numParticles) * p.TWO_PI * 3;
      let radius = p.map(p.sin(angle + time), -1, 1, 20, 80) * spreadFactor;

      particle.targetX = 200 + p.cos(angle) * radius;
      particle.targetY = focusY + p.sin(angle * 0.7) * 30;
      particle.targetSize = p.map(particle.originalY, 20, 80, 8, 3);
    }
  }

  p.draw = function() {
    time += 0.01;

    // Dynamic background with subtle gradient
    for (let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 15, 5);
      let hue = p.map(y, 0, p.height, 240, 280);
      p.stroke(hue, 30, 20, alpha);
      p.line(0, y, p.width, y);
    }

    // Mouse interaction affects lens position
    targetLensY = p.map(p.mouseY, 0, p.height, 150, 250);
    lensY = p.lerp(lensY, targetLensY, 0.05);

    updateTargets();

    // Draw the focusing lens
    drawLens();

    // Draw light rays
    drawLightRays();

    // Update and draw particles
    for (let particle of particles) {
      updateParticle(particle);
      drawParticle(particle);
    }

    // Draw connection lines showing the projection
    drawProjectionLines();
  };

  function drawLens() {
    p.stroke(200, 60, 80, 60);
    p.strokeWeight(3);
    p.noFill();

    // Lens shape - biconvex
    p.arc(200, lensY, 120, 40, 0, p.PI);
    p.arc(200, lensY, 120, 40, p.PI, p.TWO_PI);

    // Lens highlights
    p.stroke(200, 40, 95, 40);
    p.strokeWeight(1);
    p.arc(200, lensY - 5, 100, 30, 0, p.PI);
  }

  function drawLightRays() {
    p.strokeWeight(1);
    for (let i = 0; i < 8; i++) {
      let x = p.map(i, 0, 7, 60, 340);
      let alpha = p.map(p.sin(time + i), -1, 1, 10, 30);

      // Rays before lens - parallel and diffuse
      p.stroke(220, 40, 80, alpha);
      p.line(x, 50, x + p.sin(time + i) * 5, lensY - 20);

      // Rays after lens - converging
      let convergenceX = 200 + (x - 200) * 0.3;
      p.stroke(260, 60, 70, alpha * 1.5);
      p.line(x + p.sin(time + i) * 5, lensY + 20, convergenceX, lensY + 180);
    }
  }

  function updateParticle(particle) {
    // Determine if particle should be concrete based on position
    let shouldBeConcrete = particle.y > lensY + 50;

    if (shouldBeConcrete && !particle.concrete) {
      particle.concrete = true;
      particle.concreteTime = time;
    } else if (!shouldBeConcrete) {
      particle.concrete = false;
    }

    // Movement toward targets
    particle.x = p.lerp(particle.x, particle.targetX, particle.speed);
    particle.y = p.lerp(particle.y, particle.targetY, particle.speed);
    particle.size = p.lerp(particle.size, particle.targetSize, particle.speed);

    // Abstract floating motion at top
    if (!particle.concrete) {
      particle.x += p.sin(time + particle.phase) * 0.5;
      particle.y += p.cos(time * 0.7 + particle.phase) * 0.3;
    }

    // Reset particles that go too far down
    if (particle.y > p.height + 50) {
      particle.x = particle.originalX;
      particle.y = particle.originalY;
      particle.concrete = false;
    }
  }

  function drawParticle(particle) {
    p.push();
    p.translate(particle.x, particle.y);

    if (particle.concrete) {
      // Concrete form - geometric and precise
      let concreteness = p.min((time - particle.concreteTime) * 3, 1);
      p.fill(particle.hue + 40, 80, particle.brightness, particle.alpha * 1.2);
      p.stroke(particle.hue + 60, 90, 90, 60);
      p.strokeWeight(0.5);

      p.rotate(time + particle.phase);
      p.rect(0, 0, particle.size * concreteness, particle.size * concreteness);

      // Sharp crystalline details
      if (concreteness > 0.5) {
        p.noFill();
        p.stroke(particle.hue + 80, 70, 95, 40);
        p.line(-particle.size/2, 0, particle.size/2, 0);
        p.line(0, -particle.size/2, 0, particle.size/2);
      }
    } else {
      // Abstract form - soft and nebulous
      p.noStroke();
      p.fill(particle.hue, 50, particle.brightness, particle.alpha * 0.7);

      // Soft, cloud-like appearance
      for (let i = 0; i < 3; i++) {
        let offset = i * 2;
        let sizeVar = particle.size + p.sin(time + particle.phase + i) * 2;
        p.circle(p.sin(i + time) * offset, p.cos(i + time) * offset, sizeVar);
      }
    }
    p.pop();
  }

  function drawProjectionLines() {
    p.strokeWeight(0.5);
    p.stroke(240, 30, 70, 20);

    for (let i = 0; i < particles.length; i += 8) {
      let particle = particles[i];
      if (particle.concrete) {
        p.line(particle.originalX, particle.originalY, 
               particle.x, particle.y);
      }
    }
  }

  p.mousePressed = function() {
    // Clicking creates a burst of new projection
    for (let particle of particles) {
      particle.x = particle.originalX + p.random(-20, 20);
      particle.y = particle.originalY + p.random(-10, 10);
      particle.concrete = false;
      particle.phase = p.random(0, p.TWO_PI);
    }
  };
}

function sketch(p) {
  let grid;
  let cellSize = 8;
  let cols, rows;
  let gliders = [];
  let time = 0;
  let fadeTrails = [];
  let colors;

  p.setup = function() {
    p.createCanvas(400, 600);
    cols = Math.floor(p.width / cellSize);
    rows = Math.floor(p.height / cellSize);

    colors = {
      bg: p.color(8, 15, 26),
      alive: p.color(255, 215, 100),
      trail: p.color(120, 180, 255, 150),
      glow: p.color(255, 235, 160, 80)
    };

    // Initialize multiple gliders at different positions and phases
    gliders = [
      { x: 5, y: 10, phase: 0, dx: 1, dy: 1 },
      { x: 25, y: 30, phase: 1, dx: 1, dy: 1 },
      { x: 15, y: 50, phase: 2, dx: -1, dy: 1 },
      { x: 35, y: 20, phase: 3, dx: 1, dy: -1 }
    ];

    fadeTrails = [];
  };

  p.draw = function() {
    p.background(colors.bg);
    time += 0.02;

    // Draw fading trails
    for (let i = fadeTrails.length - 1; i >= 0; i--) {
      let trail = fadeTrails[i];
      trail.life -= 0.015;

      if (trail.life <= 0) {
        fadeTrails.splice(i, 1);
        continue;
      }

      let alpha = trail.life * 255;
      p.fill(p.red(colors.trail), p.green(colors.trail), p.blue(colors.trail), alpha);
      p.noStroke();

      let size = cellSize * (0.5 + 0.3 * trail.life);
      p.ellipse(trail.x * cellSize + cellSize/2, trail.y * cellSize + cellSize/2, size, size);
    }

    // Update and draw gliders
    gliders.forEach((glider, index) => {
      updateGlider(glider, index);
      drawGlider(glider, index);
    });

    // Add sparkle effect on mouse interaction
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      drawSparkles();
    }
  };

  function updateGlider(glider, index) {
    // Move glider every 15 frames
    if (p.frameCount % 15 === index * 4) {
      // Add current position to trail
      let pattern = getGliderPattern(glider.phase);
      pattern.forEach(cell => {
        fadeTrails.push({
          x: glider.x + cell.x,
          y: glider.y + cell.y,
          life: 1.0
        });
      });

      // Update position
      glider.x += glider.dx;
      glider.y += glider.dy;
      glider.phase = (glider.phase + 1) % 4;

      // Wrap around screen
      if (glider.x < -3) glider.x = cols + 2;
      if (glider.x > cols + 2) glider.x = -3;
      if (glider.y < -3) glider.y = rows + 2;
      if (glider.y > rows + 2) glider.y = -3;
    }
  }

  function drawGlider(glider, index) {
    let pattern = getGliderPattern(glider.phase);
    let phaseOffset = index * p.PI / 2;

    pattern.forEach(cell => {
      let x = glider.x + cell.x;
      let y = glider.y + cell.y;

      if (x >= 0 && x < cols && y >= 0 && y < rows) {
        let screenX = x * cellSize;
        let screenY = y * cellSize;

        // Glow effect
        p.fill(colors.glow);
        p.noStroke();
        let glowSize = cellSize * (1.5 + 0.3 * p.sin(time * 3 + phaseOffset));
        p.ellipse(screenX + cellSize/2, screenY + cellSize/2, glowSize, glowSize);

        // Main cell
        p.fill(colors.alive);
        let pulseSize = cellSize * (0.8 + 0.2 * p.sin(time * 2 + phaseOffset));
        p.ellipse(screenX + cellSize/2, screenY + cellSize/2, pulseSize, pulseSize);
      }
    });
  }

  function getGliderPattern(phase) {
    // Classic Conway's Game of Life glider patterns
    const patterns = [
      [{x: 1, y: 0}, {x: 2, y: 1}, {x: 0, y: 2}, {x: 1, y: 2}, {x: 2, y: 2}],
      [{x: 0, y: 1}, {x: 2, y: 0}, {x: 2, y: 1}, {x: 2, y: 2}, {x: 1, y: 2}],
      [{x: 1, y: 0}, {x: 2, y: 1}, {x: 2, y: 2}, {x: 1, y: 2}, {x: 0, y: 1}],
      [{x: 0, y: 0}, {x: 0, y: 1}, {x: 0, y: 2}, {x: 1, y: 0}, {x: 2, y: 1}]
    ];
    return patterns[phase];
  }

  function drawSparkles() {
    let mouseGridX = Math.floor(p.mouseX / cellSize);
    let mouseGridY = Math.floor(p.mouseY / cellSize);

    for (let i = 0; i < 3; i++) {
      let sparkleX = mouseGridX + p.random(-2, 2);
      let sparkleY = mouseGridY + p.random(-2, 2);

      if (sparkleX >= 0 && sparkleX < cols && sparkleY >= 0 && sparkleY < rows) {
        p.fill(255, 255, 255, 150 + 105 * p.sin(time * 8 + i));
        p.noStroke();
        let size = 3 + 2 * p.sin(time * 6 + i);
        p.ellipse(sparkleX * cellSize + cellSize/2, sparkleY * cellSize + cellSize/2, size, size);
      }
    }
  }

  p.mousePressed = function() {
    // Create a burst of trails at mouse position
    let mouseGridX = Math.floor(p.mouseX / cellSize);
    let mouseGridY = Math.floor(p.mouseY / cellSize);

    for (let i = 0; i < 8; i++) {
      fadeTrails.push({
        x: mouseGridX + p.random(-1, 1),
        y: mouseGridY + p.random(-1, 1),
        life: p.random(0.8, 1.2)
      });
    }
  };
}

function sketch(p) {
  let voices = [];
  let numVoices = 12;
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Create multiple voice streams with different characteristics
    for (let i = 0; i < numVoices; i++) {
      voices.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        hue: (i * 30 + p.random(-15, 15)) % 360,
        speed: p.random(0.01, 0.03),
        amplitude: p.random(20, 60),
        frequency: p.random(0.02, 0.08),
        phase: p.random(p.TWO_PI),
        nodes: [],
        opacity: p.random(0.6, 0.9)
      });

      // Initialize nodes for each voice
      for (let j = 0; j < 15; j++) {
        voices[i].nodes.push({
          offset: j * 25,
          size: p.random(3, 8)
        });
      }
    }
  };

  p.draw = function() {
    p.background(25, 15, 8);

    time += 0.01;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 2);

    // Draw connection web between voices
    p.stroke(45, 30, 85, 0.1);
    p.strokeWeight(0.5);
    for (let i = 0; i < voices.length; i++) {
      for (let j = i + 1; j < voices.length; j++) {
        let d = p.dist(voices[i].x, voices[i].y, voices[j].x, voices[j].y);
        if (d < 120) {
          let alpha = p.map(d, 0, 120, 0.15, 0.01);
          p.stroke(200, 20, 90, alpha);
          p.line(voices[i].x, voices[i].y, voices[j].x, voices[j].y);
        }
      }
    }

    // Draw each voice as a flowing stream
    for (let voice of voices) {
      let waveY = voice.y + p.sin(time * voice.speed + voice.phase) * voice.amplitude * mouseInfluence;

      // Draw the voice stream
      p.noFill();
      p.strokeWeight(2);
      p.stroke(voice.hue, 70, 85, voice.opacity * 0.8);

      p.beginShape();
      p.noFill();
      for (let i = 0; i < voice.nodes.length; i++) {
        let x = voice.x + voice.nodes[i].offset - 150;
        let y = waveY + p.sin(time * voice.frequency + i * 0.3) * 25;

        if (x > -50 && x < 450) {
          p.curveVertex(x, y);
        }
      }
      p.endShape();

      // Draw nodes along the voice
      for (let i = 0; i < voice.nodes.length; i++) {
        let x = voice.x + voice.nodes[i].offset - 150;
        let y = waveY + p.sin(time * voice.frequency + i * 0.3) * 25;

        if (x > 0 && x < 400 && y > 0 && y < 600) {
          let nodeSize = voice.nodes[i].size + p.sin(time * 2 + i) * 2;

          // Outer glow
          p.fill(voice.hue, 50, 95, 0.3);
          p.noStroke();
          p.ellipse(x, y, nodeSize * 2, nodeSize * 2);

          // Inner node
          p.fill(voice.hue, 80, 95, voice.opacity);
          p.ellipse(x, y, nodeSize, nodeSize);

          // Tiny highlight
          p.fill(voice.hue, 20, 100, 0.8);
          p.ellipse(x - nodeSize * 0.2, y - nodeSize * 0.2, nodeSize * 0.3, nodeSize * 0.3);
        }
      }

      // Update voice position with gentle drift
      voice.x += p.sin(time * voice.speed * 0.5) * 0.2;
      voice.y += p.cos(time * voice.speed * 0.3) * 0.1;

      // Keep voices roughly in bounds
      if (voice.x < 50) voice.x = 50;
      if (voice.x > 350) voice.x = 350;
      if (voice.y < 100) voice.y = 100;
      if (voice.y > 500) voice.y = 500;
    }

    // Draw harmonic resonance circles based on mouse interaction
    let resonanceStrength = p.map(p.mouseY, 0, p.height, 0, 1);
    for (let i = 0; i < 3; i++) {
      let radius = (time * 50 + i * 80) % 300;
      p.noFill();
      p.stroke(180 + i * 60, 40, 70, (1 - radius / 300) * resonanceStrength * 0.3);
      p.strokeWeight(1);
      p.ellipse(p.width / 2, p.height / 2, radius, radius);
    }

    // Add subtle interference patterns
    for (let i = 0; i < 5; i++) {
      let x = p.width / 2 + p.sin(time + i) * 100;
      let y = p.height / 2 + p.cos(time * 0.7 + i) * 80;

      p.fill(60 + i * 30, 30, 80, 0.1);
      p.noStroke();
      p.ellipse(x, y, 40 + p.sin(time * 3 + i) * 10, 40 + p.sin(time * 3 + i) * 10);
    }
  };

  p.mousePressed = function() {
    // Add a burst of new harmonic nodes
    for (let voice of voices) {
      voice.amplitude *= 1.5;
      voice.opacity = p.min(1, voice.opacity * 1.2);
    }
  };

  p.mouseReleased = function() {
    // Restore gentle motion
    for (let voice of voices) {
      voice.amplitude *= 0.8;
      voice.opacity *= 0.9;
    }
  };
}

function sketch(p) {
  let layers = [];
  let spirals = [];
  let time = 0;
  let mouseInfluence = 0;
  let recursionDepth = 0;
  let colors;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    colors = {
      bg: p.color(240, 20, 8),
      primary: p.color(280, 70, 85),
      secondary: p.color(320, 60, 75),
      accent: p.color(200, 80, 90),
      meta: p.color(60, 40, 95)
    };

    // Initialize recursive layers - each layer contains the same pattern at different scales
    for (let i = 0; i < 5; i++) {
      layers.push({
        scale: p.pow(0.7, i),
        rotation: i * p.PI / 7,
        offset: i * 0.3,
        depth: i,
        opacity: p.map(i, 0, 4, 80, 20)
      });
    }

    // Initialize spirals that reference themselves
    for (let i = 0; i < 3; i++) {
      spirals.push({
        x: p.width * (0.3 + i * 0.2),
        y: p.height * (0.4 + i * 0.15),
        phase: i * p.TWO_PI / 3,
        size: 40 + i * 20,
        direction: i % 2 === 0 ? 1 : -1
      });
    }
  };

  p.draw = function() {
    p.background(colors.bg);
    time += 0.02;

    // Mouse influence creates meta-awareness
    let targetInfluence = p.map(p.mouseX, 0, p.width, 0, 1);
    mouseInfluence = p.lerp(mouseInfluence, targetInfluence, 0.05);
    recursionDepth = p.floor(mouseInfluence * 8) + 3;

    p.push();
    p.translate(p.width/2, p.height/2);

    // Draw recursive mirror frames
    drawRecursiveFrames(0, 0, 300, recursionDepth);

    // Draw self-referential spirals
    for (let spiral of spirals) {
      drawSelfReferencingSpiral(spiral);
    }

    // Draw nested story layers
    for (let layer of layers) {
      p.push();
      p.scale(layer.scale);
      p.rotate(layer.rotation + time * 0.5);

      // Each layer draws the same pattern but references the others
      let layerAlpha = layer.opacity * (1 + 0.3 * p.sin(time + layer.offset));
      colors.primary.setAlpha(layerAlpha);

      drawStoryWithinStory(layer.depth, layerAlpha);
      p.pop();
    }

    // Meta-particle system that knows it's a particle system
    drawMetaParticles();

    p.pop();

    // Kojima signature: subtle glitch that acknowledges the medium
    if (p.random() < 0.02) {
      drawMetaGlitch();
    }
  };

  function drawRecursiveFrames(x, y, size, depth) {
    if (depth <= 0 || size < 10) return;

    let frameColor = p.lerpColor(colors.primary, colors.secondary, depth / recursionDepth);
    frameColor.setAlpha(60 - depth * 5);

    p.stroke(frameColor);
    p.strokeWeight(2);
    p.noFill();

    // Draw frame
    p.rectMode(p.CENTER);
    p.rect(x, y, size, size * 1.618);

    // Draw connection to next frame
    let nextSize = size * 0.618;
    let nextX = x + size * 0.1 * p.sin(time + depth);
    let nextY = y + size * 0.05 * p.cos(time * 1.3 + depth);

    p.line(x, y, nextX, nextY);

    // Recursive call - the frame contains itself
    drawRecursiveFrames(nextX, nextY, nextSize, depth - 1);
  }

  function drawSelfReferencingSpiral(spiral) {
    p.push();
    p.translate(spiral.x - p.width/2, spiral.y - p.height/2);

    let spiralColor = colors.accent;
    spiralColor.setAlpha(70);
    p.stroke(spiralColor);
    p.strokeWeight(1.5);
    p.noFill();

    p.beginShape();
    for (let angle = 0; angle < p.TWO_PI * 4; angle += 0.1) {
      let radius = (angle / (p.TWO_PI * 4)) * spiral.size;
      let x = p.cos(angle + time * spiral.direction + spiral.phase) * radius;
      let y = p.sin(angle + time * spiral.direction + spiral.phase) * radius;

      // Each point of the spiral references the spiral's own center
      let selfRef = p.map(p.sin(angle * 3 + time), -1, 1, 0.8, 1.2);
      x *= selfRef;
      y *= selfRef;

      p.vertex(x, y);
    }
    p.endShape();

    // Draw center dot that "knows" about the spiral
    p.fill(colors.meta);
    p.noStroke();
    p.circle(0, 0, 8 + 3 * p.sin(time * 2 + spiral.phase));

    p.pop();
  }

  function drawStoryWithinStory(depth, alpha) {
    let storyColor = colors.secondary;
    storyColor.setAlpha(alpha * 0.7);
    p.fill(storyColor);
    p.noStroke();

    // Draw nested narrative circles
    for (let i = 0; i < 5; i++) {
      let angle = (i / 5) * p.TWO_PI + time + depth * 0.5;
      let radius = 80 + 20 * p.sin(time * 1.5 + i);
      let x = p.cos(angle) * radius;
      let y = p.sin(angle) * radius;

      let size = 12 + 6 * p.sin(time * 2 + i + depth);

      // Each story element references the others
      let connectionStrength = p.map(p.sin(time + i), -1, 1, 0.3, 1);
      storyColor.setAlpha(alpha * connectionStrength);
      p.fill(storyColor);

      p.circle(x, y, size);

      // Draw connections to other story elements
      if (i < 4) {
        let nextAngle = ((i + 1) / 5) * p.TWO_PI + time + depth * 0.5;
        let nextRadius = 80 + 20 * p.sin(time * 1.5 + i + 1);
        let nextX = p.cos(nextAngle) * nextRadius;
        let nextY = p.sin(nextAngle) * nextRadius;

        p.stroke(storyColor);
        p.strokeWeight(1);
        p.line(x, y, nextX, nextY);
      }
    }
  }

  function drawMetaParticles() {
    // Particles that comment on their own existence
    for (let i = 0; i < 12; i++) {
      let angle = (i / 12) * p.TWO_PI + time * 0.3;
      let radius = 150 + 30 * p.sin(time * 2 + i);
      let x = p.cos(angle) * radius;
      let y = p.sin(angle) * radius;

      // Each particle "knows" it's part of a system
      let awareness = p.map(p.sin(time * 3 + i), -1, 1, 0.2, 1);
      let particleColor = p.lerpColor(colors.accent, colors.meta, awareness);
      particleColor.setAlpha(60 * awareness);

      p.fill(particleColor);
      p.noStroke();

      let size = 6 + 4 * awareness;
      p.circle(x, y, size);

      // Draw "consciousness" rings around self-aware particles
      if (awareness > 0.7) {
        p.noFill();
        p.stroke(particleColor);
        p.strokeWeight(1);
        p.circle(x, y, size * 2 + 5 * p.sin(time * 4 + i));
      }
    }
  }

  function drawMetaGlitch() {
    // Subtle acknowledgment that this is a digital medium
    p.push();
    p.blendMode(p.DIFFERENCE);
    p.fill(colors.meta);
    p.noStroke();

    for (let i = 0; i < 3; i++) {
      let x = p.random(p.width);
      let y = p.random(p.height);
      let w = p.random(20, 60);
      let h = p.random(2, 8);
      p.rect(x, y, w, h);
    }
    p.pop();
  }

  p.mousePressed = function() {
    // Click reveals another layer of recursion
    recursionDepth = (recursionDepth + 2) % 10 + 3;

    // Add a new self-aware spiral
    if (spirals.length < 6) {
      spirals.push({
        x: p.mouseX,
        y: p.mouseY,
        phase: p.random(p.TWO_PI),
        size: p.random(30, 60),
        direction: p.random() > 0.5 ? 1 : -1
      });
    }
  };
}

function sketch(p) {
  let particles = [];
  let flows = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize flowing particles
    for (let i = 0; i < 150; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(2, 8),
        hue: p.random(180, 300),
        life: p.random(100),
        maxLife: p.random(50, 150)
      });
    }

    // Initialize flow fields
    for (let i = 0; i < 8; i++) {
      flows.push({
        x: p.random(p.width),
        y: p.random(p.height),
        angle: p.random(p.TWO_PI),
        speed: p.random(0.5, 2),
        radius: p.random(80, 150)
      });
    }
  };

  p.draw = function() {
    // Create flowing background gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c1 = p.color(220 + p.sin(time * 0.01) * 20, 30, 15);
      let c2 = p.color(280 + p.cos(time * 0.008) * 30, 60, 25);
      let gradientColor = p.lerpColor(c1, c2, inter);
      p.stroke(gradientColor);
      p.line(0, y, p.width, y);
    }

    time++;

    // Update and draw flow fields
    for (let flow of flows) {
      flow.angle += p.random(-0.1, 0.1);
      flow.x += p.cos(flow.angle) * flow.speed;
      flow.y += p.sin(flow.angle) * flow.speed;

      // Wrap around edges
      if (flow.x < 0) flow.x = p.width;
      if (flow.x > p.width) flow.x = 0;
      if (flow.y < 0) flow.y = p.height;
      if (flow.y > p.height) flow.y = 0;

      // Draw flowing energy field
      p.push();
      p.translate(flow.x, flow.y);
      p.noFill();
      for (let r = 10; r < flow.radius; r += 15) {
        let alpha = p.map(r, 10, flow.radius, 40, 5);
        p.stroke(260 + p.sin(time * 0.02 + r * 0.1) * 40, 70, 80, alpha);
        p.strokeWeight(2);

        p.beginShape();
        p.noFill();
        for (let a = 0; a < p.TWO_PI; a += 0.2) {
          let x = p.cos(a + time * 0.01) * (r + p.sin(a * 3 + time * 0.03) * 8);
          let y = p.sin(a + time * 0.01) * (r + p.cos(a * 2 + time * 0.04) * 6);
          p.curveVertex(x, y);
        }
        p.endShape(p.CLOSE);
      }
      p.pop();
    }

    // Update and draw metabolic particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Find nearest flow field influence
      let minDist = Infinity;
      let nearestFlow = flows[0];
      for (let flow of flows) {
        let d = p.dist(particle.x, particle.y, flow.x, flow.y);
        if (d < minDist) {
          minDist = d;
          nearestFlow = flow;
        }
      }

      // Apply flow field influence
      let influence = p.map(minDist, 0, 200, 1, 0);
      influence = p.constrain(influence, 0, 1);

      let flowForceX = p.cos(nearestFlow.angle) * influence * 0.3;
      let flowForceY = p.sin(nearestFlow.angle) * influence * 0.3;

      particle.vx += flowForceX + p.random(-0.05, 0.05);
      particle.vy += flowForceY + p.random(-0.05, 0.05);

      // Add mouse influence
      let mouseInfluence = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if (mouseInfluence < 100) {
        let mouseFactor = p.map(mouseInfluence, 0, 100, 0.2, 0);
        particle.vx += (p.mouseX - particle.x) * mouseFactor * 0.01;
        particle.vy += (p.mouseY - particle.y) * mouseFactor * 0.01;
      }

      // Damping
      particle.vx *= 0.98;
      particle.vy *= 0.98;

      // Update position
      particle.x += particle.vx;
      particle.y += particle.vy;

      // Wrap around edges with transformation
      if (particle.x < 0) {
        particle.x = p.width;
        particle.hue = (particle.hue + 30) % 360;
      }
      if (particle.x > p.width) {
        particle.x = 0;
        particle.hue = (particle.hue + 30) % 360;
      }
      if (particle.y < 0) {
        particle.y = p.height;
        particle.hue = (particle.hue + 30) % 360;
      }
      if (particle.y > p.height) {
        particle.y = 0;
        particle.hue = (particle.hue + 30) % 360;
      }

      // Metabolic transformation
      particle.life += 1;
      particle.size += p.sin(particle.life * 0.1) * 0.1;
      particle.hue += 0.5;

      // Draw particle with trailing effect
      let lifeRatio = particle.life / particle.maxLife;
      let alpha = p.map(lifeRatio, 0, 1, 80, 10);

      p.fill(particle.hue % 360, 80, 90, alpha);
      p.noStroke();

      // Draw particle as morphing blob
      p.push();
      p.translate(particle.x, particle.y);
      p.beginShape();
      for (let a = 0; a < p.TWO_PI; a += 0.5) {
        let r = particle.size + p.sin(a * 3 + particle.life * 0.05) * 2;
        let x = p.cos(a) * r;
        let y = p.sin(a) * r;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();

      // Create trail effect
      p.fill(particle.hue % 360, 60, 70, alpha * 0.3);
      p.ellipse(particle.x - particle.vx * 3, particle.y - particle.vy * 3, particle.size * 0.5);

      // Regenerate particle when life expires
      if (particle.life > particle.maxLife) {
        particle.life = 0;
        particle.x = p.random(p.width);
        particle.y = p.random(p.height);
        particle.hue = p.random(180, 300);
        particle.maxLife = p.random(50, 150);
        particle.size = p.random(2, 8);
      }
    }

    // Draw connecting metabolic bonds
    p.stroke(240, 40, 60, 20);
    p.strokeWeight(1);
    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        let d = p.dist(particles[i].x, particles[i].y, particles[j].x, particles[j].y);
        if (d < 80) {
          let alpha = p.map(d, 0, 80, 25, 0);
          p.stroke(240, 40, 60, alpha);
          p.line(particles[i].x, particles[i].y, particles[j].x, particles[j].y);
        }
      }
    }
  };
}

function sketch(p) {
  let jewels = [];
  let connections = [];
  let sparkles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Create jewels in a grid-like network
    for (let i = 0; i < 8; i++) {
      for (let j = 0; j < 12; j++) {
        let x = 80 + (i * 35) + p.random(-10, 10);
        let y = 80 + (j * 40) + p.random(-10, 10);
        jewels.push({
          x: x,
          y: y,
          baseX: x,
          baseY: y,
          size: p.random(8, 16),
          hue: p.random(200, 280),
          brightness: p.random(70, 90),
          phase: p.random(p.TWO_PI),
          reflections: []
        });
      }
    }

    // Create connections between nearby jewels
    for (let i = 0; i < jewels.length; i++) {
      for (let j = i + 1; j < jewels.length; j++) {
        let d = p.dist(jewels[i].baseX, jewels[i].baseY, jewels[j].baseX, jewels[j].baseY);
        if (d < 60 && p.random() < 0.3) {
          connections.push({
            from: i,
            to: j,
            strength: 1 - (d / 60),
            phase: p.random(p.TWO_PI)
          });
        }
      }
    }

    // Initialize sparkles
    for (let i = 0; i < 30; i++) {
      sparkles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        life: p.random(1),
        maxLife: p.random(60, 120)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, p.width + p.height, 0.5, 2);

    // Deep space background
    p.background(240, 80, 8);

    // Create subtle flowing background
    for (let i = 0; i < p.width; i += 20) {
      for (let j = 0; j < p.height; j += 20) {
        let wave = p.sin(i * 0.01 + time) * p.cos(j * 0.01 + time * 0.7);
        let alpha = p.map(wave, -1, 1, 0, 0.1);
        p.fill(260, 60, 20, alpha);
        p.noStroke();
        p.ellipse(i, j, 10);
      }
    }

    // Update and draw sparkles (representing infinite reflections)
    for (let i = sparkles.length - 1; i >= 0; i--) {
      let sparkle = sparkles[i];
      sparkle.life--;

      if (sparkle.life <= 0) {
        sparkle.x = p.random(p.width);
        sparkle.y = p.random(p.height);
        sparkle.life = sparkle.maxLife;
      }

      let alpha = p.map(sparkle.life, 0, sparkle.maxLife, 0, 0.8);
      let size = p.map(sparkle.life, 0, sparkle.maxLife, 1, 4);

      p.fill(45, 80, 95, alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, size);
    }

    // Draw connections first (the web/net)
    for (let conn of connections) {
      let jewel1 = jewels[conn.from];
      let jewel2 = jewels[conn.to];

      let pulse = p.sin(time * 3 + conn.phase) * 0.5 + 0.5;
      let alpha = conn.strength * pulse * 0.4 * mouseInfluence;

      p.stroke(220, 70, 80, alpha);
      p.strokeWeight(1 + pulse);
      p.line(jewel1.x, jewel1.y, jewel2.x, jewel2.y);

      // Add flowing energy along connections
      let midX = (jewel1.x + jewel2.x) / 2;
      let midY = (jewel1.y + jewel2.y) / 2;
      let offset = p.sin(time * 4 + conn.phase) * 10;

      p.fill(180, 90, 90, alpha * 2);
      p.noStroke();
      p.ellipse(midX + offset, midY, 3);
    }

    // Update and draw jewels
    for (let i = 0; i < jewels.length; i++) {
      let jewel = jewels[i];

      // Gentle floating motion
      jewel.x = jewel.baseX + p.sin(time + jewel.phase) * 3;
      jewel.y = jewel.baseY + p.cos(time * 0.7 + jewel.phase) * 2;

      // Mouse interaction - jewels respond to proximity
      let mouseDistance = p.dist(p.mouseX, p.mouseY, jewel.x, jewel.y);
      if (mouseDistance < 80) {
        let influence = p.map(mouseDistance, 0, 80, 20, 0);
        let angle = p.atan2(jewel.y - p.mouseY, jewel.x - p.mouseX);
        jewel.x += p.cos(angle) * influence * 0.1;
        jewel.y += p.sin(angle) * influence * 0.1;
      }

      // Draw jewel with inner reflection
      let size = jewel.size * (1 + p.sin(time * 2 + jewel.phase) * 0.1);

      // Outer glow
      p.fill(jewel.hue, 60, 70, 0.3);
      p.noStroke();
      p.ellipse(jewel.x, jewel.y, size * 2);

      // Main jewel body
      p.fill(jewel.hue, 80, jewel.brightness);
      p.stroke(jewel.hue, 40, 95);
      p.strokeWeight(1);
      p.ellipse(jewel.x, jewel.y, size);

      // Inner reflection/facet
      p.fill(jewel.hue + 30, 30, 95, 0.7);
      p.noStroke();
      p.ellipse(jewel.x - size * 0.2, jewel.y - size * 0.2, size * 0.4);

      // Tiny highlight
      p.fill(0, 0, 100, 0.9);
      p.ellipse(jewel.x - size * 0.15, jewel.y - size * 0.15, 2);

      // Draw reflection lines to nearby jewels when mouse is near
      if (mouseDistance < 60) {
        for (let j = 0; j < jewels.length; j++) {
          if (i !== j) {
            let other = jewels[j];
            let d = p.dist(jewel.x, jewel.y, other.x, other.y);
            if (d < 100) {
              let alpha = p.map(d, 0, 100, 0.4, 0) * p.map(mouseDistance, 0, 60, 1, 0);
              p.stroke(jewel.hue, 40, 90, alpha);
              p.strokeWeight(0.5);
              p.line(jewel.x, jewel.y, other.x, other.y);
            }
          }
        }
      }
    }

    // Draw central nexus point that appears on mouse interaction
    let centerX = p.width / 2;
    let centerY = p.height / 2;
    let centerDistance = p.dist(p.mouseX, p.mouseY, centerX, centerY);

    if (centerDistance < 150) {
      let intensity = p.map(centerDistance, 0, 150, 1, 0);
      let pulseSize = 20 + p.sin(time * 5) * 10;

      p.fill(300, 70, 90, intensity * 0.3);
      p.noStroke();
      p.ellipse(centerX, centerY, pulseSize * 2);

      p.fill(300, 90, 95, intensity * 0.6);
      p.ellipse(centerX, centerY, pulseSize);

      // Radiating lines to show all-center nature
      for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 8) {
        let lineLength = intensity * 30;
        let x2 = centerX + p.cos(angle + time) * lineLength;
        let y2 = centerY + p.sin(angle + time) * lineLength;

        p.stroke(300, 60, 85, intensity * 0.5);
        p.strokeWeight(1);
        p.line(centerX, centerY, x2, y2);
      }
    }
  };

  p.mousePressed = function() {
    // Create ripple effect from mouse position
    for (let i = 0; i < 10; i++) {
      sparkles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        life: p.random(30, 60),
        maxLife: p.random(30, 60)
      });
    }
  };
}

function sketch(p) {
  let seed;
  let potentialThreads = [];
  let time = 0;
  let pulsePhase = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Central seed position
    seed = {
      x: 200,
      y: 300,
      baseSize: 12,
      currentSize: 12,
      energy: 0
    };

    // Initialize potential connection threads
    for (let i = 0; i < 36; i++) {
      potentialThreads.push({
        angle: (i * 10) * p.PI / 180,
        length: 0,
        maxLength: p.random(80, 200),
        opacity: 0,
        thickness: p.random(0.5, 2),
        growthRate: p.random(0.3, 0.8),
        dormant: true,
        electricalPulse: 0
      });
    }
  };

  p.draw = function() {
    // Soft background gradient from deep earth to subtle electric
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(25, 20, 15), p.color(35, 25, 20), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.02;
    pulsePhase += 0.08;

    // Mouse influence on seed energy
    let dist = p.dist(p.mouseX, p.mouseY, seed.x, seed.y);
    mouseInfluence = p.map(p.constrain(dist, 0, 150), 0, 150, 1, 0);
    seed.energy = p.lerp(seed.energy, mouseInfluence, 0.05);

    // Update seed size with gentle breathing
    let breathe = 1 + p.sin(pulsePhase) * 0.2;
    seed.currentSize = seed.baseSize * breathe * (1 + seed.energy * 0.5);

    // Wake up threads based on mouse proximity and time
    let activeThreads = p.floor(p.map(seed.energy, 0, 1, 2, 12));
    for (let i = 0; i < activeThreads; i++) {
      if (potentialThreads[i].dormant && p.random() < 0.02) {
        potentialThreads[i].dormant = false;
      }
    }

    // Draw potential connection threads
    p.push();
    p.translate(seed.x, seed.y);

    for (let thread of potentialThreads) {
      if (!thread.dormant) {
        // Grow thread length
        if (thread.length < thread.maxLength) {
          thread.length += thread.growthRate;
          thread.opacity = p.min(thread.opacity + 0.02, 0.6);
        }

        // Calculate electrical pulse
        thread.electricalPulse = p.sin(time * 3 + thread.angle * 2) * 0.3 + 0.7;

        // Draw the thread with organic curves
        p.push();
        p.rotate(thread.angle);

        let segments = 20;
        p.noFill();

        for (let i = 0; i < segments - 1; i++) {
          let progress = i / segments;
          let nextProgress = (i + 1) / segments;

          if (progress * thread.maxLength > thread.length) break;

          let x1 = progress * thread.length;
          let y1 = p.sin(progress * 8 + time * 2) * 3;
          let x2 = nextProgress * thread.length;
          let y2 = p.sin(nextProgress * 8 + time * 2) * 3;

          // Earth tone base with electric highlights
          let earthR = 101 + thread.electricalPulse * 30;
          let earthG = 67 + thread.electricalPulse * 20;
          let earthB = 33 + thread.electricalPulse * 10;

          // Add electric blue-green traces
          if (thread.electricalPulse > 0.8) {
            earthR += 20;
            earthG += 40;
            earthB += 35;
          }

          let alpha = thread.opacity * (1 - progress * 0.5) * 255;
          p.stroke(earthR, earthG, earthB, alpha);
          p.strokeWeight(thread.thickness * (1 - progress * 0.3));

          p.line(x1, y1, x2, y2);
        }

        p.pop();
      }
    }

    p.pop();

    // Draw the central seed with layered complexity
    p.push();
    p.translate(seed.x, seed.y);

    // Inner glow
    for (let r = seed.currentSize * 3; r > 0; r -= 2) {
      let alpha = p.map(r, 0, seed.currentSize * 3, 150, 0) * seed.energy;
      p.fill(120, 180, 140, alpha * 0.3);
      p.noStroke();
      p.ellipse(0, 0, r, r);
    }

    // Seed core with electrical activity
    let coreR = 89 + p.sin(time * 4) * 20 + seed.energy * 30;
    let coreG = 67 + p.sin(time * 4 + 1) * 15 + seed.energy * 40;
    let coreB = 33 + p.sin(time * 4 + 2) * 10 + seed.energy * 20;

    p.fill(coreR, coreG, coreB);
    p.noStroke();
    p.ellipse(0, 0, seed.currentSize, seed.currentSize);

    // Electrical spark in center
    if (seed.energy > 0.3) {
      p.fill(160, 220, 180, (seed.energy - 0.3) * 255);
      let sparkSize = seed.currentSize * 0.3 * p.sin(time * 8);
      p.ellipse(0, 0, sparkSize, sparkSize);
    }

    // Subtle surface texture
    for (let i = 0; i < 8; i++) {
      let angle = (i * 45) * p.PI / 180;
      let x = p.cos(angle) * seed.currentSize * 0.3;
      let y = p.sin(angle) * seed.currentSize * 0.3;
      p.fill(coreR + 20, coreG + 10, coreB + 5, 100);
      p.ellipse(x, y, 2, 2);
    }

    p.pop();

    // Ambient particles suggesting dormant potential
    p.fill(101, 67, 33, 40);
    p.noStroke();
    for (let i = 0; i < 15; i++) {
      let x = 50 + (i * 23) % (p.width - 100);
      let y = 50 + p.sin(time + i) * 20 + (i * 37) % (p.height - 100);
      let size = 1 + p.sin(time * 2 + i) * 0.5;
      p.ellipse(x, y, size, size);
    }
  };

  p.mousePressed = function() {
    // Reset some dormant threads on click
    for (let i = 0; i < 6; i++) {
      if (p.random() < 0.5) {
        potentialThreads[p.floor(p.random(potentialThreads.length))].dormant = true;
        potentialThreads[p.floor(p.random(potentialThreads.length))].length = 0;
        potentialThreads[p.floor(p.random(potentialThreads.length))].opacity = 0;
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let splitPoint;
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the initial shared root system
    splitPoint = p.createVector(200, 450);

    // Initialize the network with organic branching
    initializeNetwork();
  };

  function initializeNetwork() {
    nodes = [];
    connections = [];

    // Create root node at split point
    nodes.push({
      pos: splitPoint.copy(),
      type: 'root',
      connections: [],
      energy: 1.0,
      pulsePhase: 0
    });

    // Generate two distinct rhizomatic patterns
    generateRhizome('left', -1, p.color(139, 90, 43, 180));  // Warm brown
    generateRhizome('right', 1, p.color(85, 107, 47, 180));  // Olive green
  }

  function generateRhizome(side, direction, col) {
    let startAngle = side === 'left' ? p.PI * 0.7 : p.PI * 0.3;
    let branchCount = p.random(15, 25);

    for (let i = 0; i < branchCount; i++) {
      let angle = startAngle + p.random(-0.8, 0.8);
      let distance = p.random(80, 200);
      let depth = p.map(distance, 80, 200, 0.8, 0.3);

      let node = {
        pos: p.createVector(
          splitPoint.x + p.cos(angle) * distance + p.random(-30, 30),
          splitPoint.y - p.abs(p.sin(angle)) * distance + p.random(-20, 20)
        ),
        type: side,
        color: col,
        energy: p.random(0.3, 1.0),
        pulsePhase: p.random(0, p.TWO_PI),
        depth: depth,
        originalPos: null
      };

      // Store original position for mouse interaction
      node.originalPos = node.pos.copy();
      nodes.push(node);

      // Create organic connections within same type
      for (let j = 0; j < nodes.length - 1; j++) {
        let other = nodes[j];
        let dist = p5.Vector.dist(node.pos, other.pos);

        if (dist < 80 && (other.type === side || other.type === 'root')) {
          connections.push({
            from: node,
            to: other,
            strength: p.map(dist, 0, 80, 1, 0.2),
            type: side
          });
        }
      }
    }
  }

  p.draw = function() {
    // Rich earth background with subtle gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 35, 25), p.color(25, 20, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.02;
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseY, 0, p.height, 0, 1), 0.05);

    // Update node positions with organic movement and mouse interaction
    for (let node of nodes) {
      if (node.type !== 'root') {
        // Gentle organic drift
        let drift = p.createVector(
          p.noise(node.originalPos.x * 0.01, time) - 0.5,
          p.noise(node.originalPos.y * 0.01, time + 100) - 0.5
        );
        drift.mult(8);

        // Mouse influence creates gentle spreading
        if (p.mouseIsPressed) {
          let mouseForce = p5.Vector.sub(p.createVector(p.mouseX, p.mouseY), node.originalPos);
          mouseForce.mult(0.001);
          drift.add(mouseForce);
        }

        node.pos = p5.Vector.add(node.originalPos, drift);

        // Pulsing energy based on connection activity
        node.energy = 0.5 + 0.5 * p.sin(time * 2 + node.pulsePhase);
      }
    }

    // Draw underground soil texture
    p.noFill();
    for (let i = 0; i < 200; i++) {
      p.stroke(p.random(30, 60), p.random(25, 45), p.random(15, 35), 30);
      p.strokeWeight(p.random(1, 3));
      let x = p.random(p.width);
      let y = p.random(300, p.height);
      p.line(x, y, x + p.random(-20, 20), y + p.random(-10, 10));
    }

    // Draw connections with flowing energy
    for (let conn of connections) {
      let alpha = 120 + 60 * p.sin(time * 3 + conn.from.pulsePhase);

      if (conn.type === 'left') {
        p.stroke(139, 90, 43, alpha * conn.strength);
      } else {
        p.stroke(85, 107, 47, alpha * conn.strength);
      }

      p.strokeWeight(1 + conn.strength * 2);

      // Organic curved connections
      let mid = p5.Vector.lerp(conn.from.pos, conn.to.pos, 0.5);
      mid.add(p.random(-15, 15), p.random(-15, 15));

      p.noFill();
      p.beginShape();
      p.curveVertex(conn.from.pos.x, conn.from.pos.y);
      p.curveVertex(conn.from.pos.x, conn.from.pos.y);
      p.curveVertex(mid.x, mid.y);
      p.curveVertex(conn.to.pos.x, conn.to.pos.y);
      p.curveVertex(conn.to.pos.x, conn.to.pos.y);
      p.endShape();
    }

    // Draw nodes as organic growth points
    for (let node of nodes) {
      if (node.type === 'root') {
        // Central split point - glowing convergence
        p.fill(200, 150, 100, 200);
        p.noStroke();
        p.ellipse(node.pos.x, node.pos.y, 12 + 4 * p.sin(time * 4), 12 + 4 * p.sin(time * 4));

        // Radiating energy rings
        for (let r = 15; r < 40; r += 8) {
          p.noFill();
          p.stroke(200, 150, 100, 60 - r);
          p.strokeWeight(1);
          p.ellipse(node.pos.x, node.pos.y, r + 3 * p.sin(time * 2), r + 3 * p.sin(time * 2));
        }
      } else {
        // Network nodes with type-specific coloring
        let size = 3 + node.energy * 4;
        let brightness = 150 + node.energy * 50;

        if (node.type === 'left') {
          p.fill(139 + brightness * 0.3, 90 + brightness * 0.2, 43 + brightness * 0.1, 200);
        } else {
          p.fill(85 + brightness * 0.2, 107 + brightness * 0.3, 47 + brightness * 0.1, 200);
        }

        p.noStroke();
        p.ellipse(node.pos.x, node.pos.y, size, size);

        // Subtle halo effect
        p.fill(node.color.levels[0], node.color.levels[1], node.color.levels[2], 20);
        p.ellipse(node.pos.x, node.pos.y, size * 3, size * 3);
      }
    }

    // Electric traces showing different connection modes
    if (p.frameCount % 60 < 30) {
      drawEnergyPulse('left', p.color(255, 180, 100, 150));
    } else {
      drawEnergyPulse('right', p.color(150, 255, 120, 150));
    }
  };

  function drawEnergyPulse(type, col) {
    p.stroke(col);
    p.strokeWeight(1);
    p.noFill();

    for (let conn of connections) {
      if (conn.type === type) {
        let progress = (time * 2 + conn.from.pulsePhase) % p.TWO_PI;
        if (progress < p.PI) {
          let t = progress / p.PI;
          let pulsePos = p5.Vector.lerp(conn.from.pos, conn.to.pos, t);

          for (let r = 2; r < 8; r += 2) {
            p.stroke(col.levels[0], col.levels[1], col.levels[2], 100 - r * 10);
            p.ellipse(pulsePos.x, pulsePos.y, r, r);
          }
        }
      }
    }
  }

  p.mousePressed = function() {
    // Regenerate with slight variation on click
    if (p.random() < 0.3) {
      initializeNetwork();
    }
  };
}

function sketch(p) {
  let networks = [];
  let convergencePoint;
  let emergentParticles = [];
  let time = 0;
  let pulsePhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    convergencePoint = p.createVector(200, 300);

    // Create three rhizomatic networks from different directions
    networks.push(new Network(p.createVector(80, 150), p.color(25, 70, 40), 0));
    networks.push(new Network(p.createVector(320, 180), p.color(35, 80, 45), 120));
    networks.push(new Network(p.createVector(200, 450), p.color(45, 65, 50), 240));
  };

  p.draw = function() {
    p.background(20, 30, 15);
    time += 0.02;
    pulsePhase += 0.05;

    // Update mouse interaction
    let mouseInfluence = p.createVector(p.mouseX, p.mouseY);

    // Draw and update networks
    for(let network of networks) {
      network.update(mouseInfluence);
      network.display();
    }

    // Create emergent synthesis at convergence
    let synthesisPower = 0;
    for(let network of networks) {
      synthesisPower += network.getConvergenceStrength();
    }

    // Generate particles at synthesis point
    if(synthesisPower > 0.5 && p.random(100) < synthesisPower * 20) {
      emergentParticles.push(new EmergentParticle(convergencePoint.copy()));
    }

    // Draw synthesis glow
    p.push();
    p.translate(convergencePoint.x, convergencePoint.y);
    let glowSize = 30 + synthesisPower * 40 + p.sin(pulsePhase) * 10;

    // Multi-layered glow
    for(let i = 4; i > 0; i--) {
      p.fill(180, 80, 70, 20/i);
      p.noStroke();
      p.ellipse(0, 0, glowSize * i * 0.7);
    }

    // Central bright core
    p.fill(60, 90, 95, 80);
    p.ellipse(0, 0, glowSize * 0.3);
    p.pop();

    // Update and draw emergent particles
    for(let i = emergentParticles.length - 1; i >= 0; i--) {
      emergentParticles[i].update();
      emergentParticles[i].display();
      if(emergentParticles[i].isDead()) {
        emergentParticles.splice(i, 1);
      }
    }
  };

  class Network {
    constructor(origin, baseColor, angleOffset) {
      this.origin = origin;
      this.baseColor = baseColor;
      this.angleOffset = angleOffset;
      this.nodes = [];
      this.connections = [];
      this.generateNetwork();
    }

    generateNetwork() {
      // Create branching mycorrhizal structure
      this.nodes.push(new Node(this.origin.copy(), 0));

      for(let generation = 1; generation < 4; generation++) {
        let newNodes = [];
        for(let node of this.nodes) {
          if(node.generation === generation - 1) {
            let branchCount = p.random(2, 4);
            for(let i = 0; i < branchCount; i++) {
              let angle = this.angleOffset + p.random(-60, 60) + (i * 40);
              let distance = p.random(40, 80) * (1 - generation * 0.2);
              let newPos = p5.Vector.add(node.pos, 
                p5.Vector.fromAngle(p.radians(angle)).mult(distance));

              if(newPos.x > 0 && newPos.x < 400 && newPos.y > 0 && newPos.y < 600) {
                let newNode = new Node(newPos, generation);
                newNodes.push(newNode);
                this.connections.push([node, newNode]);
              }
            }
          }
        }
        this.nodes = this.nodes.concat(newNodes);
      }
    }

    update(mousePos) {
      for(let node of this.nodes) {
        node.update(mousePos);
      }
    }

    display() {
      // Draw connections first
      for(let connection of this.connections) {
        let [nodeA, nodeB] = connection;
        let dist = p5.Vector.dist(nodeA.pos, convergencePoint);
        let convergenceInfluence = p.map(dist, 0, 200, 1, 0.2);
        convergenceInfluence = p.constrain(convergenceInfluence, 0.2, 1);

        p.stroke(p.hue(this.baseColor), 
                p.saturation(this.baseColor) * convergenceInfluence, 
                p.brightness(this.baseColor) * convergenceInfluence, 
                60 * convergenceInfluence);
        p.strokeWeight(2 * convergenceInfluence);

        // Add flowing energy along connections
        let flowPos = p5.Vector.lerp(nodeA.pos, nodeB.pos, 
          (p.sin(time * 3 + nodeA.pos.x * 0.01) + 1) * 0.5);

        p.line(nodeA.pos.x, nodeA.pos.y, nodeB.pos.x, nodeB.pos.y);

        // Energy pulse
        p.fill(p.hue(this.baseColor), 90, 90, 80);
        p.noStroke();
        p.ellipse(flowPos.x, flowPos.y, 4);
      }

      // Draw nodes
      for(let node of this.nodes) {
        node.display(this.baseColor);
      }
    }

    getConvergenceStrength() {
      let strength = 0;
      for(let node of this.nodes) {
        let dist = p5.Vector.dist(node.pos, convergencePoint);
        if(dist < 100) {
          strength += p.map(dist, 0, 100, 1, 0);
        }
      }
      return p.constrain(strength * 0.1, 0, 1);
    }
  }

  class Node {
    constructor(pos, generation) {
      this.pos = pos;
      this.originalPos = pos.copy();
      this.generation = generation;
      this.oscillation = p.random(100);
    }

    update(mousePos) {
      // Gentle oscillation
      this.pos.x = this.originalPos.x + p.sin(time + this.oscillation) * 2;
      this.pos.y = this.originalPos.y + p.cos(time * 0.7 + this.oscillation) * 1.5;

      // Mouse attraction for interactivity
      let mouseForce = p5.Vector.sub(mousePos, this.pos);
      mouseForce.mult(0.001);
      this.pos.add(mouseForce);
    }

    display(baseColor) {
      let dist = p5.Vector.dist(this.pos, convergencePoint);
      let convergenceInfluence = p.map(dist, 0, 200, 1, 0.3);

      p.fill(p.hue(baseColor), 
             p.saturation(baseColor) * convergenceInfluence, 
             p.brightness(baseColor) * convergenceInfluence, 
             70);
      p.noStroke();

      let size = (4 - this.generation) * 3 * convergenceInfluence;
      p.ellipse(this.pos.x, this.pos.y, size);
    }
  }

  class EmergentParticle {
    constructor(pos) {
      this.pos = pos.copy();
      this.vel = p5.Vector.random2D().mult(p.random(1, 3));
      this.life = 100;
      this.maxLife = 100;
      this.size = p.random(3, 8);
      this.hue = p.random(150, 220);
    }

    update() {
      this.pos.add(this.vel);
      this.vel.mult(0.98);
      this.life--;

      // Spiral outward motion
      let angle = p.atan2(this.vel.y, this.vel.x) + 0.1;
      this.vel = p5.Vector.fromAngle(angle).mult(this.vel.mag());
    }

    display() {
      let alpha = p.map(this.life, 0, this.maxLife, 0, 100);
      p.fill(this.hue, 80, 90, alpha);
      p.noStroke();

      let currentSize = this.size * (this.life / this.maxLife);
      p.ellipse(this.pos.x, this.pos.y, currentSize);

      // Trailing glow
      p.fill(this.hue, 60, 70, alpha * 0.3);
      p.ellipse(this.pos.x, this.pos.y, currentSize * 2);
    }

    isDead() {
      return this.life <= 0;
    }
  }

  p.mousePressed = function() {
    // Create burst of emergent particles when clicked
    for(let i = 0; i < 8; i++) {
      let offset = p5.Vector.random2D().mult(p.random(20));
      emergentParticles.push(new EmergentParticle(
        p5.Vector.add(convergencePoint, offset)
      ));
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let pulseTime = 0;
  let myceliumPaths = [];
  let spores = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four foundational anchor nodes
    let anchors = [
      {x: 100, y: 150, size: 25, isAnchor: true},
      {x: 300, y: 150, size: 25, isAnchor: true},
      {x: 100, y: 450, size: 25, isAnchor: true},
      {x: 300, y: 450, size: 25, isAnchor: true}
    ];

    // Add anchor nodes
    for(let anchor of anchors) {
      nodes.push({
        x: anchor.x,
        y: anchor.y,
        baseX: anchor.x,
        baseY: anchor.y,
        size: anchor.size,
        isAnchor: true,
        energy: 1,
        pulse: p.random(p.TWO_PI)
      });
    }

    // Create network of smaller nodes between anchors
    for(let i = 0; i < 40; i++) {
      let x = p.random(80, 320);
      let y = p.random(120, 480);

      nodes.push({
        x: x,
        y: y,
        baseX: x,
        baseY: y,
        size: p.random(3, 8),
        isAnchor: false,
        energy: p.random(0.3, 0.8),
        pulse: p.random(p.TWO_PI),
        driftX: p.random(-0.5, 0.5),
        driftY: p.random(-0.5, 0.5)
      });
    }

    // Create organic connection paths
    generateMyceliumPaths();

    // Initialize floating spores
    for(let i = 0; i < 15; i++) {
      spores.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        vx: p.random(-0.3, 0.3),
        vy: p.random(-0.3, 0.3),
        size: p.random(1, 3),
        alpha: p.random(100, 200),
        pulse: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    p.background(42, 35, 28);
    pulseTime += 0.02;

    // Update node positions with subtle organic movement
    for(let node of nodes) {
      if(!node.isAnchor) {
        node.x = node.baseX + p.sin(pulseTime + node.pulse) * node.driftX * 3;
        node.y = node.baseY + p.cos(pulseTime + node.pulse * 1.3) * node.driftY * 3;
      }

      // Mouse interaction - nodes lean toward cursor
      let mouseForce = 20;
      let d = p.dist(node.x, node.y, p.mouseX, p.mouseY);
      if(d < 100) {
        let force = (100 - d) / 100 * 0.3;
        let angle = p.atan2(p.mouseY - node.y, p.mouseX - node.x);
        if(!node.isAnchor) {
          node.x += p.cos(angle) * force;
          node.y += p.sin(angle) * force;
        }
      }
    }

    // Draw mycelium network paths
    p.strokeWeight(1);
    for(let path of myceliumPaths) {
      let alpha = 60 + p.sin(pulseTime + path.pulse) * 40;
      p.stroke(139, 119, 78, alpha);

      p.noFill();
      p.beginShape();
      for(let point of path.points) {
        let wobble = p.sin(pulseTime * 2 + point.offset) * 2;
        p.vertex(point.x + wobble, point.y + p.cos(pulseTime + point.offset) * 1.5);
      }
      p.endShape();
    }

    // Draw connections between nearby nodes
    p.strokeWeight(0.5);
    for(let i = 0; i < nodes.length; i++) {
      for(let j = i + 1; j < nodes.length; j++) {
        let d = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if(d < 80) {
          let alpha = p.map(d, 0, 80, 120, 10);
          p.stroke(180, 150, 90, alpha);

          // Electric trace effect
          if(p.random() < 0.1) {
            p.stroke(255, 220, 120, alpha * 2);
            p.strokeWeight(1.5);
          } else {
            p.strokeWeight(0.5);
          }

          p.line(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        }
      }
    }

    // Draw nodes
    for(let node of nodes) {
      let pulseFactor = 1 + p.sin(pulseTime * 2 + node.pulse) * 0.2;
      let currentSize = node.size * pulseFactor;

      if(node.isAnchor) {
        // Anchor nodes - earthy foundation
        p.fill(139, 119, 78, 200);
        p.stroke(101, 87, 58);
        p.strokeWeight(2);
        p.ellipse(node.x, node.y, currentSize);

        // Inner glow
        p.fill(180, 160, 120, 100);
        p.noStroke();
        p.ellipse(node.x, node.y, currentSize * 0.6);

        // Roots extending from anchors
        p.stroke(101, 87, 58, 80);
        p.strokeWeight(1);
        for(let angle = 0; angle < p.TWO_PI; angle += p.PI/6) {
          let rootLength = 15 + p.sin(pulseTime + angle) * 5;
          let endX = node.x + p.cos(angle) * rootLength;
          let endY = node.y + p.sin(angle) * rootLength;
          p.line(node.x, node.y, endX, endY);
        }
      } else {
        // Network nodes - organic and flowing
        p.fill(160, 140, 100, 150);
        p.noStroke();
        p.ellipse(node.x, node.y, currentSize);

        // Occasional bright pulse
        if(p.sin(pulseTime * 3 + node.pulse) > 0.8) {
          p.fill(255, 220, 120, 200);
          p.ellipse(node.x, node.y, currentSize * 0.7);
        }
      }
    }

    // Draw and update floating spores
    for(let spore of spores) {
      spore.x += spore.vx;
      spore.y += spore.vy;

      // Gentle field effect from mouse
      let d = p.dist(spore.x, spore.y, p.mouseX, p.mouseY);
      if(d < 150) {
        let force = (150 - d) / 150 * 0.01;
        let angle = p.atan2(p.mouseY - spore.y, p.mouseX - spore.x);
        spore.vx += p.cos(angle) * force;
        spore.vy += p.sin(angle) * force;
      }

      // Boundary wrap
      if(spore.x < 0) spore.x = 400;
      if(spore.x > 400) spore.x = 0;
      if(spore.y < 0) spore.y = 600;
      if(spore.y > 600) spore.y = 0;

      // Velocity dampening
      spore.vx *= 0.99;
      spore.vy *= 0.99;

      // Draw spore
      let alpha = spore.alpha + p.sin(pulseTime * 4 + spore.pulse) * 50;
      p.fill(200, 180, 140, alpha);
      p.noStroke();
      p.ellipse(spore.x, spore.y, spore.size);
    }

    // Subtle ground texture
    p.stroke(101, 87, 58, 30);
    p.strokeWeight(0.5);
    for(let i = 0; i < 20; i++) {
      let x = p.random(400);
      let y = 550 + p.random(50);
      let length = p.random(10, 30);
      p.line(x, y, x + length, y + p.random(-5, 5));
    }
  };

  function generateMyceliumPaths() {
    // Create organic pathways connecting the network
    for(let i = 0; i < 8; i++) {
      let startNode = nodes[p.floor(p.random(nodes.length))];
      let path = {
        points: [],
        pulse: p.random(p.TWO_PI)
      };

      let currentX = startNode.x;
      let currentY = startNode.y;

      for(let j = 0; j < 20; j++) {
        path.points.push({
          x: currentX,
          y: currentY,
          offset: j * 0.3
        });

        // Organic growth toward other nodes
        let nearestNode = null;
        let minDist = Infinity;
        for(let node of nodes) {
          let d = p.dist(currentX, currentY, node.x, node.y);
          if(d < minDist && d > 10) {
            minDist = d;
            nearestNode = node;
          }
        }

        if(nearestNode) {
          let angle = p.atan2(nearestNode.y - currentY, nearestNode.x - currentX);
          angle += p.random(-0.8, 0.8); // Add organic wandering
          currentX += p.cos(angle) * p.random(8, 15);
          currentY += p.sin(angle) * p.random(8, 15);
        } else {
          currentX += p.random(-10, 10);
          currentY += p.random(-10, 10);
        }
      }

      myceliumPaths.push(path);
    }
  }

  p.mousePressed = function() {
    // Create ripple effect from anchors when clicked
    for(let node of nodes) {
      if(node.isAnchor) {
        let d = p.dist(p.mouseX, p.mouseY, node.x, node.y);
        if(d < 30) {
          // Pulse energy through network
          for(let otherNode of nodes) {
            let dist = p.dist(node.x, node.y, otherNode.x, otherNode.y);
            if(dist < 150) {
              otherNode.pulse = pulseTime;
            }
          }
        }
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let stressPoints = [];
  let particles = [];
  let time = 0;
  let crisisIntensity = 0.3;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create network nodes
    for (let i = 0; i < 80; i++) {
      nodes.push({
        x: p.random(50, 350),
        y: p.random(50, 550),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(2, 6),
        health: p.random(0.3, 1.0),
        connections: [],
        pulsePhase: p.random(p.TWO_PI),
        type: p.random() > 0.7 ? 'stressed' : 'normal'
      });
    }

    // Create connections between nearby nodes
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if (dist < 80 && p.random() > 0.6) {
          let connection = {
            from: i,
            to: j,
            strength: p.random(0.1, 1.0),
            breaking: p.random() > 0.8,
            forming: p.random() > 0.9
          };
          connections.push(connection);
          nodes[i].connections.push(j);
          nodes[j].connections.push(i);
        }
      }
    }

    // Create stress points
    for (let i = 0; i < 5; i++) {
      stressPoints.push({
        x: p.random(100, 300),
        y: p.random(100, 500),
        radius: p.random(30, 60),
        intensity: p.random(0.5, 1.0),
        pulseSpeed: p.random(0.02, 0.05)
      });
    }
  };

  p.draw = function() {
    p.background(15, 12, 8);
    time += 0.01;

    // Update crisis intensity based on mouse
    let mouseInfluence = p.map(p.mouseX, 0, 400, 0.1, 0.8);
    crisisIntensity = p.lerp(crisisIntensity, mouseInfluence, 0.02);

    // Draw stress fields
    p.push();
    p.blendMode(p.ADD);
    for (let stress of stressPoints) {
      let pulse = p.sin(time * stress.pulseSpeed * 50) * 0.3 + 0.7;
      let alpha = stress.intensity * pulse * crisisIntensity * 30;

      for (let r = stress.radius; r > 0; r -= 5) {
        p.fill(180, 60, 20, alpha * (r / stress.radius));
        p.noStroke();
        p.ellipse(stress.x, stress.y, r * 2);
      }
    }
    p.pop();

    // Update and draw connections
    for (let i = connections.length - 1; i >= 0; i--) {
      let conn = connections[i];
      let from = nodes[conn.from];
      let to = nodes[conn.to];

      if (!from || !to) continue;

      let dist = p.dist(from.x, from.y, to.x, to.y);
      let stress = 0;

      // Check stress from stress points
      for (let sp of stressPoints) {
        let midX = (from.x + to.x) / 2;
        let midY = (from.y + to.y) / 2;
        let stressDist = p.dist(midX, midY, sp.x, sp.y);
        if (stressDist < sp.radius) {
          stress += (1 - stressDist / sp.radius) * sp.intensity;
        }
      }

      stress *= crisisIntensity;

      // Connection breaking logic
      if (conn.breaking || stress > 0.6) {
        conn.strength -= 0.01 + stress * 0.02;
        if (conn.strength <= 0) {
          connections.splice(i, 1);
          continue;
        }
      } else if (conn.forming) {
        conn.strength = p.min(1.0, conn.strength + 0.005);
      }

      // Draw connection
      if (conn.strength > 0) {
        let alpha = conn.strength * 100 * (1 - stress * 0.5);
        let thickness = conn.strength * 2;

        if (stress > 0.3) {
          // Stressed connection - jagged and unstable
          p.stroke(220, 180 - stress * 100, 60, alpha);
          p.strokeWeight(thickness + p.sin(time * 20) * 0.5);

          let steps = 8;
          p.noFill();
          p.beginShape();
          for (let t = 0; t <= 1; t += 1/steps) {
            let x = p.lerp(from.x, to.x, t);
            let y = p.lerp(from.y, to.y, t);
            x += p.sin(t * 10 + time * 5) * stress * 5;
            y += p.cos(t * 10 + time * 5) * stress * 5;
            p.vertex(x, y);
          }
          p.endShape();
        } else {
          // Normal connection
          p.stroke(120, 180, 140, alpha);
          p.strokeWeight(thickness);
          p.line(from.x, from.y, to.x, to.y);
        }
      }
    }

    // Attempt to form new connections during crisis
    if (p.frameCount % 30 === 0 && crisisIntensity > 0.5) {
      for (let i = 0; i < 3; i++) {
        let nodeA = nodes[p.floor(p.random(nodes.length))];
        let nodeB = nodes[p.floor(p.random(nodes.length))];
        let dist = p.dist(nodeA.x, nodeA.y, nodeB.x, nodeB.y);

        if (dist < 100 && !nodeA.connections.includes(nodeB)) {
          connections.push({
            from: nodes.indexOf(nodeA),
            to: nodes.indexOf(nodeB),
            strength: 0.1,
            forming: true,
            breaking: false
          });
        }
      }
    }

    // Update and draw nodes
    for (let node of nodes) {
      // Update position with slight drift
      node.x += node.vx * (1 - crisisIntensity * 0.5);
      node.y += node.vy * (1 - crisisIntensity * 0.5);

      // Bounce off edges
      if (node.x < 20 || node.x > 380) node.vx *= -1;
      if (node.y < 20 || node.y > 580) node.vy *= -1;

      // Calculate local stress
      let localStress = 0;
      for (let sp of stressPoints) {
        let dist = p.dist(node.x, node.y, sp.x, sp.y);
        if (dist < sp.radius) {
          localStress += (1 - dist / sp.radius) * sp.intensity;
        }
      }
      localStress *= crisisIntensity;

      // Update health
      if (localStress > 0.4) {
        node.health -= 0.002;
      } else {
        node.health = p.min(1.0, node.health + 0.001);
      }

      // Draw node
      let pulse = p.sin(time * 3 + node.pulsePhase) * 0.2 + 0.8;
      let size = node.size * pulse * node.health;

      if (localStress > 0.3) {
        // Stressed node
        p.fill(240, 120 - localStress * 80, 40, 200);
        p.stroke(255, 200, 100, 100);
      } else {
        // Healthy node
        p.fill(80, 200 - localStress * 50, 120, 180);
        p.stroke(120, 255, 160, 80);
      }

      p.strokeWeight(1);
      p.ellipse(node.x, node.y, size);

      // Add energy particles around active nodes
      if (node.health > 0.7 && p.random() > 0.95) {
        particles.push({
          x: node.x + p.random(-5, 5),
          y: node.y + p.random(-5, 5),
          vx: p.random(-1, 1),
          vy: p.random(-1, 1),
          life: 60,
          maxLife: 60
        });
      }
    }

    // Update and draw particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life--;

      if (particle.life <= 0) {
        particles.splice(i, 1);
        continue;
      }

      let alpha = (particle.life / particle.maxLife) * 100;
      p.fill(150, 255, 180, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 2);
    }

    // Draw subtle background pattern
    p.push();
    p.stroke(40, 30, 20, 30);
    p.strokeWeight(0.5);
    for (let i = 0; i < 400; i += 20) {
      for (let j = 0; j < 600; j += 20) {
        let offset = p.sin(i * 0.02 + time) * p.cos(j * 0.02 + time) * 10;
        p.point(i + offset, j + offset);
      }
    }
    p.pop();
  };

  p.mousePressed = function() {
    // Add new stress point at mouse location
    stressPoints.push({
      x: p.mouseX,
      y: p.mouseY,
      radius: p.random(20, 50),
      intensity: p.random(0.6, 1.0),
      pulseSpeed: p.random(0.02, 0.05)
    });

    // Remove oldest stress point if too many
    if (stressPoints.length > 7) {
      stressPoints.shift();
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let bridges = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create six main hub nodes
    for(let i = 0; i < 6; i++) {
      let angle = (i / 6) * p.TWO_PI - p.PI/2;
      let radius = 120 + p.random(-20, 20);
      nodes.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius,
        size: p.random(15, 25),
        pulsePhase: p.random(p.TWO_PI),
        connections: [],
        energy: 0
      });
    }

    // Add smaller network nodes
    for(let i = 0; i < 15; i++) {
      nodes.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(5, 12),
        pulsePhase: p.random(p.TWO_PI),
        connections: [],
        energy: 0
      });
    }

    // Create rhizomatic connections
    for(let i = 0; i < nodes.length; i++) {
      for(let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if(dist < 120 && p.random() < 0.4) {
          connections.push({
            from: i,
            to: j,
            strength: p.random(0.3, 1),
            flowPhase: p.random(p.TWO_PI)
          });
          nodes[i].connections.push(j);
          nodes[j].connections.push(i);
        }
      }
    }

    // Identify the six strongest bridges (connections between hub nodes)
    for(let i = 0; i < 6; i++) {
      for(let j = i + 1; j < 6; j++) {
        let connectionExists = false;
        for(let conn of connections) {
          if((conn.from === i && conn.to === j) || (conn.from === j && conn.to === i)) {
            bridges.push({
              from: i,
              to: j,
              intensity: 0,
              particles: []
            });
            connectionExists = true;
            break;
          }
        }
        if(!connectionExists && bridges.length < 6) {
          connections.push({
            from: i,
            to: j,
            strength: 1,
            flowPhase: p.random(p.TWO_PI)
          });
          bridges.push({
            from: i,
            to: j,
            intensity: 0,
            particles: []
          });
        }
      }
    }

    // Keep only the first 6 bridges
    bridges = bridges.slice(0, 6);
  };

  p.draw = function() {
    time += 0.02;

    // Organic background gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(35, 40, 15), // dark earth
        p.color(45, 60, 8),  // deeper earth
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Update node energy based on mouse proximity
    for(let node of nodes) {
      let dist = p.dist(p.mouseX, p.mouseY, node.x, node.y);
      node.energy = p.map(dist, 0, 200, 1, 0.2);
      node.energy = p.constrain(node.energy, 0.2, 1);
    }

    // Draw underground root-like connections
    p.strokeWeight(1);
    for(let conn of connections) {
      let from = nodes[conn.from];
      let to = nodes[conn.to];

      let alpha = 20 + p.sin(time + conn.flowPhase) * 10;
      p.stroke(25, 80, 60, alpha);

      // Draw organic curved connection
      let midX = (from.x + to.x) / 2 + p.sin(time + conn.flowPhase) * 20;
      let midY = (from.y + to.y) / 2 + p.cos(time + conn.flowPhase) * 15;

      p.noFill();
      p.bezier(from.x, from.y, midX, midY, midX, midY, to.x, to.y);

      // Flow particles along connections
      if(p.random() < 0.02) {
        particles.push({
          x: from.x,
          y: from.y,
          targetX: to.x,
          targetY: to.y,
          progress: 0,
          life: 1,
          midX: midX,
          midY: midY
        });
      }
    }

    // Highlight the six bridges with enhanced visual flow
    for(let i = 0; i < bridges.length; i++) {
      let bridge = bridges[i];
      let from = nodes[bridge.from];
      let to = nodes[bridge.to];

      bridge.intensity = 0.5 + 0.5 * p.sin(time + i * p.PI/3);

      p.strokeWeight(3);
      let bridgeAlpha = 40 + bridge.intensity * 30;
      p.stroke(60, 90, 90, bridgeAlpha);

      // Enhanced bridge connection
      let midX = (from.x + to.x) / 2 + p.sin(time * 2 + i) * 25;
      let midY = (from.y + to.y) / 2 + p.cos(time * 2 + i) * 20;

      p.bezier(from.x, from.y, midX, midY, midX, midY, to.x, to.y);

      // Bridge-specific particles
      if(p.random() < 0.05) {
        particles.push({
          x: from.x,
          y: from.y,
          targetX: to.x,
          targetY: to.y,
          progress: 0,
          life: 1,
          midX: midX,
          midY: midY,
          isBridge: true
        });
      }
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.progress += 0.02;
      particle.life -= 0.015;

      if(particle.life <= 0 || particle.progress >= 1) {
        particles.splice(i, 1);
        continue;
      }

      // Bezier curve movement
      let t = particle.progress;
      let x = p.bezierPoint(particle.x, particle.midX, particle.midX, particle.targetX, t);
      let y = p.bezierPoint(particle.y, particle.midY, particle.midY, particle.targetY, t);

      let size = particle.isBridge ? 4 : 2;
      let hue = particle.isBridge ? 60 : 25;
      let brightness = particle.isBridge ? 95 : 80;

      p.fill(hue, 100, brightness, particle.life * 80);
      p.noStroke();
      p.ellipse(x, y, size * particle.life);
    }

    // Draw nodes as mycorrhizal hubs
    for(let i = 0; i < nodes.length; i++) {
      let node = nodes[i];
      let pulse = 1 + 0.3 * p.sin(time * 2 + node.pulsePhase) * node.energy;

      // Outer glow for main hubs
      if(i < 6) {
        p.fill(45, 70, 40, 30);
        p.noStroke();
        p.ellipse(node.x, node.y, node.size * pulse * 2.5);
      }

      // Main node
      p.fill(30, 90, 70 * node.energy);
      p.stroke(60, 100, 90, 60);
      p.strokeWeight(i < 6 ? 2 : 1);
      p.ellipse(node.x, node.y, node.size * pulse);

      // Central core
      p.fill(60, 80, 95 * node.energy);
      p.noStroke();
      p.ellipse(node.x, node.y, (node.size * pulse) * 0.4);
    }

    // Interactive response - clicking sends energy pulse through network
    if(p.mouseIsPressed) {
      // Find closest node to mouse
      let closestNode = 0;
      let minDist = p.dist(p.mouseX, p.mouseY, nodes[0].x, nodes[0].y);

      for(let i = 1; i < nodes.length; i++) {
        let dist = p.dist(p.mouseX, p.mouseY, nodes[i].x, nodes[i].y);
        if(dist < minDist) {
          minDist = dist;
          closestNode = i;
        }
      }

      // Send particles from closest node
      for(let connectedNode of nodes[closestNode].connections) {
        if(p.random() < 0.3) {
          particles.push({
            x: nodes[closestNode].x,
            y: nodes[closestNode].y,
            targetX: nodes[connectedNode].x,
            targetY: nodes[connectedNode].y,
            progress: 0,
            life: 1,
            midX: (nodes[closestNode].x + nodes[connectedNode].x) / 2,
            midY: (nodes[closestNode].y + nodes[connectedNode].y) / 2,
            isBridge: closestNode < 6 && connectedNode < 6
          });
        }
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let mirrors = [];
  let time = 0;
  let pulsePhase = 0;
  let selfAwarenessLevel = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create seven main network regions
    for (let i = 0; i < 7; i++) {
      let angle = (i / 7) * p.TWO_PI;
      let radius = 120 + p.sin(i * 0.7) * 30;
      let centerX = 200 + p.cos(angle) * radius;
      let centerY = 300 + p.sin(angle) * radius;

      // Each region contains a cluster of nodes
      let cluster = [];
      for (let j = 0; j < 12; j++) {
        let subAngle = (j / 12) * p.TWO_PI;
        let subRadius = 25 + p.sin(j * 0.5) * 15;
        cluster.push({
          x: centerX + p.cos(subAngle) * subRadius,
          y: centerY + p.sin(subAngle) * subRadius,
          baseX: centerX + p.cos(subAngle) * subRadius,
          baseY: centerY + p.sin(subAngle) * subRadius,
          phase: p.random(p.TWO_PI),
          pulse: 0,
          regionId: i,
          awareness: 0
        });
      }
      nodes.push(...cluster);

      // Create mirror representation of this cluster
      mirrors.push({
        centerX: centerX,
        centerY: centerY,
        scale: 0.3,
        opacity: 0,
        nodes: cluster.slice(),
        rotation: 0
      });
    }

    // Create rhizomatic connections
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if (dist < 80 || p.random() < 0.1) {
          connections.push({
            from: i,
            to: j,
            strength: p.map(dist, 0, 200, 1, 0.1),
            phase: p.random(p.TWO_PI),
            active: false
          });
        }
      }
    }
  };

  p.draw = function() {
    p.background(12, 8, 5);
    time += 0.02;
    pulsePhase += 0.05;

    // Calculate mouse influence for self-awareness
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 200;
    selfAwarenessLevel = p.lerp(selfAwarenessLevel, 1 - mouseInfluence, 0.05);

    // Update node positions and awareness
    for (let node of nodes) {
      node.pulse = p.sin(time * 2 + node.phase) * 0.5 + 0.5;
      node.awareness = selfAwarenessLevel * (0.5 + 0.5 * p.sin(time + node.phase));

      // Organic movement
      let drift = p.sin(time * 0.5 + node.phase) * 3;
      node.x = node.baseX + drift + p.sin(time + node.phase * 2) * 2;
      node.y = node.baseY + p.cos(time * 0.7 + node.phase) * 2;
    }

    // Update mirror regions
    for (let i = 0; i < mirrors.length; i++) {
      let mirror = mirrors[i];
      mirror.opacity = selfAwarenessLevel * 0.7;
      mirror.rotation += 0.005;
      mirror.scale = 0.2 + selfAwarenessLevel * 0.3;
    }

    // Draw connections with flowing energy
    p.strokeWeight(1);
    for (let conn of connections) {
      let fromNode = nodes[conn.from];
      let toNode = nodes[conn.to];

      conn.active = fromNode.awareness > 0.3 && toNode.awareness > 0.3;

      if (conn.active) {
        let flowPhase = time * 3 + conn.phase;
        let alpha = 120 + 100 * p.sin(flowPhase);

        // Main connection
        p.stroke(89, 67, 34, alpha);
        p.line(fromNode.x, fromNode.y, toNode.x, toNode.y);

        // Energy pulse
        let t = (p.sin(flowPhase) + 1) * 0.5;
        let pulseX = p.lerp(fromNode.x, toNode.x, t);
        let pulseY = p.lerp(fromNode.y, toNode.y, t);

        p.fill(144, 238, 144, alpha);
        p.noStroke();
        p.ellipse(pulseX, pulseY, 4);
      } else {
        p.stroke(45, 35, 20, 60);
        p.line(fromNode.x, fromNode.y, toNode.x, toNode.y);
      }
    }

    // Draw mirror regions (self-reflection)
    for (let mirror of mirrors) {
      if (mirror.opacity > 0.1) {
        p.push();
        p.translate(mirror.centerX, mirror.centerY);
        p.rotate(mirror.rotation);
        p.scale(mirror.scale);

        // Draw mirror network
        p.stroke(144, 238, 144, mirror.opacity * 100);
        p.strokeWeight(1);
        p.noFill();

        for (let i = 0; i < mirror.nodes.length; i++) {
          for (let j = i + 1; j < mirror.nodes.length; j++) {
            let node1 = mirror.nodes[i];
            let node2 = mirror.nodes[j];
            let dist = p.dist(node1.x - mirror.centerX, node1.y - mirror.centerY, 
                             node2.x - mirror.centerX, node2.y - mirror.centerY);
            if (dist < 40) {
              p.line(node1.x - mirror.centerX, node1.y - mirror.centerY,
                    node2.x - mirror.centerX, node2.y - mirror.centerY);
            }
          }
        }

        // Mirror nodes
        p.fill(144, 238, 144, mirror.opacity * 150);
        p.noStroke();
        for (let node of mirror.nodes) {
          p.ellipse(node.x - mirror.centerX, node.y - mirror.centerY, 3);
        }

        p.pop();
      }
    }

    // Draw main network nodes
    for (let node of nodes) {
      let size = 6 + node.pulse * 4 + node.awareness * 6;
      let glow = node.awareness * 80;

      // Awareness glow
      if (glow > 10) {
        p.fill(144, 238, 144, glow * 0.3);
        p.noStroke();
        p.ellipse(node.x, node.y, size * 2);
      }

      // Main node
      p.fill(139, 69, 19, 200 + node.pulse * 55);
      p.stroke(144, 238, 144, node.awareness * 200);
      p.strokeWeight(node.awareness * 2);
      p.ellipse(node.x, node.y, size);

      // Self-awareness indicator
      if (node.awareness > 0.7) {
        p.noFill();
        p.stroke(255, 215, 0, 150);
        p.strokeWeight(1);
        p.ellipse(node.x, node.y, size + 8 + p.sin(time * 4 + node.phase) * 3);
      }
    }

    // Draw recursive awareness waves
    if (selfAwarenessLevel > 0.5) {
      for (let i = 0; i < 7; i++) {
        let waveRadius = 50 + (time * 30 + i * 40) % 200;
        let alpha = p.map(waveRadius, 50, 250, 100, 0);

        p.noFill();
        p.stroke(255, 215, 0, alpha * selfAwarenessLevel);
        p.strokeWeight(1);
        p.ellipse(200, 300, waveRadius);
      }
    }
  };

  p.mousePressed = function() {
    // Trigger awareness pulse
    for (let node of nodes) {
      let dist = p.dist(p.mouseX, p.mouseY, node.x, node.y);
      if (dist < 100) {
        node.awareness = 1;
        node.phase = p.random(p.TWO_PI);
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let accumulationZones = [];
  let time = 0;
  let pulsePhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 8 accumulation zones
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = p.random(80, 180);
      let x = 200 + p.cos(angle) * radius;
      let y = 300 + p.sin(angle) * radius * 0.7;

      accumulationZones.push({
        x: x,
        y: y,
        nodes: [],
        intensity: p.random(0.5, 1.0),
        pulseOffset: i * 0.3
      });
    }

    // Generate organic network nodes
    for(let i = 0; i < 300; i++) {
      let zone = accumulationZones[p.floor(p.random(accumulationZones.length))];
      let offsetX = p.random(-60, 60);
      let offsetY = p.random(-40, 40);

      let node = {
        x: zone.x + offsetX,
        y: zone.y + offsetY,
        baseX: zone.x + offsetX,
        baseY: zone.y + offsetY,
        zone: zone,
        energy: p.random(0.2, 1.0),
        phase: p.random(p.TWO_PI),
        connections: []
      };

      nodes.push(node);
      zone.nodes.push(node);
    }

    // Create organic connections within and between zones
    for(let node of nodes) {
      let nearbyNodes = nodes.filter(other => {
        let d = p.dist(node.x, node.y, other.x, other.y);
        return d < 80 && other !== node;
      });

      // Connect to 2-5 nearby nodes
      let connectionCount = p.floor(p.random(2, 6));
      for(let i = 0; i < connectionCount && i < nearbyNodes.length; i++) {
        let target = nearbyNodes[i];
        connections.push({
          from: node,
          to: target,
          strength: p.random(0.3, 1.0),
          flow: p.random(0.5, 2.0)
        });
      }
    }
  };

  p.draw = function() {
    p.background(25, 20, 15);
    time += 0.02;
    pulsePhase += 0.05;

    // Mouse interaction - strengthen nearby accumulation
    let mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0.8, 1.5);

    // Update accumulation zone intensities
    for(let zone of accumulationZones) {
      let mouseDist = p.dist(p.mouseX, p.mouseY, zone.x, zone.y);
      zone.currentIntensity = zone.intensity;
      if(mouseDist < 100) {
        zone.currentIntensity *= p.map(mouseDist, 0, 100, 1.8, 1.0);
      }
    }

    // Draw connections with flowing energy
    p.strokeWeight(0.8);
    for(let conn of connections) {
      let zoneIntensity = (conn.from.zone.currentIntensity + conn.to.zone.currentIntensity) * 0.5;
      let flowPhase = time * conn.flow;

      // Energy accumulation effect
      let energyPulse = p.sin(flowPhase + conn.from.phase) * 0.3 + 0.7;
      let alpha = conn.strength * zoneIntensity * energyPulse * 120;

      // Earth tones with electric traces
      if(zoneIntensity > 1.2) {
        // Electric traces for high accumulation
        p.stroke(180, 220, 120, alpha);
      } else {
        // Mycorrhizal earth tones
        p.stroke(139, 101, 65, alpha * 0.8);
      }

      // Organic curved connections
      let midX = (conn.from.x + conn.to.x) * 0.5 + p.sin(time + conn.from.phase) * 8;
      let midY = (conn.from.y + conn.to.y) * 0.5 + p.cos(time * 0.7 + conn.to.phase) * 6;

      p.noFill();
      p.bezier(
        conn.from.x, conn.from.y,
        midX, midY - 20,
        midX, midY + 20,
        conn.to.x, conn.to.y
      );
    }

    // Draw nodes with accumulation visualization
    for(let node of nodes) {
      let zoneIntensity = node.zone.currentIntensity;
      let nodePulse = p.sin(pulsePhase + node.phase + node.zone.pulseOffset) * 0.4 + 0.6;

      // Node position slightly animated
      node.x = node.baseX + p.sin(time * 0.3 + node.phase) * 2;
      node.y = node.baseY + p.cos(time * 0.4 + node.phase) * 1.5;

      // Size based on zone accumulation
      let nodeSize = 2 + zoneIntensity * nodePulse * 4;

      if(zoneIntensity > 1.2) {
        // Bright nodes in high-accumulation zones
        p.fill(220, 255, 160, 200);
        p.noStroke();
        p.ellipse(node.x, node.y, nodeSize);

        // Extra glow for threshold zones
        p.fill(180, 220, 120, 60);
        p.ellipse(node.x, node.y, nodeSize * 2);
      } else {
        // Earth-toned nodes
        p.fill(160, 120, 80, 180 * nodePulse);
        p.noStroke();
        p.ellipse(node.x, node.y, nodeSize);
      }
    }

    // Draw accumulation zone centers with intensity visualization
    for(let i = 0; i < accumulationZones.length; i++) {
      let zone = accumulationZones[i];
      let zonePulse = p.sin(pulsePhase + zone.pulseOffset * 2) * 0.5 + 0.5;

      // Accumulation core
      if(zone.currentIntensity > 1.1) {
        p.fill(255, 240, 100, 80 * zonePulse);
        p.noStroke();
        p.ellipse(zone.x, zone.y, 30 * zone.currentIntensity);

        // Energy rings for high accumulation
        p.noFill();
        p.stroke(200, 255, 120, 40);
        p.strokeWeight(1);
        for(let ring = 1; ring <= 3; ring++) {
          let ringSize = ring * 15 * zone.currentIntensity * zonePulse;
          p.ellipse(zone.x, zone.y, ringSize);
        }
      }

      // Zone number (subtle)
      p.fill(100, 80, 60, 120);
      p.noStroke();
      p.textAlign(p.CENTER);
      p.textSize(8);
      p.text(i + 1, zone.x, zone.y + 3);
    }
  };

  p.mousePressed = function() {
    // Create ripple effect from mouse position
    for(let zone of accumulationZones) {
      let dist = p.dist(p.mouseX, p.mouseY, zone.x, zone.y);
      if(dist < 150) {
        zone.intensity = p.min(zone.intensity * 1.3, 2.0);
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let transformationZones = [];
  let connectionLines = [];
  let time = 0;
  let mouseForce = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create 9 transformation zones
    for(let i = 0; i < 9; i++) {
      transformationZones.push({
        x: p.random(60, 340),
        y: p.random(60, 540),
        baseRadius: p.random(30, 50),
        phase: p.random(0, p.TWO_PI),
        mutationSpeed: p.random(0.01, 0.03),
        originalHue: p.random(30, 60),
        targetHue: p.random(180, 280),
        progress: 0,
        nodes: []
      });
    }

    // Create network nodes around each zone
    for(let zone of transformationZones) {
      let nodeCount = p.random(8, 15);
      for(let j = 0; j < nodeCount; j++) {
        let angle = (p.TWO_PI / nodeCount) * j;
        let distance = p.random(20, 80);
        zone.nodes.push({
          localX: p.cos(angle) * distance,
          localY: p.sin(angle) * distance,
          size: p.random(2, 6),
          pulse: p.random(0, p.TWO_PI),
          connections: []
        });
      }
    }

    // Create inter-zone connections
    for(let i = 0; i < transformationZones.length; i++) {
      for(let j = i + 1; j < transformationZones.length; j++) {
        let zone1 = transformationZones[i];
        let zone2 = transformationZones[j];
        let distance = p.dist(zone1.x, zone1.y, zone2.x, zone2.y);

        if(distance < 120 || p.random() < 0.3) {
          connectionLines.push({
            zone1: i,
            zone2: j,
            strength: p.random(0.3, 1),
            flow: p.random(0, p.TWO_PI),
            segments: []
          });
        }
      }
    }
  };

  p.draw = function() {
    time += 0.016;
    mouseForce = p.map(p.mouseX + p.mouseY, 0, 1000, 0.5, 2);

    // Background gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(40, 20, 8), 
        p.color(25, 40, 15), 
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Update transformation zones
    for(let zone of transformationZones) {
      zone.progress = (p.sin(time * zone.mutationSpeed + zone.phase) + 1) * 0.5;
      zone.currentRadius = zone.baseRadius * (1 + zone.progress * 0.5) * mouseForce;
      zone.currentHue = p.lerp(zone.originalHue, zone.targetHue, zone.progress);
    }

    // Draw connection lines with flow
    p.strokeWeight(1);
    for(let connection of connectionLines) {
      let zone1 = transformationZones[connection.zone1];
      let zone2 = transformationZones[connection.zone2];

      connection.flow += 0.05;
      let flowPhase = p.sin(connection.flow) * 0.5 + 0.5;

      // Create organic connection path
      let steps = 15;
      let points = [];
      for(let i = 0; i <= steps; i++) {
        let t = i / steps;
        let x = p.lerp(zone1.x, zone2.x, t);
        let y = p.lerp(zone1.y, zone2.y, t);

        // Add organic curvature
        let curveAmount = p.sin(t * p.PI) * 20;
        let perpX = -(zone2.y - zone1.y) / p.dist(zone1.x, zone1.y, zone2.x, zone2.y);
        let perpY = (zone2.x - zone1.x) / p.dist(zone1.x, zone1.y, zone2.x, zone2.y);

        x += perpX * curveAmount * p.sin(time + t * 3);
        y += perpY * curveAmount * p.sin(time + t * 3);

        points.push({x: x, y: y});
      }

      // Draw connection with transformation colors
      for(let i = 0; i < points.length - 1; i++) {
        let t = i / (points.length - 1);
        let hue1 = zone1.currentHue;
        let hue2 = zone2.currentHue;
        let currentHue = p.lerp(hue1, hue2, t);

        let alpha = connection.strength * 60 * (1 + p.sin(connection.flow + t * p.TWO_PI) * 0.3);
        p.stroke(currentHue, 60, 80, alpha);

        p.line(points[i].x, points[i].y, points[i+1].x, points[i+1].y);
      }
    }

    // Draw transformation zones
    for(let zone of transformationZones) {
      p.push();
      p.translate(zone.x, zone.y);

      // Outer transformation ring
      p.noFill();
      p.strokeWeight(2);
      p.stroke(zone.currentHue, 70, 90, 40);
      let outerRadius = zone.currentRadius * 1.2;

      p.beginShape();
      for(let angle = 0; angle < p.TWO_PI; angle += 0.1) {
        let r = outerRadius * (1 + p.sin(angle * 3 + time * 2) * 0.1);
        let x = p.cos(angle) * r;
        let y = p.sin(angle) * r;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Inner mutating core
      p.fill(zone.currentHue, 80, 60, 30);
      p.noStroke();
      let coreRadius = zone.currentRadius * 0.6;

      p.beginShape();
      for(let angle = 0; angle < p.TWO_PI; angle += 0.2) {
        let r = coreRadius * (1 + p.sin(angle * 5 + time * 3 + zone.phase) * 0.2);
        let x = p.cos(angle) * r;
        let y = p.sin(angle) * r;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Network nodes
      for(let node of zone.nodes) {
        node.pulse += 0.08;
        let nodeX = node.localX * (1 + zone.progress * 0.3);
        let nodeY = node.localY * (1 + zone.progress * 0.3);

        let distance = p.dist(p.mouseX - zone.x, p.mouseY - zone.y, nodeX, nodeY);
        let mouseInfluence = p.map(distance, 0, 100, 1.5, 1);

        p.fill(zone.currentHue, 90, 95, 80);
        p.noStroke();
        let nodeSize = node.size * (1 + p.sin(node.pulse) * 0.3) * mouseInfluence;
        p.ellipse(nodeX, nodeY, nodeSize, nodeSize);

        // Tiny connection traces
        if(p.random() < 0.1) {
          p.stroke(zone.currentHue, 50, 100, 20);
          p.strokeWeight(0.5);
          p.line(0, 0, nodeX * 0.3, nodeY * 0.3);
        }
      }

      p.pop();
    }

    // Add subtle particle system for transformation energy
    if(p.frameCount % 10 === 0) {
      for(let zone of transformationZones) {
        if(zone.progress > 0.3) {
          for(let i = 0; i < 2; i++) {
            let particle = {
              x: zone.x + p.random(-zone.currentRadius, zone.currentRadius),
              y: zone.y + p.random(-zone.currentRadius, zone.currentRadius),
              vx: p.random(-1, 1),
              vy: p.random(-1, 1),
              life: 60,
              hue: zone.currentHue
            };

            // Remove old particles and add new ones
            if(!p.particles) p.particles = [];
            p.particles.push(particle);
            if(p.particles.length > 50) p.particles.shift();
          }
        }
      }
    }

    // Draw particles
    if(p.particles) {
      for(let i = p.particles.length - 1; i >= 0; i--) {
        let particle = p.particles[i];
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.life--;

        let alpha = p.map(particle.life, 0, 60, 0, 40);
        p.fill(particle.hue, 80, 90, alpha);
        p.noStroke();
        p.ellipse(particle.x, particle.y, 2, 2);

        if(particle.life <= 0) {
          p.particles.splice(i, 1);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Trigger transformation pulse
    for(let zone of transformationZones) {
      let distance = p.dist(p.mouseX, p.mouseY, zone.x, zone.y);
      if(distance < zone.currentRadius) {
        zone.mutationSpeed *= 2;
        setTimeout(() => zone.mutationSpeed *= 0.5, 2000);
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let dissolutionProgress = 0;
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 10 network nodes in organic positions
    for (let i = 0; i < 10; i++) {
      nodes.push({
        x: p.random(80, 320),
        y: p.random(100, 500),
        baseX: 0,
        baseY: 0,
        size: p.random(20, 40),
        energy: p.random(0.5, 1),
        dissolving: false,
        dissolveTime: p.random(100, 300),
        age: 0,
        connections: []
      });
    }

    // Set base positions
    for (let node of nodes) {
      node.baseX = node.x;
      node.baseY = node.y;
    }

    // Create organic connections between nearby nodes
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if (dist < 120 && p.random() < 0.6) {
          connections.push({
            from: i,
            to: j,
            strength: p.random(0.3, 1),
            pulseOffset: p.random(p.TWO_PI),
            dissolving: false
          });
          nodes[i].connections.push(j);
          nodes[j].connections.push(i);
        }
      }
    }
  };

  p.draw = function() {
    time += 0.02;

    // Rich earth gradient background
    for (let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(40, 30, 20),   // dark soil
        p.color(80, 60, 40),   // rich earth
        inter
      );
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Update dissolution cycle
    dissolutionProgress = (p.sin(time * 0.3) + 1) * 0.5;

    // Update nodes
    for (let i = 0; i < nodes.length; i++) {
      let node = nodes[i];
      node.age += 1;

      // Gentle organic movement
      node.x = node.baseX + p.sin(time + i * 0.5) * 8;
      node.y = node.baseY + p.cos(time * 0.7 + i * 0.3) * 6;

      // Dissolution logic
      let dissolveThreshold = p.map(i, 0, nodes.length - 1, 0.2, 0.8);
      if (dissolutionProgress > dissolveThreshold && !node.dissolving) {
        node.dissolving = true;
        // Create dissolution particles
        for (let j = 0; j < 8; j++) {
          particles.push({
            x: node.x,
            y: node.y,
            vx: p.random(-2, 2),
            vy: p.random(-3, 1),
            life: 60,
            maxLife: 60,
            size: p.random(2, 6)
          });
        }
      }

      if (dissolutionProgress < 0.1) {
        node.dissolving = false;
      }
    }

    // Draw connections with dissolution effect
    p.strokeWeight(2);
    for (let conn of connections) {
      let nodeA = nodes[conn.from];
      let nodeB = nodes[conn.to];

      let dissolveA = nodeA.dissolving ? 0.2 : 1;
      let dissolveB = nodeB.dissolving ? 0.2 : 1;
      let alpha = p.min(dissolveA, dissolveB) * conn.strength;

      // Pulse along connection
      let pulse = p.sin(time * 2 + conn.pulseOffset) * 0.5 + 0.5;
      alpha *= (0.3 + pulse * 0.7);

      // Connection color - electric traces fading
      let connectionHue = p.map(alpha, 0, 1, 60, 120); // earth to electric
      p.stroke(connectionHue, 40, 80, alpha * 150);

      // Draw organic curve between nodes
      let midX = (nodeA.x + nodeB.x) * 0.5 + p.sin(time + conn.from + conn.to) * 20;
      let midY = (nodeA.y + nodeB.y) * 0.5 + p.cos(time * 1.3 + conn.from + conn.to) * 15;

      p.noFill();
      p.bezier(nodeA.x, nodeA.y, midX, midY, midX, midY, nodeB.x, nodeB.y);
    }

    // Draw nodes
    for (let i = 0; i < nodes.length; i++) {
      let node = nodes[i];

      p.push();
      p.translate(node.x, node.y);

      if (node.dissolving) {
        // Dissolving state - returning to earth
        let dissolveAlpha = 0.3;
        p.fill(70, 50, 30, dissolveAlpha * 255);
        p.stroke(100, 80, 50, dissolveAlpha * 200);
        p.strokeWeight(1);

        // Fragmenting circle
        for (let a = 0; a < p.TWO_PI; a += 0.3) {
          let r = node.size * 0.3 + p.sin(time * 3 + a + i) * 5;
          let x = p.cos(a) * r;
          let y = p.sin(a) * r;
          p.circle(x, y, 4);
        }
      } else {
        // Active network node
        let nodeAlpha = node.energy;

        // Outer glow - electric potential
        p.fill(120, 60, 90, nodeAlpha * 30);
        p.noStroke();
        p.circle(0, 0, node.size * 2);

        // Inner core - organic matter
        p.fill(100, 70, 60, nodeAlpha * 200);
        p.stroke(130, 80, 70, nodeAlpha * 255);
        p.strokeWeight(1);
        p.circle(0, 0, node.size);

        // Pulsing center
        let pulse = p.sin(time * 1.5 + i) * 0.3 + 0.7;
        p.fill(150, 100, 90, pulse * nodeAlpha * 150);
        p.noStroke();
        p.circle(0, 0, node.size * 0.4);
      }

      p.pop();
    }

    // Draw and update dissolution particles
    p.noStroke();
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.vy += 0.05; // gentle gravity
      particle.life--;

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 1);
      p.fill(90, 70, 50, alpha * 180);
      p.circle(particle.x, particle.y, particle.size * alpha);

      if (particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Interactive response to mouse
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      // Mouse creates gentle ripples in the field
      p.stroke(120, 40, 80, 60);
      p.strokeWeight(1);
      p.noFill();
      let ripple = p.sin(time * 4) * 20 + 30;
      p.circle(p.mouseX, p.mouseY, ripple);
      p.circle(p.mouseX, p.mouseY, ripple * 1.5);
    }
  };

  p.mousePressed = function() {
    // Click accelerates the dissolution cycle
    time += 1;

    // Add some spontaneous particles at click location
    for (let i = 0; i < 5; i++) {
      particles.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-4, 0),
        life: 40,
        maxLife: 40,
        size: p.random(3, 8)
      });
    }
  };
}

function sketch(p) {
  let mystic = {};
  let networks = [];
  let particles = [];
  let time = 0;
  let breathe = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize mystic figure
    mystic.x = 200;
    mystic.y = 280;
    mystic.radius = 45;
    mystic.eyeOpenness = 1;

    // Create rhizomatic networks
    for (let i = 0; i < 8; i++) {
      networks.push(createNetwork(i));
    }

    // Create floating particles
    for (let i = 0; i < 80; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(2, 6),
        hue: p.random(25, 45),
        alpha: p.random(30, 70),
        connection: p.random(0.3, 0.8)
      });
    }
  };

  function createNetwork(index) {
    let network = {
      nodes: [],
      connections: [],
      rootX: p.random(50, 350),
      rootY: p.random(400, 550),
      energy: p.random(0.5, 1.5),
      hue: p.random(25, 45)
    };

    // Generate organic node structure
    for (let i = 0; i < p.random(12, 20); i++) {
      let angle = p.random(p.TWO_PI);
      let distance = p.random(20, 120);
      network.nodes.push({
        x: network.rootX + p.cos(angle) * distance,
        y: network.rootY + p.sin(angle) * distance,
        pulsePhase: p.random(p.TWO_PI),
        size: p.random(3, 8)
      });
    }

    // Create organic connections
    for (let i = 0; i < network.nodes.length; i++) {
      for (let j = i + 1; j < network.nodes.length; j++) {
        let dist = p.dist(network.nodes[i].x, network.nodes[i].y, 
                         network.nodes[j].x, network.nodes[j].y);
        if (dist < 80 && p.random() < 0.4) {
          network.connections.push([i, j]);
        }
      }
    }

    return network;
  }

  p.draw = function() {
    time += 0.02;
    breathe = p.sin(time * 2) * 0.3 + 1;

    // Gradient background
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(35, 40, 20), p.color(25, 60, 10), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Draw underground networks with pulsing energy
    drawNetworks();

    // Draw mystic figure
    drawMystic();

    // Draw floating particles with connections
    drawParticleField();

    // Draw ethereal connections from mystic to networks
    drawMysticConnections();

    // Update particle positions
    updateParticles();
  };

  function drawNetworks() {
    for (let network of networks) {
      p.push();

      // Draw connections with electric pulses
      for (let connection of network.connections) {
        let node1 = network.nodes[connection[0]];
        let node2 = network.nodes[connection[1]];

        let pulse = p.sin(time * 3 + connection[0] * 0.5) * 0.5 + 0.5;
        let alpha = 20 + pulse * 30;

        p.stroke(network.hue, 80, 70, alpha);
        p.strokeWeight(1 + pulse * 2);
        p.line(node1.x, node1.y, node2.x, node2.y);

        // Electric traces
        if (pulse > 0.7) {
          p.stroke(network.hue + 20, 60, 90, 60);
          p.strokeWeight(0.5);
          p.line(node1.x, node1.y, node2.x, node2.y);
        }
      }

      // Draw nodes with organic pulsing
      for (let node of network.nodes) {
        let pulse = p.sin(time * 2 + node.pulsePhase) * 0.3 + 0.7;

        p.fill(network.hue, 70, 60, 40 * pulse);
        p.noStroke();
        p.circle(node.x, node.y, node.size * pulse * breathe);

        // Inner glow
        p.fill(network.hue + 15, 50, 80, 60 * pulse);
        p.circle(node.x, node.y, node.size * 0.4 * pulse);
      }

      p.pop();
    }
  }

  function drawMystic() {
    p.push();
    p.translate(mystic.x, mystic.y);

    // Body dissolving into network threads
    let dissolveFactor = p.sin(time * 1.5) * 0.2 + 0.8;

    // Main body with organic breathing
    p.fill(35, 30, 85, 60 * dissolveFactor);
    p.noStroke();
    p.ellipse(0, 10, mystic.radius * 2 * breathe, mystic.radius * 2.5 * breathe);

    // Head with enhanced perception
    p.fill(30, 25, 90, 70);
    p.ellipse(0, -20, mystic.radius * 1.4 * breathe, mystic.radius * 1.6 * breathe);

    // Eyes wide with vision
    let eyeGlow = p.sin(time * 4) * 0.3 + 0.7;
    p.fill(45, 60, 95, 80 * eyeGlow);
    p.ellipse(-12, -25, 8 * mystic.eyeOpenness, 12 * mystic.eyeOpenness);
    p.ellipse(12, -25, 8 * mystic.eyeOpenness, 12 * mystic.eyeOpenness);

    // Third eye connection
    p.fill(40, 80, 90, 60 * eyeGlow);
    p.ellipse(0, -35, 6, 6);

    // Arms reaching into the network
    p.stroke(35, 40, 75, 50 * dissolveFactor);
    p.strokeWeight(6 * dissolveFactor);
    let armReach = p.sin(time) * 20;
    p.line(0, 0, -40 + armReach, 60);
    p.line(0, 0, 40 - armReach, 60);

    // Hands dissolving into network threads
    drawDissolvingHands(-40 + armReach, 60, dissolveFactor);
    drawDissolvingHands(40 - armReach, 60, dissolveFactor);

    p.pop();

    // Update eye openness based on network activity
    let networkEnergy = 0;
    for (let network of networks) {
      networkEnergy += p.sin(time * 2 + network.energy);
    }
    mystic.eyeOpenness = p.map(networkEnergy, -networks.length, networks.length, 0.7, 1.3);
  }

  function drawDissolvingHands(x, y, dissolve) {
    p.push();
    p.translate(x, y);

    for (let i = 0; i < 8; i++) {
      let angle = i * p.PI / 4;
      let length = p.random(15, 35) * dissolve;
      let alpha = 30 * dissolve * p.random(0.5, 1);

      p.stroke(35, 50, 80, alpha);
      p.strokeWeight(p.random(1, 3) * dissolve);

      let endX = p.cos(angle) * length;
      let endY = p.sin(angle) * length;
      p.line(0, 0, endX, endY);

      // Branching threads
      if (p.random() < 0.3) {
        p.stroke(40, 60, 70, alpha * 0.7);
        p.strokeWeight(1);
        let branchX = endX + p.cos(angle + p.PI/3) * 10;
        let branchY = endY + p.sin(angle + p.PI/3) * 10;
        p.line(endX, endY, branchX, branchY);
      }
    }

    p.pop();
  }

  function drawParticleField() {
    for (let particle of particles) {
      p.push();

      let pulse = p.sin(time * 2 + particle.x * 0.01) * 0.3 + 0.7;

      p.fill(particle.hue, 60, 80, particle.alpha * pulse);
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size * pulse);

      // Connect nearby particles
      for (let other of particles) {
        let dist = p.dist(particle.x, particle.y, other.x, other.y);
        if (dist < 60 && dist > 0) {
          let alpha = p.map(dist, 0, 60, 20, 0) * particle.connection;
          p.stroke(particle.hue, 40, 60, alpha * pulse);
          p.strokeWeight(0.5);
          p.line(particle.x, particle.y, other.x, other.y);
        }
      }

      p.pop();
    }
  }

  function drawMysticConnections() {
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, mystic.x, mystic.y) < 100;
    let intensity = mouseInfluence ? 1.5 : 1;

    for (let network of networks) {
      for (let node of network.nodes) {
        let dist = p.dist(mystic.x, mystic.y, node.x, node.y);
        if (dist < 200) {
          let alpha = p.map(dist, 0, 200, 30, 0) * intensity;
          let pulse = p.sin(time * 3 + dist * 0.01) * 0.5 + 0.5;

          p.stroke(35, 70, 85, alpha * pulse);
          p.strokeWeight(0.8 * intensity);
          p.line(mystic.x, mystic.y, node.x, node.y);

          // Energy flow particles
          if (pulse > 0.8 && p.random() < 0.1) {
            let flowX = p.lerp(mystic.x, node.x, p.random());
            let flowY = p.lerp(mystic.y, node.y, p.random());
            p.fill(40, 80, 90, 70);
            p.noStroke();
            p.circle(flowX, flowY, 3);
          }
        }
      }
    }
  }

  function updateParticles() {
    for (let particle of particles) {
      particle.x += particle.vx;
      particle.y += particle.vy;

      // Gentle attraction to mystic
      let dx = mystic.x - particle.x;
      let dy = mystic.y - particle.y;
      let dist = p.sqrt(dx * dx + dy * dy);
      if (dist > 0) {
        particle.vx += (dx / dist) * 0.001;
        particle.vy += (dy / dist) * 0.001;
      }

      // Wrap around edges
      if (particle.x < 0) particle.x = 400;
      if (particle.x > 400) particle.x = 0;
      if (particle.y < 0) particle.y = 600;
      if (particle.y > 600) particle.y = 0;

      // Gentle velocity damping
      particle.vx *= 0.99;
      particle.vy *= 0.99;
    }
  }

  p.mousePressed = function() {
    // Create ripple effect through the network
    for (let network of networks) {
      network.energy += p.random(0.5, 1.5);
    }

    // Spawn new particles near click
    for (let i = 0; i < 5; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(2, 6),
        hue: p.random(25, 45),
        alpha: p.random(40, 80),
        connection: p.random(0.5, 1)
      });
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let mapLines = [];
  let cartographer;
  let time = 0;
  let isMapping = false;
  let mappingProgress = 0;
  let colors;

  p.setup = function() {
    p.createCanvas(400, 600);

    colors = {
      bg: p.color(15, 25, 35),
      node: p.color(120, 200, 255, 180),
      connection: p.color(80, 160, 220, 100),
      mapLine: p.color(255, 180, 120, 200),
      cartographer: p.color(255, 220, 150)
    };

    // Create rhizomatic nodes
    for (let i = 0; i < 25; i++) {
      nodes.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        size: p.random(3, 8),
        connections: []
      });
    }

    // Create organic connections between nearby nodes
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if (dist < 80 && p.random() < 0.3) {
          connections.push({
            from: i,
            to: j,
            strength: p.random(0.1, 0.8)
          });
        }
      }
    }

    // Cartographer starts at center
    cartographer = {
      x: 200,
      y: 300,
      targetX: 200,
      targetY: 300,
      angle: 0
    };
  };

  p.draw = function() {
    p.background(colors.bg);
    time += 0.02;

    // Update node positions with gentle drift
    for (let node of nodes) {
      node.x += node.vx + p.noise(node.x * 0.01, time) * 0.2 - 0.1;
      node.y += node.vy + p.noise(node.y * 0.01, time + 100) * 0.2 - 0.1;

      // Soft boundaries
      if (node.x < 30) node.vx = p.abs(node.vx);
      if (node.x > 370) node.vx = -p.abs(node.vx);
      if (node.y < 80) node.vy = p.abs(node.vy);
      if (node.y > 520) node.vy = -p.abs(node.vy);
    }

    // Draw living connections
    p.strokeWeight(1);
    for (let conn of connections) {
      let fromNode = nodes[conn.from];
      let toNode = nodes[conn.to];

      let alpha = conn.strength * 150 + p.sin(time * 2) * 30;
      p.stroke(p.red(colors.connection), p.green(colors.connection), p.blue(colors.connection), alpha);

      // Organic curved connections
      let midX = (fromNode.x + toNode.x) / 2 + p.sin(time + conn.from) * 10;
      let midY = (fromNode.y + toNode.y) / 2 + p.cos(time + conn.to) * 10;

      p.noFill();
      p.beginShape();
      p.vertex(fromNode.x, fromNode.y);
      p.quadraticVertex(midX, midY, toNode.x, toNode.y);
      p.endShape();
    }

    // Draw nodes
    p.noStroke();
    for (let node of nodes) {
      let pulse = 1 + p.sin(time * 3 + node.x * 0.01) * 0.2;
      p.fill(colors.node);
      p.circle(node.x, node.y, node.size * pulse);

      // Inner glow
      p.fill(255, 255, 255, 80);
      p.circle(node.x, node.y, node.size * pulse * 0.3);
    }

    // Update cartographer position
    let mouseInfluence = p.map(p.mouseX, 0, 400, -50, 50);
    cartographer.targetX = 200 + mouseInfluence;
    cartographer.targetY = p.constrain(p.mouseY, 100, 500);

    cartographer.x += (cartographer.targetX - cartographer.x) * 0.05;
    cartographer.y += (cartographer.targetY - cartographer.y) * 0.05;
    cartographer.angle += 0.03;

    // Mapping behavior
    if (p.mouseIsPressed) {
      isMapping = true;
      mappingProgress += 0.03;
    } else {
      isMapping = false;
      mappingProgress *= 0.95;
    }

    // Draw map lines when mapping
    if (isMapping || mappingProgress > 0.01) {
      p.stroke(colors.mapLine);
      p.strokeWeight(2);

      for (let i = 0; i < nodes.length; i++) {
        let node = nodes[i];
        let dist = p.dist(cartographer.x, cartographer.y, node.x, node.y);

        if (dist < 120) {
          let alpha = p.map(dist, 0, 120, 255, 0) * mappingProgress;
          p.stroke(p.red(colors.mapLine), p.green(colors.mapLine), p.blue(colors.mapLine), alpha);

          // Dotted mapping line
          let steps = p.floor(dist / 8);
          for (let j = 0; j < steps; j += 2) {
            let t1 = j / steps;
            let t2 = (j + 1) / steps;
            let x1 = p.lerp(cartographer.x, node.x, t1);
            let y1 = p.lerp(cartographer.y, node.y, t1);
            let x2 = p.lerp(cartographer.x, node.x, t2);
            let y2 = p.lerp(cartographer.y, node.y, t2);
            p.line(x1, y1, x2, y2);
          }
        }
      }
    }

    // Draw cartographer
    p.push();
    p.translate(cartographer.x, cartographer.y);
    p.rotate(cartographer.angle);

    // Body
    p.fill(colors.cartographer);
    p.noStroke();
    p.ellipse(0, 0, 16, 20);

    // Compass/tool
    p.stroke(colors.cartographer);
    p.strokeWeight(2);
    p.line(-8, -5, 8, -5);
    p.line(0, -8, 0, -2);

    // Mapping tendrils
    if (mappingProgress > 0.1) {
      p.stroke(colors.mapLine);
      p.strokeWeight(1);
      for (let i = 0; i < 6; i++) {
        let angle = (p.TWO_PI / 6) * i + time;
        let length = mappingProgress * 25;
        p.line(0, 0, p.cos(angle) * length, p.sin(angle) * length);
      }
    }

    p.pop();

    // Subtle network field visualization
    p.stroke(colors.connection);
    p.strokeWeight(0.5);
    for (let x = 0; x < 400; x += 40) {
      for (let y = 0; y < 600; y += 40) {
        let fieldStrength = 0;
        for (let node of nodes) {
          let dist = p.dist(x, y, node.x, node.y);
          fieldStrength += 1 / (1 + dist * 0.01);
        }

        if (fieldStrength > 2) {
          let alpha = p.map(fieldStrength, 2, 8, 20, 60);
          p.stroke(p.red(colors.connection), p.green(colors.connection), p.blue(colors.connection), alpha);
          p.point(x, y);
        }
      }
    }
  };
}

function sketch(p) {
  let nodes = [];
  let connections = [];
  let builderHands = [];
  let mycorrhizae = [];
  let sparkles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create initial network nodes
    for(let i = 0; i < 80; i++) {
      nodes.push({
        x: p.random(50, 350),
        y: p.random(100, 550),
        size: p.random(2, 8),
        pulse: p.random(p.TWO_PI),
        energy: p.random(0.5, 1),
        active: false
      });
    }

    // Create builder hands that weave new connections
    for(let i = 0; i < 3; i++) {
      builderHands.push({
        x: p.random(100, 300),
        y: p.random(200, 400),
        targetX: p.random(100, 300),
        targetY: p.random(200, 400),
        weavingPath: [],
        isWeaving: false
      });
    }

    // Initialize mycorrhizal threads
    for(let i = 0; i < 200; i++) {
      mycorrhizae.push({
        x: p.random(400),
        y: p.random(600),
        angle: p.random(p.TWO_PI),
        length: p.random(20, 60),
        growth: 0,
        connected: false
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Earth tone gradient background
    for(let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(45, 35, 25), p.color(25, 20, 15), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    // Draw growing mycorrhizal network
    p.strokeWeight(0.5);
    for(let myc of mycorrhizae) {
      myc.growth += 0.005;
      if(myc.growth > 1) myc.growth = 1;

      let alpha = p.map(myc.growth, 0, 1, 0, 150);
      p.stroke(120, 80, 40, alpha);

      let endX = myc.x + p.cos(myc.angle) * myc.length * myc.growth;
      let endY = myc.y + p.sin(myc.angle) * myc.length * myc.growth;

      p.line(myc.x, myc.y, endX, endY);

      // Branch occasionally
      if(p.random() < 0.002 && myc.growth > 0.7) {
        mycorrhizae.push({
          x: endX,
          y: endY,
          angle: myc.angle + p.random(-p.PI/3, p.PI/3),
          length: myc.length * 0.7,
          growth: 0,
          connected: false
        });
      }
    }

    // Update and draw network nodes
    p.strokeWeight(1);
    for(let node of nodes) {
      node.pulse += 0.1;
      let pulseSize = node.size + p.sin(node.pulse) * 2;

      // Check if mouse is nearby to activate
      let dist = p.dist(p.mouseX, p.mouseY, node.x, node.y);
      node.active = dist < 60;

      if(node.active) {
        p.fill(180, 120, 60, 200);
        p.stroke(220, 160, 80);

        // Add sparkle
        if(p.random() < 0.1) {
          sparkles.push({
            x: node.x + p.random(-10, 10),
            y: node.y + p.random(-10, 10),
            life: 30
          });
        }
      } else {
        p.fill(100, 70, 40, 150);
        p.stroke(140, 100, 60);
      }

      p.ellipse(node.x, node.y, pulseSize);
    }

    // Draw dynamic connections between nearby active nodes
    connections = [];
    p.strokeWeight(0.8);
    for(let i = 0; i < nodes.length; i++) {
      for(let j = i + 1; j < nodes.length; j++) {
        let dist = p.dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
        if(dist < 100 && (nodes[i].active || nodes[j].active)) {
          let alpha = p.map(dist, 0, 100, 180, 20);
          p.stroke(160, 100, 50, alpha);

          // Slightly curved connection
          let midX = (nodes[i].x + nodes[j].x) / 2 + p.sin(time + i + j) * 5;
          let midY = (nodes[i].y + nodes[j].y) / 2 + p.cos(time + i + j) * 5;

          p.noFill();
          p.beginShape();
          p.vertex(nodes[i].x, nodes[i].y);
          p.quadraticVertex(midX, midY, nodes[j].x, nodes[j].y);
          p.endShape();
        }
      }
    }

    // Update and draw builder hands
    p.strokeWeight(3);
    for(let hand of builderHands) {
      // Move toward target
      hand.x = p.lerp(hand.x, hand.targetX, 0.02);
      hand.y = p.lerp(hand.y, hand.targetY, 0.02);

      // Choose new target when close
      if(p.dist(hand.x, hand.y, hand.targetX, hand.targetY) < 10) {
        hand.targetX = p.random(100, 300);
        hand.targetY = p.random(200, 400);
        hand.weavingPath = [];
      }

      // Add to weaving path
      hand.weavingPath.push({x: hand.x, y: hand.y});
      if(hand.weavingPath.length > 20) {
        hand.weavingPath.shift();
      }

      // Draw weaving trail
      p.noFill();
      p.stroke(200, 140, 80, 180);
      p.strokeWeight(2);
      p.beginShape();
      for(let point of hand.weavingPath) {
        p.vertex(point.x, point.y);
      }
      p.endShape();

      // Draw hand as gentle circle
      p.fill(220, 180, 120);
      p.stroke(180, 140, 100);
      p.strokeWeight(1);
      p.ellipse(hand.x, hand.y, 12);
    }

    // Draw and update sparkles
    for(let i = sparkles.length - 1; i >= 0; i--) {
      let sparkle = sparkles[i];
      sparkle.life--;

      let alpha = p.map(sparkle.life, 0, 30, 0, 255);
      p.fill(255, 220, 120, alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, 3);

      if(sparkle.life <= 0) {
        sparkles.splice(i, 1);
      }
    }

    // Mouse interaction - create new connection threads
    if(p.mouseIsPressed && p.frameCount % 3 === 0) {
      mycorrhizae.push({
        x: p.mouseX,
        y: p.mouseY,
        angle: p.random(p.TWO_PI),
        length: p.random(30, 80),
        growth: 0,
        connected: false
      });
    }
  };
}

function sketch(p) {
  let prophet;
  let networks = [];
  let knowledge = [];
  let teachingLines = [];
  let time = 0;
  let earthTones = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    earthTones = [
      p.color(139, 115, 85),   // saddle brown
      p.color(160, 82, 45),    // sienna
      p.color(205, 133, 63),   // peru
      p.color(222, 184, 135),  // burlywood
      p.color(85, 107, 47),    // dark olive
      p.color(107, 142, 35)    // olive drab
    ];

    // Create prophet figure
    prophet = {
      x: 200,
      y: 250,
      armAngle: 0,
      glowIntensity: 0
    };

    // Create network nodes
    for(let i = 0; i < 35; i++) {
      networks.push({
        x: p.random(50, 350),
        y: p.random(100, 550),
        connections: [],
        size: p.random(3, 8),
        energy: p.random(0.5, 1),
        phase: p.random(0, p.TWO_PI)
      });
    }

    // Create connections between nearby nodes
    for(let i = 0; i < networks.length; i++) {
      for(let j = i + 1; j < networks.length; j++) {
        let d = p.dist(networks[i].x, networks[i].y, networks[j].x, networks[j].y);
        if(d < 80 && p.random() < 0.6) {
          networks[i].connections.push(j);
        }
      }
    }

    // Create knowledge particles
    for(let i = 0; i < 15; i++) {
      knowledge.push({
        x: prophet.x + p.random(-30, 30),
        y: prophet.y + p.random(-30, 30),
        targetX: p.random(50, 350),
        targetY: p.random(100, 550),
        progress: 0,
        brightness: p.random(0.5, 1),
        size: p.random(2, 5)
      });
    }
  };

  p.draw = function() {
    p.background(45, 35, 25);
    time += 0.02;

    // Draw mycorrhizal background pattern
    p.push();
    p.stroke(earthTones[4]);
    p.strokeWeight(0.5);
    p.noFill();
    for(let i = 0; i < 8; i++) {
      let y = 100 + i * 60;
      p.beginShape();
      p.noFill();
      for(let x = 0; x <= 400; x += 10) {
        let wave = p.sin(x * 0.02 + time * 2 + i * 0.5) * 15;
        p.curveVertex(x, y + wave);
      }
      p.endShape();
    }
    p.pop();

    // Draw network connections with energy flow
    for(let node of networks) {
      for(let connId of node.connections) {
        let other = networks[connId];
        let flow = p.sin(time * 3 + node.phase) * 0.5 + 0.5;

        p.push();
        let col = p.lerpColor(earthTones[0], p.color(255, 255, 100, 150), flow * 0.3);
        p.stroke(col);
        p.strokeWeight(1 + flow);

        // Curved connection line
        let midX = (node.x + other.x) / 2 + p.sin(time + node.phase) * 10;
        let midY = (node.y + other.y) / 2 + p.cos(time + node.phase) * 10;

        p.noFill();
        p.beginShape();
        p.curveVertex(node.x, node.y);
        p.curveVertex(node.x, node.y);
        p.curveVertex(midX, midY);
        p.curveVertex(other.x, other.y);
        p.curveVertex(other.x, other.y);
        p.endShape();
        p.pop();
      }
    }

    // Draw network nodes
    for(let i = 0; i < networks.length; i++) {
      let node = networks[i];
      let pulse = p.sin(time * 2 + node.phase) * 0.3 + 0.7;

      p.push();
      p.fill(earthTones[2]);
      p.stroke(255, 255, 100, pulse * 100);
      p.strokeWeight(pulse);
      p.circle(node.x, node.y, node.size * pulse);
      p.pop();

      // Mouse interaction - nodes respond to proximity
      let mouseD = p.dist(p.mouseX, p.mouseY, node.x, node.y);
      if(mouseD < 50) {
        node.energy = p.min(node.energy + 0.05, 2);
        p.push();
        p.fill(255, 255, 150, 100);
        p.noStroke();
        p.circle(node.x, node.y, 20 * (1 - mouseD/50));
        p.pop();
      } else {
        node.energy = p.max(node.energy - 0.01, 0.5);
      }
    }

    // Update and draw knowledge particles
    for(let k of knowledge) {
      k.progress += 0.008;
      if(k.progress >= 1) {
        k.progress = 0;
        k.x = prophet.x + p.random(-30, 30);
        k.y = prophet.y + p.random(-30, 30);
        k.targetX = p.random(50, 350);
        k.targetY = p.random(100, 550);
      }

      let currentX = p.lerp(k.x, k.targetX, p.sin(k.progress * p.PI) * k.progress);
      let currentY = p.lerp(k.y, k.targetY, p.sin(k.progress * p.PI) * k.progress);

      p.push();
      let alpha = p.sin(k.progress * p.PI) * k.brightness * 255;
      p.fill(255, 200, 100, alpha);
      p.noStroke();
      p.circle(currentX, currentY, k.size);
      p.pop();
    }

    // Draw prophet figure
    prophet.armAngle = p.sin(time * 1.5) * 0.3;
    prophet.glowIntensity = p.sin(time * 2) * 0.2 + 0.8;

    // Prophet's glow
    p.push();
    p.fill(255, 200, 150, 30 * prophet.glowIntensity);
    p.noStroke();
    p.circle(prophet.x, prophet.y, 80);
    p.pop();

    // Prophet's robe
    p.push();
    p.fill(earthTones[1]);
    p.stroke(earthTones[4]);
    p.strokeWeight(2);
    p.ellipse(prophet.x, prophet.y + 20, 60, 100);
    p.pop();

    // Prophet's head
    p.push();
    p.fill(205, 180, 150);
    p.stroke(earthTones[4]);
    p.strokeWeight(1);
    p.circle(prophet.x, prophet.y - 30, 35);
    p.pop();

    // Prophet's pointing arm
    p.push();
    p.stroke(earthTones[1]);
    p.strokeWeight(6);
    let armX = prophet.x + p.cos(prophet.armAngle - 0.5) * 40;
    let armY = prophet.y - 10 + p.sin(prophet.armAngle - 0.5) * 20;
    p.line(prophet.x + 15, prophet.y - 10, armX, armY);

    // Hand with emanating understanding
    p.fill(205, 180, 150);
    p.noStroke();
    p.circle(armX, armY, 8);

    // Understanding rays from hand
    for(let i = 0; i < 5; i++) {
      let angle = (i / 5) * p.TWO_PI + time;
      let rayX = armX + p.cos(angle) * 15;
      let rayY = armY + p.sin(angle) * 15;
      p.stroke(255, 255, 150, 150);
      p.strokeWeight(2);
      p.line(armX, armY, rayX, rayY);
    }
    p.pop();

    // Teaching frameworks - geometric overlay that makes sense of the network
    if(p.mouseIsPressed) {
      p.push();
      p.stroke(255, 255, 200, 100);
      p.strokeWeight(1);
      p.noFill();

      // Draw organizing principles
      let gridSize = 40;
      for(let x = 0; x < 400; x += gridSize) {
        for(let y = 0; y < 600; y += gridSize) {
          let wave = p.sin(x * 0.1 + y * 0.1 + time) * 10;
          p.circle(x + 20 + wave, y + 20, 15);
        }
      }
      p.pop();

      // Show connection potentials
      p.push();
      p.stroke(255, 255, 100, 80);
      p.strokeWeight(0.5);
      for(let i = 0; i < networks.length; i += 3) {
        for(let j = i + 2; j < networks.length; j += 4) {
          p.line(networks[i].x, networks[i].y, networks[j].x, networks[j].y);
        }
      }
      p.pop();
    }
  };
}

function sketch(p) {
  let cellStructures = [];
  let organelles = [];
  let boundaryPoints = [];
  let pulsePhase = 0;
  let nucleusGlow = 0;
  let membraneThickness = 1;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the organizing structures within the cell
    for (let i = 0; i < 8; i++) {
      cellStructures.push({
        angle: (i / 8) * p.TWO_PI,
        radius: p.random(30, 60),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.01, 0.03)
      });
    }

    // Create floating organelles
    for (let i = 0; i < 15; i++) {
      organelles.push({
        x: p.random(100, 300),
        y: p.random(150, 450),
        size: p.random(3, 8),
        drift: p.createVector(p.random(-0.2, 0.2), p.random(-0.2, 0.2)),
        phase: p.random(p.TWO_PI),
        type: p.floor(p.random(3))
      });
    }

    // Create boundary definition points
    for (let i = 0; i < 60; i++) {
      let angle = (i / 60) * p.TWO_PI;
      boundaryPoints.push({
        baseAngle: angle,
        baseRadius: 120,
        variation: p.random(10, 25),
        phase: p.random(p.TWO_PI),
        speed: p.random(0.02, 0.05)
      });
    }
  };

  p.draw = function() {
    p.background(15, 12, 18);

    pulsePhase += 0.02;
    nucleusGlow = p.sin(pulsePhase) * 0.3 + 0.7;

    let centerX = 200;
    let centerY = 300;

    // Mouse interaction affects organization intensity
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, centerX, centerY) / 200;
    mouseInfluence = p.constrain(1 - mouseInfluence, 0, 1);
    membraneThickness = 1 + mouseInfluence * 3;

    // Draw organizing field (background structure)
    p.push();
    p.translate(centerX, centerY);
    p.stroke(120, 45, 45, 30);
    p.strokeWeight(0.5);
    p.noFill();

    for (let r = 30; r < 200; r += 20) {
      p.beginShape();
      for (let a = 0; a < p.TWO_PI + 0.1; a += 0.1) {
        let noise = p.noise(r * 0.01, a, pulsePhase * 0.5) * 10;
        let x = (r + noise) * p.cos(a);
        let y = (r + noise) * p.sin(a);
        p.vertex(x, y);
      }
      p.endShape();
    }
    p.pop();

    // Draw cellular organelles
    for (let organelle of organelles) {
      organelle.x += organelle.drift.x;
      organelle.y += organelle.drift.y;

      // Boundary reflection
      if (organelle.x < 80 || organelle.x > 320) organelle.drift.x *= -1;
      if (organelle.y < 180 || organelle.y > 420) organelle.drift.y *= -1;

      let alpha = (p.sin(organelle.phase + pulsePhase) * 0.3 + 0.7) * 255;

      p.push();
      p.translate(organelle.x, organelle.y);

      if (organelle.type === 0) {
        // Mitochondria-like
        p.fill(180, 60, 60, alpha);
        p.noStroke();
        p.ellipse(0, 0, organelle.size * 2, organelle.size);
        p.fill(220, 80, 80, alpha * 0.6);
        p.ellipse(0, 0, organelle.size, organelle.size * 0.5);
      } else if (organelle.type === 1) {
        // Ribosome-like
        p.fill(100, 100, 150, alpha);
        p.noStroke();
        p.ellipse(0, 0, organelle.size);
        p.fill(130, 130, 180, alpha);
        p.ellipse(0, 0, organelle.size * 0.6);
      } else {
        // Vesicle-like
        p.stroke(160, 90, 90, alpha);
        p.strokeWeight(1);
        p.noFill();
        p.ellipse(0, 0, organelle.size);
      }
      p.pop();

      organelle.phase += 0.02;
    }

    // Draw internal organizing structures
    p.push();
    p.translate(centerX, centerY);

    for (let structure of cellStructures) {
      structure.phase += structure.speed;
      let radius = structure.radius + p.sin(structure.phase + pulsePhase) * 10;
      let x = radius * p.cos(structure.angle + pulsePhase * 0.3);
      let y = radius * p.sin(structure.angle + pulsePhase * 0.3);

      p.stroke(200, 80, 80, 100);
      p.strokeWeight(2);
      p.line(0, 0, x * 0.7, y * 0.7);

      p.fill(220, 100, 100, 150);
      p.noStroke();
      p.ellipse(x, y, 6, 6);
    }
    p.pop();

    // Draw the nucleus (organizing center)
    p.push();
    p.translate(centerX, centerY);

    // Nuclear membrane
    p.fill(80, 30, 30, 80);
    p.stroke(140, 60, 60, 200 * nucleusGlow);
    p.strokeWeight(membraneThickness * 2);
    p.ellipse(0, 0, 50, 50);

    // Chromatin/organizing material
    p.fill(180, 80, 80, 150 * nucleusGlow);
    p.noStroke();
    for (let i = 0; i < 5; i++) {
      let angle = (i / 5) * p.TWO_PI + pulsePhase;
      let x = 12 * p.cos(angle);
      let y = 12 * p.sin(angle);
      p.ellipse(x, y, 4, 4);
    }

    // Nuclear center
    p.fill(220, 120, 120, 200 * nucleusGlow);
    p.ellipse(0, 0, 8, 8);
    p.pop();

    // Draw cell membrane (boundary definition)
    p.push();
    p.translate(centerX, centerY);
    p.stroke(160, 70, 70, 180);
    p.strokeWeight(membraneThickness);
    p.noFill();

    p.beginShape();
    for (let point of boundaryPoints) {
      point.phase += point.speed;
      let radius = point.baseRadius + point.variation * p.sin(point.phase);
      let x = radius * p.cos(point.baseAngle);
      let y = radius * p.sin(point.baseAngle);
      p.vertex(x, y);
    }
    p.endShape(p.CLOSE);
    p.pop();

    // Territorial glow effect
    p.push();
    p.translate(centerX, centerY);
    p.fill(200, 60, 60, 20 * mouseInfluence);
    p.noStroke();
    p.ellipse(0, 0, 280, 280);
    p.pop();
  };

  p.mousePressed = function() {
    // Reorganize on click
    pulsePhase += p.PI * 0.25;
    for (let organelle of organelles) {
      organelle.drift.mult(p.random(0.8, 1.2));
      organelle.phase += p.random(-0.5, 0.5);
    }
  };
}

function sketch(p) {
  let heartPulse = 0;
  let chamberSeparation = 0;
  let bloodCells = [];
  let structuralLines = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create floating blood cells
    for (let i = 0; i < 40; i++) {
      bloodCells.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(3, 8),
        speed: p.random(0.5, 2),
        angle: p.random(p.TWO_PI),
        chamber: i < 20 ? 'left' : 'right',
        opacity: p.random(150, 255)
      });
    }

    // Create structural support lines
    for (let i = 0; i < 12; i++) {
      structuralLines.push({
        x1: p.random(80, 320),
        y1: p.random(150, 450),
        x2: p.random(80, 320),
        y2: p.random(150, 450),
        weight: p.random(1, 3),
        pulse: p.random(0, p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Dark, organic background
    p.background(20, 15, 25);

    // Mouse influence creates subtle reactive breathing
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseY, 0, 600, 0.8, 1.2), 0.05);

    // Heart pulse animation
    heartPulse += 0.08;
    let pulseScale = 1 + p.sin(heartPulse) * 0.15 * mouseInfluence;

    // Chamber separation grows over time
    chamberSeparation = p.map(p.sin(p.millis() * 0.001), -1, 1, 10, 35);

    p.push();
    p.translate(200, 300);
    p.scale(pulseScale);

    // Draw structural framework - architectural ribbing
    p.stroke(90, 85, 100, 120);
    p.strokeWeight(2);
    p.noFill();

    for (let line of structuralLines) {
      let dynamicWeight = line.weight + p.sin(heartPulse + line.pulse) * 0.5;
      p.strokeWeight(dynamicWeight);
      p.line(line.x1 - 200, line.y1 - 300, line.x2 - 200, line.y2 - 300);
    }

    // Main organ structure - heart-like with architectural elements
    p.stroke(140, 60, 80, 200);
    p.strokeWeight(4);
    p.fill(80, 35, 45, 180);

    // Left chamber
    p.push();
    p.translate(-chamberSeparation, 0);
    p.beginShape();
    p.vertex(-60, -80);
    p.bezierVertex(-90, -60, -90, 60, -30, 90);
    p.bezierVertex(0, 100, 20, 80, 0, 0);
    p.bezierVertex(-20, -40, -40, -70, -60, -80);
    p.endShape(p.CLOSE);
    p.pop();

    // Right chamber
    p.push();
    p.translate(chamberSeparation, 0);
    p.beginShape();
    p.vertex(60, -80);
    p.bezierVertex(90, -60, 90, 60, 30, 90);
    p.bezierVertex(0, 100, -20, 80, 0, 0);
    p.bezierVertex(20, -40, 40, -70, 60, -80);
    p.endShape(p.CLOSE);
    p.pop();

    // Central division - the septum that creates the split
    p.stroke(200, 180, 160, 255);
    p.strokeWeight(6);
    p.line(0, -70, 0, 90);

    // Architectural connectors
    p.stroke(160, 140, 120, 180);
    p.strokeWeight(2);
    p.line(-chamberSeparation * 0.7, -40, chamberSeparation * 0.7, -40);
    p.line(-chamberSeparation * 0.5, 20, chamberSeparation * 0.5, 20);
    p.line(-chamberSeparation * 0.3, 60, chamberSeparation * 0.3, 60);

    p.pop();

    // Animate blood cells with chamber-specific behavior
    for (let cell of bloodCells) {
      cell.angle += 0.02;

      // Different flow patterns for each chamber
      if (cell.chamber === 'left') {
        cell.x += p.cos(cell.angle) * cell.speed;
        cell.y += p.sin(cell.angle * 0.7) * cell.speed * 0.8;
      } else {
        cell.x += p.cos(cell.angle * 1.3) * cell.speed;
        cell.y += p.sin(cell.angle) * cell.speed * 0.9;
      }

      // Boundary behavior - keep cells in their chambers mostly
      let centerX = cell.chamber === 'left' ? 150 : 250;
      if (p.dist(cell.x, cell.y, centerX, 300) > 120) {
        cell.x = p.lerp(cell.x, centerX + p.random(-80, 80), 0.1);
        cell.y = p.lerp(cell.y, 300 + p.random(-100, 100), 0.1);
      }

      // Wrap around canvas
      if (cell.x < 0) cell.x = 400;
      if (cell.x > 400) cell.x = 0;
      if (cell.y < 0) cell.y = 600;
      if (cell.y > 600) cell.y = 0;

      // Draw blood cells
      let cellColor = cell.chamber === 'left' ? 
        [180, 60, 80, cell.opacity] : 
        [140, 80, 120, cell.opacity];

      p.fill(cellColor[0], cellColor[1], cellColor[2], cellColor[3]);
      p.noStroke();
      p.ellipse(cell.x, cell.y, cell.size + p.sin(heartPulse * 2) * 2, cell.size + p.sin(heartPulse * 2) * 2);
    }

    // Interactive response - clicking creates momentary unity pulse
    if (p.mouseIsPressed) {
      p.push();
      p.translate(200, 300);
      p.noFill();
      p.stroke(255, 200, 150, 100);
      p.strokeWeight(3);
      let unityRadius = p.map(p.sin(p.millis() * 0.02), -1, 1, 100, 150);
      p.ellipse(0, 0, unityRadius, unityRadius);
      p.pop();
    }

    // Subtle energy field around the division point
    p.push();
    p.translate(200, 300);
    p.noFill();
    p.stroke(255, 255, 200, 30);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      let fieldRadius = 80 + i * 20 + p.sin(heartPulse + i) * 10;
      p.ellipse(0, 0, fieldRadius, fieldRadius);
    }
    p.pop();
  };
}

function sketch(p) {
  let organs = [];
  let particles = [];
  let convergencePoint = { x: 200, y: 300 };
  let pulsePhase = 0;
  let emergentStructure = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three distinct organ structures
    organs.push({
      x: 120, y: 150,
      segments: createOrganSegments(120, 150, 8),
      color: p.color(180, 60, 60),
      type: 'branching'
    });

    organs.push({
      x: 280, y: 200,
      segments: createOrganSegments(280, 200, 6),
      color: p.color(120, 80, 80),
      type: 'circular'
    });

    organs.push({
      x: 200, y: 450,
      segments: createOrganSegments(200, 450, 7),
      color: p.color(160, 40, 40),
      type: 'linear'
    });

    // Initialize emergent structure
    for (let i = 0; i < 12; i++) {
      emergentStructure.push({
        angle: (i / 12) * p.TWO_PI,
        radius: 0,
        targetRadius: 40 + i * 8,
        growth: 0
      });
    }
  };

  function createOrganSegments(centerX, centerY, count) {
    let segments = [];
    for (let i = 0; i < count; i++) {
      let angle = (i / count) * p.TWO_PI;
      let distance = 30 + p.random(20);
      segments.push({
        x: centerX + p.cos(angle) * distance,
        y: centerY + p.sin(angle) * distance,
        size: 8 + p.random(12),
        phase: p.random(p.TWO_PI)
      });
    }
    return segments;
  }

  p.draw = function() {
    p.background(25, 20, 30);

    pulsePhase += 0.03;
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, convergencePoint.x, convergencePoint.y) / 200;
    let intensity = 1 + (1 - p.constrain(mouseInfluence, 0, 1)) * 0.5;

    // Draw connection lines with energy flow
    drawEnergeticConnections(intensity);

    // Draw the three organs
    organs.forEach((organ, index) => {
      drawOrgan(organ, index, intensity);

      // Generate particles moving toward convergence
      if (p.frameCount % (10 - Math.floor(intensity * 3)) === index * 3) {
        particles.push({
          x: organ.x + p.random(-20, 20),
          y: organ.y + p.random(-20, 20),
          targetX: convergencePoint.x,
          targetY: convergencePoint.y,
          color: organ.color,
          life: 1,
          size: 3 + p.random(4)
        });
      }
    });

    // Update and draw particles
    updateParticles();

    // Draw emergent structure at convergence
    drawEmergentStructure(intensity);

    // Clean up old particles
    particles = particles.filter(particle => particle.life > 0);
  };

  function drawOrgan(organ, index, intensity) {
    p.push();
    p.translate(organ.x, organ.y);

    // Organ core with architectural elements
    p.fill(organ.color.toString());
    p.stroke(255, 100);
    p.strokeWeight(2);

    let coreSize = 25 + p.sin(pulsePhase + index) * 5 * intensity;
    p.ellipse(0, 0, coreSize, coreSize);

    // Draw organ segments with biological/architectural feel
    organ.segments.forEach((segment, i) => {
      let segmentIntensity = intensity + p.sin(pulsePhase * 2 + segment.phase) * 0.3;

      p.stroke(p.red(organ.color) + 30, p.green(organ.color) + 20, p.blue(organ.color) + 20, 150);
      p.strokeWeight(1 + segmentIntensity);
      p.line(0, 0, segment.x - organ.x, segment.y - organ.y);

      // Segment nodes
      p.fill(p.red(organ.color) + 40, p.green(organ.color) + 30, p.blue(organ.color) + 30);
      p.noStroke();
      let nodeSize = segment.size * segmentIntensity;

      if (organ.type === 'branching' && i % 2 === 0) {
        p.rect(segment.x - organ.x - nodeSize/2, segment.y - organ.y - nodeSize/2, nodeSize, nodeSize/2);
      } else if (organ.type === 'circular') {
        p.ellipse(segment.x - organ.x, segment.y - organ.y, nodeSize, nodeSize);
      } else {
        p.triangle(
          segment.x - organ.x, segment.y - organ.y - nodeSize/2,
          segment.x - organ.x - nodeSize/2, segment.y - organ.y + nodeSize/2,
          segment.x - organ.x + nodeSize/2, segment.y - organ.y + nodeSize/2
        );
      }
    });

    p.pop();
  }

  function drawEnergeticConnections(intensity) {
    organs.forEach((organ, i) => {
      let flowPhase = pulsePhase + i * p.TWO_PI / 3;

      p.stroke(100 + intensity * 50, 60 + intensity * 40, 80 + intensity * 60, 80);
      p.strokeWeight(2 + intensity);

      // Curved energy lines to convergence point
      p.noFill();
      p.beginShape();
      p.vertex(organ.x, organ.y);

      let midX = p.lerp(organ.x, convergencePoint.x, 0.5) + p.sin(flowPhase) * 30;
      let midY = p.lerp(organ.y, convergencePoint.y, 0.5) + p.cos(flowPhase) * 20;

      p.quadraticVertex(midX, midY, convergencePoint.x, convergencePoint.y);
      p.endShape();
    });
  }

  function updateParticles() {
    particles.forEach(particle => {
      // Move toward convergence with slight randomness
      particle.x = p.lerp(particle.x, particle.targetX + p.sin(p.frameCount * 0.1) * 10, 0.08);
      particle.y = p.lerp(particle.y, particle.targetY + p.cos(p.frameCount * 0.1) * 10, 0.08);

      particle.life -= 0.015;

      // Draw particle
      p.fill(p.red(particle.color) + 30, p.green(particle.color) + 20, p.blue(particle.color) + 20, particle.life * 255);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size * particle.life, particle.size * particle.life);
    });
  }

  function drawEmergentStructure(intensity) {
    p.push();
    p.translate(convergencePoint.x, convergencePoint.y);

    // Central emergent core
    let coreGlow = 30 + intensity * 20 + p.sin(pulsePhase * 2) * 10;

    // Glowing center
    for (let i = 0; i < 3; i++) {
      p.fill(200 - i * 30, 100 - i * 20, 120 - i * 25, 100 - i * 30);
      p.noStroke();
      p.ellipse(0, 0, coreGlow + i * 15, coreGlow + i * 15);
    }

    // Emergent structural elements
    emergentStructure.forEach((element, i) => {
      element.growth = p.lerp(element.growth, intensity, 0.05);
      element.radius = element.targetRadius * element.growth;

      let x = p.cos(element.angle + pulsePhase * 0.5) * element.radius;
      let y = p.sin(element.angle + pulsePhase * 0.5) * element.radius;

      // Emergent nodes
      p.fill(180 + element.growth * 40, 80 + element.growth * 30, 100 + element.growth * 35, 200);
      p.stroke(255, 150);
      p.strokeWeight(1);

      let nodeSize = 6 + element.growth * 8 + p.sin(pulsePhase * 3 + i) * 2;

      // Mix of geometric forms representing synthesis
      if (i % 3 === 0) {
        p.rect(x - nodeSize/2, y - nodeSize/2, nodeSize, nodeSize);
      } else if (i % 3 === 1) {
        p.ellipse(x, y, nodeSize, nodeSize);
      } else {
        p.triangle(x, y - nodeSize/2, x - nodeSize/2, y + nodeSize/2, x + nodeSize/2, y + nodeSize/2);
      }

      // Connection to center
      p.stroke(150 + element.growth * 50, 70 + element.growth * 30, 90 + element.growth * 40, 120);
      p.strokeWeight(1 + element.growth);
      p.line(0, 0, x, y);
    });

    p.pop();
  }

  p.mousePressed = function() {
    // Pulse effect on click
    pulsePhase += p.PI / 4;

    // Add burst of particles
    for (let i = 0; i < 15; i++) {
      let angle = p.random(p.TWO_PI);
      let distance = p.random(20, 60);
      particles.push({
        x: convergencePoint.x + p.cos(angle) * distance,
        y: convergencePoint.y + p.sin(angle) * distance,
        targetX: convergencePoint.x,
        targetY: convergencePoint.y,
        color: p.color(p.random(150, 200), p.random(60, 100), p.random(80, 120)),
        life: 1,
        size: 2 + p.random(3)
      });
    }
  };
}

function sketch(p) {
  let heartbeat = 0;
  let pillars = [];
  let chambers = [];
  let stabilityParticles = [];
  let foundationPulse = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize four main pillars
    for (let i = 0; i < 4; i++) {
      let angle = (i * p.PI / 2) - p.PI / 4;
      pillars.push({
        x: 200 + p.cos(angle) * 120,
        y: 300 + p.sin(angle) * 80,
        strength: 0.8 + p.random(0.4),
        pulse: p.random(p.TWO_PI)
      });
    }

    // Initialize four heart chambers
    chambers.push({ x: 180, y: 280, size: 40, phase: 0 });
    chambers.push({ x: 220, y: 280, size: 40, phase: p.PI / 2 });
    chambers.push({ x: 180, y: 320, size: 40, phase: p.PI });
    chambers.push({ x: 220, y: 320, size: 40, phase: 3 * p.PI / 2 });

    // Stability particles
    for (let i = 0; i < 60; i++) {
      stabilityParticles.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        vx: 0,
        vy: 0,
        anchor: p.random(4),
        life: p.random(1)
      });
    }
  };

  p.draw = function() {
    p.background(25, 20, 35);

    heartbeat += 0.08;
    foundationPulse += 0.05;

    // Draw foundation grid
    p.stroke(80, 60, 70, 120);
    p.strokeWeight(1);
    for (let i = 0; i < 5; i++) {
      for (let j = 0; j < 7; j++) {
        let x = 80 + i * 60;
        let y = 80 + j * 70;
        let pulse = p.sin(foundationPulse + i * 0.3 + j * 0.2) * 0.2 + 0.8;
        p.stroke(80 * pulse, 60 * pulse, 70 * pulse, 120);
        p.line(x - 10, y, x + 10, y);
        p.line(x, y - 10, x, y + 10);
      }
    }

    // Draw connecting beams between pillars
    p.stroke(160, 120, 140, 180);
    p.strokeWeight(3);
    for (let i = 0; i < 4; i++) {
      let next = (i + 1) % 4;
      let strength1 = pillars[i].strength * (0.8 + 0.2 * p.sin(heartbeat + pillars[i].pulse));
      let strength2 = pillars[next].strength * (0.8 + 0.2 * p.sin(heartbeat + pillars[next].pulse));
      p.stroke(160 * strength1, 120 * strength1, 140 * strength1, 180);
      p.line(pillars[i].x, pillars[i].y, pillars[next].x, pillars[next].y);
    }

    // Draw diagonal bracing
    p.stroke(140, 100, 120, 120);
    p.strokeWeight(2);
    p.line(pillars[0].x, pillars[0].y, pillars[2].x, pillars[2].y);
    p.line(pillars[1].x, pillars[1].y, pillars[3].x, pillars[3].y);

    // Draw the four main structural pillars
    for (let i = 0; i < 4; i++) {
      let pillar = pillars[i];
      let pulse = 0.8 + 0.2 * p.sin(heartbeat + pillar.pulse);
      let size = 25 * pulse * pillar.strength;

      // Pillar core
      p.fill(200 * pulse, 80 * pulse, 100 * pulse, 220);
      p.noStroke();
      p.ellipse(pillar.x, pillar.y, size);

      // Pillar glow
      p.fill(255, 120, 140, 60 * pulse);
      p.ellipse(pillar.x, pillar.y, size * 1.5);

      // Structural detail
      p.stroke(255, 160, 180, 180);
      p.strokeWeight(2);
      p.noFill();
      p.ellipse(pillar.x, pillar.y, size * 0.6);
    }

    // Draw heart chambers in center
    p.push();
    p.translate(200, 300);

    for (let i = 0; i < 4; i++) {
      let chamber = chambers[i];
      let beat = p.sin(heartbeat * 2 + chamber.phase) * 0.3 + 0.7;
      let x = chamber.x - 200;
      let y = chamber.y - 300;

      // Chamber wall
      p.fill(180 * beat, 60 * beat, 80 * beat, 200);
      p.noStroke();
      p.ellipse(x, y, chamber.size * beat);

      // Chamber cavity
      p.fill(120, 40, 50, 150);
      p.ellipse(x, y, chamber.size * beat * 0.6);

      // Flow lines between chambers
      if (i < 2) {
        p.stroke(200, 100, 120, 100 * beat);
        p.strokeWeight(3);
        let nextChamber = chambers[i + 2];
        let nx = nextChamber.x - 200;
        let ny = nextChamber.y - 300;
        p.line(x, y, nx, ny);
      }
    }
    p.pop();

    // Update and draw stability particles
    for (let particle of stabilityParticles) {
      let anchorPillar = pillars[Math.floor(particle.anchor)];
      let dx = anchorPillar.x - particle.x;
      let dy = anchorPillar.y - particle.y;
      let dist = p.sqrt(dx * dx + dy * dy);

      if (dist > 100) {
        particle.vx += dx * 0.0001;
        particle.vy += dy * 0.0001;
      }

      particle.vx *= 0.98;
      particle.vy *= 0.98;
      particle.x += particle.vx;
      particle.y += particle.vy;

      particle.life += 0.01;
      let alpha = p.sin(particle.life) * 0.5 + 0.5;

      p.fill(140, 100, 120, alpha * 100);
      p.noStroke();
      p.ellipse(particle.x, particle.y, 3);
    }

    // Mouse interaction - strengthen nearest pillar
    let mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0.8, 1.5);
    for (let pillar of pillars) {
      let mouseDist = p.dist(p.mouseX, p.mouseY, pillar.x, pillar.y);
      if (mouseDist < 80) {
        pillar.strength = p.lerp(pillar.strength, mouseInfluence, 0.1);
      } else {
        pillar.strength = p.lerp(pillar.strength, 1.0, 0.05);
      }
    }

    // Structural integrity visualization
    let avgStrength = pillars.reduce((sum, p) => sum + p.strength, 0) / 4;
    p.fill(255, 200, 220, 30 * avgStrength);
    p.noStroke();
    p.rect(0, 0, 400, 600);
  };
}

function sketch(p) {
  let cells = [];
  let cracks = [];
  let time = 0;
  let stressLevel = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create organic cellular structure
    for (let i = 0; i < 5; i++) {
      cells.push({
        x: p.random(80, 320),
        y: p.random(100, 500),
        size: p.random(60, 120),
        health: p.random(0.3, 1.0),
        pulsing: p.random(0.02, 0.05),
        connections: [],
        fragments: []
      });
    }

    // Create connections between cells
    for (let i = 0; i < cells.length; i++) {
      for (let j = i + 1; j < cells.length; j++) {
        let dist = p.dist(cells[i].x, cells[i].y, cells[j].x, cells[j].y);
        if (dist < 150) {
          cells[i].connections.push(j);
        }
      }
    }

    // Initialize crack system
    for (let i = 0; i < 8; i++) {
      cracks.push({
        x: p.random(50, 350),
        y: p.random(50, 550),
        angle: p.random(p.TWO_PI),
        length: 0,
        maxLength: p.random(40, 80),
        speed: p.random(0.5, 1.5),
        active: false,
        startTime: p.random(120, 300)
      });
    }
  };

  p.draw = function() {
    time++;

    // Dynamic background with stress visualization
    let bgStress = p.map(p.sin(time * 0.02), -1, 1, 0.1, 0.3);
    p.background(20 + bgStress * 80, 15 + bgStress * 40, 25 + bgStress * 60);

    // Update stress level based on mouse proximity
    let mouseStress = 0;
    for (let cell of cells) {
      let d = p.dist(p.mouseX, p.mouseY, cell.x, cell.y);
      if (d < 100) {
        mouseStress = p.max(mouseStress, p.map(d, 0, 100, 1, 0));
      }
    }
    stressLevel = p.lerp(stressLevel, mouseStress, 0.05);

    // Draw connections between cells (showing stress)
    p.stroke(120 + stressLevel * 100, 40 + stressLevel * 60, 50 + stressLevel * 80, 150);
    p.strokeWeight(1 + stressLevel * 2);

    for (let i = 0; i < cells.length; i++) {
      let cell = cells[i];
      for (let connIndex of cell.connections) {
        let other = cells[connIndex];
        let connectionHealth = (cell.health + other.health) / 2;

        // Stressed connections become jagged
        let steps = p.floor(4 + stressLevel * 6);
        let distortion = stressLevel * 15;

        p.beginShape();
        p.noFill();
        for (let t = 0; t <= 1; t += 1/steps) {
          let x = p.lerp(cell.x, other.x, t);
          let y = p.lerp(cell.y, other.y, t);

          if (t > 0 && t < 1) {
            x += p.sin(time * 0.1 + t * p.PI * 3) * distortion * connectionHealth;
            y += p.cos(time * 0.07 + t * p.PI * 2) * distortion * connectionHealth;
          }

          p.vertex(x, y);
        }
        p.endShape();
      }
    }

    // Draw and update cells
    for (let i = 0; i < cells.length; i++) {
      let cell = cells[i];

      // Cell health deteriorates under stress
      if (stressLevel > 0.5) {
        cell.health = p.max(0.1, cell.health - 0.002);
      } else if (cell.health < 0.8) {
        cell.health += 0.001; // Slow recovery
      }

      // Pulsing effect
      let pulse = 1 + p.sin(time * cell.pulsing) * 0.1 * cell.health;
      let currentSize = cell.size * pulse;

      // Cell color based on health and stress
      let r = 180 - cell.health * 100 + stressLevel * 80;
      let g = 60 + cell.health * 40 - stressLevel * 30;
      let b = 70 + cell.health * 30 - stressLevel * 40;

      // Draw cell membrane
      p.fill(r, g, b, 120 + cell.health * 100);
      p.stroke(r + 40, g + 20, b + 30, 200);
      p.strokeWeight(2 + stressLevel * 3);

      p.push();
      p.translate(cell.x, cell.y);

      // Distorted cell shape under stress
      p.beginShape();
      let vertices = 12;
      for (let angle = 0; angle < p.TWO_PI; angle += p.TWO_PI / vertices) {
        let radius = currentSize / 2;
        let distortion = 1 + p.sin(angle * 2 + time * 0.05) * stressLevel * 0.3;
        let x = p.cos(angle) * radius * distortion;
        let y = p.sin(angle) * radius * distortion;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Internal organelles under stress
      if (cell.health > 0.3) {
        p.fill(r + 30, g + 15, b + 20, 80);
        p.noStroke();
        for (let j = 0; j < 3; j++) {
          let orgX = p.sin(time * 0.03 + j) * currentSize * 0.2;
          let orgY = p.cos(time * 0.04 + j) * currentSize * 0.15;
          let orgSize = currentSize * 0.15 * cell.health;
          p.ellipse(orgX, orgY, orgSize, orgSize);
        }
      }

      p.pop();

      // Generate cell fragments when severely damaged
      if (cell.health < 0.4 && p.random() < 0.02) {
        cell.fragments.push({
          x: cell.x + p.random(-20, 20),
          y: cell.y + p.random(-20, 20),
          vx: p.random(-2, 2),
          vy: p.random(-2, 2),
          life: 60,
          size: p.random(3, 8)
        });
      }
    }

    // Draw and update fragments
    for (let cell of cells) {
      for (let i = cell.fragments.length - 1; i >= 0; i--) {
        let frag = cell.fragments[i];

        frag.x += frag.vx;
        frag.y += frag.vy;
        frag.life--;
        frag.vy += 0.1; // gravity

        let alpha = p.map(frag.life, 0, 60, 0, 255);
        p.fill(200, 80, 90, alpha);
        p.noStroke();
        p.ellipse(frag.x, frag.y, frag.size, frag.size);

        if (frag.life <= 0) {
          cell.fragments.splice(i, 1);
        }
      }
    }

    // Draw and update cracks
    for (let crack of cracks) {
      if (time > crack.startTime) {
        crack.active = true;
      }

      if (crack.active && crack.length < crack.maxLength) {
        crack.length += crack.speed * (1 + stressLevel);
      }

      if (crack.length > 0) {
        p.stroke(160 + stressLevel * 60, 60 + stressLevel * 40, 70 + stressLevel * 50, 180);
        p.strokeWeight(1 + stressLevel * 2);

        let endX = crack.x + p.cos(crack.angle) * crack.length;
        let endY = crack.y + p.sin(crack.angle) * crack.length;

        // Jagged crack line
        p.beginShape();
        p.noFill();
        let segments = p.floor(crack.length / 10);
        for (let i = 0; i <= segments; i++) {
          let t = i / segments;
          let x = p.lerp(crack.x, endX, t);
          let y = p.lerp(crack.y, endY, t);

          if (i > 0 && i < segments) {
            let offset = p.sin(t * p.PI * 4 + time * 0.1) * stressLevel * 3;
            x += p.cos(crack.angle + p.PI/2) * offset;
            y += p.sin(crack.angle + p.PI/2) * offset;
          }

          p.vertex(x, y);
        }
        p.endShape();
      }
    }

    // Adaptive glow effect during high stress
    if (stressLevel > 0.7) {
      p.drawingContext.shadowBlur = 20;
      p.drawingContext.shadowColor = `rgba(${220}, ${100}, ${120}, 0.5)`;
    } else {
      p.drawingContext.shadowBlur = 0;
    }
  };

  p.mousePressed = function() {
    // Mouse click creates localized disruption
    for (let cell of cells) {
      let d = p.dist(p.mouseX, p.mouseY, cell.x, cell.y);
      if (d < 80) {
        cell.health = p.max(0.1, cell.health - 0.3);

        // Create new cracks from impact point
        for (let i = 0; i < 3; i++) {
          cracks.push({
            x: p.mouseX + p.random(-10, 10),
            y: p.mouseY + p.random(-10, 10),
            angle: p.random(p.TWO_PI),
            length: 0,
            maxLength: p.random(30, 60),
            speed: p.random(1, 2),
            active: true,
            startTime: 0
          });
        }
      }
    }
  };
}

function sketch(p) {
  let organs = [];
  let bridges = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create six organ-like structures
    let positions = [
      {x: 100, y: 150}, {x: 300, y: 150},
      {x: 80, y: 300}, {x: 320, y: 300},
      {x: 120, y: 450}, {x: 280, y: 450}
    ];

    for(let i = 0; i < 6; i++) {
      organs.push({
        x: positions[i].x,
        y: positions[i].y,
        size: p.random(40, 60),
        pulse: p.random(0, p.TWO_PI),
        connections: [],
        type: i % 3 // Different organ types
      });
    }

    // Create bridges between organs
    for(let i = 0; i < organs.length; i++) {
      for(let j = i + 1; j < organs.length; j++) {
        let distance = p.dist(organs[i].x, organs[i].y, organs[j].x, organs[j].y);
        if(distance < 200) {
          bridges.push({
            from: i,
            to: j,
            flow: p.random(0, p.TWO_PI),
            strength: p.map(distance, 80, 200, 1, 0.3)
          });
        }
      }
    }

    // Initialize particles
    for(let i = 0; i < 60; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: 0,
        vy: 0,
        target: p.floor(p.random(bridges.length)),
        progress: p.random(1)
      });
    }
  };

  p.draw = function() {
    // Deep burgundy background with subtle gradient
    for(let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(15, 5, 10), p.color(40, 15, 20), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    time += 0.02;

    // Update and draw bridges first (behind organs)
    p.strokeWeight(2);
    for(let bridge of bridges) {
      let org1 = organs[bridge.from];
      let org2 = organs[bridge.to];

      // Animated flow along bridges
      let flowIntensity = 0.5 + 0.5 * p.sin(time + bridge.flow);
      let alpha = 100 + 100 * flowIntensity * bridge.strength;

      // Create organic curved connection
      p.noFill();
      p.stroke(180, 60, 80, alpha);

      let midX = (org1.x + org2.x) / 2 + 30 * p.sin(time * 0.5 + bridge.flow);
      let midY = (org1.y + org2.y) / 2 + 20 * p.cos(time * 0.7 + bridge.flow);

      p.bezier(org1.x, org1.y, midX, midY, midX, midY, org2.x, org2.y);

      // Flow indicators
      let flowPos = 0.5 + 0.3 * p.sin(time * 2 + bridge.flow);
      let flowX = p.lerp(org1.x, org2.x, flowPos);
      let flowY = p.lerp(org1.y, org2.y, flowPos);

      p.fill(220, 100, 120, alpha);
      p.noStroke();
      p.circle(flowX, flowY, 4);
    }

    // Update and draw particles
    for(let particle of particles) {
      if(particle.target < bridges.length) {
        let bridge = bridges[particle.target];
        let org1 = organs[bridge.from];
        let org2 = organs[bridge.to];

        particle.progress += 0.008;
        if(particle.progress > 1) {
          particle.progress = 0;
          particle.target = p.floor(p.random(bridges.length));
        }

        particle.x = p.lerp(org1.x, org2.x, particle.progress);
        particle.y = p.lerp(org1.y, org2.y, particle.progress);

        p.fill(255, 120, 140, 150);
        p.noStroke();
        p.circle(particle.x, particle.y, 2);
      }
    }

    // Draw organs
    for(let i = 0; i < organs.length; i++) {
      let organ = organs[i];
      let mouseDistance = p.dist(p.mouseX, p.mouseY, organ.x, organ.y);
      let excitement = p.map(p.constrain(mouseDistance, 0, 100), 100, 0, 0, 1);

      let pulseSize = organ.size + 8 * p.sin(time * 2 + organ.pulse) + excitement * 10;

      // Organ shadow
      p.fill(20, 0, 10, 100);
      p.noStroke();
      p.circle(organ.x + 3, organ.y + 3, pulseSize);

      // Main organ body
      if(organ.type === 0) {
        // Circular organs
        p.fill(160, 40, 60, 200);
        p.stroke(120, 80, 90);
        p.strokeWeight(2);
        p.circle(organ.x, organ.y, pulseSize);

        // Inner structure
        p.fill(200, 80, 100, 150);
        p.noStroke();
        p.circle(organ.x, organ.y, pulseSize * 0.6);

      } else if(organ.type === 1) {
        // Hexagonal organs
        p.fill(140, 50, 70, 200);
        p.stroke(100, 70, 80);
        p.strokeWeight(2);
        p.push();
        p.translate(organ.x, organ.y);
        p.rotate(time * 0.5);
        p.beginShape();
        for(let a = 0; a < p.TWO_PI; a += p.TWO_PI/6) {
          let x = p.cos(a) * pulseSize/2;
          let y = p.sin(a) * pulseSize/2;
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
        p.pop();

      } else {
        // Oval organs
        p.fill(180, 30, 50, 200);
        p.stroke(140, 60, 70);
        p.strokeWeight(2);
        p.push();
        p.translate(organ.x, organ.y);
        p.rotate(p.sin(time + organ.pulse) * 0.3);
        p.ellipse(0, 0, pulseSize, pulseSize * 0.7);
        p.pop();
      }

      // Connection points
      for(let j = 0; j < bridges.length; j++) {
        let bridge = bridges[j];
        if(bridge.from === i || bridge.to === i) {
          let angle = p.atan2(
            organs[bridge.from === i ? bridge.to : bridge.from].y - organ.y,
            organs[bridge.from === i ? bridge.to : bridge.from].x - organ.x
          );
          let connX = organ.x + p.cos(angle) * (pulseSize/2 - 5);
          let connY = organ.y + p.sin(angle) * (pulseSize/2 - 5);

          p.fill(255, 150, 170, 180 + 60 * p.sin(time * 3 + j));
          p.noStroke();
          p.circle(connX, connY, 6);
        }
      }
    }

    // Interactive glow effect
    if(p.mouseX > 0 && p.mouseX < 400 && p.mouseY > 0 && p.mouseY < 600) {
      p.fill(255, 100, 120, 30);
      p.noStroke();
      p.circle(p.mouseX, p.mouseY, 60);

      // Enhance nearby connections
      for(let bridge of bridges) {
        let org1 = organs[bridge.from];
        let org2 = organs[bridge.to];
        let midX = (org1.x + org2.x) / 2;
        let midY = (org1.y + org2.y) / 2;
        let distance = p.dist(p.mouseX, p.mouseY, midX, midY);

        if(distance < 80) {
          p.stroke(255, 180, 200, 100);
          p.strokeWeight(3);
          p.line(org1.x, org1.y, org2.x, org2.y);
        }
      }
    }
  };

  p.mousePressed = function() {
    // Add burst of particles on click
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: 0,
        vy: 0,
        target: p.floor(p.random(bridges.length)),
        progress: p.random(1)
      });
    }

    // Remove excess particles
    if(particles.length > 100) {
      particles.splice(0, particles.length - 100);
    }
  };
}

function sketch(p) {
  let organs = [];
  let pulseTime = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create seven nested organ structures
    for(let i = 0; i < 7; i++) {
      organs.push({
        x: 200 + p.cos(i * p.TWO_PI / 7) * (60 + i * 15),
        y: 300 + p.sin(i * p.TWO_PI / 7) * (60 + i * 15),
        size: 80 - i * 8,
        phase: i * p.PI / 3,
        chambers: [],
        selfMap: []
      });

      // Each organ contains smaller versions of the whole pattern
      for(let j = 0; j < 7; j++) {
        organs[i].chambers.push({
          angle: j * p.TWO_PI / 7,
          dist: organs[i].size * 0.3,
          pulse: p.random(p.TWO_PI)
        });

        // Self-referential mapping within each organ
        organs[i].selfMap.push({
          x: p.cos(j * p.TWO_PI / 7) * organs[i].size * 0.15,
          y: p.sin(j * p.TWO_PI / 7) * organs[i].size * 0.15,
          reflection: i
        });
      }
    }
  };

  p.draw = function() {
    p.background(25, 15, 30);
    pulseTime += 0.02;

    // Mouse influence creates ripples of self-awareness
    let mouseX = p.constrain(p.mouseX, 0, 400);
    let mouseY = p.constrain(p.mouseY, 0, 600);
    mouseInfluence = p.map(p.dist(mouseX, mouseY, 200, 300), 0, 300, 1, 0);
    mouseInfluence = p.max(0, mouseInfluence);

    // Draw connection web between organs
    p.stroke(120, 40, 60, 80);
    p.strokeWeight(1);
    for(let i = 0; i < organs.length; i++) {
      for(let j = i + 1; j < organs.length; j++) {
        let pulse1 = p.sin(pulseTime + organs[i].phase) * 0.3 + 0.7;
        let pulse2 = p.sin(pulseTime + organs[j].phase) * 0.3 + 0.7;
        let connection = pulse1 * pulse2 * mouseInfluence;

        p.stroke(160, 60, 80, connection * 120);
        p.line(organs[i].x, organs[i].y, organs[j].x, organs[j].y);
      }
    }

    // Draw each organ with its self-referential structure
    for(let i = 0; i < organs.length; i++) {
      let organ = organs[i];
      let pulse = p.sin(pulseTime + organ.phase) * 0.2 + 0.8;
      let awareness = mouseInfluence * p.sin(pulseTime * 2 + i) * 0.3 + 0.7;

      p.push();
      p.translate(organ.x, organ.y);
      p.rotate(pulseTime * 0.1 + i * 0.3);

      // Main organ boundary
      p.stroke(180, 80, 100, 200);
      p.strokeWeight(2);
      p.fill(80 + awareness * 60, 25 + awareness * 40, 40 + awareness * 50, 180);
      p.ellipse(0, 0, organ.size * pulse, organ.size * pulse);

      // Internal chambers that reflect the whole pattern
      for(let j = 0; j < organ.chambers.length; j++) {
        let chamber = organ.chambers[j];
        let chamberPulse = p.sin(pulseTime * 1.5 + chamber.pulse) * 0.15 + 0.85;
        let chamberX = p.cos(chamber.angle) * chamber.dist * pulse;
        let chamberY = p.sin(chamber.angle) * chamber.dist * pulse;

        p.push();
        p.translate(chamberX, chamberY);

        // Each chamber contains a micro-version of the organ pattern
        p.fill(120 + awareness * 80, 40 + awareness * 60, 60 + awareness * 40, 150);
        p.stroke(200, 100, 120, 180);
        p.strokeWeight(1);
        p.ellipse(0, 0, 15 * chamberPulse, 15 * chamberPulse);

        // Tiny self-referential elements
        for(let k = 0; k < 3; k++) {
          let microX = p.cos(k * p.TWO_PI / 3) * 4;
          let microY = p.sin(k * p.TWO_PI / 3) * 4;
          p.fill(160, 80, 90, awareness * 255);
          p.noStroke();
          p.ellipse(microX, microY, 2, 2);
        }
        p.pop();
      }

      // Self-mapping visualization - the organ's awareness of itself
      for(let j = 0; j < organ.selfMap.length; j++) {
        let mapPoint = organ.selfMap[j];
        let mapPulse = p.sin(pulseTime * 2 + j + mapPoint.reflection) * 0.2 + 0.8;

        p.push();
        p.translate(mapPoint.x * pulse, mapPoint.y * pulse);

        // Recursive reflection visualization
        p.stroke(220, 120, 140, awareness * 200);
        p.strokeWeight(0.5);
        p.noFill();

        for(let layer = 0; layer < 3; layer++) {
          let layerSize = (3 - layer) * 3 * mapPulse;
          p.ellipse(0, 0, layerSize, layerSize);
        }

        // Central awareness point
        p.fill(255, 150, 180, awareness * 255);
        p.noStroke();
        p.ellipse(0, 0, 1.5 * mapPulse, 1.5 * mapPulse);
        p.pop();
      }

      // Center of consciousness - the organ's self-recognition
      p.fill(255, 180, 200, awareness * 200);
      p.noStroke();
      let centerPulse = p.sin(pulseTime * 3 + organ.phase) * 2 + 4;
      p.ellipse(0, 0, centerPulse, centerPulse);

      p.pop();
    }

    // Overlay reflection patterns
    if(mouseInfluence > 0.3) {
      p.push();
      p.translate(200, 300);
      p.rotate(pulseTime * 0.2);

      p.stroke(255, 200, 220, mouseInfluence * 60);
      p.strokeWeight(0.5);
      p.noFill();

      for(let ring = 1; ring <= 5; ring++) {
        let ringSize = ring * 40 * (p.sin(pulseTime + ring) * 0.1 + 0.9);
        p.ellipse(0, 0, ringSize, ringSize);

        // Reflection markers
        for(let mark = 0; mark < 7; mark++) {
          let markX = p.cos(mark * p.TWO_PI / 7) * ringSize * 0.5;
          let markY = p.sin(mark * p.TWO_PI / 7) * ringSize * 0.5;
          p.point(markX, markY);
        }
      }
      p.pop();
    }
  };
}

function sketch(p) {
  let organZones = [];
  let pulseTime = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create eight zones of accumulating organization
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let radius = 120 + (i % 2) * 40;
      let x = 200 + p.cos(angle) * radius;
      let y = 300 + p.sin(angle) * radius;

      organZones.push({
        x: x,
        y: y,
        baseSize: 30 + i * 8,
        currentSize: 30 + i * 8,
        cells: [],
        intensity: 0.5 + (i / 8) * 0.5,
        growthRate: 0.02 + i * 0.01,
        connections: []
      });

      // Generate cellular structures for each zone
      for (let j = 0; j < 20 + i * 5; j++) {
        let cellAngle = p.random(p.TWO_PI);
        let cellDist = p.random(organZones[i].baseSize * 0.8);
        organZones[i].cells.push({
          x: p.cos(cellAngle) * cellDist,
          y: p.sin(cellAngle) * cellDist,
          size: p.random(2, 6),
          phase: p.random(p.TWO_PI)
        });
      }
    }

    // Create connections between zones
    for (let i = 0; i < organZones.length; i++) {
      for (let j = i + 1; j < organZones.length; j++) {
        if (p.random() < 0.4) {
          organZones[i].connections.push(j);
        }
      }
    }
  };

  p.draw = function() {
    p.background(15, 12, 18);
    pulseTime += 0.03;
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0.5, 2.0);

    // Update zone sizes based on accumulation
    for (let i = 0; i < organZones.length; i++) {
      let zone = organZones[i];
      let targetSize = zone.baseSize * (1 + p.sin(pulseTime + i * 0.3) * 0.3 * zone.intensity);
      targetSize *= mouseInfluence * 0.8;
      zone.currentSize = p.lerp(zone.currentSize, targetSize, zone.growthRate);
    }

    // Draw connections between zones (structural network)
    p.stroke(80, 60, 70, 100);
    p.strokeWeight(1);
    for (let i = 0; i < organZones.length; i++) {
      let zone = organZones[i];
      for (let connection of zone.connections) {
        let targetZone = organZones[connection];
        let opacity = p.map(p.sin(pulseTime * 2 + i), -1, 1, 30, 120);
        p.stroke(120, 90, 100, opacity);
        p.line(zone.x, zone.y, targetZone.x, targetZone.y);
      }
    }

    // Draw each organ zone
    for (let i = 0; i < organZones.length; i++) {
      let zone = organZones[i];
      p.push();
      p.translate(zone.x, zone.y);

      // Outer boundary (territorialization)
      let boundaryPulse = 1 + p.sin(pulseTime * 1.5 + i * 0.5) * 0.2;
      p.stroke(180, 60, 80, 150);
      p.strokeWeight(2 + zone.intensity * 2);
      p.noFill();
      p.ellipse(0, 0, zone.currentSize * 2 * boundaryPulse);

      // Inner cellular structure
      for (let cell of zone.cells) {
        let cellPulse = p.sin(pulseTime * 3 + cell.phase) * 0.5 + 0.5;
        let cellSize = cell.size * (0.8 + cellPulse * 0.4) * mouseInfluence;

        // Cell body
        p.fill(220 - i * 15, 40 + cellPulse * 30, 60 + i * 10, 200);
        p.noStroke();
        p.ellipse(cell.x, cell.y, cellSize);

        // Cell nucleus
        p.fill(255, 80 + cellPulse * 40, 100 + i * 8, 180);
        p.ellipse(cell.x, cell.y, cellSize * 0.3);
      }

      // Central organizing structure
      let coreSize = zone.currentSize * 0.4;
      let corePulse = p.sin(pulseTime * 2 + i * 0.7) * 0.3 + 0.7;

      p.fill(200, 20, 40, 120);
      p.ellipse(0, 0, coreSize * corePulse);

      p.fill(255, 60, 80, 200);
      p.ellipse(0, 0, coreSize * corePulse * 0.6);

      // Intensity indicators (showing accumulation)
      for (let j = 0; j < 3; j++) {
        let ringRadius = (coreSize * 0.3) + j * 8;
        let ringOpacity = zone.intensity * 100 * (1 - j * 0.2);
        p.stroke(255, 100 + j * 20, 120, ringOpacity);
        p.strokeWeight(1);
        p.noFill();
        p.ellipse(0, 0, ringRadius * 2 * corePulse);
      }

      p.pop();
    }

    // Overlay structural grid (architectural element)
    p.stroke(60, 50, 55, 80);
    p.strokeWeight(0.5);
    for (let x = 0; x < 400; x += 50) {
      p.line(x, 0, x, 600);
    }
    for (let y = 0; y < 600; y += 50) {
      p.line(0, y, 400, y);
    }

    // Central accumulation point
    p.push();
    p.translate(200, 300);
    let centralPulse = p.sin(pulseTime * 1.2) * 0.4 + 0.6;
    p.fill(255, 40, 60, 60 * centralPulse);
    p.noStroke();
    p.ellipse(0, 0, 80 * centralPulse * mouseInfluence);
    p.pop();
  };

  p.mousePressed = function() {
    // Trigger growth burst in nearest zone
    let minDist = Infinity;
    let nearestZone = 0;
    for (let i = 0; i < organZones.length; i++) {
      let dist = p.dist(p.mouseX, p.mouseY, organZones[i].x, organZones[i].y);
      if (dist < minDist) {
        minDist = dist;
        nearestZone = i;
      }
    }
    organZones[nearestZone].intensity = p.min(organZones[nearestZone].intensity + 0.2, 1.5);
  };
}

function sketch(p) {
  let organs = [];
  let transformTime = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create nine organ structures in a 3x3 grid
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        let x = 80 + i * 120;
        let y = 100 + j * 130;
        organs.push(new Organ(x, y, i * 3 + j));
      }
    }
  };

  p.draw = function() {
    p.background(15, 12, 18);

    transformTime += 0.008;
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0, 1);

    // Subtle background tissue texture
    p.noFill();
    p.stroke(40, 25, 35, 80);
    p.strokeWeight(0.5);
    for (let i = 0; i < 20; i++) {
      let x = p.noise(i * 0.1, transformTime * 0.3) * p.width;
      let y = p.noise(i * 0.1 + 100, transformTime * 0.3) * p.height;
      p.circle(x, y, 30 + p.sin(transformTime + i) * 10);
    }

    // Draw connecting tissue between organs
    p.stroke(120, 80, 100, 60);
    p.strokeWeight(1);
    for (let i = 0; i < organs.length - 1; i++) {
      for (let j = i + 1; j < organs.length; j++) {
        let dist = p.dist(organs[i].x, organs[i].y, organs[j].x, organs[j].y);
        if (dist < 150) {
          let alpha = p.map(dist, 0, 150, 80, 10);
          p.stroke(120, 80, 100, alpha);
          p.line(organs[i].x, organs[i].y, organs[j].x, organs[j].y);
        }
      }
    }

    // Update and draw each organ
    organs.forEach(organ => {
      organ.update();
      organ.display();
    });

    // Transformation particles
    if (mouseInfluence > 0.3) {
      for (let i = 0; i < 5; i++) {
        let x = p.random(p.width);
        let y = p.random(p.height);
        p.fill(220, 120, 160, 40);
        p.noStroke();
        p.circle(x, y, p.random(2, 8));
      }
    }
  };

  class Organ {
    constructor(x, y, id) {
      this.x = x;
      this.y = y;
      this.id = id;
      this.baseSize = 35;
      this.transformPhase = id * 0.7; // Each organ transforms at slightly different times
      this.nodes = [];
      this.boundaries = [];

      // Create internal structure nodes
      for (let i = 0; i < 6; i++) {
        this.nodes.push({
          angle: i * p.TWO_PI / 6,
          radius: p.random(8, 20),
          originalRadius: p.random(8, 20),
          phase: p.random(p.TWO_PI)
        });
      }

      // Create boundary points
      for (let i = 0; i < 12; i++) {
        this.boundaries.push({
          angle: i * p.TWO_PI / 12,
          radius: this.baseSize,
          originalRadius: this.baseSize,
          phase: p.random(p.TWO_PI)
        });
      }
    }

    update() {
      let globalTransform = p.sin(transformTime + this.transformPhase) * 0.5 + 0.5;
      let mouseEffect = p.dist(p.mouseX, p.mouseY, this.x, this.y) < 80 ? mouseInfluence : 0;

      // Update internal nodes - they transform more dramatically
      this.nodes.forEach((node, i) => {
        let transform = globalTransform + mouseEffect * 0.5;
        node.radius = p.lerp(node.originalRadius, 
                           node.originalRadius * (1.5 + p.sin(transformTime * 2 + node.phase) * 0.3), 
                           transform);
        node.angle += 0.005 * transform;
      });

      // Update boundary - maintains integrity while shifting
      this.boundaries.forEach((boundary, i) => {
        let transform = globalTransform * 0.7 + mouseEffect * 0.3;
        let variation = p.sin(transformTime * 1.5 + boundary.phase + i * 0.5) * 5;
        boundary.radius = boundary.originalRadius + variation * transform;
      });
    }

    display() {
      p.push();
      p.translate(this.x, this.y);

      let globalTransform = p.sin(transformTime + this.transformPhase) * 0.5 + 0.5;

      // Draw boundary membrane
      p.stroke(180, 120, 140, 150);
      p.strokeWeight(2);
      p.fill(80 + globalTransform * 40, 40 + globalTransform * 30, 50 + globalTransform * 35, 120);

      p.beginShape();
      this.boundaries.forEach(boundary => {
        let x = p.cos(boundary.angle) * boundary.radius;
        let y = p.sin(boundary.angle) * boundary.radius;
        p.vertex(x, y);
      });
      p.endShape(p.CLOSE);

      // Draw internal transforming structure
      this.nodes.forEach((node, i) => {
        let x = p.cos(node.angle) * node.radius;
        let y = p.sin(node.angle) * node.radius;

        // Node color shifts with transformation
        let r = 160 + p.sin(transformTime + i) * 60;
        let g = 60 + p.sin(transformTime + i + 1) * 40;
        let b = 80 + p.sin(transformTime + i + 2) * 50;

        p.fill(r, g, b, 180);
        p.noStroke();
        p.circle(x, y, 6 + globalTransform * 4);

        // Connect to neighboring nodes
        if (i < this.nodes.length - 1) {
          let nextNode = this.nodes[i + 1];
          let nextX = p.cos(nextNode.angle) * nextNode.radius;
          let nextY = p.sin(nextNode.angle) * nextNode.radius;

          p.stroke(r, g, b, 100);
          p.strokeWeight(1 + globalTransform);
          p.line(x, y, nextX, nextY);
        }
      });

      // Central transformation core
      let coreSize = 8 + globalTransform * 6;
      p.fill(220, 140, 170, 200);
      p.noStroke();
      p.circle(0, 0, coreSize);

      // Transformation energy rings
      if (globalTransform > 0.6) {
        for (let i = 0; i < 3; i++) {
          let ringSize = (i + 1) * 15 + globalTransform * 10;
          p.noFill();
          p.stroke(240, 180, 200, 60 - i * 20);
          p.strokeWeight(1);
          p.circle(0, 0, ringSize);
        }
      }

      p.pop();
    }
  }

  p.mousePressed = function() {
    // Trigger transformation wave on click
    organs.forEach((organ, i) => {
      organ.transformPhase += p.random(-0.5, 0.5);
    });
  };
}

function sketch(p) {
  let organs = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create 10 organ-like structures arranged in a gentle spiral
    for(let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI * 2;
      let radius = 80 + i * 15;
      let x = 200 + p.cos(angle) * radius;
      let y = 300 + p.sin(angle) * radius * 0.7;

      organs.push({
        x: x,
        y: y,
        size: 30 + i * 3,
        age: i * 0.3,
        dissolution: 0,
        cells: [],
        veins: []
      });

      // Create cellular structures for each organ
      for(let j = 0; j < 8; j++) {
        let cellAngle = (j / 8) * p.TWO_PI;
        let cellDist = 15 + p.random(-5, 5);
        organs[i].cells.push({
          x: p.cos(cellAngle) * cellDist,
          y: p.sin(cellAngle) * cellDist,
          size: p.random(3, 8),
          phase: p.random(p.TWO_PI)
        });
      }

      // Create vein networks
      for(let k = 0; k < 5; k++) {
        organs[i].veins.push({
          angle: p.random(p.TWO_PI),
          length: p.random(20, 40),
          branches: []
        });
      }
    }
  };

  p.draw = function() {
    // Deep substrate background
    p.background(25, 20, 8);

    // Draw substrate particles floating up from dissolution
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.y -= particle.speed;
      particle.x += p.sin(particle.y * 0.01 + particle.phase) * 0.5;
      particle.life -= 0.8;
      particle.size *= 0.998;

      let alpha = p.map(particle.life, 0, 100, 0, 30);
      p.fill(particle.hue, 60, 80, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      if(particle.life <= 0 || particle.y < 0) {
        particles.splice(i, 1);
      }
    }

    time += 0.01;

    // Draw each organ in its dissolution cycle
    for(let i = 0; i < organs.length; i++) {
      let organ = organs[i];

      // Calculate dissolution based on age and time
      organ.dissolution = p.constrain((time - organ.age) * 0.3, 0, 1);

      p.push();
      p.translate(organ.x, organ.y);

      // Mouse interaction - accelerate dissolution near mouse
      let mouseDistance = p.dist(p.mouseX, p.mouseY, organ.x, organ.y);
      let mouseInfluence = p.map(mouseDistance, 0, 100, 0.02, 0);
      organ.dissolution += mouseInfluence;
      organ.dissolution = p.constrain(organ.dissolution, 0, 1);

      // Draw vein networks dissolving
      p.strokeWeight(1);
      for(let vein of organ.veins) {
        let veinAlpha = (1 - organ.dissolution) * 40;
        p.stroke(0, 80, 90, veinAlpha);

        let endX = p.cos(vein.angle) * vein.length * (1 - organ.dissolution * 0.7);
        let endY = p.sin(vein.angle) * vein.length * (1 - organ.dissolution * 0.7);

        // Main vein with organic curve
        for(let t = 0; t < 1; t += 0.1) {
          let x1 = p.lerp(0, endX, t);
          let y1 = p.lerp(0, endY, t);
          let x2 = p.lerp(0, endX, t + 0.1);
          let y2 = p.lerp(0, endY, t + 0.1);

          // Add organic waviness
          let wave = p.sin(t * 10 + time * 2) * 2 * (1 - organ.dissolution);
          x1 += p.sin(vein.angle + p.PI/2) * wave;
          y1 += p.cos(vein.angle + p.PI/2) * wave;
          x2 += p.sin(vein.angle + p.PI/2) * wave;
          y2 += p.cos(vein.angle + p.PI/2) * wave;

          if(t + 0.1 <= 1 - organ.dissolution) {
            p.line(x1, y1, x2, y2);
          }
        }
      }

      // Draw cellular structures
      for(let cell of organ.cells) {
        let cellX = cell.x * (1 - organ.dissolution * 0.8);
        let cellY = cell.y * (1 - organ.dissolution * 0.8);
        let cellSize = cell.size * (1 - organ.dissolution);

        // Cells pulsing with life, then fading
        let pulse = p.sin(time * 3 + cell.phase) * 0.2 + 1;
        cellSize *= pulse * (1 - organ.dissolution * 0.5);

        // Color transition from vibrant red to earth tones
        let hue = p.lerp(0, 30, organ.dissolution); // red to brown
        let sat = p.lerp(90, 40, organ.dissolution);
        let bright = p.lerp(85, 30, organ.dissolution);
        let alpha = (1 - organ.dissolution) * 70;

        p.fill(hue, sat, bright, alpha);
        p.noStroke();
        p.ellipse(cellX, cellY, cellSize, cellSize);

        // Generate dissolution particles
        if(organ.dissolution > 0.3 && p.random(100) < 2) {
          particles.push({
            x: organ.x + cellX + p.random(-5, 5),
            y: organ.y + cellY + p.random(-5, 5),
            speed: p.random(0.5, 2),
            size: p.random(1, 3),
            life: 100,
            hue: hue,
            phase: p.random(p.TWO_PI)
          });
        }
      }

      // Draw main organ membrane
      let membraneAlpha = (1 - organ.dissolution) * 30;
      let membraneSize = organ.size * (1 + organ.dissolution * 0.3); // slight expansion as it dissolves

      p.stroke(0, 60, 70, membraneAlpha);
      p.strokeWeight(1);
      p.noFill();

      // Organic, slightly irregular shape
      p.beginShape();
      for(let a = 0; a < p.TWO_PI; a += 0.2) {
        let radius = membraneSize + p.sin(a * 3 + time * 2) * 3 * (1 - organ.dissolution);
        let x = p.cos(a) * radius;
        let y = p.sin(a) * radius;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      p.pop();
    }

    // Draw subtle substrate grid emerging
    p.stroke(30, 30, 20, 15);
    p.strokeWeight(0.5);
    let gridSpacing = 40;
    let gridOffset = time * 10;

    for(let x = 0; x < p.width; x += gridSpacing) {
      for(let y = 0; y < p.height; y += gridSpacing) {
        let wave = p.sin((x + y) * 0.01 + time) * 5;
        p.point(x + wave, y + gridOffset % gridSpacing);
      }
    }
  };

  p.mousePressed = function() {
    // Create burst of dissolution particles at mouse location
    for(let i = 0; i < 10; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        speed: p.random(1, 3),
        size: p.random(2, 6),
        life: 120,
        hue: p.random(0, 40),
        phase: p.random(p.TWO_PI)
      });
    }
  };
}

function sketch(p) {
  let mystic;
  let organs = [];
  let structures = [];
  let time = 0;
  let pulsePhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize mystic
    mystic = {
      x: 200,
      y: 300,
      breathing: 0,
      eyeIntensity: 0,
      boundedness: 0
    };

    // Create floating organ forms
    for (let i = 0; i < 8; i++) {
      organs.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(30, 80),
        type: p.floor(p.random(3)),
        phase: p.random(p.TWO_PI),
        connections: []
      });
    }

    // Create architectural structures
    for (let i = 0; i < 12; i++) {
      structures.push({
        x: p.random(400),
        y: p.random(600),
        width: p.random(5, 30),
        height: p.random(20, 100),
        angle: p.random(p.TWO_PI),
        opacity: p.random(20, 60)
      });
    }
  };

  p.draw = function() {
    // Deep red-gray gradient background
    for (let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.3, 0.8);
      let hue = p.map(y, 0, p.height, 0, 15);
      p.stroke(hue, 40, 20, alpha * 100);
      p.line(0, y, p.width, y);
    }

    time += 0.01;
    pulsePhase += 0.03;

    // Update mystic state based on mouse proximity
    let mouseInfluence = p.map(p.dist(p.mouseX, p.mouseY, mystic.x, mystic.y), 0, 200, 1, 0);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);

    mystic.breathing = p.sin(time * 2) * 10 * (1 + mouseInfluence);
    mystic.eyeIntensity = mouseInfluence * 0.7 + 0.3;
    mystic.boundedness = p.map(p.sin(time), -1, 1, 0.3, 0.8) * mouseInfluence + 0.2;

    // Draw architectural structures merging with figure
    p.push();
    for (let struct of structures) {
      p.push();
      p.translate(struct.x, struct.y);
      p.rotate(struct.angle + time * 0.5);

      // Structures bend toward the mystic
      let bendForce = p.map(p.dist(struct.x, struct.y, mystic.x, mystic.y), 0, 200, 0.02, 0);
      let bendAngle = p.atan2(mystic.y - struct.y, mystic.x - struct.x) * bendForce;
      p.rotate(bendAngle);

      p.fill(10, 30, 60, struct.opacity);
      p.noStroke();
      p.rect(-struct.width/2, -struct.height/2, struct.width, struct.height);
      p.pop();
    }
    p.pop();

    // Draw organ forms with pulsing life
    for (let organ of organs) {
      p.push();
      p.translate(organ.x, organ.y);

      let pulse = p.sin(pulsePhase + organ.phase) * 5;
      let organSize = organ.size + pulse;

      // Connection lines to mystic when close
      let dist = p.dist(organ.x, organ.y, mystic.x, mystic.y);
      if (dist < 150) {
        let alpha = p.map(dist, 0, 150, 60, 0);
        p.stroke(0, 60, 80, alpha);
        p.strokeWeight(2);
        p.line(0, 0, mystic.x - organ.x, mystic.y - organ.y);
      }

      p.noStroke();

      // Different organ types
      if (organ.type === 0) {
        // Heart-like
        p.fill(350, 70, 70, 80);
        p.ellipse(-organSize * 0.2, -organSize * 0.2, organSize * 0.6, organSize * 0.8);
        p.ellipse(organSize * 0.2, -organSize * 0.2, organSize * 0.6, organSize * 0.8);
        p.triangle(0, organSize * 0.3, -organSize * 0.4, 0, organSize * 0.4, 0);

        p.fill(350, 90, 90, 60);
        p.ellipse(0, 0, organSize * 0.3, organSize * 0.3);
      } else if (organ.type === 1) {
        // Brain-like
        p.fill(340, 40, 60, 70);
        p.ellipse(0, 0, organSize, organSize * 0.8);

        p.stroke(340, 60, 80, 50);
        p.strokeWeight(1);
        for (let i = 0; i < 6; i++) {
          let angle = i * p.PI / 3;
          p.line(0, 0, 
                p.cos(angle) * organSize * 0.3, 
                p.sin(angle) * organSize * 0.3);
        }
      } else {
        // Vessel-like
        p.fill(10, 50, 50, 60);
        p.ellipse(0, 0, organSize * 0.4, organSize);
        p.ellipse(0, -organSize * 0.3, organSize * 0.6, organSize * 0.4);
        p.ellipse(0, organSize * 0.3, organSize * 0.6, organSize * 0.4);
      }

      p.pop();
    }

    // Draw the mystic figure
    p.push();
    p.translate(mystic.x, mystic.y);

    // Body with breathing
    p.fill(30, 30, 40, 80);
    p.noStroke();
    let bodyWidth = 40 + mystic.breathing * 0.5;
    let bodyHeight = 80 + mystic.breathing;
    p.ellipse(0, 20, bodyWidth, bodyHeight);

    // Arms reaching toward organs
    p.stroke(30, 40, 60, 70);
    p.strokeWeight(8);
    p.strokeCap(p.ROUND);

    let leftArm = p.createVector(-30, 10);
    let rightArm = p.createVector(30, 10);

    // Arms bend toward nearest organs
    let nearestLeft = null, nearestRight = null;
    let minDistLeft = Infinity, minDistRight = Infinity;

    for (let organ of organs) {
      let dist = p.dist(organ.x, organ.y, mystic.x, mystic.y);
      if (organ.x < mystic.x && dist < minDistLeft) {
        nearestLeft = organ;
        minDistLeft = dist;
      } else if (organ.x > mystic.x && dist < minDistRight) {
        nearestRight = organ;
        minDistRight = dist;
      }
    }

    if (nearestLeft) {
      leftArm.x = p.lerp(leftArm.x, nearestLeft.x - mystic.x, 0.1);
      leftArm.y = p.lerp(leftArm.y, nearestLeft.y - mystic.y, 0.1);
      leftArm.mult(0.6);
    }

    if (nearestRight) {
      rightArm.x = p.lerp(rightArm.x, nearestRight.x - mystic.x, 0.1);
      rightArm.y = p.lerp(rightArm.y, nearestRight.y - mystic.y, 0.1);
      rightArm.mult(0.6);
    }

    p.line(0, 0, leftArm.x, leftArm.y);
    p.line(0, 0, rightArm.x, rightArm.y);

    // Head
    p.fill(30, 25, 50, 90);
    p.noStroke();
    p.ellipse(0, -30, 35, 35);

    // Eyes with visionary intensity
    let eyeGlow = mystic.eyeIntensity * 100;
    p.fill(180, 80, 90, eyeGlow);
    p.ellipse(-8, -32, 6 + mystic.eyeIntensity * 4, 8 + mystic.eyeIntensity * 2);
    p.ellipse(8, -32, 6 + mystic.eyeIntensity * 4, 8 + mystic.eyeIntensity * 2);

    // Pupil intensity
    p.fill(200, 100, 100, eyeGlow * 1.2);
    p.ellipse(-8, -32, 2, 3);
    p.ellipse(8, -32, 2, 3);

    // Boundary manifestation - structures growing from/into the figure
    if (mystic.boundedness > 0.4) {
      p.stroke(0, 40, 70, mystic.boundedness * 60);
      p.strokeWeight(2);
      p.noFill();

      // Geometric boundaries emerging from the body
      for (let i = 0; i < 6; i++) {
        let angle = i * p.PI / 3 + time;
        let radius = 30 * mystic.boundedness;
        let x1 = p.cos(angle) * radius;
        let y1 = p.sin(angle) * radius;
        let x2 = p.cos(angle + p.PI/3) * radius;
        let y2 = p.sin(angle + p.PI/3) * radius;
        p.line(x1, y1, x2, y2);
      }
    }

    p.pop();

    // Particle system for direct encounter energy
    if (p.frameCount % 3 === 0) {
      for (let i = 0; i < 2; i++) {
        let particle = {
          x: mystic.x + p.random(-20, 20),
          y: mystic.y + p.random(-20, 20),
          vx: p.random(-1, 1),
          vy: p.random(-2, 0),
          life: 60,
          hue: p.random(340, 20)
        };

        // Add to temporary particle array
        if (!p.particles) p.particles = [];
        p.particles.push(particle);
      }
    }

    // Draw and update particles
    if (p.particles) {
      for (let i = p.particles.length - 1; i >= 0; i--) {
        let particle = p.particles[i];
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.life--;

        let alpha = p.map(particle.life, 0, 60, 0, 70);
        p.fill(particle.hue, 60, 80, alpha);
        p.noStroke();
        p.ellipse(particle.x, particle.y, 3, 3);

        if (particle.life <= 0) {
          p.particles.splice(i, 1);
        }
      }
    }
  };
}

function sketch(p) {
  let organs = [];
  let mapLines = [];
  let cartographer;
  let measurementTools = [];
  let annotations = [];
  let breathPhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the cartographer figure
    cartographer = {
      x: 200,
      y: 350,
      armAngle: 0,
      measuring: false
    };

    // Create organic structures to map
    for (let i = 0; i < 3; i++) {
      organs.push({
        x: 80 + i * 120,
        y: 150 + Math.sin(i) * 40,
        nodes: [],
        mapped: false,
        mapProgress: 0
      });

      // Generate organic node structure for each organ
      let centerX = organs[i].x;
      let centerY = organs[i].y;
      for (let j = 0; j < 8; j++) {
        let angle = (j / 8) * p.TWO_PI;
        let radius = 30 + Math.sin(j * 0.7) * 15;
        organs[i].nodes.push({
          x: centerX + Math.cos(angle) * radius,
          y: centerY + Math.sin(angle) * radius,
          connected: false,
          pulsePhase: j * 0.3
        });
      }
    }

    // Initialize measurement tools
    for (let i = 0; i < 5; i++) {
      measurementTools.push({
        x: 300 + Math.random() * 80,
        y: 450 + Math.random() * 100,
        angle: Math.random() * p.TWO_PI,
        type: Math.floor(Math.random() * 3) // compass, ruler, caliper
      });
    }
  };

  p.draw = function() {
    // Deep burgundy to gray gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(40, 20, 25), p.color(60, 55, 55), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    breathPhase += 0.02;

    // Draw organs with organic pulsing
    for (let organ of organs) {
      p.push();
      p.translate(organ.x, organ.y);

      // Organ body with breathing motion
      let breathScale = 1 + Math.sin(breathPhase) * 0.05;
      p.scale(breathScale);

      p.fill(120, 40, 45, 180);
      p.stroke(160, 60, 65);
      p.strokeWeight(2);

      // Draw organic blob shape
      p.beginShape();
      for (let i = 0; i < organ.nodes.length; i++) {
        let node = organ.nodes[i];
        let nextNode = organ.nodes[(i + 1) % organ.nodes.length];

        if (i === 0) {
          p.vertex(node.x - organ.x, node.y - organ.y);
        }

        let cpx = (node.x + nextNode.x) / 2 - organ.x;
        let cpy = (node.y + nextNode.y) / 2 - organ.y;
        p.quadraticVertex(
          cpx + Math.sin(breathPhase + node.pulsePhase) * 5,
          cpy + Math.cos(breathPhase + node.pulsePhase) * 5,
          nextNode.x - organ.x,
          nextNode.y - organ.y
        );
      }
      p.endShape(p.CLOSE);

      // Draw measurement grid if being mapped
      if (organ.mapped || organ.mapProgress > 0) {
        p.stroke(200, 180, 160, organ.mapProgress * 255);
        p.strokeWeight(1);

        // Grid lines
        for (let i = -2; i <= 2; i++) {
          p.line(i * 15, -40, i * 15, 40);
          p.line(-40, i * 15, 40, i * 15);
        }

        // Measurement points
        p.fill(220, 200, 180, organ.mapProgress * 255);
        p.noStroke();
        for (let node of organ.nodes) {
          p.circle(node.x - organ.x, node.y - organ.y, 3);
        }
      }

      p.pop();
    }

    // Draw connecting measurement lines
    p.stroke(180, 160, 140, 150);
    p.strokeWeight(1);
    for (let line of mapLines) {
      p.line(line.x1, line.y1, line.x2, line.y2);

      // Animated measurement markers
      let progress = (p.millis() / 2000 + line.phase) % 1;
      let markerX = p.lerp(line.x1, line.x2, progress);
      let markerY = p.lerp(line.y1, line.y2, progress);

      p.fill(200, 180, 160);
      p.noStroke();
      p.circle(markerX, markerY, 2);
    }

    // Draw cartographer figure
    p.push();
    p.translate(cartographer.x, cartographer.y);

    // Body
    p.fill(80, 70, 75);
    p.noStroke();
    p.ellipse(0, 0, 30, 45);

    // Head
    p.fill(140, 120, 110);
    p.circle(0, -30, 25);

    // Measuring arm
    cartographer.armAngle = Math.sin(p.millis() * 0.003) * 0.3;
    p.push();
    p.rotate(cartographer.armAngle);
    p.stroke(100, 90, 85);
    p.strokeWeight(3);
    p.line(0, -10, 25, -5);

    // Tool in hand (compass/caliper)
    p.stroke(160, 140, 120);
    p.strokeWeight(2);
    p.line(25, -5, 30, -8);
    p.line(25, -5, 30, -2);
    p.pop();

    // Other arm holding measuring device
    p.push();
    p.rotate(-0.5);
    p.stroke(100, 90, 85);
    p.strokeWeight(3);
    p.line(0, -5, -20, 5);
    p.pop();

    p.pop();

    // Draw measurement tools scattered around
    for (let tool of measurementTools) {
      p.push();
      p.translate(tool.x, tool.y);
      p.rotate(tool.angle + Math.sin(p.millis() * 0.001 + tool.x) * 0.1);

      p.stroke(160, 140, 120);
      p.strokeWeight(2);

      if (tool.type === 0) { // Compass
        p.line(0, 0, 15, 0);
        p.line(0, 0, 10, 10);
        p.circle(15, 0, 3);
      } else if (tool.type === 1) { // Ruler
        p.line(-10, 0, 10, 0);
        for (let i = -8; i <= 8; i += 4) {
          p.line(i, -2, i, 2);
        }
      } else { // Caliper
        p.line(0, 0, 8, -5);
        p.line(0, 0, 8, 5);
        p.line(8, -5, 12, -8);
        p.line(8, 5, 12, 8);
      }
      p.pop();
    }

    // Interactive mapping progress
    let mouseOrgan = null;
    for (let organ of organs) {
      let d = p.dist(p.mouseX, p.mouseY, organ.x, organ.y);
      if (d < 50) {
        mouseOrgan = organ;
        break;
      }
    }

    if (mouseOrgan && !mouseOrgan.mapped) {
      mouseOrgan.mapProgress = p.min(1, mouseOrgan.mapProgress + 0.02);
      if (mouseOrgan.mapProgress >= 1) {
        mouseOrgan.mapped = true;

        // Add measurement lines
        mapLines.push({
          x1: cartographer.x,
          y1: cartographer.y,
          x2: mouseOrgan.x,
          y2: mouseOrgan.y,
          phase: Math.random()
        });
      }
    }

    // Subtle particle system for measurement dust
    if (p.frameCount % 10 === 0 && mapLines.length > 0) {
      let randomLine = mapLines[Math.floor(Math.random() * mapLines.length)];
      annotations.push({
        x: p.lerp(randomLine.x1, randomLine.x2, Math.random()),
        y: p.lerp(randomLine.y1, randomLine.y2, Math.random()),
        life: 60,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2
      });
    }

    // Draw and update annotation particles
    for (let i = annotations.length - 1; i >= 0; i--) {
      let ann = annotations[i];
      ann.x += ann.vx;
      ann.y += ann.vy;
      ann.life--;

      p.fill(200, 180, 160, (ann.life / 60) * 100);
      p.noStroke();
      p.circle(ann.x, ann.y, 2);

      if (ann.life <= 0) {
        annotations.splice(i, 1);
      }
    }
  };

  p.mousePressed = function() {
    // Add measurement line from cartographer to mouse
    if (mapLines.length < 8) {
      mapLines.push({
        x1: cartographer.x,
        y1: cartographer.y,
        x2: p.mouseX,
        y2: p.mouseY,
        phase: Math.random()
      });
    }
  };
}

function sketch(p) {
  let organs = [];
  let buildingParticles = [];
  let architectHands = [];
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize organs at different stages of construction
    for(let i = 0; i < 8; i++) {
      organs.push({
        x: p.random(50, 350),
        y: p.random(100, 500),
        size: p.random(30, 80),
        completion: p.random(0.2, 0.9),
        type: p.floor(p.random(3)), // heart, lung, kidney
        pulse: p.random(p.TWO_PI),
        constructionSpeed: p.random(0.005, 0.02)
      });
    }

    // Initialize architect hands
    for(let i = 0; i < 4; i++) {
      architectHands.push({
        x: p.random(100, 300),
        y: p.random(150, 450),
        targetX: p.random(100, 300),
        targetY: p.random(150, 450),
        angle: p.random(p.TWO_PI),
        working: false
      });
    }
  };

  p.draw = function() {
    // Deep red to gray gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(40, 20, 20), p.color(80, 70, 70), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Update and draw building particles
    for(let i = buildingParticles.length - 1; i >= 0; i--) {
      let particle = buildingParticles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 2;
      particle.size *= 0.98;

      p.fill(180, 60, 60, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        buildingParticles.splice(i, 1);
      }
    }

    // Draw and update organs
    for(let organ of organs) {
      organ.pulse += 0.1;
      organ.completion += organ.constructionSpeed * (1 + mouseInfluence * 0.5);
      if(organ.completion > 1) organ.completion = 1;

      let organColor = p.color(160 + p.sin(organ.pulse) * 20, 40, 40);
      let boundaryColor = p.color(120, 100, 100);

      p.push();
      p.translate(organ.x, organ.y);

      // Draw construction scaffold/boundary
      p.stroke(boundaryColor);
      p.strokeWeight(2);
      p.noFill();

      if(organ.type === 0) { // Heart
        drawHeartScaffold(organ.size, organ.completion);
        p.fill(p.red(organColor), p.green(organColor), p.blue(organColor), 150 * organ.completion);
        drawHeart(organ.size * organ.completion);
      } else if(organ.type === 1) { // Lung
        drawLungScaffold(organ.size, organ.completion);
        p.fill(p.red(organColor), p.green(organColor), p.blue(organColor), 120 * organ.completion);
        drawLung(organ.size * organ.completion);
      } else { // Kidney
        drawKidneyScaffold(organ.size, organ.completion);
        p.fill(p.red(organColor), p.green(organColor), p.blue(organColor), 130 * organ.completion);
        drawKidney(organ.size * organ.completion);
      }

      p.pop();

      // Spawn building particles at incomplete organs
      if(organ.completion < 0.95 && p.random() < 0.1) {
        buildingParticles.push({
          x: organ.x + p.random(-20, 20),
          y: organ.y + p.random(-20, 20),
          vx: p.random(-1, 1),
          vy: p.random(-2, 0),
          size: p.random(3, 8),
          life: 100
        });
      }
    }

    // Update and draw architect hands
    for(let hand of architectHands) {
      // Move towards targets
      let dx = hand.targetX - hand.x;
      let dy = hand.targetY - hand.y;
      hand.x += dx * 0.02;
      hand.y += dy * 0.02;

      // Find new target when close
      if(p.abs(dx) < 10 && p.abs(dy) < 10) {
        hand.targetX = p.random(100, 300);
        hand.targetY = p.random(150, 450);
        hand.working = true;
      }

      hand.angle += 0.05;

      // Draw hand
      p.push();
      p.translate(hand.x, hand.y);
      p.rotate(hand.angle);

      // Palm
      p.fill(140, 120, 110);
      p.noStroke();
      p.ellipse(0, 0, 12, 16);

      // Fingers
      for(let i = 0; i < 4; i++) {
        let fingerAngle = p.map(i, 0, 3, -0.3, 0.3);
        p.push();
        p.rotate(fingerAngle);
        p.rect(-1, -8, 2, 8);
        p.pop();
      }

      // Thumb
      p.push();
      p.rotate(-0.8);
      p.rect(-1, -6, 2, 6);
      p.pop();

      p.pop();

      // Create construction effect when working
      if(hand.working && p.random() < 0.3) {
        buildingParticles.push({
          x: hand.x + p.random(-5, 5),
          y: hand.y + p.random(-5, 5),
          vx: p.random(-0.5, 0.5),
          vy: p.random(-1, 1),
          size: p.random(2, 5),
          life: 80
        });
        hand.working = false;
      }
    }
  };

  function drawHeartScaffold(size, completion) {
    p.beginShape();
    for(let a = 0; a < p.TWO_PI * completion; a += 0.1) {
      let x = size * 0.5 * (16 * p.pow(p.sin(a), 3));
      let y = -size * 0.5 * (13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a));
      p.vertex(x * 0.05, y * 0.05);
    }
    p.endShape();
  }

  function drawHeart(size) {
    p.noStroke();
    p.beginShape();
    for(let a = 0; a < p.TWO_PI; a += 0.1) {
      let x = size * 0.5 * (16 * p.pow(p.sin(a), 3));
      let y = -size * 0.5 * (13 * p.cos(a) - 5 * p.cos(2*a) - 2 * p.cos(3*a) - p.cos(4*a));
      p.vertex(x * 0.05, y * 0.05);
    }
    p.endShape(p.CLOSE);
  }

  function drawLungScaffold(size, completion) {
    let branches = 6;
    for(let i = 0; i < branches * completion; i++) {
      let angle = p.map(i, 0, branches, -p.PI/3, p.PI/3);
      let length = size * 0.3;
      p.line(0, 0, p.cos(angle) * length, p.sin(angle) * length);

      // Sub-branches
      for(let j = 0; j < 3; j++) {
        let subAngle = angle + p.map(j, 0, 2, -0.3, 0.3);
        let subLength = length * 0.6;
        p.line(p.cos(angle) * length * 0.7, p.sin(angle) * length * 0.7,
               p.cos(angle) * length * 0.7 + p.cos(subAngle) * subLength,
               p.sin(angle) * length * 0.7 + p.sin(subAngle) * subLength);
      }
    }
  }

  function drawLung(size) {
    p.noStroke();
    p.ellipse(0, 0, size * 0.8, size);

    // Internal structure
    p.fill(120, 30, 30, 100);
    for(let i = 0; i < 8; i++) {
      let angle = p.map(i, 0, 8, 0, p.TWO_PI);
      let r = size * 0.2;
      p.ellipse(p.cos(angle) * r, p.sin(angle) * r, 6, 6);
    }
  }

  function drawKidneyScaffold(size, completion) {
    let points = 20;
    p.beginShape();
    for(let i = 0; i < points * completion; i++) {
      let angle = p.map(i, 0, points, 0, p.TWO_PI);
      let r = size * 0.4 * (1 + 0.3 * p.sin(angle * 3));
      if(angle > p.PI * 0.3 && angle < p.PI * 0.7) {
        r *= 0.7; // Kidney indentation
      }
      p.vertex(p.cos(angle) * r, p.sin(angle) * r);
    }
    p.endShape();
  }

  function drawKidney(size) {
    p.noStroke();
    p.beginShape();
    let points = 20;
    for(let i = 0; i < points; i++) {
      let angle = p.map(i, 0, points, 0, p.TWO_PI);
      let r = size * 0.4 * (1 + 0.3 * p.sin(angle * 3));
      if(angle > p.PI * 0.3 && angle < p.PI * 0.7) {
        r *= 0.7;
      }
      p.vertex(p.cos(angle) * r, p.sin(angle) * r);
    }
    p.endShape(p.CLOSE);
  }

  p.mousePressed = function() {
    // Add new organ under construction at mouse position
    if(organs.length < 12) {
      organs.push({
        x: p.mouseX,
        y: p.mouseY,
        size: p.random(40, 70),
        completion: 0.1,
        type: p.floor(p.random(3)),
        pulse: 0,
        constructionSpeed: p.random(0.01, 0.03)
      });

      // Burst of construction particles
      for(let i = 0; i < 10; i++) {
        buildingParticles.push({
          x: p.mouseX + p.random(-10, 10),
          y: p.mouseY + p.random(-10, 10),
          vx: p.random(-2, 2),
          vy: p.random(-3, 1),
          size: p.random(4, 10),
          life: 120
        });
      }
    }
  };
}

function sketch(p) {
  let prophet;
  let organs = [];
  let patterns = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the prophet figure
    prophet = {
      x: 200,
      y: 180,
      armAngle: 0,
      breathe: 0
    };

    // Create organ structures
    for (let i = 0; i < 5; i++) {
      organs.push({
        x: 80 + i * 60,
        y: 350 + p.sin(i) * 40,
        size: 40 + i * 8,
        chambers: 4 + i % 3,
        phase: i * 0.7,
        growth: 0,
        understanding: 0
      });
    }

    // Create pattern flows
    for (let i = 0; i < 30; i++) {
      patterns.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        size: p.random(3, 8),
        alpha: p.random(100, 255),
        connections: []
      });
    }
  };

  p.draw = function() {
    // Deep red-gray gradient background
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(40, 20, 20), p.color(80, 60, 60), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    time += 0.02;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.1);

    // Draw understanding patterns in background
    drawUnderstandingField();

    // Draw organs with their emergent structures
    drawOrganicStructures();

    // Draw the prophet figure
    drawProphet();

    // Draw teaching emanations
    drawTeachingFlow();

    // Interactive framework overlays
    if (p.mouseIsPressed) {
      drawFrameworkOverlay();
    }
  };

  function drawUnderstandingField() {
    p.stroke(120, 80, 80, 60);
    p.strokeWeight(1);
    p.noFill();

    for (let i = 0; i < patterns.length; i++) {
      let pt = patterns[i];
      pt.x += pt.vx * (1 + mouseInfluence * 0.5);
      pt.y += pt.vy * (1 + mouseInfluence * 0.5);

      // Wrap around
      if (pt.x < 0) pt.x = 400;
      if (pt.x > 400) pt.x = 0;
      if (pt.y < 0) pt.y = 600;
      if (pt.y > 600) pt.y = 0;

      // Draw connections to nearby points
      for (let j = i + 1; j < patterns.length; j++) {
        let other = patterns[j];
        let d = p.dist(pt.x, pt.y, other.x, other.y);
        if (d < 80) {
          let alpha = p.map(d, 0, 80, 40, 0);
          p.stroke(160, 100, 100, alpha);
          p.line(pt.x, pt.y, other.x, other.y);
        }
      }

      p.fill(140, 90, 90, pt.alpha);
      p.noStroke();
      p.ellipse(pt.x, pt.y, pt.size);
    }
  }

  function drawOrganicStructures() {
    for (let i = 0; i < organs.length; i++) {
      let organ = organs[i];
      let pulse = p.sin(time * 2 + organ.phase) * 0.3 + 1;
      let mouseProx = 1 - p.constrain(p.dist(p.mouseX, p.mouseY, organ.x, organ.y) / 100, 0, 1);
      organ.understanding = p.lerp(organ.understanding, mouseProx, 0.1);

      p.push();
      p.translate(organ.x, organ.y);

      // Main organ structure
      p.fill(180 + organ.understanding * 40, 60 + organ.understanding * 20, 60, 180);
      p.stroke(220, 100, 100, 150);
      p.strokeWeight(2);
      p.ellipse(0, 0, organ.size * pulse);

      // Internal chambers
      for (let j = 0; j < organ.chambers; j++) {
        let angle = (j / organ.chambers) * p.TWO_PI + time;
        let chamberX = p.cos(angle) * organ.size * 0.3;
        let chamberY = p.sin(angle) * organ.size * 0.3;

        p.fill(200 + organ.understanding * 55, 80 + organ.understanding * 40, 80, 120);
        p.ellipse(chamberX, chamberY, 12 + organ.understanding * 8);

        // Connective tissue
        p.stroke(160 + organ.understanding * 60, 70, 70, 100);
        p.strokeWeight(1 + organ.understanding * 2);
        p.line(0, 0, chamberX, chamberY);
      }

      // Emerging boundary patterns
      if (organ.understanding > 0.3) {
        p.noFill();
        p.stroke(255, 120, 120, organ.understanding * 100);
        p.strokeWeight(1);
        for (let k = 0; k < 3; k++) {
          let expandRadius = organ.size * (1.2 + k * 0.3 + organ.understanding * 0.5);
          p.ellipse(0, 0, expandRadius);
        }
      }

      p.pop();
    }
  }

  function drawProphet() {
    prophet.breathe = p.sin(time * 1.5) * 0.1;
    prophet.armAngle = p.sin(time * 0.8) * 0.3 + mouseInfluence * 0.5;

    p.push();
    p.translate(prophet.x, prophet.y);
    p.scale(1 + prophet.breathe);

    // Prophet's torso
    p.fill(100, 70, 80, 200);
    p.stroke(140, 90, 90);
    p.strokeWeight(2);
    p.ellipse(0, 0, 60, 80);

    // Head with understanding aura
    p.fill(120, 85, 95, 220);
    p.ellipse(0, -50, 40, 45);

    // Aura of comprehension
    p.noFill();
    p.stroke(200, 120, 120, 80 + mouseInfluence * 100);
    p.strokeWeight(1);
    for (let i = 0; i < 4; i++) {
      p.ellipse(0, -50, 50 + i * 10 + p.sin(time + i) * 5);
    }

    // Teaching arm
    p.push();
    p.rotate(prophet.armAngle);
    p.stroke(140, 90, 90);
    p.strokeWeight(4);
    p.line(0, 0, 40, -20);
    // Hand pointing
    p.fill(130, 80, 90);
    p.ellipse(40, -20, 8);
    p.pop();

    // Other arm holding diagram
    p.push();
    p.rotate(-0.5);
    p.stroke(140, 90, 90);
    p.strokeWeight(4);
    p.line(0, 0, -30, -10);
    // Diagram in hand
    drawDiagramInHand(-30, -10);
    p.pop();

    p.pop();
  }

  function drawDiagramInHand(x, y) {
    p.push();
    p.translate(x, y);
    p.rotate(p.sin(time) * 0.2);

    p.fill(220, 140, 140, 180);
    p.stroke(255, 160, 160);
    p.strokeWeight(1);
    p.rect(-10, -8, 20, 16);

    // Miniature organ diagram
    p.fill(180, 100, 100);
    p.noStroke();
    p.ellipse(0, 0, 8);
    p.ellipse(-3, -2, 3);
    p.ellipse(3, 2, 3);
    p.stroke(200, 120, 120);
    p.strokeWeight(0.5);
    p.line(-3, -2, 3, 2);

    p.pop();
  }

  function drawTeachingFlow() {
    // Energy flowing from prophet to organs
    for (let i = 0; i < organs.length; i++) {
      let organ = organs[i];
      if (organ.understanding > 0.1) {
        let steps = 8;
        for (let j = 0; j < steps; j++) {
          let t = j / steps;
          let flowX = p.lerp(prophet.x + 30, organ.x, t) + p.sin(time * 3 + j) * 5;
          let flowY = p.lerp(prophet.y, organ.y, t) + p.cos(time * 3 + j) * 3;

          p.fill(255, 140 + p.sin(time * 4 + j) * 40, 140, 60 + organ.understanding * 100);
          p.noStroke();
          p.ellipse(flowX, flowY, 3 + organ.understanding * 3);
        }
      }
    }
  }

  function drawFrameworkOverlay() {
    // Interactive framework that appears on click
    p.stroke(255, 180, 180, 120);
    p.strokeWeight(1);
    p.noFill();

    // Grid showing organizational principles
    for (let x = 50; x < 400; x += 50) {
      for (let y = 100; y < 600; y += 50) {
        let proximity = 1 - p.constrain(p.dist(p.mouseX, p.mouseY, x, y) / 100, 0, 1);
        if (proximity > 0.3) {
          p.stroke(255, 160, 160, proximity * 150);
          p.ellipse(x, y, 20 + proximity * 10);

          // Connection lines to nearby grid points
          if (x < 350) {
            p.line(x, y, x + 50, y);
          }
          if (y < 550) {
            p.line(x, y, x, y + 50);
          }
        }
      }
    }
  }

  p.mousePressed = function() {
    // Pulse effect when clicking
    for (let organ of organs) {
      let d = p.dist(p.mouseX, p.mouseY, organ.x, organ.y);
      if (d < organ.size) {
        organ.understanding = 1;
      }
    }
  };
}

function sketch(p) {
  let seed;
  let particles = [];
  let time = 0;
  let pulseIntensity = 0;
  let escapeVelocity = 0;
  let readyToEscape = false;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    seed = {
      x: 200,
      y: 300,
      energy: 0,
      size: 8,
      coreTemp: 240
    };

    // Initialize potential particles
    for(let i = 0; i < 120; i++) {
      particles.push({
        angle: p.random(p.TWO_PI),
        distance: p.random(2, 15),
        speed: p.random(0.5, 2),
        life: 0,
        maxLife: p.random(30, 80),
        size: p.random(1, 3),
        hue: p.random(220, 280)
      });
    }
  };

  p.draw = function() {
    p.background(15, 20, 8);
    time += 0.02;

    // Calculate mouse influence
    let mouseDistance = p.dist(p.mouseX, p.mouseY, seed.x, seed.y);
    let mouseInfluence = p.map(mouseDistance, 0, 200, 1, 0);
    mouseInfluence = p.constrain(mouseInfluence, 0, 1);

    // Build energy based on proximity and time
    seed.energy += mouseInfluence * 0.03;
    seed.energy += 0.005; // Natural buildup
    seed.energy = p.constrain(seed.energy, 0, 1);

    // Determine escape readiness
    escapeVelocity = p.pow(seed.energy, 2.5);
    readyToEscape = seed.energy > 0.7;

    // Pulse intensity
    pulseIntensity = p.sin(time * 8) * 0.3 + 0.7;
    pulseIntensity *= seed.energy;

    // Draw the plasma seed core
    p.push();
    p.translate(seed.x, seed.y);

    // Outer energy field
    let fieldSize = seed.size * (3 + seed.energy * 4) * pulseIntensity;
    p.fill(seed.coreTemp + 20, 80, 40, 20);
    p.noStroke();
    p.ellipse(0, 0, fieldSize * 2, fieldSize * 2);

    // Inner plasma layers
    for(let layer = 3; layer >= 0; layer--) {
      let layerSize = seed.size * (1 + layer * 0.3) * (1 + seed.energy * 2) * pulseIntensity;
      let layerAlpha = 60 + layer * 15;
      let layerHue = seed.coreTemp + layer * 15;

      p.fill(layerHue, 90 - layer * 10, 85 + layer * 5, layerAlpha);
      p.ellipse(0, 0, layerSize, layerSize);
    }

    // Core spark
    let coreSize = seed.size * 0.6 * pulseIntensity;
    p.fill(300, 30, 98, 90);
    p.ellipse(0, 0, coreSize, coreSize);

    p.pop();

    // Escape velocity vectors
    if(readyToEscape) {
      p.strokeWeight(1 + seed.energy);
      for(let i = 0; i < 8; i++) {
        let angle = (p.TWO_PI / 8) * i + time * 2;
        let vectorLength = 15 + escapeVelocity * 40;
        let startX = seed.x + p.cos(angle) * (seed.size + 5);
        let startY = seed.y + p.sin(angle) * (seed.size + 5);
        let endX = startX + p.cos(angle) * vectorLength;
        let endY = startY + p.sin(angle) * vectorLength;

        p.stroke(260, 70, 80, 60 + escapeVelocity * 40);
        p.line(startX, startY, endX, endY);

        // Arrow tips
        let tipSize = 3 + escapeVelocity * 2;
        let tipAngle1 = angle + 2.8;
        let tipAngle2 = angle - 2.8;
        p.line(endX, endY, endX + p.cos(tipAngle1) * tipSize, endY + p.sin(tipAngle1) * tipSize);
        p.line(endX, endY, endX + p.cos(tipAngle2) * tipSize, endY + p.sin(tipAngle2) * tipSize);
      }
    }

    // Potential particles orbiting and getting activated
    for(let particle of particles) {
      if(seed.energy > 0.3) {
        particle.life = p.min(particle.life + 1, particle.maxLife);

        let particleAngle = particle.angle + time * particle.speed;
        let particleDistance = particle.distance * (1 + seed.energy * 3);
        let px = seed.x + p.cos(particleAngle) * particleDistance;
        let py = seed.y + p.sin(particleAngle) * particleDistance;

        let alpha = p.map(particle.life, 0, particle.maxLife, 0, 60) * seed.energy;
        let size = particle.size * (0.5 + seed.energy * 1.5);

        p.fill(particle.hue, 80, 90, alpha);
        p.noStroke();
        p.ellipse(px, py, size, size);

        // Connecting threads to core when highly energized
        if(seed.energy > 0.6 && p.random() < 0.3) {
          p.stroke(particle.hue, 60, 70, alpha * 0.4);
          p.strokeWeight(0.5);
          p.line(px, py, seed.x, seed.y);
        }
      }
    }

    // Compression rings when building energy
    if(seed.energy > 0.4) {
      p.noFill();
      for(let ring = 0; ring < 3; ring++) {
        let ringSize = (seed.size * 6) + ring * 20 - (seed.energy * 15);
        let ringAlpha = 30 - ring * 8;
        p.stroke(240, 70, 80, ringAlpha * seed.energy);
        p.strokeWeight(1);
        p.ellipse(seed.x, seed.y, ringSize, ringSize);
      }
    }
  };

  p.mousePressed = function() {
    // Reset or boost the seed energy
    if(p.dist(p.mouseX, p.mouseY, seed.x, seed.y) < 50) {
      if(readyToEscape) {
        seed.energy = 0; // Release and reset
        // Scatter particles briefly
        for(let particle of particles) {
          particle.life = 0;
          particle.angle = p.random(p.TWO_PI);
        }
      } else {
        seed.energy += 0.3; // Boost toward escape
      }
    }
  };
}

function sketch(p) {
  let particles = [];
  let splitPoint = { x: 200, y: 300 };
  let mouseInfluence = 0;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Initialize particle system
    for (let i = 0; i < 150; i++) {
      particles.push(new FlowParticle());
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, -0.5, 0.5);

    // Dark background with subtle gradient
    for (let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0.1, 0.03);
      p.fill(250, 20, 5, alpha);
      p.noStroke();
      p.rect(0, y, p.width, 1);
    }

    // Update and draw particles
    particles.forEach(particle => {
      particle.update();
      particle.display();
    });

    // Draw the central splitting energy field
    drawEnergyField();

    // Spawn new particles at the bottom
    if (p.frameCount % 3 === 0) {
      particles.push(new FlowParticle());
    }

    // Remove old particles
    particles = particles.filter(p => p.life > 0);
  };

  function drawEnergyField() {
    p.push();
    p.translate(splitPoint.x, splitPoint.y);

    // Main energy vortex at split point
    for (let r = 20; r < 80; r += 10) {
      let alpha = p.map(r, 20, 80, 0.8, 0.1);
      let rotation = time * 2 + r * 0.1;

      p.stroke(270 + p.sin(time * 3) * 30, 80, 90, alpha);
      p.strokeWeight(2);
      p.noFill();

      p.push();
      p.rotate(rotation);
      p.beginShape();
      for (let a = 0; a < p.TWO_PI; a += 0.1) {
        let radius = r + p.sin(a * 4 + time * 5) * 8;
        let x = p.cos(a) * radius;
        let y = p.sin(a) * radius;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();
    }

    p.pop();
  }

  class FlowParticle {
    constructor() {
      this.reset();
    }

    reset() {
      this.pos = p.createVector(p.random(180, 220), p.height + 20);
      this.vel = p.createVector(0, p.random(-2, -4));
      this.acc = p.createVector(0, 0);
      this.life = 255;
      this.maxLife = 255;
      this.size = p.random(2, 6);
      this.hasChosenPath = false;
      this.pathChoice = 0; // 0 = undecided, 1 = left path, 2 = right path
      this.color = p.random(240, 300); // Purple to blue range
      this.brightness = p.random(70, 90);
    }

    update() {
      // Flow upward until reaching split point
      if (this.pos.y > splitPoint.y + 50) {
        // Rising phase - gentle upward flow with slight wobble
        this.vel.y *= 0.98;
        this.acc.x = p.sin(this.pos.y * 0.02 + time * 2) * 0.1;
        this.acc.x += (splitPoint.x - this.pos.x) * 0.002; // Gentle attraction to center
      } else if (!this.hasChosenPath) {
        // Decision point - choose path based on position and mouse influence
        let decision = p.noise(this.pos.x * 0.01, time * 0.5) + mouseInfluence;
        this.pathChoice = decision > 0.5 ? 2 : 1;
        this.hasChosenPath = true;

        // Adjust color based on path choice
        if (this.pathChoice === 1) {
          this.color = 260; // Blue
        } else {
          this.color = 280; // Purple
        }
      } else {
        // Post-split behavior
        if (this.pathChoice === 1) {
          // Left path - curves left and flows with electric energy
          this.acc.x = -0.3 + p.sin(time * 3 + this.pos.y * 0.05) * 0.2;
          this.acc.y = -0.1 + p.cos(time * 2) * 0.05;
        } else {
          // Right path - curves right with plasma-like flow
          this.acc.x = 0.3 + p.sin(time * 4 + this.pos.y * 0.03) * 0.15;
          this.acc.y = -0.08 + p.sin(time * 3) * 0.08;
        }
      }

      // Apply forces
      this.vel.add(this.acc);
      this.vel.mult(0.95); // Slight drag
      this.pos.add(this.vel);
      this.acc.mult(0);

      // Age the particle
      this.life -= 2;

      // Reset if off screen or dead
      if (this.life <= 0 || this.pos.x < -50 || this.pos.x > 450 || this.pos.y < -50) {
        this.reset();
      }
    }

    display() {
      let alpha = p.map(this.life, 0, this.maxLife, 0, 1);

      // Main particle
      p.fill(this.color, 70, this.brightness, alpha * 0.8);
      p.noStroke();
      p.ellipse(this.pos.x, this.pos.y, this.size);

      // Glowing core
      p.fill(this.color, 30, 95, alpha * 0.4);
      p.ellipse(this.pos.x, this.pos.y, this.size * 2);

      // Trail effect for post-split particles
      if (this.hasChosenPath && this.vel.mag() > 1) {
        p.stroke(this.color, 60, this.brightness, alpha * 0.3);
        p.strokeWeight(1);
        let trailEnd = p5.Vector.sub(this.pos, p5.Vector.mult(this.vel, 5));
        p.line(this.pos.x, this.pos.y, trailEnd.x, trailEnd.y);
      }
    }
  }

  p.mousePressed = function() {
    // Create burst of particles at mouse position if near split point
    let d = p.dist(p.mouseX, p.mouseY, splitPoint.x, splitPoint.y);
    if (d < 100) {
      for (let i = 0; i < 20; i++) {
        let burst = new FlowParticle();
        burst.pos = p.createVector(p.mouseX + p.random(-20, 20), p.mouseY + p.random(-20, 20));
        burst.vel = p5.Vector.random2D().mult(p.random(1, 4));
        burst.life = 150;
        particles.push(burst);
      }
    }
  };
}

function sketch(p) {
  let flows = [];
  let convergencePoint;
  let plasmaParticles = [];
  let time = 0;
  let synthesisPower = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    convergencePoint = p.createVector(200, 300);

    // Create three distinct flows
    flows.push({
      origin: p.createVector(50, 150),
      color: p.color(240, 80, 90),
      nodes: [],
      angle: p.PI / 4
    });

    flows.push({
      origin: p.createVector(350, 200),
      color: p.color(280, 85, 95),
      nodes: [],
      angle: 3 * p.PI / 4
    });

    flows.push({
      origin: p.createVector(200, 50),
      color: p.color(260, 75, 85),
      nodes: [],
      angle: p.PI / 2
    });

    // Initialize flow nodes
    for(let flow of flows) {
      for(let i = 0; i < 15; i++) {
        flow.nodes.push({
          pos: flow.origin.copy(),
          vel: p.createVector(0, 0),
          life: p.random(100)
        });
      }
    }
  };

  p.draw = function() {
    p.background(20, 30, 15);
    time += 0.02;

    // Mouse interaction affects synthesis power
    let mouseDistance = p.dist(p.mouseX, p.mouseY, convergencePoint.x, convergencePoint.y);
    synthesisPower = p.map(mouseDistance, 0, 200, 2, 0.3);
    synthesisPower = p.constrain(synthesisPower, 0.3, 2);

    // Update and draw flows
    for(let i = 0; i < flows.length; i++) {
      let flow = flows[i];
      updateFlow(flow, i);
      drawFlow(flow);
    }

    // Draw convergence synthesis
    drawSynthesis();

    // Update plasma particles
    updatePlasma();

    // Add subtle pulsing background gradient
    drawBackground();
  };

  function updateFlow(flow, index) {
    for(let j = 0; j < flow.nodes.length; j++) {
      let node = flow.nodes[j];

      // Flow toward convergence with organic deviation
      let toCenter = p5.Vector.sub(convergencePoint, node.pos);
      toCenter.normalize();

      // Add noise for organic movement
      let noiseX = p.noise(node.pos.x * 0.01, node.pos.y * 0.01, time + index) - 0.5;
      let noiseY = p.noise(node.pos.x * 0.01, node.pos.y * 0.01, time + index + 100) - 0.5;

      node.vel.add(toCenter.mult(0.5));
      node.vel.add(noiseX * 0.3, noiseY * 0.3);
      node.vel.mult(0.95);

      node.pos.add(node.vel);
      node.life++;

      // Reset nodes that reach convergence
      if(p.dist(node.pos.x, node.pos.y, convergencePoint.x, convergencePoint.y) < 30) {
        node.pos = flow.origin.copy();
        node.vel = p.createVector(0, 0);
        node.life = 0;

        // Generate plasma particle
        if(p.random() < 0.7) {
          createPlasmaParticle();
        }
      }
    }
  }

  function drawFlow(flow) {
    p.stroke(flow.color);
    p.strokeWeight(2);
    p.noFill();

    // Connect nodes with flowing lines
    p.beginShape();
    p.noFill();
    for(let i = 0; i < flow.nodes.length - 1; i++) {
      let alpha = p.map(flow.nodes[i].life, 0, 100, 1, 0.3);
      let col = p.color(p.hue(flow.color), p.saturation(flow.color), p.brightness(flow.color), alpha);
      p.stroke(col);

      if(i === 0) {
        p.vertex(flow.nodes[i].pos.x, flow.nodes[i].pos.y);
      }

      let cp1x = flow.nodes[i].pos.x + p.sin(time + i * 0.3) * 10;
      let cp1y = flow.nodes[i].pos.y + p.cos(time + i * 0.3) * 10;
      let cp2x = flow.nodes[i+1].pos.x + p.sin(time + i * 0.3 + 1) * 10;
      let cp2y = flow.nodes[i+1].pos.y + p.cos(time + i * 0.3 + 1) * 10;

      p.bezierVertex(cp1x, cp1y, cp2x, cp2y, flow.nodes[i+1].pos.x, flow.nodes[i+1].pos.y);
    }
    p.endShape();
  }

  function drawSynthesis() {
    p.push();
    p.translate(convergencePoint.x, convergencePoint.y);

    // Pulsing synthesis core
    let coreSize = 20 + p.sin(time * 3) * 8 * synthesisPower;

    // Multiple rings of synthesis energy
    for(let r = 0; r < 5; r++) {
      let size = coreSize + r * 15;
      let alpha = 0.8 - r * 0.15;

      p.fill(60 + r * 20, 90, 95, alpha * synthesisPower);
      p.noStroke();
      p.ellipse(0, 0, size, size);
    }

    // Electric discharge lines
    p.strokeWeight(1);
    for(let i = 0; i < 12; i++) {
      let angle = (i / 12) * p.TWO_PI + time;
      let length = 30 + p.sin(time * 2 + i) * 20;

      p.stroke(50, 100, 100, 0.7 * synthesisPower);
      p.line(0, 0, 
             p.cos(angle) * length, 
             p.sin(angle) * length);
    }

    p.pop();
  }

  function createPlasmaParticle() {
    plasmaParticles.push({
      pos: convergencePoint.copy(),
      vel: p.createVector(p.random(-3, 3), p.random(-3, 3)),
      life: 60,
      maxLife: 60,
      hue: p.random(40, 80)
    });
  }

  function updatePlasma() {
    for(let i = plasmaParticles.length - 1; i >= 0; i--) {
      let particle = plasmaParticles[i];

      particle.pos.add(particle.vel);
      particle.vel.mult(0.98);
      particle.life--;

      let alpha = particle.life / particle.maxLife;
      let size = p.map(particle.life, 0, particle.maxLife, 1, 8);

      p.fill(particle.hue, 80, 100, alpha);
      p.noStroke();
      p.ellipse(particle.pos.x, particle.pos.y, size, size);

      if(particle.life <= 0) {
        plasmaParticles.splice(i, 1);
      }
    }
  }

  function drawBackground() {
    // Subtle animated background texture
    p.noFill();
    p.strokeWeight(0.5);

    for(let x = 0; x < p.width; x += 40) {
      for(let y = 0; y < p.height; y += 40) {
        let alpha = p.noise(x * 0.01, y * 0.01, time * 0.5) * 0.1;
        p.stroke(220, 20, 30, alpha);

        let size = p.noise(x * 0.02, y * 0.02, time) * 10;
        p.ellipse(x, y, size, size);
      }
    }
  }

  p.mousePressed = function() {
    // Create burst of plasma on click
    for(let i = 0; i < 8; i++) {
      createPlasmaParticle();
    }
  };
}

function sketch(p) {
  let pillars = [];
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four foundational pillars/anchors
    pillars = [
      { x: 100, y: 150, baseX: 100, baseY: 150 },
      { x: 300, y: 150, baseX: 300, baseY: 150 },
      { x: 100, y: 450, baseX: 100, baseY: 450 },
      { x: 300, y: 450, baseX: 300, baseY: 450 }
    ];

    // Initialize flow particles
    for (let i = 0; i < 120; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: p.random(1),
        size: p.random(2, 6),
        hue: p.random(200, 280)
      });
    }
  };

  p.draw = function() {
    // Deep space background with subtle gradient
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(10, 5, 25), p.color(5, 10, 35), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.02;
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, p.width + p.height, 0.8, 1.4);

    // Update pillar positions with gentle breathing motion
    for (let i = 0; i < pillars.length; i++) {
      let pillar = pillars[i];
      let breathe = p.sin(time + i * p.PI/2) * 8;
      pillar.x = pillar.baseX + breathe;
      pillar.y = pillar.baseY + p.cos(time * 0.7 + i * p.PI/3) * 5;
    }

    // Draw connecting energy flows between pillars
    p.strokeWeight(3);
    for (let i = 0; i < pillars.length; i++) {
      for (let j = i + 1; j < pillars.length; j++) {
        let p1 = pillars[i];
        let p2 = pillars[j];

        // Multiple flowing lines between each pair
        for (let k = 0; k < 3; k++) {
          let offset = (k - 1) * 15;
          let wave = p.sin(time * 2 + i + j + k) * 20;

          let midX = (p1.x + p2.x) / 2 + wave + offset;
          let midY = (p1.y + p2.y) / 2 + p.cos(time * 1.5 + i + j) * 15;

          // Gradient stroke
          let hue = (180 + i * 30 + j * 20 + time * 50) % 360;
          p.stroke(p.color(hue, 70, 85, 150));

          p.noFill();
          p.beginShape();
          p.curveVertex(p1.x, p1.y);
          p.curveVertex(p1.x, p1.y);
          p.curveVertex(midX, midY);
          p.curveVertex(p2.x, p2.y);
          p.curveVertex(p2.x, p2.y);
          p.endShape();
        }
      }
    }

    // Draw the four foundation pillars
    for (let i = 0; i < pillars.length; i++) {
      let pillar = pillars[i];
      let pulse = p.sin(time * 3 + i * p.PI/2) * 0.3 + 1;

      // Outer glow
      for (let r = 30; r > 0; r -= 3) {
        let alpha = p.map(r, 0, 30, 180, 0);
        p.fill(220 + i * 15, 80, 90, alpha);
        p.noStroke();
        p.ellipse(pillar.x, pillar.y, r * pulse, r * pulse);
      }

      // Core pillar
      p.fill(240 + i * 10, 85, 95);
      p.noStroke();
      p.ellipse(pillar.x, pillar.y, 15 * pulse, 15 * pulse);

      // Inner sparkle
      p.fill(255, 100, 100);
      p.ellipse(pillar.x, pillar.y, 8 * pulse, 8 * pulse);
    }

    // Update and draw flow particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Find nearest pillar for attraction
      let nearestDist = Infinity;
      let nearestPillar = null;
      for (let pillar of pillars) {
        let d = p.dist(particle.x, particle.y, pillar.x, pillar.y);
        if (d < nearestDist) {
          nearestDist = d;
          nearestPillar = pillar;
        }
      }

      // Flow around pillars in stable orbits
      if (nearestPillar && nearestDist < 120) {
        let angle = p.atan2(particle.y - nearestPillar.y, particle.x - nearestPillar.x);
        let orbitalVel = 0.03 * mouseInfluence;
        angle += orbitalVel;

        let orbitRadius = nearestDist * 0.98; // Slight inward spiral
        particle.x = nearestPillar.x + p.cos(angle) * orbitRadius;
        particle.y = nearestPillar.y + p.sin(angle) * orbitRadius;
      } else {
        // Free flow with gentle directional bias
        particle.vx += p.random(-0.02, 0.02);
        particle.vy += p.random(-0.02, 0.02);

        // Constrain velocity
        particle.vx = p.constrain(particle.vx, -2, 2);
        particle.vy = p.constrain(particle.vy, -2, 2);

        particle.x += particle.vx * mouseInfluence;
        particle.y += particle.vy * mouseInfluence;
      }

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      // Update life and regenerate
      particle.life += 0.008;
      if (particle.life > 1) {
        particle.life = 0;
        particle.hue = p.random(200, 280);
        particle.size = p.random(2, 6);
      }

      // Draw particle with life-based opacity
      let alpha = p.sin(particle.life * p.PI) * 255;
      p.fill(particle.hue, 70, 90, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size, particle.size);

      // Trail effect
      if (p.random() < 0.3) {
        p.fill(particle.hue, 50, 70, alpha * 0.3);
        p.ellipse(particle.x - particle.vx * 3, particle.y - particle.vy * 3, particle.size * 0.7);
      }
    }

    // Interactive mouse effect - create temporary flow disturbance
    if (p.mouseIsPressed) {
      let ripples = 8;
      for (let i = 0; i < ripples; i++) {
        let angle = (i / ripples) * p.TWO_PI + time * 2;
        let radius = (p.sin(time * 4) * 0.5 + 0.5) * 40 + 20;
        let x = p.mouseX + p.cos(angle) * radius;
        let y = p.mouseY + p.sin(angle) * radius;

        p.fill(280, 80, 100, 100);
        p.noStroke();
        p.ellipse(x, y, 8, 8);
      }
    }
  };
}

function sketch(p) {
  let flows = [];
  let obstacles = [];
  let sparks = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create five main flow streams
    for (let i = 0; i < 5; i++) {
      flows.push({
        points: [],
        color: p.color(120 + i * 30, 80 + i * 20, 255 - i * 20),
        energy: 1,
        disrupted: false,
        originalPath: [],
        fragments: []
      });

      // Initialize flow paths
      for (let j = 0; j < 80; j++) {
        let x = 50 + i * 70 + p.sin(j * 0.1) * 20;
        let y = j * 8;
        flows[i].points.push({x, y, vx: 0, vy: 2});
        flows[i].originalPath.push({x, y});
      }
    }

    // Create disruption obstacles
    for (let i = 0; i < 3; i++) {
      obstacles.push({
        x: p.random(100, 300),
        y: 200 + i * 120,
        size: 30 + i * 10,
        charge: p.random(-1, 1),
        pulsePhase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    p.background(15, 10, 25);
    time += 0.02;

    // Update and draw obstacles
    for (let obs of obstacles) {
      let pulse = 1 + p.sin(time * 3 + obs.pulsePhase) * 0.3;

      // Glowing obstacle cores
      p.push();
      p.translate(obs.x, obs.y);
      p.noFill();

      for (let r = obs.size * pulse; r > 0; r -= 8) {
        let alpha = p.map(r, 0, obs.size * pulse, 255, 0);
        p.stroke(255, 100, 150, alpha);
        p.strokeWeight(2);
        p.ellipse(0, 0, r);
      }
      p.pop();
    }

    // Update and draw flows
    for (let flowIndex = 0; flowIndex < flows.length; flowIndex++) {
      let flow = flows[flowIndex];

      // Check for disruptions
      for (let i = 0; i < flow.points.length; i++) {
        let point = flow.points[i];

        for (let obs of obstacles) {
          let dist = p.dist(point.x, point.y, obs.x, obs.y);

          if (dist < obs.size) {
            // Create disruption
            let angle = p.atan2(point.y - obs.y, point.x - obs.x);
            let force = p.map(dist, 0, obs.size, 3, 0);

            point.vx += p.cos(angle) * force * obs.charge;
            point.vy += p.sin(angle) * force * obs.charge;

            // Create sparks
            if (p.random() < 0.1) {
              sparks.push({
                x: point.x,
                y: point.y,
                vx: p.random(-3, 3),
                vy: p.random(-3, 3),
                life: 30,
                maxLife: 30
              });
            }

            flow.disrupted = true;
          }
        }

        // Apply velocity and dampening
        point.x += point.vx;
        point.y += point.vy;
        point.vx *= 0.95;
        point.vy = p.lerp(point.vy, 2, 0.1); // Tendency to flow downward

        // Boundary wrapping for creative escape paths
        if (point.x < 0) point.x = p.width;
        if (point.x > p.width) point.x = 0;
        if (point.y > p.height) {
          point.y = 0;
          point.x = flow.originalPath[i % flow.originalPath.length].x + p.random(-50, 50);
        }
      }

      // Draw flow
      p.noFill();
      p.strokeWeight(3);

      for (let i = 0; i < flow.points.length - 1; i++) {
        let p1 = flow.points[i];
        let p2 = flow.points[i + 1];

        let dist = p.dist(p1.x, p1.y, p2.x, p2.y);
        if (dist < 50) { // Only draw connected segments
          let alpha = p.map(i, 0, flow.points.length, 255, 50);
          let disruption = flow.disrupted ? p.sin(time * 10 + i * 0.1) * 0.5 + 0.5 : 1;

          p.stroke(p.red(flow.color), p.green(flow.color), p.blue(flow.color), alpha * disruption);

          if (flow.disrupted) {
            // Chaotic, fragmented drawing
            p.strokeWeight(p.random(1, 4));
            if (p.random() < 0.7) {
              p.line(p1.x, p1.y, p2.x, p2.y);
            }
          } else {
            p.line(p1.x, p1.y, p2.x, p2.y);
          }
        }
      }

      flow.disrupted = false; // Reset for next frame
    }

    // Update and draw sparks
    for (let i = sparks.length - 1; i >= 0; i--) {
      let spark = sparks[i];

      spark.x += spark.vx;
      spark.y += spark.vy;
      spark.vx *= 0.98;
      spark.vy *= 0.98;
      spark.life--;

      let alpha = p.map(spark.life, 0, spark.maxLife, 0, 255);
      p.fill(255, 200, 100, alpha);
      p.noStroke();
      p.ellipse(spark.x, spark.y, 3);

      if (spark.life <= 0) {
        sparks.splice(i, 1);
      }
    }

    // Mouse interaction - create temporary disruption
    if (p.mouseIsPressed) {
      obstacles.push({
        x: p.mouseX,
        y: p.mouseY,
        size: 40,
        charge: p.sin(time * 5),
        pulsePhase: 0,
        temporary: true
      });

      // Remove temporary obstacles
      obstacles = obstacles.filter(obs => !obs.temporary || p.random() < 0.95);
    }

    // Subtle background energy field
    p.stroke(100, 50, 150, 30);
    p.strokeWeight(1);
    for (let x = 0; x < p.width; x += 20) {
      for (let y = 0; y < p.height; y += 20) {
        let fieldX = x + p.sin(time + x * 0.01 + y * 0.01) * 5;
        let fieldY = y + p.cos(time * 1.3 + x * 0.01 + y * 0.01) * 5;
        p.point(fieldX, fieldY);
      }
    }
  };
}

function sketch(p) {
  let flows = [];
  let bridges = [];
  let particles = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create six transformation flows
    for (let i = 0; i < 6; i++) {
      flows.push({
        start: p.createVector(p.random(50, 350), p.random(100, 500)),
        end: p.createVector(p.random(50, 350), p.random(100, 500)),
        energy: p.random(0.5, 2.0),
        hue: p.random(200, 280),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create bridges between flows
    for (let i = 0; i < 6; i++) {
      for (let j = i + 1; j < 6; j++) {
        if (p.random() < 0.7) { // Not all flows connect
          bridges.push({
            from: i,
            to: j,
            strength: p.random(0.3, 1.0),
            pulse: p.random(p.TWO_PI)
          });
        }
      }
    }

    // Ensure we have exactly 6 main bridges
    while (bridges.length > 6) bridges.pop();
    while (bridges.length < 6) {
      let from = Math.floor(p.random(flows.length));
      let to = Math.floor(p.random(flows.length));
      if (from !== to) {
        bridges.push({
          from: from,
          to: to,
          strength: p.random(0.3, 1.0),
          pulse: p.random(p.TWO_PI)
        });
      }
    }

    // Initialize particles
    for (let i = 0; i < 60; i++) {
      particles.push({
        pos: p.createVector(p.random(p.width), p.random(p.height)),
        vel: p.createVector(p.random(-1, 1), p.random(-1, 1)),
        life: p.random(100),
        maxLife: p.random(80, 120),
        hue: p.random(200, 280),
        flowIndex: Math.floor(p.random(flows.length))
      });
    }
  };

  p.draw = function() {
    p.background(15, 20, 8);
    time += 0.02;

    // Update flow positions with subtle breathing
    flows.forEach((flow, i) => {
      let breathe = p.sin(time * 0.5 + flow.phase) * 20;
      flow.currentStart = p.createVector(
        flow.start.x + p.sin(time + i) * 30 + breathe,
        flow.start.y + p.cos(time * 0.7 + i) * 15
      );
      flow.currentEnd = p.createVector(
        flow.end.x + p.cos(time * 0.8 + i) * 25 - breathe,
        flow.end.y + p.sin(time * 0.6 + i) * 20
      );
    });

    // Draw transformation flows
    flows.forEach((flow, i) => {
      p.strokeWeight(3);

      // Main flow line with energy pulses
      for (let t = 0; t <= 1; t += 0.02) {
        let pos = p5.Vector.lerp(flow.currentStart, flow.currentEnd, t);
        let pulse = p.sin(time * flow.energy * 3 - t * 10) * 0.5 + 0.5;
        let brightness = 60 + pulse * 40;
        let alpha = 70 + pulse * 30;

        p.stroke(flow.hue, 80, brightness, alpha);
        p.strokeWeight(2 + pulse * 4);

        if (t > 0) {
          let prevPos = p5.Vector.lerp(flow.currentStart, flow.currentEnd, t - 0.02);
          p.line(prevPos.x, prevPos.y, pos.x, pos.y);
        }
      }
    });

    // Draw bridges between flows
    bridges.forEach((bridge, i) => {
      let flowA = flows[bridge.from];
      let flowB = flows[bridge.to];

      if (!flowA || !flowB) return;

      // Find midpoints of flows
      let midA = p5.Vector.lerp(flowA.currentStart, flowA.currentEnd, 0.5);
      let midB = p5.Vector.lerp(flowB.currentStart, flowB.currentEnd, 0.5);

      // Create curved bridge
      let bridgePulse = p.sin(time * 2 + bridge.pulse) * 0.5 + 0.5;
      let controlOffset = p.createVector(
        (midB.x - midA.x) * 0.5 + p.sin(time + i) * 40,
        (midB.y - midA.y) * 0.5 + p.cos(time * 0.7 + i) * 30
      );
      let control = p5.Vector.add(midA, controlOffset);

      // Draw bridge as series of connected segments
      p.strokeWeight(1 + bridgePulse * 3);
      let bridgeHue = (flowA.hue + flowB.hue) / 2;

      for (let t = 0; t <= 1; t += 0.05) {
        let pos = quadraticBezier(midA, control, midB, t);
        let energy = bridgePulse * bridge.strength;
        let alpha = 40 + energy * 60;

        p.stroke(bridgeHue, 90, 80 + energy * 20, alpha);

        if (t > 0) {
          let prevPos = quadraticBezier(midA, control, midB, t - 0.05);
          p.line(prevPos.x, prevPos.y, pos.x, pos.y);
        }

        // Add glowing exchange points
        if (t === 0.5 || p.abs(t - 0.5) < 0.1) {
          p.fill(bridgeHue, 70, 95, 80 + bridgePulse * 20);
          p.noStroke();
          p.ellipse(pos.x, pos.y, 6 + bridgePulse * 8);
        }
      }
    });

    // Update and draw energy particles
    particles.forEach((particle, i) => {
      // Move towards nearest flow
      let targetFlow = flows[particle.flowIndex];
      if (targetFlow) {
        let flowMid = p5.Vector.lerp(targetFlow.currentStart, targetFlow.currentEnd, 0.5);
        let force = p5.Vector.sub(flowMid, particle.pos);
        force.mult(0.002);
        particle.vel.add(force);
      }

      // Add some randomness and flow along bridges
      particle.vel.add(p.random(-0.1, 0.1), p.random(-0.1, 0.1));
      particle.vel.mult(0.98);
      particle.pos.add(particle.vel);

      // Wrap around edges
      if (particle.pos.x < 0) particle.pos.x = p.width;
      if (particle.pos.x > p.width) particle.pos.x = 0;
      if (particle.pos.y < 0) particle.pos.y = p.height;
      if (particle.pos.y > p.height) particle.pos.y = 0;

      // Draw particle
      particle.life--;
      if (particle.life <= 0) {
        particle.life = particle.maxLife;
        particle.pos.set(p.random(p.width), p.random(p.height));
        particle.flowIndex = Math.floor(p.random(flows.length));
      }

      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 60);
      p.fill(particle.hue, 60, 90, alpha);
      p.noStroke();
      p.ellipse(particle.pos.x, particle.pos.y, 2 + p.sin(time * 3 + i) * 1);
    });

    // Interactive mouse influence
    if (p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      let mouseForce = p.createVector(p.mouseX, p.mouseY);

      // Attract nearby particles
      particles.forEach(particle => {
        let dist = p5.Vector.dist(particle.pos, mouseForce);
        if (dist < 100) {
          let attraction = p5.Vector.sub(mouseForce, particle.pos);
          attraction.mult(0.001 * (100 - dist) / 100);
          particle.vel.add(attraction);
        }
      });

      // Add ripple effect
      p.noFill();
      p.strokeWeight(1);
      let ripple = (time * 10) % 50;
      p.stroke(250, 70, 80, p.map(ripple, 0, 50, 40, 0));
      p.ellipse(p.mouseX, p.mouseY, ripple * 4);
    }
  };

  function quadraticBezier(p0, p1, p2, t) {
    let x = (1 - t) * (1 - t) * p0.x + 2 * (1 - t) * t * p1.x + t * t * p2.x;
    let y = (1 - t) * (1 - t) * p0.y + 2 * (1 - t) * t * p1.y + t * t * p2.y;
    return p.createVector(x, y);
  }
}

function sketch(p) {
  let flows = [];
  let reflections = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create seven main flow streams
    for (let i = 0; i < 7; i++) {
      flows.push({
        points: [],
        angle: (i / 7) * p.TWO_PI,
        radius: 80 + i * 15,
        speed: 0.02 + i * 0.005,
        phase: i * p.PI / 3.5,
        reflectionDepth: 3,
        mirrors: []
      });

      // Initialize points for each flow
      for (let j = 0; j < 40; j++) {
        flows[i].points.push({
          x: 0,
          y: 0,
          age: j / 40,
          intensity: 0
        });
      }
    }
  };

  p.draw = function() {
    p.background(5, 40, 8);
    time += 0.01;

    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 300, 0.05);

    p.translate(200, 300);

    // Draw recursive lightning patterns
    for (let f = 0; f < flows.length; f++) {
      let flow = flows[f];
      let centerRadius = flow.radius * (0.8 + 0.3 * p.sin(time * flow.speed + flow.phase));

      // Update main flow points
      for (let i = 0; i < flow.points.length; i++) {
        let point = flow.points[i];
        let spiralAngle = flow.angle + time * flow.speed + i * 0.2;
        let spiralRadius = centerRadius * (1 - point.age * 0.7);

        // Add fractal noise for organic movement
        let noiseScale = 0.01;
        let noiseX = p.noise(i * noiseScale, time * 0.5, f * 0.1) - 0.5;
        let noiseY = p.noise(i * noiseScale + 100, time * 0.5, f * 0.1) - 0.5;

        point.x = p.cos(spiralAngle) * spiralRadius + noiseX * 30;
        point.y = p.sin(spiralAngle) * spiralRadius + noiseY * 30;
        point.intensity = (1 - point.age) * (0.7 + 0.3 * p.sin(time * 2 + i * 0.5));
      }

      // Draw main flow with recursive reflections
      drawRecursiveFlow(flow, f, 0, 1.0, 0);
    }

    // Draw central awareness node
    drawAwarenessCore();
  };

  function drawRecursiveFlow(flow, flowIndex, depth, scale, rotation) {
    if (depth > 2) return;

    p.push();
    p.rotate(rotation);
    p.scale(scale);

    // Main flow color shifts through blues and purples
    let hueBase = 240 + flowIndex * 15 + depth * 20;
    let sat = 80 - depth * 20;
    let bright = 90 - depth * 15;

    // Draw the flow stream
    p.noFill();
    for (let pass = 0; pass < 3; pass++) {
      p.strokeWeight((3 - pass) * scale);
      p.stroke(hueBase + pass * 10, sat, bright - pass * 10, 70 - depth * 20);

      p.beginShape();
      p.noFill();
      for (let i = 0; i < flow.points.length - 1; i++) {
        let point = flow.points[i];
        let intensity = point.intensity * (1 - depth * 0.3);

        if (intensity > 0.1) {
          let alpha = intensity * (70 - depth * 20);
          p.stroke(hueBase + pass * 10, sat, bright - pass * 10, alpha);

          if (i === 0) {
            p.vertex(point.x, point.y);
          } else {
            let prevPoint = flow.points[i - 1];
            p.bezierVertex(
              prevPoint.x + p.sin(time + i) * 5,
              prevPoint.y + p.cos(time + i) * 5,
              point.x + p.sin(time + i + 1) * 5,
              point.y + p.cos(time + i + 1) * 5,
              point.x,
              point.y
            );
          }
        }
      }
      p.endShape();
    }

    // Draw energy nodes along the flow
    for (let i = 0; i < flow.points.length; i += 6) {
      let point = flow.points[i];
      if (point.intensity > 0.3) {
        p.fill(hueBase, sat + 20, bright, point.intensity * 60);
        p.noStroke();
        let nodeSize = (4 + p.sin(time * 3 + i) * 2) * scale;
        p.ellipse(point.x, point.y, nodeSize, nodeSize);

        // Recursive mini-flows at key nodes (self-reflection)
        if (i % 12 === 0 && depth < 2) {
          p.push();
          p.translate(point.x, point.y);
          let miniScale = 0.3 * scale * (1 + mouseInfluence * 0.2);
          let miniRotation = time * (1 + depth) + flowIndex;
          drawRecursiveFlow(flow, flowIndex, depth + 1, miniScale, miniRotation);
          p.pop();
        }
      }
    }

    p.pop();
  }

  function drawAwarenessCore() {
    // Central point where all flows observe themselves
    p.push();

    let coreSize = 20 + p.sin(time * 2) * 8 + mouseInfluence * 15;
    let layers = 5;

    for (let layer = layers; layer > 0; layer--) {
      let layerSize = coreSize * (layer / layers);
      let alpha = (layers - layer + 1) * 15;
      let hue = 280 + layer * 10 + time * 20;

      p.fill(hue, 70, 95, alpha);
      p.noStroke();
      p.ellipse(0, 0, layerSize, layerSize);
    }

    // Awareness pulse rings
    for (let ring = 0; ring < 3; ring++) {
      let ringTime = time * 1.5 - ring * 0.5;
      let ringRadius = (p.sin(ringTime) + 1) * 60 + ring * 20;
      let ringAlpha = (p.sin(ringTime) + 1) * 20;

      if (ringAlpha > 2) {
        p.noFill();
        p.stroke(260 + ring * 20, 80, 90, ringAlpha);
        p.strokeWeight(2);
        p.ellipse(0, 0, ringRadius, ringRadius);
      }
    }

    p.pop();
  }

  p.mousePressed = function() {
    // Trigger awareness wave
    for (let flow of flows) {
      flow.speed *= 1.5;
      setTimeout(() => {
        flow.speed /= 1.5;
      }, 1000);
    }
  };

  p.mouseMoved = function() {
    // Flows bend slightly toward mouse, representing observation effect
    let mouseAngle = p.atan2(p.mouseY - 300, p.mouseX - 200);
    for (let i = 0; i < flows.length; i++) {
      let angleDiff = mouseAngle - flows[i].angle;
      flows[i].angle += p.sin(angleDiff) * 0.01;
    }
  };
}

function sketch(p) {
  let zones = [];
  let particles = [];
  let time = 0;
  let chargeLevel = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create 8 accumulation zones in a dynamic pattern
    for (let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI + p.PI/4;
      let radius = 120 + p.sin(i * 0.8) * 40;
      zones.push({
        x: 200 + p.cos(angle) * radius,
        y: 300 + p.sin(angle) * radius * 0.7,
        energy: 0,
        particles: [],
        hue: 220 + i * 15,
        pulsePhase: i * 0.3
      });
    }

    // Initialize particles
    for (let i = 0; i < 200; i++) {
      particles.push(createParticle());
    }
  };

  function createParticle() {
    return {
      x: p.random(p.width),
      y: p.random(p.height),
      vx: p.random(-1, 1),
      vy: p.random(-1, 1),
      life: p.random(100, 255),
      maxLife: p.random(100, 255),
      attracted: false,
      targetZone: p.floor(p.random(8))
    };
  }

  p.draw = function() {
    time += 0.02;

    // Dark gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(240, 60, 15), p.color(260, 80, 5), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Mouse influence for interactive acceleration
    mouseInfluence = p.map(p.mouseX + p.mouseY, 0, p.width + p.height, 0.5, 2.5);

    // Build charge level over time
    chargeLevel = (p.sin(time * 0.3) + 1) * 0.5 * mouseInfluence;

    // Update and draw zones
    for (let i = 0; i < zones.length; i++) {
      let zone = zones[i];

      // Energy accumulates in waves
      zone.energy = 30 + p.sin(time * 2 + zone.pulsePhase) * 20 + chargeLevel * 40;

      // Draw energy field around zone
      p.push();
      p.translate(zone.x, zone.y);

      // Multiple energy rings showing accumulation
      for (let r = 0; r < 5; r++) {
        let radius = zone.energy * 0.3 + r * 8;
        let alpha = p.map(r, 0, 4, 80, 10) * (zone.energy / 70);

        p.noFill();
        p.stroke(zone.hue, 70 + r * 5, 90, alpha);
        p.strokeWeight(2 - r * 0.3);
        p.ellipse(0, 0, radius * 2);
      }

      // Core accumulation point
      let coreSize = zone.energy * 0.2;
      p.fill(zone.hue, 80, 95, 90);
      p.noStroke();
      p.ellipse(0, 0, coreSize);

      p.pop();
    }

    // Update particles - they get pulled toward zones as energy builds
    for (let particle of particles) {
      let zone = zones[particle.targetZone];

      // Calculate attraction force
      let dx = zone.x - particle.x;
      let dy = zone.y - particle.y;
      let dist = p.sqrt(dx * dx + dy * dy);

      if (dist < zone.energy * 2) {
        // Strong attraction when close to energized zones
        let force = p.map(zone.energy, 10, 90, 0.02, 0.15);
        particle.vx += (dx / dist) * force;
        particle.vy += (dy / dist) * force;
        particle.attracted = true;
      } else {
        // Gentle drift when far away
        particle.vx += p.random(-0.01, 0.01);
        particle.vy += p.random(-0.01, 0.01);
      }

      // Velocity limits
      particle.vx = p.constrain(particle.vx, -3, 3);
      particle.vy = p.constrain(particle.vy, -3, 3);

      // Update position
      particle.x += particle.vx;
      particle.y += particle.vy;

      // Wrap around screen
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      // Draw particle with velocity-based trail
      let speed = p.sqrt(particle.vx * particle.vx + particle.vy * particle.vy);
      let brightness = p.map(speed, 0, 3, 30, 95);
      let hue = 250 - speed * 10;

      p.stroke(hue, 60, brightness, particle.attracted ? 80 : 40);
      p.strokeWeight(particle.attracted ? 2 : 1);
      p.point(particle.x, particle.y);

      // Velocity streaks for fast particles
      if (speed > 1.5) {
        p.stroke(hue, 80, brightness, 30);
        p.line(particle.x, particle.y, 
               particle.x - particle.vx * 5, particle.y - particle.vy * 5);
      }
    }

    // Draw connecting energy between zones when charge is high
    if (chargeLevel > 0.7) {
      for (let i = 0; i < zones.length; i++) {
        for (let j = i + 1; j < zones.length; j++) {
          if (p.random() < 0.3) {
            let alpha = (chargeLevel - 0.7) * 300;
            p.stroke(235, 70, 90, alpha);
            p.strokeWeight(1);
            p.line(zones[i].x, zones[i].y, zones[j].x, zones[j].y);
          }
        }
      }
    }
  };

  p.mousePressed = function() {
    // Create burst of new particles at mouse location
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-2, 2),
        life: 255,
        maxLife: 255,
        attracted: false,
        targetZone: p.floor(p.random(8))
      });
    }
  };
}

function sketch(p) {
  let zones = [];
  let transformationField = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Create 9 transformation zones
    for (let i = 0; i < 9; i++) {
      zones.push({
        x: (i % 3) * 133 + 67,
        y: Math.floor(i / 3) * 150 + 100,
        flows: [],
        mutationSpeed: p.random(0.5, 2.0),
        transformPhase: p.random(p.TWO_PI),
        energyLevel: p.random(0.3, 1.0)
      });

      // Initialize flows for each zone
      for (let j = 0; j < 12; j++) {
        zones[i].flows.push({
          angle: p.random(p.TWO_PI),
          velocity: p.random(1, 4),
          length: p.random(20, 60),
          thickness: p.random(1, 4),
          mutationType: p.random(['plasma', 'vector', 'current']),
          evolutionState: 0
        });
      }
    }

    // Background transformation field
    for (let x = 0; x < 20; x++) {
      transformationField[x] = [];
      for (let y = 0; y < 30; y++) {
        transformationField[x][y] = {
          intensity: p.noise(x * 0.1, y * 0.1) * 100,
          phase: p.random(p.TWO_PI)
        };
      }
    }
  };

  p.draw = function() {
    // Dynamic background showing meta-transformation
    for (let x = 0; x < 20; x++) {
      for (let y = 0; y < 30; y++) {
        let field = transformationField[x][y];
        field.phase += 0.02;
        let brightness = 5 + p.sin(field.phase) * 3;
        let hue = (240 + p.sin(field.phase * 0.7) * 60) % 360;
        p.fill(hue, 80, brightness, 20);
        p.noStroke();
        p.rect(x * 20, y * 20, 20, 20);
      }
    }

    // Mouse influence creates ripples of meta-change
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, 200, 300) / 200;

    // Draw the nine transformation zones
    zones.forEach((zone, zoneIndex) => {
      p.push();
      p.translate(zone.x, zone.y);

      zone.transformPhase += zone.mutationSpeed * 0.05;

      // Each zone transforms its own transformation nature
      let metaHue = (240 + zoneIndex * 15 + p.sin(zone.transformPhase) * 40) % 360;
      let zoneEnergy = zone.energyLevel + p.sin(zone.transformPhase * 2) * 0.3;

      zone.flows.forEach((flow, flowIndex) => {
        // Each flow evolves its mutation type
        flow.evolutionState += 0.03 + mouseInfluence * 0.02;

        let startX = p.cos(flow.angle) * 10;
        let startY = p.sin(flow.angle) * 10;

        if (flow.mutationType === 'plasma') {
          // Lightning mutating into plasma
          p.stroke(metaHue, 90, 90, 80);
          p.strokeWeight(flow.thickness * (1 + p.sin(flow.evolutionState) * 0.5));

          let segments = 8;
          let prevX = startX;
          let prevY = startY;

          for (let s = 1; s <= segments; s++) {
            let progress = s / segments;
            let plasmaFactor = p.sin(flow.evolutionState + progress * p.PI) * 20;

            let nextX = p.cos(flow.angle + progress * 0.5) * flow.length * progress + p.sin(flow.evolutionState * 3 + s) * plasmaFactor;
            let nextY = p.sin(flow.angle + progress * 0.5) * flow.length * progress + p.cos(flow.evolutionState * 2 + s) * plasmaFactor;

            p.line(prevX, prevY, nextX, nextY);

            // Plasma particles that don't follow electrical laws
            if (s % 2 === 0) {
              p.fill(metaHue + 30, 70, 100, 60);
              p.noStroke();
              p.ellipse(nextX, nextY, 3 + p.sin(flow.evolutionState * 4) * 2);
            }

            prevX = nextX;
            prevY = nextY;
          }

        } else if (flow.mutationType === 'vector') {
          // Flow vectors achieving new velocities
          let velocityEvolution = 1 + p.sin(flow.evolutionState) * 2;
          p.stroke(metaHue + 60, 80, 85, 70);
          p.strokeWeight(flow.thickness);

          let endX = p.cos(flow.angle + flow.evolutionState * 0.1) * flow.length * velocityEvolution;
          let endY = p.sin(flow.angle + flow.evolutionState * 0.1) * flow.length * velocityEvolution;

          p.line(startX, startY, endX, endY);

          // New motion patterns
          p.fill(metaHue + 60, 60, 100, 80);
          p.noStroke();
          p.ellipse(endX, endY, 4);

          // Trail showing evolved motion
          for (let t = 1; t < 5; t++) {
            let trailFactor = 1 - t * 0.2;
            let trailX = p.cos(flow.angle + (flow.evolutionState - t * 0.1) * 0.1) * flow.length * velocityEvolution * trailFactor;
            let trailY = p.sin(flow.angle + (flow.evolutionState - t * 0.1) * 0.1) * flow.length * velocityEvolution * trailFactor;
            p.fill(metaHue + 60, 60, 100, 40 / t);
            p.ellipse(trailX, trailY, 2);
          }

        } else if (flow.mutationType === 'current') {
          // Energy currents reorganizing into unprecedented patterns
          p.stroke(metaHue - 30, 85, 80, 75);
          p.strokeWeight(flow.thickness * 0.8);
          p.noFill();

          let curvature = p.sin(flow.evolutionState) * 2;
          let currentPath = flow.length * (1 + p.sin(flow.evolutionState * 0.5) * 0.4);

          p.beginShape();
          for (let c = 0; c <= 10; c++) {
            let t = c / 10;
            let x = p.cos(flow.angle) * currentPath * t + p.sin(flow.evolutionState + t * p.PI) * curvature * 15;
            let y = p.sin(flow.angle) * currentPath * t + p.cos(flow.evolutionState * 1.3 + t * p.PI) * curvature * 10;
            p.vertex(x, y);
          }
          p.endShape();

          // Unprecedented pattern nodes
          for (let n = 0; n < 3; n++) {
            let nodeT = (n + 1) / 4;
            let nodeX = p.cos(flow.angle) * currentPath * nodeT + p.sin(flow.evolutionState + nodeT * p.PI) * curvature * 15;
            let nodeY = p.sin(flow.angle) * currentPath * nodeT + p.cos(flow.evolutionState * 1.3 + nodeT * p.PI) * curvature * 10;

            p.fill(metaHue - 30, 70, 95, 85);
            p.noStroke();
            p.ellipse(nodeX, nodeY, 5 + p.sin(flow.evolutionState * 3 + n) * 2);
          }
        }

        flow.angle += 0.01 * zoneEnergy;
      });

      // Zone center showing transformation of transformation
      p.fill(metaHue, 60, 90, 40);
      p.noStroke();
      p.ellipse(0, 0, 15 + p.sin(zone.transformPhase * 3) * 8);

      p.pop();
    });
  };

  p.mousePressed = function() {
    // Click creates waves of meta-transformation
    zones.forEach(zone => {
      let distance = p.dist(p.mouseX, p.mouseY, zone.x, zone.y);
      if (distance < 100) {
        zone.mutationSpeed *= 1.5;
        zone.flows.forEach(flow => {
          flow.evolutionState += p.random(0.5, 1.5);
          flow.mutationType = p.random(['plasma', 'vector', 'current']);
        });
      }
    });
  };
}

