      maxEnergy: p.random(50, 100),
      hue: p.random(220, 280),
      trail: []
    };
  }

  p.draw = function() {
    p.background(230, 15, 8);
    time += 0.02;

    // Update completion zones
    for (let zone of completionZones) {
      let pulse = p.sin(time * 2 + zone.phase) * 0.5 + 0.5;
      zone.intensity = pulse * 30;

      // Draw zone aura
      p.push();
      p.translate(zone.x, zone.y);
      for (let r = zone.size; r > 0; r -= 3) {
        let alpha = p.map(r, 0, zone.size, zone.intensity, 0);
        p.fill(250, 60, 80, alpha);
        p.noStroke();
        p.circle(0, 0, r);
      }
      p.pop();
    }

    // Update and draw flow particles
    for (let i = flows.length - 1; i >= 0; i--) {
      let flow = flows[i];

      // Find nearest completion zone
      let nearestDist = Infinity;
      let nearestZone = null;
      for (let zone of completionZones) {
        let d = p.dist(flow.x, flow.y, zone.x, zone.y);
        if (d < nearestDist) {
          nearestDist = d;
          nearestZone = zone;
        }
      }

      // Attraction to completion zones
      if (nearestZone && nearestDist < 80) {
        let attraction = p.map(nearestDist, 0, 80, 0.05, 0.001);
        let angle = p.atan2(nearestZone.y - flow.y, nearestZone.x - flow.x);
        flow.vx += p.cos(angle) * attraction;
        flow.vy += p.sin(angle) * attraction;

        // Energy dissipation near zones
        if (nearestDist < 30) {
          flow.energy *= 0.95;
        }
      }

      // Mouse interaction - gentle dispersal
      let mouseDist = p.dist(flow.x, flow.y, p.mouseX, p.mouseY);
      if (mouseDist < 60) {
        let repulsion = p.map(mouseDist, 0, 60, 0.02, 0);
        let angle = p.atan2(flow.y - p.mouseY, flow.x - p.mouseX);
        flow.vx += p.cos(angle) * repulsion;
        flow.vy += p.sin(angle) * repulsion;
      }

      // Update trail
      flow.trail.push({x: flow.x, y: flow.y});
      if (flow.trail.length > 15) {
        flow.trail.shift();
      }

      // Movement with gentle decay
      flow.vx *= 0.98;
      flow.vy *= 0.98;
      flow.x += flow.vx;
      flow.y += flow.vy;

      // Boundary wrapping
      if (flow.x < 0) flow.x = 400;
      if (flow.x > 400) flow.x = 0;
      if (flow.y < 0) flow.y = 600;
      if (flow.y > 600) flow.y = 0;

      // Draw trail
      for (let j = 0; j < flow.trail.length - 1; j++) {
        let alpha = p.map(j, 0, flow.trail.length - 1, 0, flow.energy);
        let weight = p.map(j, 0, flow.trail.length - 1, 0.5, 2);
        p.stroke(flow.hue, 70, 90, alpha);
        p.strokeWeight(weight);
        p.line(flow.trail[j].x, flow.trail[j].y, 
               flow.trail[j + 1].x, flow.trail[j + 1].y);
      }

      // Draw particle
      let size = p.map(flow.energy, 0, flow.maxEnergy, 2, 6);
      p.fill(flow.hue, 80, 95, flow.energy);
      p.noStroke();
      p.circle(flow.x, flow.y, size);

      // When energy is very low, transform into ground particle
      if (flow.energy < 10) {
        groundParticles.push({
          x: flow.x,
          y: flow.y,
          vx: 0,
          vy: 0,
          alpha: 20,
          baseAlpha: 20,
          size: p.random(1, 2)
        });
        flows.splice(i, 1);

        // Occasionally spawn new flow from the ground
        if (p.random(100) < 30) {
          flows.push(createFlowParticle());
        }
      }
    }

    // Update ground particles
    for (let ground of groundParticles) {
      // Gentle drift in the substrate
      ground.vx += p.random(-0.01, 0.01);
      ground.vy += p.random(-0.01, 0.01);
      ground.vx *= 0.95;
      ground.vy *= 0.95;

      ground.x += ground.vx;
      ground.y += ground.vy;

      // Fade over time
      ground.alpha *= 0.999;

      // Draw as gentle points
      p.fill(240, 30, 60, ground.alpha);
      p.noStroke();
      p.circle(ground.x, ground.y, ground.size);
    }

    // Remove faded ground particles
    groundParticles = groundParticles.filter(g => g.alpha > 1);

    // Ensure minimum flow particles
    while (flows.length < 40) {
      flows.push(createFlowParticle());
    }
  };
}

function sketch(p) {
  let mystic = {};
  let flows = [];
  let sparkles = [];
  let time = 0;
  let ecstasyLevel = 0;

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize mystic
    mystic.x = 200;
    mystic.y = 350;
    mystic.dissolution = 0;
    mystic.eyeIntensity = 0;

    // Create flowing energy streams
    for (let i = 0; i < 8; i++) {
      flows.push({
        angle: (360 / 8) * i,
        radius: 80,
        speed: p.random(0.02, 0.08),
        thickness: p.random(3, 8),
        nodes: []
      });

      // Initialize nodes for each flow
      for (let j = 0; j < 15; j++) {
        flows[i].nodes.push({
          distance: j * 20,
          offset: p.random(-20, 20),
          phase: p.random(p.TWO_PI)
        });
      }
    }

    // Create sparkle particles
    for (let i = 0; i < 100; i++) {
      sparkles.push({
        x: p.random(400),
        y: p.random(600),
        size: p.random(1, 4),
        speed: p.random(0.5, 2),
        hue: p.random(220, 280),
        brightness: p.random(60, 100),
        phase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dynamic background with depth
    for (let y = 0; y < 600; y += 2) {
      let intensity = p.map(p.sin(y * 0.01 + time), -1, 1, 5, 25);
      p.fill(250, 80, intensity);
      p.noStroke();
      p.rect(0, y, 400, 2);
    }

    // Calculate mouse influence
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, mystic.x, mystic.y) / 200;
    ecstasyLevel = p.lerp(ecstasyLevel, 1 - p.constrain(mouseInfluence, 0, 1), 0.05);

    // Update mystic properties
    mystic.dissolution = ecstasyLevel * 0.8 + p.sin(time * 2) * 0.1;
    mystic.eyeIntensity = ecstasyLevel * 0.9 + p.sin(time * 3) * 0.1;

    // Draw energy flows
    p.strokeWeight(2);
    flows.forEach((flow, flowIndex) => {
      let flowHue = 240 + flowIndex * 10 + p.sin(time + flowIndex) * 20;

      for (let i = 0; i < flow.nodes.length - 1; i++) {
        let node1 = flow.nodes[i];
        let node2 = flow.nodes[i + 1];

        let angle1 = p.radians(flow.angle + p.sin(time * flow.speed + node1.phase) * 30);
        let angle2 = p.radians(flow.angle + p.sin(time * flow.speed + node2.phase) * 30);

        let x1 = mystic.x + p.cos(angle1) * (flow.radius + node1.distance) + p.sin(time + node1.phase) * node1.offset;
        let y1 = mystic.y + p.sin(angle1) * (flow.radius + node1.distance) * 0.7 + p.cos(time + node1.phase) * node1.offset;

        let x2 = mystic.x + p.cos(angle2) * (flow.radius + node2.distance) + p.sin(time + node2.phase) * node2.offset;
        let y2 = mystic.y + p.sin(angle2) * (flow.radius + node2.distance) * 0.7 + p.cos(time + node2.phase) * node2.offset;

        let alpha = p.map(i, 0, flow.nodes.length, 80, 10) * (1 + ecstasyLevel);
        p.stroke(flowHue, 70, 90, alpha);
        p.line(x1, y1, x2, y2);

        // Add energy pulses
        if (i % 3 === 0) {
          p.fill(flowHue, 50, 100, alpha * 0.5);
          p.noStroke();
          p.ellipse(x1, y1, 3 + p.sin(time * 4 + i) * 2);
        }
      }
    });

    // Draw sparkle field
    sparkles.forEach(sparkle => {
      sparkle.x += p.sin(time + sparkle.phase) * sparkle.speed;
      sparkle.y += p.cos(time * 0.7 + sparkle.phase) * sparkle.speed * 0.5;

      if (sparkle.x < -10) sparkle.x = 410;
      if (sparkle.x > 410) sparkle.x = -10;
      if (sparkle.y < -10) sparkle.y = 610;
      if (sparkle.y > 610) sparkle.y = -10;

      let twinkle = p.sin(time * 3 + sparkle.phase) * 0.5 + 0.5;
      let alpha = twinkle * sparkle.brightness * (0.3 + ecstasyLevel * 0.7);

      p.fill(sparkle.hue, 60, 100, alpha);
      p.noStroke();
      p.ellipse(sparkle.x, sparkle.y, sparkle.size * (1 + twinkle * 0.5));
    });

    // Draw mystic figure
    p.push();
    p.translate(mystic.x, mystic.y);

    // Body with dissolution effect
    let bodyAlpha = 70 - mystic.dissolution * 30;
    p.fill(280, 40, 80, bodyAlpha);
    p.noStroke();

    // Torso
    for (let i = 0; i < 5; i++) {
      let offset = p.sin(time * 2 + i) * mystic.dissolution * 5;
      p.ellipse(offset, -20 + i * 8, 25 - mystic.dissolution * 10, 35);
    }

    // Arms reaching into flow
    p.strokeWeight(4);
    p.stroke(280, 40, 80, bodyAlpha);
    p.noFill();

    let leftArmX = -15 + p.sin(time + 1) * mystic.dissolution * 10;
    let leftArmY = -10 + p.cos(time + 1) * mystic.dissolution * 8;
    let rightArmX = 15 + p.sin(time + 2) * mystic.dissolution * 10;
    let rightArmY = -10 + p.cos(time + 2) * mystic.dissolution * 8;

    p.line(0, -15, leftArmX, leftArmY);
    p.line(0, -15, rightArmX, rightArmY);

    // Head with visionary eyes
    p.fill(280, 30, 90, bodyAlpha + 20);
    p.noStroke();
    p.ellipse(0, -55, 20 + p.sin(time) * mystic.dissolution * 3);

    // Eyes - wide with cosmic vision
    let eyeGlow = mystic.eyeIntensity * 100;
    p.fill(200, 80, 100, eyeGlow);
    p.ellipse(-4, -58, 3 + eyeGlow * 0.05);
    p.ellipse(4, -58, 3 + eyeGlow * 0.05);

    // Third eye chakra
    p.fill(260, 90, 100, eyeGlow * 0.8);
    p.ellipse(0, -62, 2 + eyeGlow * 0.03);

    // Energy corona around head
    for (let i = 0; i < 12; i++) {
      let angle = (360 / 12) * i + time * 50;
      let x = p.cos(p.radians(angle)) * (15 + p.sin(time * 2 + i) * 5);
      let y = -55 + p.sin(p.radians(angle)) * (10 + p.sin(time * 2 + i) * 3);

      p.fill(240 + i * 5, 70, 90, mystic.eyeIntensity * 60);
      p.ellipse(x, y, 2 + mystic.eyeIntensity * 2);
    }

    p.pop();

    // Draw plasma currents connecting to mystic
    if (p.mouseIsPressed || ecstasyLevel > 0.7) {
      p.strokeWeight(3);
      for (let i = 0; i < 5; i++) {
        let startX = p.mouseX || mystic.x;
        let startY = p.mouseY || mystic.y;
        let steps = 20;

        let prevX = startX;
        let prevY = startY;

        for (let j = 1; j <= steps; j++) {
          let progress = j / steps;
          let x = p.lerp(startX, mystic.x, progress) + p.sin(time * 5 + i + j * 0.5) * 10;
          let y = p.lerp(startY, mystic.y, progress) + p.cos(time * 4 + i + j * 0.3) * 8;

          let hue = 220 + i * 15 + j * 2;
          let alpha = (1 - progress) * 80 * ecstasyLevel;

          p.stroke(hue, 80, 100, alpha);
          p.line(prevX, prevY, x, y);

          prevX = x;
          prevY = y;
        }
      }
    }
  };

  p.mousePressed = function() {
    // Create burst of new sparkles on click
    for (let i = 0; i < 20; i++) {
      sparkles.push({
        x: p.mouseX + p.random(-50, 50),
        y: p.mouseY + p.random(-50, 50),
        size: p.random(2, 6),
        speed: p.random(1, 3),
        hue: p.random(200, 300),
        brightness: p.random(70, 100),
        phase: p.random(p.TWO_PI)
      });
    }

    // Remove excess sparkles
    if (sparkles.length > 150) {
      sparkles.splice(0, sparkles.length - 150);
    }
  };
}

function sketch(p) {
  let flows = [];
  let cartographer;
  let mappingLines = [];
  let vectorPoints = [];
  let flowField = [];
  let gridSize = 20;
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize flow field
    for (let x = 0; x < p.width; x += gridSize) {
      for (let y = 0; y < p.height; y += gridSize) {
        flowField.push({
          x: x,
          y: y,
          angle: 0,
          magnitude: 0
        });
      }
    }

    // Create flowing particles
    for (let i = 0; i < 80; i++) {
      flows.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        trail: [],
        maxTrail: p.random(15, 30),
        color: p.color(p.random(180, 220), p.random(120, 180), p.random(200, 255), 150),
        size: p.random(2, 5)
      });
    }

    // Cartographer figure
    cartographer = {
      x: p.width * 0.5,
      y: p.height * 0.7,
      mappingRadius: 80,
      currentVector: 0
    };

    p.colorMode(p.HSB, 360, 100, 100, 100);
  };

  p.draw = function() {
    p.background(220, 20, 15);

    time += 0.02;

    // Update flow field based on mouse and time
    let mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 2);
    for (let i = 0; i < flowField.length; i++) {
      let field = flowField[i];
      let noise = p.noise(field.x * 0.01, field.y * 0.01, time);
      let distToMouse = p.dist(field.x, field.y, p.mouseX, p.mouseY);

      field.angle = noise * p.TWO_PI * 4 + p.atan2(p.mouseY - field.y, p.mouseX - field.x) * 0.3;
      field.magnitude = p.map(distToMouse, 0, 200, mouseInfluence, 0.3);
    }

    // Draw subtle flow field visualization
    p.stroke(200, 30, 80, 20);
    p.strokeWeight(1);
    for (let field of flowField) {
      let endX = field.x + p.cos(field.angle) * field.magnitude * 15;
      let endY = field.y + p.sin(field.angle) * field.magnitude * 15;
      p.line(field.x, field.y, endX, endY);
    }

    // Update and draw flows
    for (let flow of flows) {
      // Find nearest flow field point
      let gridX = Math.floor(flow.x / gridSize) * gridSize;
      let gridY = Math.floor(flow.y / gridSize) * gridSize;
      let fieldIndex = flowField.findIndex(f => f.x === gridX && f.y === gridY);

      if (fieldIndex >= 0) {
        let field = flowField[fieldIndex];
        flow.vx += p.cos(field.angle) * field.magnitude * 0.1;
        flow.vy += p.sin(field.angle) * field.magnitude * 0.1;
      }

      // Apply some random drift
      flow.vx += p.random(-0.05, 0.05);
      flow.vy += p.random(-0.05, 0.05);

      // Limit velocity
      let vel = p.sqrt(flow.vx * flow.vx + flow.vy * flow.vy);
      if (vel > 3) {
        flow.vx = (flow.vx / vel) * 3;
        flow.vy = (flow.vy / vel) * 3;
      }

      // Update position
      flow.x += flow.vx;
      flow.y += flow.vy;

      // Wrap around edges
      if (flow.x < 0) flow.x = p.width;
      if (flow.x > p.width) flow.x = 0;
      if (flow.y < 0) flow.y = p.height;
      if (flow.y > p.height) flow.y = 0;

      // Update trail
      flow.trail.push({x: flow.x, y: flow.y});
      if (flow.trail.length > flow.maxTrail) {
        flow.trail.shift();
      }

      // Draw trail
      p.strokeWeight(1);
      for (let i = 0; i < flow.trail.length - 1; i++) {
        let alpha = p.map(i, 0, flow.trail.length, 0, 60);
        p.stroke(p.hue(flow.color), p.saturation(flow.color), p.brightness(flow.color), alpha);
        p.line(flow.trail[i].x, flow.trail[i].y, flow.trail[i + 1].x, flow.trail[i + 1].y);
      }

      // Draw particle
      p.fill(flow.color);
      p.noStroke();
      p.circle(flow.x, flow.y, flow.size);
    }

    // Cartographer's mapping activity
    let mappingAngle = time * 2;
    let vectorX = cartographer.x + p.cos(mappingAngle) * cartographer.mappingRadius;
    let vectorY = cartographer.y + p.sin(mappingAngle) * cartographer.mappingRadius;

    // Add vector points periodically
    if (p.frameCount % 10 === 0) {
      vectorPoints.push({
        x: vectorX,
        y: vectorY,
        age: 0,
        maxAge: 120
      });
    }

    // Update and draw vector points
    for (let i = vectorPoints.length - 1; i >= 0; i--) {
      let point = vectorPoints[i];
      point.age++;

      if (point.age > point.maxAge) {
        vectorPoints.splice(i, 1);
        continue;
      }

      let alpha = p.map(point.age, 0, point.maxAge, 80, 0);
      p.fill(40, 80, 90, alpha);
      p.noStroke();
      p.circle(point.x, point.y, 3);
    }

    // Draw mapping lines connecting recent vector points
    if (vectorPoints.length > 1) {
      p.stroke(40, 60, 95, 40);
      p.strokeWeight(1);
      p.noFill();
      p.beginShape();
      for (let point of vectorPoints.slice(-20)) {
        p.vertex(point.x, point.y);
      }
      p.endShape();
    }

    // Draw cartographer figure
    p.fill(30, 70, 95);
    p.noStroke();

    // Body
    p.ellipse(cartographer.x, cartographer.y, 20, 30);

    // Head
    p.ellipse(cartographer.x, cartographer.y - 20, 15, 15);

    // Mapping tool/compass
    p.stroke(50, 80, 100);
    p.strokeWeight(2);
    p.line(cartographer.x, cartographer.y, vectorX, vectorY);

    // Compass/tool at end
    p.fill(50, 80, 100);
    p.noStroke();
    p.circle(vectorX, vectorY, 6);

    // Interactive mapping on mouse press
    if (p.mouseIsPressed) {
      // Draw temporary mapping vectors
      p.stroke(60, 90, 100, 60);
      p.strokeWeight(1);
      for (let flow of flows) {
        if (p.dist(flow.x, flow.y, p.mouseX, p.mouseY) < 50) {
          p.line(p.mouseX, p.mouseY, flow.x, flow.y);

          // Show velocity vector
          let endX = flow.x + flow.vx * 20;
          let endY = flow.y + flow.vy * 20;
          p.stroke(180, 80, 100, 80);
          p.line(flow.x, flow.y, endX, endY);
          p.circle(endX, endY, 3);
        }
      }
    }

    // Subtle border
    p.noFill();
    p.stroke(200, 40, 90, 30);
    p.strokeWeight(2);
    p.rect(10, 10, p.width - 20, p.height - 20, 15);
  };
}

function sketch(p) {
  let flowLines = [];
  let structures = [];
  let architect = {};
  let time = 0;
  let particleSystem = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize architect figure
    architect = {
      x: 200,
      y: 400,
      armAngle: 0,
      energy: 0
    };

    // Initialize flowing energy lines
    for (let i = 0; i < 15; i++) {
      flowLines.push({
        points: [],
        color: p.random(['#4A90E2', '#7B68EE', '#9370DB', '#6495ED']),
        speed: p.random(0.02, 0.08),
        amplitude: p.random(20, 60),
        offset: p.random(0, p.TWO_PI)
      });

      // Create initial points for each flow
      for (let j = 0; j < 50; j++) {
        flowLines[i].points.push({
          x: p.random(-50, 450),
          y: p.random(50, 550),
          baseY: p.random(50, 550)
        });
      }
    }

    // Initialize architectural structures that form from flows
    for (let i = 0; i < 8; i++) {
      structures.push({
        x: p.random(50, 350),
        y: p.random(100, 300),
        segments: [],
        brightness: 0,
        forming: false
      });
    }
  };

  p.draw = function() {
    // Gradient background
    for (let i = 0; i <= 600; i++) {
      let inter = p.map(i, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(20, 10, 40), p.color(5, 5, 15), inter);
      p.stroke(c);
      p.line(0, i, 400, i);
    }

    time += 0.016;

    // Update architect based on mouse proximity
    let mouseInfluence = p.dist(p.mouseX, p.mouseY, architect.x, architect.y) / 200;
    architect.energy = p.map(mouseInfluence, 0, 2, 1, 0.3);
    architect.armAngle = p.sin(time * 3) * 0.3 + p.atan2(p.mouseY - architect.y, p.mouseX - architect.x) * 0.2;

    // Draw flowing energy lines
    p.noFill();
    for (let flow of flowLines) {
      p.strokeWeight(2);

      // Create flowing effect
      for (let i = 0; i < flow.points.length - 1; i++) {
        let point = flow.points[i];
        point.y = point.baseY + p.sin(time * flow.speed + i * 0.3 + flow.offset) * flow.amplitude;

        // Attract towards architect's hands when mouse is near
        if (p.dist(p.mouseX, p.mouseY, architect.x, architect.y) < 100) {
          let handX = architect.x + p.cos(architect.armAngle) * 40;
          let handY = architect.y + p.sin(architect.armAngle) * 40;
          let attraction = p.createVector(handX - point.x, handY - point.y);
          attraction.mult(0.003);
          point.x += attraction.x;
          point.y += attraction.y;
        }

        // Create glowing effect
        for (let glow = 3; glow > 0; glow--) {
          let alpha = p.map(glow, 1, 3, 255, 50);
          p.stroke(p.red(p.color(flow.color)), p.green(p.color(flow.color)), p.blue(p.color(flow.color)), alpha);
          p.strokeWeight(glow * 2);

          if (i < flow.points.length - 1) {
            p.line(point.x, point.y, flow.points[i + 1].x, flow.points[i + 1].y);
          }
        }
      }
    }

    // Update and draw architectural structures forming from flows
    for (let struct of structures) {
      if (p.random() < 0.02 || (p.mouseIsPressed && p.dist(p.mouseX, p.mouseY, struct.x, struct.y) < 80)) {
        struct.forming = true;
        struct.brightness = p.min(struct.brightness + 5, 255);

        // Add new segments
        if (struct.segments.length < 12) {
          struct.segments.push({
            x: struct.x + p.random(-30, 30),
            y: struct.y + p.random(-30, 30),
            vx: p.random(-1, 1),
            vy: p.random(-1, 1),
            life: 255
          });
        }
      } else {
        struct.brightness = p.max(struct.brightness - 2, 0);
      }

      // Draw structure segments
      p.fill(100, 150, 255, struct.brightness);
      p.noStroke();
      for (let seg of struct.segments) {
        seg.x += seg.vx * 0.5;
        seg.y += seg.vy * 0.5;
        seg.life -= 1;

        if (seg.life > 0) {
          p.push();
          p.translate(seg.x, seg.y);
          p.rotate(time + seg.x * 0.01);
          p.fill(120, 160, 255, seg.life * struct.brightness / 255);
          p.rect(-3, -3, 6, 6);
          p.pop();
        }
      }

      // Remove dead segments
      struct.segments = struct.segments.filter(seg => seg.life > 0);
    }

    // Draw architect figure
    p.push();
    p.translate(architect.x, architect.y);

    // Body
    p.fill(80, 60, 120, 200);
    p.noStroke();
    p.ellipse(0, 0, 30, 50);

    // Arms channeling energy
    p.stroke(150, 180, 255, 180);
    p.strokeWeight(4);
    let armLength = 40;
    let rightArmX = p.cos(architect.armAngle) * armLength;
    let rightArmY = p.sin(architect.armAngle) * armLength;
    p.line(0, -10, rightArmX, rightArmY - 10);

    let leftArmX = p.cos(architect.armAngle + 0.5) * armLength;
    let leftArmY = p.sin(architect.armAngle + 0.5) * armLength;
    p.line(0, -10, leftArmX, leftArmY - 10);

    // Energy emanating from hands
    if (architect.energy > 0.5) {
      for (let i = 0; i < 8; i++) {
        let sparkX = rightArmX + p.random(-15, 15);
        let sparkY = rightArmY - 10 + p.random(-15, 15);
        p.fill(180, 200, 255, p.random(100, 255));
        p.noStroke();
        p.ellipse(sparkX, sparkY, 3, 3);
      }
    }

    // Head
    p.fill(90, 70, 130, 220);
    p.ellipse(0, -35, 20, 20);

    p.pop();

    // Add floating particles that respond to interaction
    if (p.frameCount % 3 === 0) {
      particleSystem.push({
        x: p.random(400),
        y: 600,
        vx: p.random(-0.5, 0.5),
        vy: p.random(-2, -0.5),
        life: 255,
        size: p.random(2, 6)
      });
    }

    // Update and draw particles
    for (let i = particleSystem.length - 1; i >= 0; i--) {
      let particle = particleSystem[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 2;

      // Mouse interaction
      if (p.dist(p.mouseX, p.mouseY, particle.x, particle.y) < 50) {
        particle.vx += (particle.x - p.mouseX) * 0.002;
        particle.vy += (particle.y - p.mouseY) * 0.002;
      }

      p.fill(120, 160, 255, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if (particle.life <= 0 || particle.y < 0) {
        particleSystem.splice(i, 1);
      }
    }
  };

  p.mousePressed = function() {
    // Create burst of energy at mouse position
    for (let i = 0; i < 20; i++) {
      particleSystem.push({
        x: p.mouseX,
        y: p.mouseY,
        vx: p.random(-3, 3),
        vy: p.random(-3, 3),
        life: 150,
        size: p.random(3, 8)
      });
    }
  };
}

function sketch(p) {
  let prophet;
  let trajectories = [];
  let flowParticles = [];
  let teachings = [];
  let time = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    prophet = {
      x: 200,
      y: 320,
      armAngle: 0,
      headTilt: 0,
      eyeGlow: 0
    };

    // Create trajectory lines that show where flows are heading
    for(let i = 0; i < 8; i++) {
      trajectories.push({
        startX: prophet.x + p.random(-40, 40),
        startY: prophet.y + p.random(-60, -20),
        points: [],
        color: p.color(p.random(180, 250), p.random(100, 200), p.random(200, 255), 150),
        phase: p.random(p.TWO_PI)
      });

      // Generate curved trajectory points
      for(let j = 0; j < 20; j++) {
        let progress = j / 19;
        trajectories[i].points.push({
          x: trajectories[i].startX + progress * p.random(100, 180) * p.cos(progress * p.PI + i * 0.3),
          y: trajectories[i].startY - progress * p.random(120, 200),
          intensity: 1 - progress
        });
      }
    }

    // Flow particles that respond to understanding
    for(let i = 0; i < 60; i++) {
      flowParticles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-1, 1),
        vy: p.random(-2, 0),
        size: p.random(2, 8),
        color: p.color(p.random(150, 255), p.random(80, 180), p.random(180, 255), 120),
        originalX: 0,
        originalY: 0,
        influenced: false
      });
      flowParticles[i].originalX = flowParticles[i].x;
      flowParticles[i].originalY = flowParticles[i].y;
    }

    // Teaching emanations - frameworks that don't freeze motion
    for(let i = 0; i < 5; i++) {
      teachings.push({
        x: prophet.x + p.cos(i * p.TWO_PI / 5) * 80,
        y: prophet.y + p.sin(i * p.TWO_PI / 5) * 60,
        radius: 0,
        maxRadius: p.random(30, 50),
        phase: i * 0.8
      });
    }
  };

  p.draw = function() {
    // Deep space background with flowing gradients
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(15, 5, 35),
        p.color(45, 25, 85),
        inter + p.sin(time * 0.01 + y * 0.01) * 0.1
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 1;

    // Update prophet's gestures
    prophet.armAngle = p.sin(time * 0.02) * 0.3;
    prophet.headTilt = p.sin(time * 0.015) * 0.1;
    prophet.eyeGlow = p.map(p.sin(time * 0.03), -1, 1, 100, 255);

    // Draw flowing particles with understanding influence
    let mouseInfluence = p.createVector(p.mouseX, p.mouseY);

    for(let particle of flowParticles) {
      let distance = p.dist(particle.x, particle.y, prophet.x, prophet.y);
      let understanding = p.map(distance, 0, 200, 1, 0);
      understanding = p.constrain(understanding, 0, 1);

      if(understanding > 0.3) {
        // Particles near prophet become more organized but keep moving
        let targetX = particle.originalX + p.sin(time * 0.01 + particle.x * 0.01) * understanding * 20;
        let targetY = particle.originalY + p.cos(time * 0.008 + particle.y * 0.01) * understanding * 15;
        particle.x = p.lerp(particle.x, targetX, 0.02);
        particle.y = p.lerp(particle.y, targetY, 0.02);
        particle.influenced = true;
      } else {
        // Free-flowing particles
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.influenced = false;
      }

      // Mouse interaction - gentle guidance, not control
      let mouseDist = p.dist(particle.x, particle.y, p.mouseX, p.mouseY);
      if(mouseDist < 80) {
        let force = p.map(mouseDist, 0, 80, 0.5, 0);
        let angle = p.atan2(particle.y - p.mouseY, particle.x - p.mouseX);
        particle.vx += p.cos(angle) * force * 0.1;
        particle.vy += p.sin(angle) * force * 0.1;
      }

      // Wrap around edges
      if(particle.x < 0) particle.x = p.width;
      if(particle.x > p.width) particle.x = 0;
      if(particle.y < 0) particle.y = p.height;
      if(particle.y > p.height) particle.y = 0;

      // Draw particle with glow
      p.push();
      p.translate(particle.x, particle.y);

      // Glow effect
      for(let r = particle.size * 3; r > 0; r--) {
        let alpha = p.map(r, 0, particle.size * 3, 255, 0) * (particle.influenced ? 0.8 : 0.4);
        particle.color.setAlpha(alpha * 0.3);
        p.fill(particle.color);
        p.noStroke();
        p.ellipse(0, 0, r);
      }

      // Core particle
      particle.color.setAlpha(200);
      p.fill(particle.color);
      p.ellipse(0, 0, particle.size);
      p.pop();
    }

    // Draw trajectory lines - showing where flows are heading
    for(let traj of trajectories) {
      p.stroke(traj.color);
      p.noFill();

      for(let i = 1; i < traj.points.length; i++) {
        let prev = traj.points[i-1];
        let curr = traj.points[i];

        let pulse = p.sin(time * 0.05 + traj.phase + i * 0.2) * 0.3 + 0.7;
        p.strokeWeight(curr.intensity * 3 * pulse);

        // Add some organic curve
        let offsetX = p.sin(time * 0.02 + i * 0.3) * 5;
        let offsetY = p.cos(time * 0.025 + i * 0.4) * 3;

        p.line(
          prev.x + offsetX, prev.y + offsetY,
          curr.x + offsetX, curr.y + offsetY
        );
      }

      // Arrow at the end showing direction
      let lastPoint = traj.points[traj.points.length - 1];
      let secondLast = traj.points[traj.points.length - 2];
      let angle = p.atan2(lastPoint.y - secondLast.y, lastPoint.x - secondLast.x);

      p.push();
      p.translate(lastPoint.x, lastPoint.y);
      p.rotate(angle);
      p.strokeWeight(2);
      p.line(-10, -5, 0, 0);
      p.line(-10, 5, 0, 0);
      p.pop();
    }

    // Draw teaching emanations - frameworks that preserve motion
    for(let teaching of teachings) {
      teaching.radius = p.sin(time * 0.03 + teaching.phase) * teaching.maxRadius * 0.5 + teaching.maxRadius * 0.5;

      p.push();
      p.translate(teaching.x, teaching.y);

      // Rotating framework patterns
      p.rotate(time * 0.01 + teaching.phase);
      p.stroke(150, 120, 255, 100);
      p.strokeWeight(1);
      p.noFill();

      // Geometric framework that breathes
      for(let i = 0; i < 6; i++) {
        let angle = i * p.TWO_PI / 6;
        let x1 = p.cos(angle) * teaching.radius * 0.3;
        let y1 = p.sin(angle) * teaching.radius * 0.3;
        let x2 = p.cos(angle) * teaching.radius;
        let y2 = p.sin(angle) * teaching.radius;
        p.line(x1, y1, x2, y2);
      }

      // Inner flowing pattern
      p.stroke(180, 150, 255, 150);
      for(let i = 0; i < 12; i++) {
        let angle = i * p.TWO_PI / 12 + time * 0.02;
        let r = teaching.radius * 0.6 + p.sin(time * 0.05 + i * 0.5) * 10;
        let x = p.cos(angle) * r;
        let y = p.sin(angle) * r;
        p.point(x, y);
      }

      p.pop();
    }

    // Draw the prophet figure
    p.push();
    p.translate(prophet.x, prophet.y);

    // Body - flowing robes
    p.fill(60, 40, 120, 200);
    p.stroke(120, 100, 200, 150);
    p.strokeWeight(2);

    // Flowing robe shape
    p.beginShape();
    for(let i = 0; i < 16; i++) {
      let angle = i * p.TWO_PI / 16;
      let r = 35 + p.sin(time * 0.03 + i * 0.5) * 8;
      let x = p.cos(angle) * r;
      let y = p.sin(angle) * r + 60;
      p.vertex(x, y);
    }
    p.endShape(p.CLOSE);

    // Arms - one pointing toward transformation
    p.push();
    p.rotate(prophet.armAngle);
    p.stroke(150, 120, 255);
    p.strokeWeight(4);
    p.line(0, 0, 60, -30);

    // Hand with energy
    p.push();
    p.translate(60, -30);
    p.fill(200, 150, 255, prophet.eyeGlow);
    p.noStroke();
    p.ellipse(0, 0, 12);

    // Energy emanation from pointing finger
    for(let i = 0; i < 8; i++) {
      let angle = i * p.TWO_PI / 8 + time * 0.05;
      let r = 15 + p.sin(time * 0.1 + i) * 5;
      let x = p.cos(angle) * r;
      let y = p.sin(angle) * r;
      p.fill(220, 180, 255, 100);
      p.ellipse(x, y, 4);
    }
    p.pop();
    p.pop();

    // Head with understanding glow
    p.push();
    p.rotate(prophet.headTilt);

    // Head glow
    p.fill(180, 140, 255, prophet.eyeGlow * 0.3);
    p.noStroke();
    p.ellipse(0, -60, 50);

    // Head
    p.fill(120, 100, 180);
    p.stroke(160, 140, 220);
    p.strokeWeight(1);
    p.ellipse(0, -60, 35);

    // Eyes that see transformation patterns
    p.fill(prophet.eyeGlow, 200, 255);
    p.noStroke();
    p.ellipse(-8, -65, 6);
    p.ellipse(8, -65, 6);

    // Third eye - understanding
    p.fill(255, 220, 255, prophet.eyeGlow);
    p.ellipse(0, -70, 4);

    p.pop();
    p.pop();

    // Interactive teaching - mouse proximity creates understanding ripples
    let mouseDist = p.dist(p.mouseX, p.mouseY, prophet.x, prophet.y);
    if(mouseDist < 150) {
      let intensity = p.map(mouseDist, 0, 150, 1, 0);

      p.push();
      p.translate(prophet.x, prophet.y);
      p.stroke(200, 150, 255, intensity * 100);
      p.strokeWeight(2);
      p.noFill();

      for(let i = 1; i <= 4; i++) {
        let radius = i * 30 + p.sin(time * 0.1) * 10;
        p.ellipse(0, 0, radius * intensity * 2);
      }
      p.pop();
    }
  };
}

function sketch(p) {
  let crystalSeeds = [];
  let time = 0;
  let mouseInfluence = 0;
  let plateauLines = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 1);

    // Create the main crystal seed at center
    crystalSeeds.push({
      x: 200,
      y: 300,
      size: 80,
      rotation: 0,
      pulsePhase: 0,
      isMain: true,
      coherence: 0
    });

    // Create smaller potential seeds around it
    for(let i = 0; i < 8; i++) {
      let angle = i * p.TWO_PI / 8;
      crystalSeeds.push({
        x: 200 + p.cos(angle) * 120,
        y: 300 + p.sin(angle) * 100,
        size: p.random(15, 30),
        rotation: p.random(p.TWO_PI),
        pulsePhase: p.random(p.TWO_PI),
        isMain: false,
        coherence: 0
      });
    }

    // Initialize plateau formation lines
    for(let i = 0; i < 60; i++) {
      plateauLines.push({
        x1: p.random(400),
        y1: p.random(600),
        x2: p.random(400),
        y2: p.random(600),
        alpha: 0,
        targetAlpha: 0
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0, 1);

    // Deep space background with subtle gradient
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(
        p.color(230, 80, 15),  // Deep blue
        p.color(200, 60, 5),   // Darker blue
        inter
      );
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Update coherence based on mouse interaction
    let targetCoherence = mouseInfluence * 0.8 + 0.2;

    // Draw plateau formation lines (sacred geometry substrate)
    p.strokeWeight(1);
    for(let line of plateauLines) {
      line.targetAlpha = targetCoherence * 0.3;
      line.alpha = p.lerp(line.alpha, line.targetAlpha, 0.05);

      if(line.alpha > 0.01) {
        p.stroke(45, 90, 90, line.alpha);
        p.line(line.x1, line.y1, line.x2, line.y2);
      }
    }

    // Draw connection web between seeds
    p.strokeWeight(1);
    for(let i = 0; i < crystalSeeds.length; i++) {
      for(let j = i + 1; j < crystalSeeds.length; j++) {
        let seed1 = crystalSeeds[i];
        let seed2 = crystalSeeds[j];
        let distance = p.dist(seed1.x, seed1.y, seed2.x, seed2.y);

        if(distance < 200) {
          let connectionStrength = p.map(distance, 0, 200, 1, 0) * targetCoherence;
          p.stroke(45, 70, 80, connectionStrength * 0.4);
          p.line(seed1.x, seed1.y, seed2.x, seed2.y);
        }
      }
    }

    // Draw crystal seeds
    for(let seed of crystalSeeds) {
      p.push();
      p.translate(seed.x, seed.y);
      p.rotate(seed.rotation + time * 0.3);

      seed.coherence = p.lerp(seed.coherence, targetCoherence, 0.08);
      let pulse = p.sin(time * 2 + seed.pulsePhase) * 0.3 + 1;
      let currentSize = seed.size * pulse * (0.6 + seed.coherence * 0.8);

      // Draw the crystal structure
      p.noFill();
      p.strokeWeight(2);

      // Outer crystal formation
      p.stroke(45, 80, 85, 0.8);
      drawCrystalShape(p, currentSize, 6);

      // Inner geometric core
      p.stroke(45, 90, 95, seed.coherence);
      drawCrystalShape(p, currentSize * 0.6, 3);

      // Central nucleus
      if(seed.isMain) {
        p.fill(45, 100, 100, seed.coherence * 0.7);
        p.noStroke();
        p.circle(0, 0, currentSize * 0.2);

        // Emanating potential lines
        p.strokeWeight(1);
        for(let i = 0; i < 12; i++) {
          let angle = i * p.TWO_PI / 12;
          let length = currentSize * 0.8 * seed.coherence;
          p.stroke(45, 70, 90, seed.coherence * 0.6);
          p.line(0, 0, p.cos(angle) * length, p.sin(angle) * length);
        }
      }

      p.pop();

      // Update rotation
      seed.rotation += 0.005;
    }

    // Draw emergent plateau hints (when coherence is high)
    if(targetCoherence > 0.5) {
      p.strokeWeight(2);
      p.noFill();
      let plateauAlpha = p.map(targetCoherence, 0.5, 1, 0, 0.6);

      // Mesa-like formation emerging from center
      p.stroke(45, 60, 70, plateauAlpha);
      let plateau1 = 150 * targetCoherence;
      let plateau2 = 100 * targetCoherence;

      p.beginShape();
      p.vertex(200 - plateau1, 350);
      p.vertex(200 - plateau2, 250);
      p.vertex(200 + plateau2, 250);
      p.vertex(200 + plateau1, 350);
      p.endShape();
    }
  };

  function drawCrystalShape(p, size, sides) {
    p.beginShape();
    for(let i = 0; i < sides; i++) {
      let angle = i * p.TWO_PI / sides;
      let x = p.cos(angle) * size;
      let y = p.sin(angle) * size;
      p.vertex(x, y);
    }
    p.endShape(p.CLOSE);
  }

  p.mousePressed = function() {
    // Pulse effect on click
    for(let seed of crystalSeeds) {
      seed.pulsePhase = time * 2;
    }

    // Reorganize plateau lines
    for(let line of plateauLines) {
      if(p.random() < 0.3) {
        line.x1 = p.random(400);
        line.y1 = p.random(600);
        line.x2 = p.random(400);
        line.y2 = p.random(600);
      }
    }
  };
}

function sketch(p) {
  let crystals = [];
  let particles = [];
  let time = 0;
  let splitProgress = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize crystal formations
    for (let i = 0; i < 12; i++) {
      crystals.push({
        x: p.random(100, 300),
        y: p.random(200, 500),
        size: p.random(15, 40),
        angle: p.random(p.TWO_PI),
        growth: p.random(0.5, 1.5),
        side: i < 6 ? 'left' : 'right',
        baseY: p.random(350, 450),
        height: p.random(80, 150)
      });
    }

    // Initialize floating particles
    for (let i = 0; i < 30; i++) {
      particles.push({
        x: p.random(p.width),
        y: p.random(p.height),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.3, 0.3),
        size: p.random(2, 6),
        alpha: p.random(100, 200)
      });
    }
  };

  p.draw = function() {
    time += 0.01;

    // Deep blue to black gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(20, 40, 80), p.color(5, 10, 25), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Calculate mouse influence
    mouseInfluence = p.map(p.mouseX, 0, p.width, -1, 1);
    splitProgress = p.map(p.mouseY, 0, p.height, 0.2, 1);

    // Draw central division line with energy
    p.push();
    p.stroke(255, 220, 100, 150);
    p.strokeWeight(2);
    for (let i = 0; i < 20; i++) {
      let y = p.map(i, 0, 19, 100, 500);
      let wave = p.sin(time * 3 + i * 0.3) * 15 * splitProgress;
      let x = p.width/2 + wave;
      if (i > 0) {
        let prevY = p.map(i-1, 0, 19, 100, 500);
        let prevWave = p.sin(time * 3 + (i-1) * 0.3) * 15 * splitProgress;
        let prevX = p.width/2 + prevWave;
        p.line(prevX, prevY, x, y);
      }
    }
    p.pop();

    // Draw crystal formations on both sides
    crystals.forEach((crystal, i) => {
      let targetX = crystal.side === 'left' ? 
        p.map(splitProgress, 0, 1, 200, 150) : 
        p.map(splitProgress, 0, 1, 200, 250);

      crystal.x = p.lerp(crystal.x, targetX + p.sin(time + i) * 10, 0.02);

      p.push();
      p.translate(crystal.x, crystal.baseY);

      // Crystal color based on side and mouse interaction
      let hue = crystal.side === 'left' ? 
        220 + mouseInfluence * 20 : 
        45 + mouseInfluence * 15;

      p.fill(p.color(`hsl(${hue}, 70%, 60%)`));
      p.stroke(p.color(`hsl(${hue}, 80%, 80%)`));
      p.strokeWeight(1.5);

      // Draw crystalline structure
      p.beginShape();
      for (let angle = 0; angle < p.TWO_PI; angle += p.PI/3) {
        let radius = crystal.size * (1 + p.sin(time * crystal.growth + angle) * 0.1);
        let x = p.cos(angle + crystal.angle) * radius;
        let y = p.sin(angle + crystal.angle) * radius - crystal.height * splitProgress;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Inner glow
      p.fill(p.color(`hsl(${hue}, 90%, 80%)`));
      p.noStroke();
      p.beginShape();
      for (let angle = 0; angle < p.TWO_PI; angle += p.PI/3) {
        let radius = crystal.size * 0.6;
        let x = p.cos(angle + crystal.angle) * radius;
        let y = p.sin(angle + crystal.angle) * radius - crystal.height * splitProgress * 0.8;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      p.pop();
    });

    // Draw connecting energy between sides
    p.stroke(255, 200, 100, 100);
    p.strokeWeight(1);
    for (let i = 0; i < 8; i++) {
      let leftCrystal = crystals[i % 6];
      let rightCrystal = crystals[6 + (i % 6)];

      let energy = p.sin(time * 2 + i) * 0.5 + 0.5;
      p.stroke(255, 200, 100, energy * 80);

      p.line(
        leftCrystal.x, leftCrystal.baseY - leftCrystal.height * splitProgress * 0.5,
        rightCrystal.x, rightCrystal.baseY - rightCrystal.height * splitProgress * 0.5
      );
    }

    // Update and draw floating particles
    particles.forEach(particle => {
      particle.x += particle.vx + mouseInfluence * 0.2;
      particle.y += particle.vy + p.sin(time + particle.x * 0.01) * 0.1;

      // Wrap around edges
      if (particle.x < 0) particle.x = p.width;
      if (particle.x > p.width) particle.x = 0;
      if (particle.y < 0) particle.y = p.height;
      if (particle.y > p.height) particle.y = 0;

      // Draw particle
      let side = particle.x < p.width/2 ? 'left' : 'right';
      let hue = side === 'left' ? 220 : 45;

      p.fill(p.color(`hsl(${hue}, 60%, 70%)`));
      p.noStroke();
      p.circle(particle.x, particle.y, particle.size * (1 + p.sin(time * 3 + particle.x) * 0.2));
    });

    // Draw plateau base structure
    p.fill(40, 50, 70, 150);
    p.stroke(100, 120, 150, 200);
    p.strokeWeight(2);

    // Left plateau base
    p.beginShape();
    p.vertex(50, p.height - 50);
    p.vertex(50 + p.sin(time) * 5, 450 - splitProgress * 30);
    p.vertex(180 + p.cos(time * 0.7) * 8, 420 - splitProgress * 40);
    p.vertex(200, p.height - 50);
    p.endShape(p.CLOSE);

    // Right plateau base  
    p.beginShape();
    p.vertex(200, p.height - 50);
    p.vertex(220 + p.sin(time * 0.8) * 6, 420 - splitProgress * 35);
    p.vertex(350 + p.cos(time * 0.5) * 10, 450 - splitProgress * 25);
    p.vertex(350, p.height - 50);
    p.endShape(p.CLOSE);
  };

  p.mousePressed = function() {
    // Add burst of particles at mouse position
    for (let i = 0; i < 5; i++) {
      particles.push({
        x: p.mouseX + p.random(-20, 20),
        y: p.mouseY + p.random(-20, 20),
        vx: p.random(-2, 2),
        vy: p.random(-2, 2),
        size: p.random(3, 8),
        alpha: 255
      });
    }

    // Keep particle count manageable
    if (particles.length > 50) {
      particles.splice(0, particles.length - 50);
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let convergencePoint;
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create three plateau formations
    plateaus = [
      {
        x: 100, y: 400, 
        baseWidth: 80, baseHeight: 60,
        layers: 4,
        rotation: 0,
        color: p.color(45, 55, 120, 180),
        accent: p.color(180, 150, 60, 120)
      },
      {
        x: 300, y: 450, 
        baseWidth: 90, baseHeight: 70,
        layers: 3,
        rotation: p.PI/6,
        color: p.color(60, 45, 100, 180),
        accent: p.color(220, 180, 80, 120)
      },
      {
        x: 200, y: 350, 
        baseWidth: 85, baseHeight: 65,
        layers: 5,
        rotation: -p.PI/8,
        color: p.color(35, 65, 95, 180),
        accent: p.color(255, 200, 90, 120)
      }
    ];

    // Convergence point where new form emerges
    convergencePoint = {
      x: 200,
      y: 250,
      energy: 0
    };

    // Initialize particles for the emergent crystalline discharge
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: convergencePoint.x + p.random(-30, 30),
        y: convergencePoint.y + p.random(-30, 30),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.5, 0.5),
        life: p.random(100, 255),
        maxLife: p.random(100, 255),
        size: p.random(2, 8)
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Gradient background - deep blues to golds
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 55), p.color(45, 35, 25), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Draw energy connections between plateaus
    drawEnergyConnections();

    // Draw individual plateaus
    for (let plateau of plateaus) {
      drawPlateau(plateau);
    }

    // Draw emergent form at convergence
    drawEmergentForm();

    // Draw and update particles
    updateParticles();

    // Draw sacred geometry overlay
    drawSacredGeometry();
  };

  function drawPlateau(plateau) {
    p.push();
    p.translate(plateau.x, plateau.y);
    p.rotate(plateau.rotation + p.sin(time) * 0.1);

    // Draw layered plateau structure
    for (let i = plateau.layers - 1; i >= 0; i--) {
      let layerScale = 1 - (i * 0.15);
      let layerY = -i * 12;

      // Main plateau body
      p.fill(plateau.color);
      p.stroke(plateau.accent);
      p.strokeWeight(1);

      p.beginShape();
      p.vertex(-plateau.baseWidth * layerScale / 2, layerY);
      p.vertex(-plateau.baseWidth * layerScale / 3, layerY - plateau.baseHeight * layerScale / 3);
      p.vertex(plateau.baseWidth * layerScale / 3, layerY - plateau.baseHeight * layerScale / 3);
      p.vertex(plateau.baseWidth * layerScale / 2, layerY);
      p.vertex(plateau.baseWidth * layerScale / 3, layerY + plateau.baseHeight * layerScale / 4);
      p.vertex(-plateau.baseWidth * layerScale / 3, layerY + plateau.baseHeight * layerScale / 4);
      p.endShape(p.CLOSE);

      // Crystalline details
      let crystalCount = 3 + i;
      for (let j = 0; j < crystalCount; j++) {
        let angle = (j / crystalCount) * p.TWO_PI;
        let crystalX = p.cos(angle) * (plateau.baseWidth * layerScale / 4);
        let crystalY = layerY + p.sin(angle) * (plateau.baseHeight * layerScale / 6);

        p.fill(plateau.accent);
        p.noStroke();
        p.ellipse(crystalX, crystalY, 4 + p.sin(time + j) * 2);
      }
    }

    p.pop();
  };

  function drawEnergyConnections() {
    p.stroke(255, 200, 100, 150 + mouseInfluence * 100);
    p.strokeWeight(2);
    p.noFill();

    // Connections between plateaus
    for (let i = 0; i < plateaus.length; i++) {
      for (let j = i + 1; j < plateaus.length; j++) {
        let p1 = plateaus[i];
        let p2 = plateaus[j];

        // Curved energy lines
        let midX = (p1.x + p2.x) / 2 + p.sin(time + i + j) * 20;
        let midY = (p1.y + p2.y) / 2 - 40 - p.cos(time + i + j) * 15;

        p.bezier(p1.x, p1.y - 30, midX, midY, midX, midY, p2.x, p2.y - 30);
      }

      // Connection to convergence point
      let plateau = plateaus[i];
      let midX = (plateau.x + convergencePoint.x) / 2;
      let midY = (plateau.y + convergencePoint.y) / 2 - 30;

      p.bezier(
        plateau.x, plateau.y - 30,
        midX + p.sin(time + i) * 15, midY,
        midX + p.cos(time + i) * 15, midY,
        convergencePoint.x, convergencePoint.y
      );
    }
  };

  function drawEmergentForm() {
    p.push();
    p.translate(convergencePoint.x, convergencePoint.y);

    let pulseSize = 1 + p.sin(time * 2) * 0.3 + mouseInfluence * 0.5;
    p.scale(pulseSize);

    // Central emergent crystal
    p.fill(255, 220, 120, 200);
    p.stroke(255, 255, 200);
    p.strokeWeight(2);

    // Multi-layered emergent structure
    for (let layer = 0; layer < 3; layer++) {
      p.rotate(time + layer * p.PI/3);

      p.beginShape();
      for (let i = 0; i < 6; i++) {
        let angle = (i / 6) * p.TWO_PI;
        let radius = 25 + layer * 8;
        let x = p.cos(angle) * radius;
        let y = p.sin(angle) * radius;

        if (i % 2 === 0) {
          p.vertex(x, y);
        } else {
          p.vertex(x * 0.7, y * 0.7);
        }
      }
      p.endShape(p.CLOSE);
    }

    p.pop();
  };

  function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Update position with slight attraction to mouse
      particle.vx += (p.mouseX - particle.x) * 0.0001;
      particle.vy += (p.mouseY - particle.y) * 0.0001;

      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.5;

      // Draw particle
      let alpha = p.map(particle.life, 0, particle.maxLife, 0, 255);
      p.fill(255, 220, 150, alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      // Remove dead particles
      if (particle.life <= 0) {
        particles.splice(i, 1);
        // Add new particle at convergence
        particles.push({
          x: convergencePoint.x + p.random(-20, 20),
          y: convergencePoint.y + p.random(-20, 20),
          vx: p.random(-0.5, 0.5),
          vy: p.random(-0.5, 0.5),
          life: p.random(100, 255),
          maxLife: p.random(100, 255),
          size: p.random(2, 8)
        });
      }
    }
  };

  function drawSacredGeometry() {
    p.push();
    p.translate(200, 150);
    p.rotate(time * 0.1);

    p.stroke(255, 200, 100, 100 + mouseInfluence * 50);
    p.strokeWeight(1);
    p.noFill();

    // Overlapping circles representing the geometry of convergence
    for (let i = 0; i < 3; i++) {
      let angle = (i / 3) * p.TWO_PI;
      let offsetX = p.cos(angle) * 40;
      let offsetY = p.sin(angle) * 40;

      p.circle(offsetX, offsetY, 80);
    }

    p.pop();
  };
}

function sketch(p) {
  let columns = [];
  let crystals = [];
  let particleSystem;
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create four foundational columns
    for (let i = 0; i < 4; i++) {
      let angle = i * p.PI / 2;
      let x = 200 + p.cos(angle) * 80;
      let y = 500 + p.sin(angle) * 40;
      columns.push({
        x: x,
        y: y,
        height: p.random(120, 180),
        width: p.random(25, 35),
        baseY: y,
        oscillation: p.random(0.01, 0.03),
        phase: p.random(p.TWO_PI)
      });
    }

    // Create floating crystals above the plateau
    for (let i = 0; i < 12; i++) {
      crystals.push({
        x: p.random(120, 280),
        y: p.random(200, 350),
        size: p.random(8, 20),
        rotation: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.02, 0.02),
        floatSpeed: p.random(0.005, 0.015),
        floatOffset: p.random(p.TWO_PI),
        sides: p.random([3, 4, 6])
      });
    }

    particleSystem = new ParticleSystem();
  };

  p.draw = function() {
    // Deep blue to gold gradient background
    for (let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 35, 85), p.color(45, 25, 15), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.016;
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseX, 0, p.width, 0, 1), 0.05);

    // Draw connecting energy between columns
    p.strokeWeight(2);
    p.stroke(255, 215, 0, 100 + mouseInfluence * 50);
    for (let i = 0; i < columns.length; i++) {
      let next = (i + 1) % columns.length;
      let x1 = columns[i].x;
      let y1 = columns[i].baseY - columns[i].height;
      let x2 = columns[next].x;
      let y2 = columns[next].baseY - columns[next].height;

      // Curved connection with gentle pulsing
      let midX = (x1 + x2) / 2;
      let midY = (y1 + y2) / 2 - 20 - p.sin(time + i) * 8;

      p.noFill();
      p.bezier(x1, y1, x1, midY, x2, midY, x2, y2);
    }

    // Draw foundational columns
    for (let col of columns) {
      let wobble = p.sin(time * col.oscillation + col.phase) * 2;

      // Column glow
      for (let r = col.width + 20; r > 0; r -= 5) {
        let alpha = p.map(r, 0, col.width + 20, 150, 0);
        p.fill(255, 215, 0, alpha);
        p.noStroke();
        p.ellipse(col.x + wobble, col.baseY - col.height / 2, r * 0.8, col.height + 20);
      }

      // Main column
      p.fill(220, 180, 40, 200 + mouseInfluence * 55);
      p.stroke(255, 235, 100, 180);
      p.strokeWeight(2);
      p.rect(col.x - col.width/2 + wobble, col.baseY - col.height, col.width, col.height, 8);

      // Sacred geometry patterns on columns
      p.push();
      p.translate(col.x + wobble, col.baseY - col.height/2);
      p.noFill();
      p.stroke(255, 240, 150, 120 + p.sin(time + col.phase) * 40);
      p.strokeWeight(1);

      let segments = 6;
      for (let i = 0; i < segments; i++) {
        let r = 8 + p.sin(time + i * 0.5) * 3;
        p.rotate(p.PI / 3);
        p.ellipse(0, 0, r, r);
      }
      p.pop();

      // Column base anchors
      p.fill(40, 60, 120, 180);
      p.stroke(100, 150, 255, 100);
      p.strokeWeight(3);
      p.ellipse(col.x + wobble, col.baseY, col.width * 1.5, 15);
    }

    // Draw plateau surface connecting the columns
    p.fill(80, 100, 160, 120 + mouseInfluence * 30);
    p.stroke(150, 180, 255, 80);
    p.strokeWeight(2);
    p.beginShape();
    for (let i = 0; i < columns.length; i++) {
      let col = columns[i];
      let wobble = p.sin(time * col.oscillation + col.phase) * 2;
      p.vertex(col.x + wobble, col.baseY - col.height);
    }
    p.endShape(p.CLOSE);

    // Draw floating crystals
    for (let crystal of crystals) {
      crystal.rotation += crystal.rotSpeed;
      let floatY = crystal.y + p.sin(time * crystal.floatSpeed + crystal.floatOffset) * 8;

      p.push();
      p.translate(crystal.x, floatY);
      p.rotate(crystal.rotation);

      // Crystal glow
      for (let r = crystal.size + 8; r > 0; r -= 2) {
        let alpha = p.map(r, 0, crystal.size + 8, 80, 0);
        p.fill(200, 230, 255, alpha);
        p.noStroke();
        p.ellipse(0, 0, r, r);
      }

      // Main crystal
      p.fill(180, 220, 255, 160 + p.sin(time + crystal.floatOffset) * 40);
      p.stroke(220, 240, 255, 200);
      p.strokeWeight(1);

      p.beginShape();
      for (let i = 0; i < crystal.sides; i++) {
        let angle = i * p.TWO_PI / crystal.sides;
        let x = p.cos(angle) * crystal.size;
        let y = p.sin(angle) * crystal.size;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Inner sacred geometry
      p.noFill();
      p.stroke(255, 255, 255, 100 + p.sin(time * 2 + crystal.floatOffset) * 50);
      p.strokeWeight(0.5);
      p.ellipse(0, 0, crystal.size * 0.6, crystal.size * 0.6);

      p.pop();
    }

    // Update and draw particle system
    particleSystem.update();
    particleSystem.display();
  };

  p.mousePressed = function() {
    // Add burst of particles when clicked
    for (let i = 0; i < 8; i++) {
      particleSystem.addParticle(p.mouseX, p.mouseY);
    }
  };

  class ParticleSystem {
    constructor() {
      this.particles = [];
    }

    addParticle(x, y) {
      this.particles.push(new Particle(x, y));
    }

    update() {
      // Continuously add gentle particles from columns
      if (p.frameCount % 20 === 0) {
        let col = p.random(columns);
        let wobble = p.sin(time * col.oscillation + col.phase) * 2;
        this.addParticle(col.x + wobble, col.baseY - col.height - 10);
      }

      for (let i = this.particles.length - 1; i >= 0; i--) {
        let particle = this.particles[i];
        particle.update();
        if (particle.isDead()) {
          this.particles.splice(i, 1);
        }
      }
    }

    display() {
      for (let particle of this.particles) {
        particle.display();
      }
    }
  }

  class Particle {
    constructor(x, y) {
      this.position = p.createVector(x, y);
      this.velocity = p.createVector(p.random(-1, 1), p.random(-2, -0.5));
      this.acceleration = p.createVector(0, 0.02);
      this.life = 255;
      this.lifespan = p.random(60, 120);
      this.size = p.random(2, 6);
    }

    update() {
      this.velocity.add(this.acceleration);
      this.position.add(this.velocity);
      this.life -= 255 / this.lifespan;

      // Gentle drift toward mouse
      let mouse = p.createVector(p.mouseX, p.mouseY);
      let force = p5.Vector.sub(mouse, this.position);
      force.mult(0.0005);
      this.velocity.add(force);
    }

    display() {
      p.push();
      p.translate(this.position.x, this.position.y);

      // Soft glow
      p.noStroke();
      p.fill(255, 230, 100, this.life * 0.3);
      p.ellipse(0, 0, this.size * 2, this.size * 2);

      // Core
      p.fill(255, 240, 150, this.life);
      p.ellipse(0, 0, this.size, this.size);

      p.pop();
    }

    isDead() {
      return this.life <= 0;
    }
  }
}

function sketch(p) {
  let plateau;
  let fissures = [];
  let crystals = [];
  let particles = [];
  let time = 0;
  let stressLevel = 0;
  let reorganizing = false;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize plateau as a polygon with 5 major points
    plateau = {
      center: p.createVector(200, 350),
      radius: 140,
      vertices: [],
      originalVertices: [],
      stress: 0
    };

    // Create plateau vertices
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI - p.PI/2;
      let r = plateau.radius + p.random(-20, 20);
      let x = plateau.center.x + p.cos(angle) * r;
      let y = plateau.center.y + p.sin(angle) * r * 0.6;
      plateau.vertices.push(p.createVector(x, y));
      plateau.originalVertices.push(p.createVector(x, y));
    }

    // Create 5 major fissures
    for(let i = 0; i < 5; i++) {
      let angle = (i / 5) * p.TWO_PI + p.random(-0.3, 0.3);
      let startR = p.random(40, 80);
      let endR = p.random(120, 160);

      fissures.push({
        start: p.createVector(
          plateau.center.x + p.cos(angle) * startR,
          plateau.center.y + p.sin(angle) * startR * 0.6
        ),
        end: p.createVector(
          plateau.center.x + p.cos(angle) * endR,
          plateau.center.y + p.sin(angle) * endR * 0.6
        ),
        width: 0,
        maxWidth: p.random(8, 15),
        growth: 0,
        branches: []
      });

      // Add smaller branch fissures
      for(let j = 0; j < p.random(2, 4); j++) {
        let branchAngle = angle + p.random(-p.PI/3, p.PI/3);
        let branchStart = p.random(0.3, 0.7);
        let branchLength = p.random(20, 50);

        fissures[i].branches.push({
          startRatio: branchStart,
          angle: branchAngle,
          length: branchLength,
          width: 0,
          maxWidth: p.random(3, 8)
        });
      }
    }

    // Initialize floating crystals
    for(let i = 0; i < 12; i++) {
      crystals.push({
        pos: p.createVector(p.random(50, 350), p.random(100, 250)),
        vel: p.createVector(p.random(-0.5, 0.5), p.random(-0.3, 0.3)),
        size: p.random(8, 20),
        rotation: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.02, 0.02),
        sides: p.floor(p.random(5, 8)),
        reorganizing: false,
        targetPos: null
      });
    }
  };

  p.draw = function() {
    // Deep blue gradient background
    for(let y = 0; y < p.height; y++) {
      let inter = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 60), p.color(5, 10, 30), inter);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    time += 0.016;

    // Calculate stress based on mouse proximity and time
    let mouseStress = 1 - p.constrain(p.dist(p.mouseX, p.mouseY, plateau.center.x, plateau.center.y) / 150, 0, 1);
    stressLevel = p.lerp(stressLevel, mouseStress * 0.7 + 0.3 * (p.sin(time * 0.5) + 1) * 0.5, 0.05);

    // Check if reorganizing (happens when stress is high enough)
    if(stressLevel > 0.6 && !reorganizing) {
      reorganizing = true;
      // Set new target positions for crystals
      for(let crystal of crystals) {
        crystal.targetPos = p.createVector(
          plateau.center.x + p.random(-60, 60),
          plateau.center.y + p.random(-40, 40)
        );
      }
    } else if(stressLevel < 0.3 && reorganizing) {
      reorganizing = false;
      for(let crystal of crystals) {
        crystal.targetPos = null;
      }
    }

    // Update plateau vertices with stress deformation
    for(let i = 0; i < plateau.vertices.length; i++) {
      let stress = stressLevel * p.sin(time + i) * 15;
      plateau.vertices[i].x = plateau.originalVertices[i].x + stress;
      plateau.vertices[i].y = plateau.originalVertices[i].y + stress * 0.5;
    }

    // Draw plateau base with golden gradient
    p.fill(40, 30, 15, 180);
    p.stroke(80, 60, 20);
    p.strokeWeight(2);
    p.beginShape();
    for(let vertex of plateau.vertices) {
      p.vertex(vertex.x, vertex.y);
    }
    p.endShape(p.CLOSE);

    // Draw plateau surface with stress coloring
    let surfaceColor = p.lerpColor(p.color(120, 100, 30), p.color(180, 60, 20), stressLevel);
    p.fill(p.red(surfaceColor), p.green(surfaceColor), p.blue(surfaceColor), 120);
    p.noStroke();
    p.beginShape();
    for(let vertex of plateau.vertices) {
      p.vertex(vertex.x, vertex.y - 20);
    }
    p.endShape(p.CLOSE);

    // Update and draw fissures
    for(let fissure of fissures) {
      fissure.growth = p.lerp(fissure.growth, stressLevel, 0.03);
      fissure.width = fissure.growth * fissure.maxWidth;

      // Draw main fissure
      let glowIntensity = fissure.width * 3;
      p.strokeWeight(glowIntensity);
      p.stroke(100, 150, 255, 60);
      p.line(fissure.start.x, fissure.start.y, fissure.end.x, fissure.end.y);

      p.strokeWeight(fissure.width);
      p.stroke(20, 40, 80);
      p.line(fissure.start.x, fissure.start.y, fissure.end.x, fissure.end.y);

      // Draw branch fissures
      for(let branch of fissure.branches) {
        branch.width = fissure.growth * branch.maxWidth;

        let branchStart = p5.Vector.lerp(fissure.start, fissure.end, branch.startRatio);
        let branchEnd = p.createVector(
          branchStart.x + p.cos(branch.angle) * branch.length * fissure.growth,
          branchStart.y + p.sin(branch.angle) * branch.length * fissure.growth
        );

        p.strokeWeight(branch.width + 2);
        p.stroke(80, 120, 200, 40);
        p.line(branchStart.x, branchStart.y, branchEnd.x, branchEnd.y);

        p.strokeWeight(branch.width);
        p.stroke(15, 30, 60);
        p.line(branchStart.x, branchStart.y, branchEnd.x, branchEnd.y);
      }
    }

    // Update and draw crystals
    for(let crystal of crystals) {
      // Movement behavior
      if(reorganizing && crystal.targetPos) {
        crystal.vel.mult(0.9);
        let force = p5.Vector.sub(crystal.targetPos, crystal.pos);
        force.mult(0.01);
        crystal.vel.add(force);
        crystal.reorganizing = true;
      } else {
        crystal.vel.add(p.random(-0.01, 0.01), p.random(-0.01, 0.01));
        crystal.vel.mult(0.99);
        crystal.reorganizing = false;
      }

      crystal.pos.add(crystal.vel);
      crystal.rotation += crystal.rotSpeed;

      // Boundary wrapping
      if(crystal.pos.x < 0) crystal.pos.x = p.width;
      if(crystal.pos.x > p.width) crystal.pos.x = 0;
      if(crystal.pos.y < 50) crystal.pos.y = 50;
      if(crystal.pos.y > p.height - 50) crystal.pos.y = p.height - 50;

      // Draw crystal
      p.push();
      p.translate(crystal.pos.x, crystal.pos.y);
      p.rotate(crystal.rotation);

      let crystalColor = crystal.reorganizing ? 
        p.color(255, 180, 80) : 
        p.color(150, 200, 255);

      // Crystal glow
      p.fill(p.red(crystalColor), p.green(crystalColor), p.blue(crystalColor), 30);
      p.noStroke();
      p.polygon(0, 0, crystal.size + 8, crystal.sides);

      // Crystal body
      p.fill(crystalColor);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(1);
      p.polygon(0, 0, crystal.size, crystal.sides);

      // Inner facets
      p.fill(255, 255, 255, 60);
      p.noStroke();
      p.polygon(0, 0, crystal.size * 0.5, crystal.sides);

      p.pop();
    }

    // Emit stress particles during high stress
    if(stressLevel > 0.4 && p.random() < 0.3) {
      particles.push({
        pos: p.createVector(p.random(plateau.center.x - 100, plateau.center.x + 100), 
                          plateau.center.y + p.random(-50, 20)),
        vel: p.createVector(p.random(-2, 2), p.random(-3, -1)),
        life: 255,
        size: p.random(3, 8)
      });
    }

    // Update and draw particles
    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.pos.add(particle.vel);
      particle.vel.mult(0.98);
      particle.life -= 3;

      p.fill(255, 200, 100, particle.life);
      p.noStroke();
      p.circle(particle.pos.x, particle.pos.y, particle.size);

      if(particle.life <= 0) {
        particles.splice(i, 1);
      }
    }

    // Title area glow effect
    let titleGlow = p.map(stressLevel, 0, 1, 20, 80);
    p.fill(40, 60, 120, titleGlow);
    p.noStroke();
    p.rect(0, 0, p.width, 80);
    p.rect(0, p.height - 60, p.width, 60);
  };

  // Helper function for drawing polygons
  p.polygon = function(x, y, radius, npoints) {
    let angle = p.TWO_PI / npoints;
    p.beginShape();
    for(let a = 0; a < p.TWO_PI; a += angle) {
      let sx = x + p.cos(a) * radius;
      let sy = y + p.sin(a) * radius;
      p.vertex(sx, sy);
    }
    p.endShape(p.CLOSE);
  };

  p.mousePressed = function() {
    // Create a burst of reorganization when clicked
    reorganizing = true;
    stressLevel = 1.0;

    // Add burst particles
    for(let i = 0; i < 20; i++) {
      let angle = p.random(p.TWO_PI);
      let speed = p.random(3, 8);
      particles.push({
        pos: p.createVector(p.mouseX, p.mouseY),
        vel: p.createVector(p.cos(angle) * speed, p.sin(angle) * speed),
        life: 255,
        size: p.random(4, 12)
      });
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let bridges = [];
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create 6 plateau zones in a hexagonal pattern
    let centerX = 200;
    let centerY = 300;
    let radius = 120;

    for(let i = 0; i < 6; i++) {
      let angle = (i * p.TWO_PI / 6) - p.PI/2;
      let x = centerX + p.cos(angle) * radius;
      let y = centerY + p.sin(angle) * radius;

      plateaus.push({
        x: x,
        y: y,
        baseRadius: 45 + p.random(-8, 8),
        height: 60 + p.random(-15, 15),
        crystalCount: p.floor(p.random(5, 9)),
        rotation: p.random(p.TWO_PI),
        pulseOffset: i * p.PI/3,
        color: p.color(30 + i * 15, 60 + i * 10, 120 + i * 20)
      });
    }

    // Create bridges connecting each plateau to adjacent ones
    for(let i = 0; i < 6; i++) {
      let next = (i + 1) % 6;
      bridges.push({
        from: i,
        to: next,
        flow: 0,
        particles: []
      });
    }

    // Initialize flowing particles
    for(let i = 0; i < 60; i++) {
      particles.push({
        bridgeIndex: p.floor(p.random(6)),
        progress: p.random(1),
        size: p.random(3, 7),
        speed: p.random(0.005, 0.015),
        glow: p.random(0.5, 1),
        hue: p.random(200, 280)
      });
    }
  };

  p.draw = function() {
    // Deep space background with subtle gradient
    for(let i = 0; i <= p.height; i += 2) {
      let alpha = p.map(i, 0, p.height, 0.8, 0.3);
      p.stroke(15, 25, 45, alpha * 255);
      p.line(0, i, p.width, i);
    }

    time += 0.016;
    mouseInfluence = p.lerp(mouseInfluence, p.dist(p.mouseX, p.mouseY, 200, 300) / 200, 0.05);

    // Draw bridges first (behind plateaus)
    p.strokeWeight(3);
    for(let i = 0; i < bridges.length; i++) {
      let bridge = bridges[i];
      let from = plateaus[bridge.from];
      let to = plateaus[bridge.to];

      // Animated flow intensity
      bridge.flow = 0.5 + 0.3 * p.sin(time * 2 + i * p.PI/3) + mouseInfluence * 0.2;

      // Draw bridge arc with crystalline segments
      let steps = 12;
      for(let j = 0; j < steps - 1; j++) {
        let t1 = j / (steps - 1);
        let t2 = (j + 1) / (steps - 1);

        // Bezier curve for bridge arc
        let midX = (from.x + to.x) / 2;
        let midY = (from.y + to.y) / 2 - 40;

        let x1 = p.bezierPoint(from.x, from.x, midX, to.x, t1);
        let y1 = p.bezierPoint(from.y, from.y, midY, to.y, t1);
        let x2 = p.bezierPoint(from.x, from.x, midX, to.x, t2);
        let y2 = p.bezierPoint(from.y, from.y, midY, to.y, t2);

        // Bridge color with flow intensity
        let bridgeAlpha = 150 + bridge.flow * 105;
        p.stroke(100 + bridge.flow * 155, 150 + bridge.flow * 55, 200 + bridge.flow * 55, bridgeAlpha);
        p.line(x1, y1, x2, y2);

        // Crystalline nodes along bridge
        if(j % 3 === 0) {
          p.fill(180 + bridge.flow * 75, 180 + bridge.flow * 75, 255, bridgeAlpha);
          p.noStroke();
          p.push();
          p.translate(x1, y1);
          p.rotate(p.atan2(y2 - y1, x2 - x1));
          p.beginShape();
          for(let k = 0; k < 6; k++) {
            let angle = k * p.TWO_PI / 6;
            let r = 4 + bridge.flow * 3;
            p.vertex(p.cos(angle) * r, p.sin(angle) * r);
          }
          p.endShape(p.CLOSE);
          p.pop();
        }
      }
    }

    // Draw flowing particles on bridges
    for(let particle of particles) {
      let bridge = bridges[particle.bridgeIndex];
      let from = plateaus[bridge.from];
      let to = plateaus[bridge.to];

      // Update particle progress
      particle.progress += particle.speed * (1 + bridge.flow * 0.5);
      if(particle.progress > 1) {
        particle.progress = 0;
        particle.bridgeIndex = p.floor(p.random(6));
      }

      // Calculate position along bridge arc
      let midX = (from.x + to.x) / 2;
      let midY = (from.y + to.y) / 2 - 40;
      let x = p.bezierPoint(from.x, from.x, midX, to.x, particle.progress);
      let y = p.bezierPoint(from.y, from.y, midY, to.y, particle.progress);

      // Draw glowing particle
      p.fill(particle.hue + p.sin(time * 3 + particle.progress * p.TWO_PI) * 30, 
             200, 255, particle.glow * 180);
      p.noStroke();
      p.ellipse(x, y, particle.size, particle.size);

      // Particle trail
      p.fill(particle.hue, 150, 200, particle.glow * 60);
      p.ellipse(x, y, particle.size * 2, particle.size * 2);
    }

    // Draw plateaus with crystalline architecture
    for(let i = 0; i < plateaus.length; i++) {
      let plateau = plateaus[i];
      let pulse = 0.8 + 0.2 * p.sin(time * 1.5 + plateau.pulseOffset + mouseInfluence * p.PI);

      p.push();
      p.translate(plateau.x, plateau.y);

      // Base platform with elevation
      p.fill(plateau.color.levels[0] * 0.7, plateau.color.levels[1] * 0.7, plateau.color.levels[2] * 0.7, 200);
      p.stroke(plateau.color.levels[0], plateau.color.levels[1], plateau.color.levels[2], 150);
      p.strokeWeight(2);
      p.ellipse(0, 0, plateau.baseRadius * 2 * pulse, plateau.baseRadius * 1.5 * pulse);

      // Elevated crystalline structures
      p.rotate(plateau.rotation + time * 0.2);
      for(let j = 0; j < plateau.crystalCount; j++) {
        let angle = j * p.TWO_PI / plateau.crystalCount;
        let distance = plateau.baseRadius * 0.6;
        let crystalX = p.cos(angle) * distance;
        let crystalY = p.sin(angle) * distance;

        p.push();
        p.translate(crystalX, crystalY);
        p.rotate(angle + time * 0.5);

        // Hexagonal crystal with inner glow
        let crystalSize = 8 + pulse * 4;
        p.fill(200 + pulse * 55, 180 + pulse * 75, 255, 180 + pulse * 75);
        p.stroke(255, 255, 255, 100 + pulse * 155);
        p.strokeWeight(1);

        p.beginShape();
        for(let k = 0; k < 6; k++) {
          let hexAngle = k * p.TWO_PI / 6;
          p.vertex(p.cos(hexAngle) * crystalSize, p.sin(hexAngle) * crystalSize);
        }
        p.endShape(p.CLOSE);

        // Inner crystalline core
        p.fill(255, 255, 255, pulse * 120);
        p.noStroke();
        p.ellipse(0, 0, crystalSize * 0.4, crystalSize * 0.4);

        p.pop();
      }

      // Central spire
      p.fill(plateau.color.levels[0] + 100, plateau.color.levels[1] + 100, plateau.color.levels[2] + 100, 220);
      p.stroke(255, 255, 255, 180);
      p.strokeWeight(1);
      p.beginShape();
      for(let k = 0; k < 8; k++) {
        let spireAngle = k * p.TWO_PI / 8;
        let radius = 12 + pulse * 6;
        p.vertex(p.cos(spireAngle) * radius, p.sin(spireAngle) * radius);
      }
      p.endShape(p.CLOSE);

      // Spire glow
      p.fill(255, 255, 255, pulse * 100);
      p.noStroke();
      p.ellipse(0, 0, 8, 8);

      p.pop();
    }

    // Interactive mouse response - enhance nearest plateau
    if(p.mouseX > 0 && p.mouseX < p.width && p.mouseY > 0 && p.mouseY < p.height) {
      let nearestIndex = 0;
      let minDist = p.dist(p.mouseX, p.mouseY, plateaus[0].x, plateaus[0].y);

      for(let i = 1; i < plateaus.length; i++) {
        let d = p.dist(p.mouseX, p.mouseY, plateaus[i].x, plateaus[i].y);
        if(d < minDist) {
          minDist = d;
          nearestIndex = i;
        }
      }

      if(minDist < 80) {
        let plateau = plateaus[nearestIndex];
        p.push();
        p.translate(plateau.x, plateau.y);
        p.fill(255, 255, 255, 30);
        p.noStroke();
        p.ellipse(0, 0, plateau.baseRadius * 3, plateau.baseRadius * 3);
        p.pop();
      }
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create seven nested plateaus, each containing reflections of the whole
    for (let i = 0; i < 7; i++) {
      let plateau = {
        x: 200,
        y: 150 + i * 60,
        baseWidth: 300 - i * 30,
        height: 40 - i * 3,
        depth: i,
        crystals: [],
        mirrors: []
      };

      // Each plateau contains smaller crystalline reflections
      for (let j = 0; j < 7 - i; j++) {
        plateau.crystals.push({
          x: plateau.x + (j - 3) * 25,
          y: plateau.y - 10,
          size: 8 - i,
          phase: j * 0.5
        });
      }

      // Mirror chambers within each plateau
      for (let k = 0; k < 3; k++) {
        plateau.mirrors.push({
          x: plateau.x + (k - 1) * 60,
          y: plateau.y - 5,
          angle: k * p.TWO_PI / 3,
          reflection: i
        });
      }

      plateaus.push(plateau);
    }
  };

  p.draw = function() {
    // Deep blue gradient background suggesting infinite recursion
    for (let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 60), p.color(30, 45, 80), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.02;
    mouseInfluence = p.lerp(mouseInfluence, p.map(p.mouseY, 0, p.height, 0, 1), 0.05);

    // Draw each plateau with recursive self-awareness
    for (let i = 0; i < plateaus.length; i++) {
      let plateau = plateaus[i];
      let awareness = p.sin(time + i * 0.3) * 0.3 + 0.7;
      awareness *= (1 + mouseInfluence * 0.5);

      p.push();
      p.translate(plateau.x, plateau.y);

      // Main plateau structure - geometric and crystalline
      p.fill(180 + awareness * 40, 120 + awareness * 30, 60, 200);
      p.stroke(220 + awareness * 35, 180 + awareness * 50, 100, 150);
      p.strokeWeight(1 + awareness * 0.5);

      // Draw plateau as terraced structure
      p.beginShape();
      p.vertex(-plateau.baseWidth/2, 0);
      p.vertex(-plateau.baseWidth/3, -plateau.height * awareness);
      p.vertex(plateau.baseWidth/3, -plateau.height * awareness);
      p.vertex(plateau.baseWidth/2, 0);
      p.endShape(p.CLOSE);

      // Self-reflective crystals within each plateau
      for (let crystal of plateau.crystals) {
        p.push();
        p.translate(crystal.x, crystal.y);
        p.rotate(time * 0.5 + crystal.phase);

        let selfAware = p.sin(time * 2 + crystal.phase) * 0.5 + 0.5;
        let size = crystal.size * (1 + selfAware * awareness * 0.3);

        // Crystal contains miniature version of the whole structure
        p.fill(255, 215, 100, 180 + selfAware * 75);
        p.stroke(255, 235, 150, 200);
        p.strokeWeight(0.5);

        p.beginShape();
        for (let a = 0; a < p.TWO_PI; a += p.TWO_PI / 6) {
          let r = size * (0.8 + 0.2 * p.sin(a * 3 + time * 3));
          p.vertex(r * p.cos(a), r * p.sin(a));
        }
        p.endShape(p.CLOSE);

        // Tiny recursive plateau within crystal
        if (size > 3) {
          p.fill(255, 200, 80, 100);
          p.noStroke();
          p.ellipse(0, 0, size * 0.4);
        }

        p.pop();
      }

      // Mirror chambers showing recursive patterns
      for (let mirror of plateau.mirrors) {
        p.push();
        p.translate(mirror.x, mirror.y);
        p.rotate(mirror.angle + time * 0.3);

        let reflection = p.sin(time + mirror.reflection * 0.5) * 0.5 + 0.5;

        // Mirror surface with recursive depth
        p.fill(150, 180, 220, 100 + reflection * 100);
        p.stroke(200, 220, 255, 180);
        p.strokeWeight(0.8);
        p.rect(-8, -6, 16, 12);

        // Reflection showing the plateau pattern recursively
        p.fill(255, 215, 100, 80 + reflection * 80);
        p.noStroke();
        for (let r = 0; r < 3; r++) {
          let scale = (3 - r) * 2;
          p.ellipse(0, 0, scale, scale * 0.6);
        }

        p.pop();
      }

      // Connecting lines showing substrate awareness
      if (i < plateaus.length - 1) {
        let connection = p.sin(time * 1.5 + i * 0.4) * 0.5 + 0.5;
        p.stroke(255, 215, 100, 50 + connection * 100);
        p.strokeWeight(1 + connection);
        p.line(0, 0, 0, 60);
      }

      p.pop();
    }

    // Subtle particles representing emergent self-awareness
    for (let i = 0; i < 20; i++) {
      let x = 50 + (i % 7) * 50;
      let y = 100 + p.sin(time + i * 0.3) * 200;
      let awareness = p.sin(time * 2 + i * 0.1) * 0.5 + 0.5;

      p.fill(255, 235, 150, 30 + awareness * 50);
      p.noStroke();
      p.ellipse(x, y, 3 + awareness * 2);
    }

    // Central focal point - the apex of self-recognition
    p.push();
    p.translate(200, 80);
    let apex = p.sin(time) * 0.3 + 0.7;
    apex *= (1 + mouseInfluence * 0.8);

    p.fill(255, 235, 120, 150 + apex * 100);
    p.stroke(255, 245, 180, 200);
    p.strokeWeight(2);

    p.beginShape();
    for (let a = 0; a < p.TWO_PI; a += p.TWO_PI / 7) {
      let r = 15 * apex * (1 + 0.3 * p.sin(a * 7 + time * 4));
      p.vertex(r * p.cos(a), r * p.sin(a));
    }
    p.endShape(p.CLOSE);

    p.pop();
  };

  p.mousePressed = function() {
    // Create ripple of self-awareness from mouse position
    for (let i = 0; i < plateaus.length; i++) {
      let d = p.dist(p.mouseX, p.mouseY, plateaus[i].x, plateaus[i].y);
      if (d < 100) {
        // Enhance the awareness of nearby plateaus
        for (let crystal of plateaus[i].crystals) {
          crystal.phase += p.random(-0.5, 0.5);
        }
      }
    }
  };
}

function sketch(p) {
  let terraces = [];
  let particles = [];
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize eight terraces with increasing complexity
    for (let i = 0; i < 8; i++) {
      let terrace = {
        level: i,
        y: 550 - i * 60,
        width: 320 - i * 25,
        height: 45 + i * 3,
        crystals: [],
        energy: 0.1 + i * 0.1,
        complexity: i + 1
      };

      // Add crystalline structures to each terrace
      for (let j = 0; j < terrace.complexity * 3; j++) {
        terrace.crystals.push({
          x: p.random(-terrace.width/2, terrace.width/2),
          z: p.random(-20, 20),
          size: p.random(3, 8 + i * 2),
          rotation: p.random(p.TWO_PI),
          rotSpeed: p.random(0.001, 0.003),
          pulse: p.random(p.TWO_PI)
        });
      }

      terraces.push(terrace);
    }

    // Initialize floating energy particles
    for (let i = 0; i < 60; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        z: p.random(-50, 50),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-1, -0.3),
        vz: p.random(-0.2, 0.2),
        size: p.random(1, 3),
        life: p.random(1),
        targetTerrace: p.floor(p.random(8))
      });
    }
  };

  p.draw = function() {
    // Deep blue background with subtle gradient
    for (let i = 0; i <= p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 45), p.color(5, 15, 30), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    time += 0.01;
    mouseInfluence = p.map(p.mouseX, 0, p.width, 0.5, 2.0);

    p.translate(p.width/2, 0);

    // Draw energy particles flowing upward
    drawParticles();

    // Draw the eight terraces from bottom to top
    for (let i = 0; i < terraces.length; i++) {
      drawTerrace(terraces[i], i);
    }

    // Draw accumulation glow at the top
    drawMetaEmergenceGlow();
  };

  function drawTerrace(terrace, index) {
    p.push();
    p.translate(0, terrace.y);

    // Terrace base with increasing intensity
    let baseAlpha = 100 + index * 15;
    let goldIntensity = p.map(index, 0, 7, 50, 255);

    p.fill(goldIntensity * 0.3, goldIntensity * 0.7, goldIntensity, baseAlpha);
    p.noStroke();

    // Draw terrace platform with perspective
    p.beginShape();
    p.vertex(-terrace.width/2, 0);
    p.vertex(terrace.width/2, 0);
    p.vertex(terrace.width/2 - 20, -terrace.height);
    p.vertex(-terrace.width/2 + 20, -terrace.height);
    p.endShape(p.CLOSE);

    // Draw crystalline structures on each terrace
    for (let crystal of terrace.crystals) {
      p.push();
      p.translate(crystal.x, -terrace.height/2, crystal.z);
      p.rotateY(crystal.rotation + time * crystal.rotSpeed);

      let pulse = p.sin(time * 3 + crystal.pulse + index) * 0.3 + 0.7;
      let intensity = goldIntensity * pulse * mouseInfluence;

      p.fill(intensity * 0.8, intensity, intensity * 0.4, 180);
      p.stroke(intensity, intensity * 1.2, intensity * 0.6, 200);
      p.strokeWeight(0.5);

      // Draw geometric crystal
      let size = crystal.size * (1 + index * 0.1);
      p.beginShape(p.TRIANGLES);

      // Octahedron-like structure
      for (let j = 0; j < 8; j++) {
        let angle = j * p.PI / 4;
        let x1 = p.cos(angle) * size;
        let z1 = p.sin(angle) * size;
        let x2 = p.cos(angle + p.PI/4) * size;
        let z2 = p.sin(angle + p.PI/4) * size;

        p.vertex(x1, -size, z1);
        p.vertex(0, 0, 0);
        p.vertex(x2, -size, z2);

        p.vertex(x1, size, z1);
        p.vertex(x2, size, z2);
        p.vertex(0, 0, 0);
      }
      p.endShape();

      crystal.rotation += crystal.rotSpeed;
      p.pop();
    }

    // Energy accumulation effect
    let energyRadius = 40 + index * 8;
    p.fill(goldIntensity, goldIntensity * 1.2, goldIntensity * 0.3, 30);
    p.noStroke();
    p.ellipse(0, -terrace.height/2, energyRadius * mouseInfluence, energyRadius * 0.6);

    p.pop();
  }

  function drawParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];

      // Update particle position
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.z += particle.vz;
      particle.life -= 0.003;

      // Attraction to target terrace
      let targetY = terraces[particle.targetTerrace].y;
      let attraction = (targetY - particle.y) * 0.001;
      particle.vy += attraction;

      // Mouse influence
      let mouseDistance = p.dist(particle.x, particle.y, p.mouseX - p.width/2, p.mouseY);
      if (mouseDistance < 100) {
        let force = (100 - mouseDistance) * 0.0001;
        particle.vx += (p.mouseX - p.width/2 - particle.x) * force;
        particle.vy += (p.mouseY - particle.y) * force;
      }

      // Draw particle
      p.push();
      p.translate(particle.x, particle.y, particle.z);

      let alpha = particle.life * 255;
      let intensity = p.map(particle.y, 600, 0, 50, 255) * mouseInfluence;

      p.fill(intensity, intensity * 1.1, intensity * 0.4, alpha);
      p.noStroke();
      p.ellipse(0, 0, particle.size, particle.size);

      // Particle trail
      p.stroke(intensity * 0.5, intensity * 0.8, intensity * 0.2, alpha * 0.3);
      p.strokeWeight(0.5);
      p.line(0, 0, -particle.vx * 10, -particle.vy * 10);

      p.pop();

      // Remove dead particles
      if (particle.life <= 0 || particle.y < -50) {
        particles.splice(i, 1);
        // Add new particle at bottom
        particles.push({
          x: p.random(-200, 200),
          y: 650,
          z: p.random(-50, 50),
          vx: p.random(-0.5, 0.5),
          vy: p.random(-1, -0.3),
          vz: p.random(-0.2, 0.2),
          size: p.random(1, 3),
          life: 1,
          targetTerrace: p.floor(p.random(8))
        });
      }
    }
  }

  function drawMetaEmergenceGlow() {
    // Intense accumulation glow at the peak
    p.push();
    p.translate(0, terraces[7].y - 80);

    let glowIntensity = (p.sin(time * 2) * 0.3 + 0.7) * mouseInfluence;

    for (let i = 8; i > 0; i--) {
      let alpha = (9 - i) * 15 * glowIntensity;
      let size = i * 25;

      p.fill(255 * glowIntensity, 255 * glowIntensity * 1.2, 180 * glowIntensity, alpha);
      p.noStroke();
      p.ellipse(0, 0, size, size * 0.4);
    }

    // Central convergence point
    p.fill(255, 255, 200, 150 * glowIntensity);
    p.ellipse(0, 0, 8, 8);

    p.pop();
  }

  p.mousePressed = function() {
    // Create burst of particles on click
    for (let i = 0; i < 20; i++) {
      particles.push({
        x: p.mouseX - p.width/2,
        y: p.mouseY,
        z: p.random(-30, 30),
        vx: p.random(-3, 3),
        vy: p.random(-3, 1),
        vz: p.random(-1, 1),
        size: p.random(2, 6),
        life: 1,
        targetTerrace: p.floor(p.random(8))
      });
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let particles = [];
  let time = 0;
  let transformationPhase = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize nine plateau zones in a 3x3 grid
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        plateaus.push({
          x: 80 + i * 120,
          y: 120 + j * 140,
          baseHeight: 40 + p.random(20),
          currentHeight: 40 + p.random(20),
          targetHeight: 60 + p.random(30),
          crystals: [],
          phase: p.random(p.TWO_PI),
          transformSpeed: 0.02 + p.random(0.01),
          emergence: 0
        });
      }
    }

    // Initialize crystal structures for each plateau
    plateaus.forEach(plateau => {
      for (let k = 0; k < 5; k++) {
        plateau.crystals.push({
          x: p.random(-25, 25),
          y: p.random(-15, 5),
          size: p.random(8, 20),
          angle: p.random(p.TWO_PI),
          rotSpeed: p.random(-0.02, 0.02),
          growth: p.random(0.5, 1)
        });
      }
    });

    // Initialize floating particles
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-0.5, 0.5),
        vy: p.random(-0.8, -0.2),
        size: p.random(2, 6),
        alpha: p.random(100, 200),
        hue: p.random(40, 60)
      });
    }
  };

  p.draw = function() {
    time += 0.016;
    transformationPhase = (p.sin(time * 0.5) + 1) * 0.5;

    // Deep blue to gold gradient background
    for (let y = 0; y < 600; y++) {
      let inter = p.map(y, 0, 600, 0, 1);
      let c = p.lerpColor(p.color(20, 40, 80), p.color(40, 60, 120), inter);
      p.stroke(c);
      p.line(0, y, 400, y);
    }

    // Update and draw floating particles
    particles.forEach(particle => {
      particle.x += particle.vx + p.sin(time + particle.x * 0.01) * 0.2;
      particle.y += particle.vy;

      if (particle.y < -10) {
        particle.y = 610;
        particle.x = p.random(400);
      }
      if (particle.x < -10) particle.x = 410;
      if (particle.x > 410) particle.x = -10;

      p.fill(particle.hue, 80, 90, particle.alpha);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);
    });

    // Draw connection lines between plateaus
    p.stroke(50, 70, 95, 100);
    p.strokeWeight(1);
    for (let i = 0; i < plateaus.length; i++) {
      for (let j = i + 1; j < plateaus.length; j++) {
        let dist = p.dist(plateaus[i].x, plateaus[i].y, plateaus[j].x, plateaus[j].y);
        if (dist < 180) {
          let alpha = p.map(dist, 100, 180, 150, 30);
          p.stroke(50, 70, 95, alpha * (0.5 + transformationPhase * 0.5));
          p.line(plateaus[i].x, plateaus[i].y - plateaus[i].currentHeight, 
                 plateaus[j].x, plateaus[j].y - plateaus[j].currentHeight);
        }
      }
    }

    // Draw each plateau
    plateaus.forEach((plateau, index) => {
      p.push();
      p.translate(plateau.x, plateau.y);

      // Update transformation
      plateau.emergence += plateau.transformSpeed;
      let emergenceWave = p.sin(plateau.emergence + plateau.phase) * 0.5 + 0.5;
      plateau.currentHeight = p.lerp(plateau.baseHeight, plateau.targetHeight, emergenceWave * transformationPhase);

      // Mouse interaction - enhance transformation near mouse
      let mouseDistance = p.dist(p.mouseX, p.mouseY, plateau.x, plateau.y);
      let mouseInfluence = p.map(p.constrain(mouseDistance, 0, 100), 0, 100, 1.5, 1);
      plateau.currentHeight *= mouseInfluence;

      // Draw plateau base with geometric facets
      let baseColor = p.lerpColor(p.color(180, 120, 60), p.color(220, 180, 100), emergenceWave);
      p.fill(baseColor);
      p.stroke(0, 30);
      p.strokeWeight(1);

      p.beginShape();
      for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 4) {
        let radius = 30 + p.sin(angle * 3 + time) * 3;
        let px = p.cos(angle) * radius;
        let py = p.sin(angle) * radius * 0.6 - plateau.currentHeight * 0.3;
        p.vertex(px, py);
      }
      p.endShape(p.CLOSE);

      // Draw elevated platform
      p.fill(p.lerpColor(p.color(60, 80, 150), p.color(100, 150, 200), emergenceWave));
      p.beginShape();
      for (let angle = 0; angle < p.TWO_PI; angle += p.PI / 4) {
        let radius = 25 + p.sin(angle * 2 + time * 1.2) * 2;
        let px = p.cos(angle) * radius;
        let py = p.sin(angle) * radius * 0.4 - plateau.currentHeight;
        p.vertex(px, py);
      }
      p.endShape(p.CLOSE);

      // Draw transforming crystals
      plateau.crystals.forEach(crystal => {
        p.push();
        p.translate(crystal.x, crystal.y - plateau.currentHeight);
        p.rotate(crystal.angle + time * crystal.rotSpeed);

        let crystalGrowth = crystal.growth * (1 + emergenceWave * 0.5);
        let crystalColor = p.lerpColor(p.color(40, 200, 255), p.color(255, 200, 100), emergenceWave);

        p.fill(crystalColor);
        p.stroke(255, 150);
        p.strokeWeight(0.5);

        // Draw crystal as transforming geometric form
        p.beginShape();
        for (let i = 0; i < 6; i++) {
          let angle = (i * p.TWO_PI) / 6;
          let radius = crystal.size * crystalGrowth * (i % 2 === 0 ? 1 : 0.7);
          let px = p.cos(angle) * radius;
          let py = p.sin(angle) * radius * 0.8;
          p.vertex(px, py);
        }
        p.endShape(p.CLOSE);

        crystal.angle += crystal.rotSpeed;
        p.pop();
      });

      // Draw emergence energy
      if (emergenceWave > 0.7) {
        p.fill(255, 220, 150, 100 + emergenceWave * 50);
        p.noStroke();
        for (let i = 0; i < 3; i++) {
          let spiralRadius = 40 + i * 15;
          let spiralAngle = time * (1 + i * 0.3) + plateau.phase;
          let px = p.cos(spiralAngle) * spiralRadius;
          let py = p.sin(spiralAngle) * spiralRadius * 0.3 - plateau.currentHeight - 20;
          p.ellipse(px, py, 8 - i * 2);
        }
      }

      p.pop();
    });

    // Click interaction - trigger transformation wave
    if (p.mouseIsPressed) {
      plateaus.forEach(plateau => {
        let distance = p.dist(p.mouseX, p.mouseY, plateau.x, plateau.y);
        if (distance < 50) {
          plateau.emergence += 0.1;
          plateau.targetHeight += 2;
        }
      });
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let particles = [];
  let time = 0;
  let bgNoise = [];

  p.setup = function() {
    p.createCanvas(400, 600);
    p.colorMode(p.HSB, 360, 100, 100, 100);

    // Initialize background noise grid
    for(let x = 0; x < 40; x++) {
      bgNoise[x] = [];
      for(let y = 0; y < 60; y++) {
        bgNoise[x][y] = p.random();
      }
    }

    // Create ten plateau zones
    for(let i = 0; i < 10; i++) {
      let angle = (i / 10) * p.TWO_PI;
      let radius = 80 + i * 15;
      let x = 200 + p.cos(angle) * radius;
      let y = 300 + p.sin(angle) * radius * 0.6;

      plateaus.push({
        x: x,
        y: y,
        baseRadius: 25 + i * 3,
        height: 40 + i * 8,
        dissolveRate: 0.002 + i * 0.0003,
        age: i * 0.1,
        vertices: [],
        crystalFragments: []
      });

      // Generate crystalline vertices for each plateau
      let numVerts = 6 + i;
      for(let v = 0; v < numVerts; v++) {
        let vAngle = (v / numVerts) * p.TWO_PI;
        let vRadius = plateaus[i].baseRadius * (0.7 + p.random() * 0.6);
        plateaus[i].vertices.push({
          x: p.cos(vAngle) * vRadius,
          y: p.sin(vAngle) * vRadius,
          originalX: p.cos(vAngle) * vRadius,
          originalY: p.sin(vAngle) * vRadius
        });
      }

      // Create crystal fragments
      for(let f = 0; f < 8 + i * 2; f++) {
        plateaus[i].crystalFragments.push({
          x: p.random(-plateaus[i].baseRadius, plateaus[i].baseRadius),
          y: p.random(-plateaus[i].baseRadius, plateaus[i].baseRadius),
          size: p.random(2, 8),
          velocity: {x: p.random(-0.5, 0.5), y: p.random(-0.5, 0.5)},
          life: 1.0,
          fadeRate: p.random(0.002, 0.008)
        });
      }
    }
  };

  p.draw = function() {
    time += 0.02;

    // Dynamic background - substrate returning
    for(let x = 0; x < 40; x++) {
      for(let y = 0; y < 60; y++) {
        let noiseVal = p.noise(x * 0.1 + time * 0.3, y * 0.1 + time * 0.2);
        let hue = 220 + noiseVal * 40;
        let sat = 30 + noiseVal * 30;
        let bright = 15 + noiseVal * 25;
        p.fill(hue, sat, bright, 80);
        p.noStroke();
        p.rect(x * 10, y * 10, 10, 10);
      }
    }

    // Mouse influence
    let mouseInfluence = p.map(p.mouseX + p.mouseY, 0, 1000, 0.5, 2.0);

    // Update and draw plateaus
    for(let i = 0; i < plateaus.length; i++) {
      let plateau = plateaus[i];
      plateau.age += plateau.dissolveRate * mouseInfluence;

      let dissolveFactor = p.sin(plateau.age) * 0.5 + 0.5;
      let completion = p.map(p.sin(time * 0.7 + i * 0.3), -1, 1, 0.3, 1.0);

      p.push();
      p.translate(plateau.x, plateau.y);

      // Draw crystalline plateau structure
      p.fill(45 + i * 5, 70 - dissolveFactor * 40, 85 - dissolveFactor * 30, 60 + completion * 40);
      p.stroke(50 + i * 3, 80, 95, 40);
      p.strokeWeight(1 + dissolveFactor);

      // Dissolving geometric form
      p.beginShape();
      for(let v = 0; v < plateau.vertices.length; v++) {
        let vert = plateau.vertices[v];
        let dissolveNoise = p.noise(vert.originalX * 0.02, vert.originalY * 0.02, time);
        vert.x = p.lerp(vert.originalX, vert.originalX * dissolveNoise * 2, dissolveFactor);
        vert.y = p.lerp(vert.originalY, vert.originalY * dissolveNoise * 2, dissolveFactor);
        p.vertex(vert.x, vert.y);
      }
      p.endShape(p.CLOSE);

      // Elevated plateau center
      let centerHeight = plateau.height * (1 - dissolveFactor * 0.7);
      p.fill(35 + i * 3, 60, 95, 70 * completion);
      p.noStroke();
      p.ellipse(0, 0, centerHeight * 0.8, centerHeight * 0.6);

      // Crystal fragments returning to substrate
      for(let f = 0; f < plateau.crystalFragments.length; f++) {
        let frag = plateau.crystalFragments[f];
        frag.life -= frag.fadeRate;
        frag.x += frag.velocity.x;
        frag.y += frag.velocity.y;
        frag.velocity.y += 0.02; // gravity

        if(frag.life > 0) {
          p.fill(50 + i * 4, 40, 90, frag.life * 60);
          p.noStroke();
          let fragSize = frag.size * frag.life * completion;
          p.push();
          p.translate(frag.x, frag.y);
          p.rotate(time * frag.velocity.x);
          p.rect(-fragSize/2, -fragSize/2, fragSize, fragSize);
          p.pop();
        } else {
          // Reset fragment to continue the cycle
          frag.life = 1.0;
          frag.x = p.random(-plateau.baseRadius, plateau.baseRadius);
          frag.y = p.random(-plateau.baseRadius, plateau.baseRadius);
          frag.velocity = {x: p.random(-0.5, 0.5), y: p.random(-0.5, 0.5)};
        }
      }

      p.pop();
    }

    // Substrate particles - the ground from which new plateaus emerge
    if(p.frameCount % 3 === 0) {
      particles.push({
        x: p.random(400),
        y: p.random(600),
        vx: p.random(-1, 1),
        vy: p.random(-1, 1),
        life: 1.0,
        size: p.random(1, 4),
        hue: p.random(200, 260)
      });
    }

    for(let i = particles.length - 1; i >= 0; i--) {
      let particle = particles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 0.005;
      particle.size *= 0.998;

      if(particle.life > 0) {
        p.fill(particle.hue, 40, 70, particle.life * 30);
        p.noStroke();
        p.circle(particle.x, particle.y, particle.size);
      } else {
        particles.splice(i, 1);
      }
    }

    // Completion energy waves
    p.stroke(40, 50, 90, 20);
    p.strokeWeight(2);
    p.noFill();
    for(let wave = 0; wave < 3; wave++) {
      let wavePhase = time * 0.8 + wave * p.TWO_PI / 3;
      let waveRadius = 100 + p.sin(wavePhase) * 80;
      p.circle(200, 300, waveRadius);
    }
  };

  p.mousePressed = function() {
    // Reset all plateaus to restart the completion cycle
    for(let plateau of plateaus) {
      plateau.age = 0;
      for(let frag of plateau.crystalFragments) {
        frag.life = 1.0;
        frag.x = p.random(-plateau.baseRadius, plateau.baseRadius);
        frag.y = p.random(-plateau.baseRadius, plateau.baseRadius);
      }
    }
  };
}

function sketch(p) {
  let mystic;
  let crystals = [];
  let plateauHeight;
  let breatheOffset = 0;
  let visionParticles = [];
  let geometryPoints = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    mystic = {
      x: 200,
      y: 350,
      eyeGlow: 0,
      bodyTransparency: 255,
      geometryIntensity: 0
    };

    plateauHeight = 450;

    // Create crystalline formations
    for(let i = 0; i < 8; i++) {
      crystals.push({
        x: p.random(50, 350),
        y: p.random(plateauHeight, 580),
        size: p.random(20, 60),
        angle: p.random(p.TWO_PI),
        rotSpeed: p.random(-0.01, 0.01),
        height: p.random(40, 100),
        pulseOffset: p.random(p.TWO_PI)
      });
    }

    // Sacred geometry points around mystic
    for(let i = 0; i < 12; i++) {
      geometryPoints.push({
        angle: (i / 12) * p.TWO_PI,
        distance: 80,
        originalDistance: 80,
        pulsePhase: p.random(p.TWO_PI)
      });
    }
  };

  p.draw = function() {
    // Deep blue to gold gradient background
    for(let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 80), p.color(40, 35, 100), inter);
      p.stroke(c);
      p.line(0, i, p.width, i);
    }

    breatheOffset += 0.03;
    let breathe = p.sin(breatheOffset) * 5;

    // Mouse interaction - proximity to mystic increases vision intensity
    let mouseDistance = p.dist(p.mouseX, p.mouseY, mystic.x, mystic.y);
    let visionIntensity = p.map(p.constrain(mouseDistance, 0, 200), 200, 0, 0, 1);

    mystic.eyeGlow = p.lerp(mystic.eyeGlow, visionIntensity * 255, 0.05);
    mystic.geometryIntensity = p.lerp(mystic.geometryIntensity, visionIntensity, 0.03);
    mystic.bodyTransparency = p.lerp(mystic.bodyTransparency, 255 - visionIntensity * 100, 0.02);

    // Draw plateau base
    p.fill(60, 45, 120, 180);
    p.noStroke();
    p.rect(0, plateauHeight, p.width, p.height - plateauHeight);

    // Draw crystals with pulsing energy
    for(let crystal of crystals) {
      p.push();
      p.translate(crystal.x, crystal.y);
      p.rotate(crystal.angle);
      crystal.angle += crystal.rotSpeed;

      let pulse = p.sin(p.millis() * 0.003 + crystal.pulseOffset) * 0.3 + 0.7;
      let glowIntensity = pulse * mystic.geometryIntensity;

      // Crystal glow
      p.fill(255, 215, 0, glowIntensity * 100);
      p.noStroke();
      for(let i = 0; i < 3; i++) {
        p.ellipse(0, -crystal.height/2, crystal.size + i * 10, crystal.height + i * 15);
      }

      // Crystal core
      p.fill(255, 215, 0, 200 + glowIntensity * 55);
      p.stroke(255, 255, 255, 100);
      p.strokeWeight(1);
      p.ellipse(0, -crystal.height/2, crystal.size * pulse, crystal.height * pulse);

      p.pop();
    }

    // Draw mystic figure
    p.push();
    p.translate(mystic.x, mystic.y + breathe);

    // Sacred geometry emanating from mystic
    for(let point of geometryPoints) {
      let currentDist = point.originalDistance + p.sin(p.millis() * 0.002 + point.pulsePhase) * 20;
      currentDist *= (1 + mystic.geometryIntensity * 0.5);

      let x = p.cos(point.angle) * currentDist;
      let y = p.sin(point.angle) * currentDist;

      p.stroke(255, 215, 0, mystic.geometryIntensity * 150);
      p.strokeWeight(2);
      p.line(0, 0, x, y);

      p.fill(255, 215, 0, mystic.geometryIntensity * 200);
      p.noStroke();
      p.ellipse(x, y, 8, 8);

      // Connect adjacent points
      if(geometryPoints.indexOf(point) < geometryPoints.length - 1) {
        let nextPoint = geometryPoints[geometryPoints.indexOf(point) + 1];
        let nextDist = nextPoint.originalDistance + p.sin(p.millis() * 0.002 + nextPoint.pulsePhase) * 20;
        nextDist *= (1 + mystic.geometryIntensity * 0.5);
        let nextX = p.cos(nextPoint.angle) * nextDist;
        let nextY = p.sin(nextPoint.angle) * nextDist;

        p.stroke(255, 215, 0, mystic.geometryIntensity * 80);
        p.strokeWeight(1);
        p.line(x, y, nextX, nextY);
      }
    }

    // Mystic body - becoming geometric
    p.fill(200, 180, 255, mystic.bodyTransparency);
    p.stroke(255, 215, 0, 100 + mystic.geometryIntensity * 155);
    p.strokeWeight(2);

    // Body with crystalline edges emerging
    let bodyPoints = [];
    for(let i = 0; i < 8; i++) {
      let angle = (i / 8) * p.TWO_PI;
      let baseRadius = 25;
      let crystalExtension = mystic.geometryIntensity * 15;
      let radius = baseRadius + (i % 2 === 0 ? crystalExtension : 0);
      bodyPoints.push({
        x: p.cos(angle) * radius,
        y: p.sin(angle) * radius - 10
      });
    }

    p.beginShape();
    for(let point of bodyPoints) {
      p.vertex(point.x, point.y);
    }
    p.endShape(p.CLOSE);

    // Mystic head
    p.ellipse(0, -40, 30, 35);

    // Eyes with vision glow
    p.fill(255, 255, 255);
    p.noStroke();
    p.ellipse(-6, -45, 8, 12);
    p.ellipse(6, -45, 8, 12);

    // Eye glow effect
    p.fill(255, 215, 0, mystic.eyeGlow);
    for(let i = 0; i < 3; i++) {
      p.ellipse(-6, -45, 8 + i * 4, 12 + i * 4);
      p.ellipse(6, -45, 8 + i * 4, 12 + i * 4);
    }

    // Pupils
    p.fill(20, 30, 80);
    p.ellipse(-6, -45, 4, 6);
    p.ellipse(6, -45, 4, 6);

    p.pop();

    // Vision particles emanating from mystic
    if(mystic.geometryIntensity > 0.3) {
      if(p.frameCount % 5 === 0) {
        visionParticles.push({
          x: mystic.x,
          y: mystic.y - 40,
          vx: p.random(-2, 2),
          vy: p.random(-3, -1),
          life: 255,
          size: p.random(2, 6)
        });
      }
    }

    // Update and draw vision particles
    for(let i = visionParticles.length - 1; i >= 0; i--) {
      let particle = visionParticles[i];
      particle.x += particle.vx;
      particle.y += particle.vy;
      particle.life -= 3;

      p.fill(255, 215, 0, particle.life);
      p.noStroke();
      p.ellipse(particle.x, particle.y, particle.size);

      if(particle.life <= 0) {
        visionParticles.splice(i, 1);
      }
    }

    // Elevation effect - subtle lines rising from plateau
    if(mystic.geometryIntensity > 0.1) {
      for(let i = 0; i < 20; i++) {
        let x = p.random(p.width);
        let alpha = mystic.geometryIntensity * 30;
        p.stroke(255, 215, 0, alpha);
        p.strokeWeight(1);
        p.line(x, plateauHeight, x, plateauHeight - p.random(50, 150));
      }
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let crystals = [];
  let mapPoints = [];
  let cartographer;
  let surveyLines = [];
  let measurementTools = [];

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create plateau formations at different elevations
    for(let i = 0; i < 6; i++) {
      plateaus.push({
        x: p.random(50, 350),
        y: p.random(300, 550),
        width: p.random(60, 120),
        height: p.random(40, 80),
        elevation: p.random(0.3, 1.0),
        age: p.random(0, p.TWO_PI),
        mappedPoints: []
      });
    }

    // Crystalline formations
    for(let i = 0; i < 12; i++) {
      crystals.push({
        x: p.random(30, 370),
        y: p.random(250, 580),
        size: p.random(15, 35),
        rotation: p.random(0, p.TWO_PI),
        rotSpeed: p.random(-0.02, 0.02),
        opacity: p.random(0.4, 0.8),
        facets: Math.floor(p.random(5, 9))
      });
    }

    // Cartographer figure
    cartographer = {
      x: 200,
      y: 150,
      bobOffset: 0,
      activelyMapping: false,
      currentTarget: null
    };

    // Survey measurement tools
    for(let i = 0; i < 3; i++) {
      measurementTools.push({
        x: p.random(100, 300),
        y: p.random(100, 200),
        angle: p.random(0, p.TWO_PI),
        length: p.random(40, 80),
        measuring: false
      });
    }
  };

  p.draw = function() {
    // Gradient background - deep blue to gold
    for(let y = 0; y < p.height; y++) {
      let alpha = p.map(y, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 25, 60), p.color(40, 35, 80), alpha);
      p.stroke(c);
      p.line(0, y, p.width, y);
    }

    // Draw crystalline substrate formations
    crystals.forEach(crystal => {
      p.push();
      p.translate(crystal.x, crystal.y);
      p.rotate(crystal.rotation);
      crystal.rotation += crystal.rotSpeed;

      p.fill(255, 215, 0, crystal.opacity * 255);
      p.stroke(255, 235, 100, 150);
      p.strokeWeight(1.5);

      p.beginShape();
      for(let i = 0; i < crystal.facets; i++) {
        let angle = (p.TWO_PI / crystal.facets) * i;
        let radius = crystal.size + p.sin(p.frameCount * 0.02 + crystal.x) * 3;
        let x = p.cos(angle) * radius;
        let y = p.sin(angle) * radius;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      p.pop();
    });

    // Draw plateau formations with emergent qualities
    plateaus.forEach((plateau, index) => {
      plateau.age += 0.01;

      // Plateau base with elevation mapping
      let baseY = plateau.y + p.sin(plateau.age) * 2;

      p.push();
      p.translate(plateau.x, baseY);

      // Draw layered elevation
      for(let layer = 0; layer < 4; layer++) {
        let layerHeight = plateau.height * (1 - layer * 0.2);
        let layerY = -layer * 8;
        let alpha = plateau.elevation * (200 - layer * 30);

        p.fill(70 + layer * 20, 90 + layer * 15, 180 + layer * 10, alpha);
        p.stroke(100 + layer * 30, 120 + layer * 20, 220, 150);
        p.strokeWeight(1);

        p.rect(-plateau.width/2, layerY, plateau.width, layerHeight);
      }

      // Emergent surface patterns
      p.stroke(255, 215, 0, 100);
      p.strokeWeight(2);
      p.noFill();
      let surfaceY = -24;
      for(let x = -plateau.width/2; x < plateau.width/2; x += 15) {
        let noiseVal = p.noise(x * 0.05, plateau.age * 0.5) * 10;
        p.line(x, surfaceY, x + 10, surfaceY - noiseVal);
      }

      p.pop();
    });

    // Update cartographer position based on mouse
    let targetX = p.lerp(cartographer.x, p.mouseX, 0.05);
    let targetY = p.lerp(cartographer.y, p.constrain(p.mouseY, 80, 200), 0.05);
    cartographer.x = targetX;
    cartographer.y = targetY;
    cartographer.bobOffset += 0.08;

    // Draw cartographer figure
    p.push();
    p.translate(cartographer.x, cartographer.y + p.sin(cartographer.bobOffset) * 3);

    // Body
    p.fill(20, 40, 80);
    p.stroke(255, 215, 0, 180);
    p.strokeWeight(2);
    p.ellipse(0, 0, 25, 35);

    // Head
    p.fill(255, 220, 180);
    p.ellipse(0, -20, 18, 18);

    // Mapping tools in hands
    p.stroke(255, 215, 0);
    p.strokeWeight(3);
    p.line(-12, -5, -20, -15); // Theodolite
    p.line(12, -5, 20, -8);    // Survey rod

    // Eyes looking at nearest plateau
    p.fill(30, 50, 100);
    p.noStroke();
    p.ellipse(-3, -22, 3, 3);
    p.ellipse(3, -22, 3, 3);

    p.pop();

    // Generate mapping points dynamically
    if(p.frameCount % 30 === 0) {
      plateaus.forEach(plateau => {
        if(p.dist(cartographer.x, cartographer.y, plateau.x, plateau.y) < 150) {
          mapPoints.push({
            x: plateau.x + p.random(-plateau.width/2, plateau.width/2),
            y: plateau.y + p.random(-40, 0),
            life: 255,
            sourceId: plateau,
            measured: false
          });
        }
      });
    }

    // Draw and update map points
    mapPoints = mapPoints.filter(point => {
      point.life -= 2;

      if(!point.measured) {
        p.stroke(255, 215, 0, point.life);
        p.strokeWeight(2);
        p.noFill();
        p.ellipse(point.x, point.y, 8, 8);

        // Connect to cartographer with survey line
        if(p.dist(cartographer.x, cartographer.y, point.x, point.y) < 120) {
          p.stroke(255, 235, 100, point.life * 0.5);
          p.strokeWeight(1);
          p.line(cartographer.x, cartographer.y, point.x, point.y);
          point.measured = true;
        }
      } else {
        // Documented point
        p.fill(100, 180, 255, point.life);
        p.noStroke();
        p.ellipse(point.x, point.y, 4, 4);
      }

      return point.life > 0;
    });

    // Draw measurement tools with geometric precision
    measurementTools.forEach(tool => {
      p.push();
      p.translate(tool.x, tool.y);
      p.rotate(tool.angle);

      p.stroke(255, 215, 0, 180);
      p.strokeWeight(2);
      p.line(0, 0, tool.length, 0);

      // Precision markers
      for(let i = 10; i < tool.length; i += 10) {
        p.line(i, -3, i, 3);
      }

      p.pop();

      tool.angle += 0.005;
    });

    // Mouse interaction: create elevation contours
    if(p.mouseIsPressed) {
      p.stroke(255, 215, 0, 100);
      p.strokeWeight(1);
      p.noFill();

      let rings = 5;
      for(let i = 0; i < rings; i++) {
        let radius = 30 + i * 15 + p.sin(p.frameCount * 0.1) * 5;
        p.ellipse(p.mouseX, p.mouseY, radius * 2, radius * 2);
      }
    }

    // Subtle grid overlay suggesting cartographic measurement
    p.stroke(255, 215, 0, 20);
    p.strokeWeight(0.5);
    for(let x = 0; x < p.width; x += 40) {
      p.line(x, 0, x, p.height);
    }
    for(let y = 0; y < p.height; y += 40) {
      p.line(0, y, p.width, y);
    }
  };
}

function sketch(p) {
  let crystals = [];
  let platforms = [];
  let architect = {};
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Initialize architect figure
    architect = {
      x: 200,
      y: 400,
      armAngle: 0,
      buildingFocus: 0
    };

    // Create base platforms at different elevations
    for (let i = 0; i < 4; i++) {
      platforms.push({
        x: 50 + i * 80,
        y: 500 - i * 30,
        width: 100 + i * 20,
        height: 20,
        elevation: i,
        stability: 0.8 + i * 0.05,
        glow: 0
      });
    }

    // Initialize crystals being built
    for (let i = 0; i < 12; i++) {
      crystals.push({
        x: 100 + (i % 4) * 80,
        y: 300 - Math.floor(i / 4) * 80,
        size: 15 + Math.random() * 20,
        growth: Math.random(),
        targetSize: 20 + Math.random() * 30,
        rotation: Math.random() * p.TWO_PI,
        rotSpeed: (Math.random() - 0.5) * 0.02,
        coherence: Math.random() * 0.5 + 0.5,
        emerging: false,
        connected: []
      });
    }
  };

  p.draw = function() {
    time += 0.02;
    mouseInfluence = p.map(p.mouseX, 0, 400, 0, 1);

    // Deep blue gradient background
    for (let y = 0; y < 600; y++) {
      let alpha = p.map(y, 0, 600, 0.2, 1);
      p.stroke(10, 25, 60, alpha * 255);
      p.line(0, y, 400, y);
    }

    // Update and draw platforms
    for (let i = 0; i < platforms.length; i++) {
      let platform = platforms[i];
      platform.glow = p.sin(time + i) * 0.3 + 0.7;

      // Platform glow
      p.fill(255, 215, 0, platform.glow * 50);
      p.noStroke();
      p.ellipse(platform.x + platform.width/2, platform.y, platform.width + 40, 60);

      // Main platform
      p.fill(255, 215, 0, 180);
      p.stroke(255, 215, 0);
      p.strokeWeight(2);
      p.rect(platform.x, platform.y, platform.width, platform.height, 10);

      // Geometric details
      p.stroke(255, 215, 0, 150);
      p.strokeWeight(1);
      for (let j = 0; j < 3; j++) {
        let lineX = platform.x + (j + 1) * platform.width / 4;
        p.line(lineX, platform.y, lineX, platform.y + platform.height);
      }
    }

    // Update crystals
    for (let i = 0; i < crystals.length; i++) {
      let crystal = crystals[i];

      // Growth based on mouse interaction and time
      let distToMouse = p.dist(p.mouseX, p.mouseY, crystal.x, crystal.y);
      let mouseEffect = p.map(distToMouse, 0, 200, 1, 0.3);
      mouseEffect = p.constrain(mouseEffect, 0, 1);

      crystal.growth += (mouseEffect * 0.02 + 0.005);
      crystal.size = p.lerp(crystal.size, crystal.targetSize * crystal.growth, 0.02);
      crystal.rotation += crystal.rotSpeed;

      // Emergence check
      if (crystal.growth > 0.7 && !crystal.emerging) {
        crystal.emerging = true;
        crystal.coherence = 1.0;
      }

      // Connection to nearby crystals
      crystal.connected = [];
      for (let j = 0; j < crystals.length; j++) {
        if (i !== j) {
          let dist = p.dist(crystal.x, crystal.y, crystals[j].x, crystals[j].y);
          if (dist < 100 && crystals[j].emerging) {
            crystal.connected.push(j);
          }
        }
      }
    }

    // Draw crystal connections
    p.stroke(100, 150, 255, 80);
    p.strokeWeight(1);
    for (let i = 0; i < crystals.length; i++) {
      let crystal = crystals[i];
      if (crystal.emerging) {
        for (let connectedIndex of crystal.connected) {
          let connected = crystals[connectedIndex];
          let pulse = p.sin(time * 3 + i) * 0.3 + 0.7;
          p.stroke(100, 150, 255, pulse * 120);
          p.line(crystal.x, crystal.y, connected.x, connected.y);
        }
      }
    }

    // Draw crystals
    for (let crystal of crystals) {
      p.push();
      p.translate(crystal.x, crystal.y);
      p.rotate(crystal.rotation);

      // Crystal glow
      if (crystal.emerging) {
        p.fill(100, 150, 255, 50);
        p.noStroke();
        p.ellipse(0, 0, crystal.size + 20, crystal.size + 20);
      }

      // Main crystal
      p.fill(100, 150, 255, crystal.coherence * 200);
      p.stroke(150, 200, 255);
      p.strokeWeight(1);

      // Draw hexagonal crystal
      p.beginShape();
      for (let i = 0; i < 6; i++) {
        let angle = i * p.PI / 3;
        let x = p.cos(angle) * crystal.size;
        let y = p.sin(angle) * crystal.size;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);

      // Inner geometry
      if (crystal.emerging) {
        p.stroke(255, 215, 0, 150);
        p.strokeWeight(1);
        p.beginShape();
        for (let i = 0; i < 6; i++) {
          let angle = i * p.PI / 3;
          let x = p.cos(angle) * crystal.size * 0.5;
          let y = p.sin(angle) * crystal.size * 0.5;
          p.vertex(x, y);
        }
        p.endShape(p.CLOSE);
      }

      p.pop();
    }

    // Draw architect figure
    architect.armAngle = p.sin(time * 2) * 0.3;
    architect.buildingFocus = p.map(p.mouseY, 0, 600, 0, 1);

    p.push();
    p.translate(architect.x, architect.y);

    // Body glow
    p.fill(255, 215, 0, 30);
    p.noStroke();
    p.ellipse(0, 0, 80, 120);

    // Body
    p.fill(255, 215, 0, 150);
    p.stroke(255, 215, 0);
    p.strokeWeight(2);
    p.ellipse(0, -10, 25, 40);

    // Head
    p.fill(255, 215, 0, 180);
    p.ellipse(0, -35, 20, 20);

    // Building arms
    p.strokeWeight(3);
    p.push();
    p.rotate(architect.armAngle);
    p.line(0, -20, -15, -5);
    p.line(-15, -5, -25, 10);
    p.pop();

    p.push();
    p.rotate(-architect.armAngle * 0.7);
    p.line(0, -20, 15, -5);
    p.line(15, -5, 25, 10);
    p.pop();

    // Hands creating energy
    let handGlow = architect.buildingFocus * 100 + 50;
    p.fill(100, 150, 255, handGlow);
    p.noStroke();
    p.ellipse(-25, 10, 8, 8);
    p.ellipse(25, 10, 8, 8);

    // Energy streams from hands to nearest crystals
    if (mouseInfluence > 0.3) {
      p.stroke(100, 150, 255, 100);
      p.strokeWeight(1);
      for (let crystal of crystals) {
        let dist = p.dist(architect.x, architect.y, crystal.x, crystal.y);
        if (dist < 150) {
          let pulse = p.sin(time * 4) * 0.3 + 0.7;
          p.stroke(100, 150, 255, pulse * 80);
          p.line(architect.x - 25, architect.y + 10, crystal.x, crystal.y);
          p.line(architect.x + 25, architect.y + 10, crystal.x, crystal.y);
        }
      }
    }

    p.pop();

    // Sacred geometry overlay
    p.push();
    p.translate(200, 150);
    p.rotate(time * 0.5);
    p.stroke(255, 215, 0, 30);
    p.strokeWeight(1);
    p.noFill();
    for (let i = 0; i < 3; i++) {
      let size = 50 + i * 40;
      p.beginShape();
      for (let j = 0; j < 6; j++) {
        let angle = j * p.PI / 3;
        let x = p.cos(angle) * size;
        let y = p.sin(angle) * size;
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
    }
    p.pop();
  };

  p.mousePressed = function() {
    // Create new crystal at mouse position if on elevated ground
    for (let platform of platforms) {
      if (p.mouseX > platform.x && p.mouseX < platform.x + platform.width &&
          p.mouseY > platform.y - 50 && p.mouseY < platform.y + platform.height + 50) {
        crystals.push({
          x: p.mouseX,
          y: p.mouseY - 20,
          size: 5,
          growth: 0.1,
          targetSize: 25 + Math.random() * 15,
          rotation: Math.random() * p.TWO_PI,
          rotSpeed: (Math.random() - 0.5) * 0.03,
          coherence: 0.8,
          emerging: false,
          connected: []
        });
        break;
      }
    }
  };
}

function sketch(p) {
  let plateaus = [];
  let teachings = [];
  let prophet;
  let time = 0;
  let mouseInfluence = 0;

  p.setup = function() {
    p.createCanvas(400, 600);

    // Create the prophet figure
    prophet = {
      x: 200,
      y: 450,
      scale: 1,
      pulse: 0
    };

    // Initialize plateaus at different elevations
    for (let i = 0; i < 5; i++) {
      plateaus.push({
        level: i,
        y: 500 - i * 80,
        width: 300 - i * 40,
        nodes: [],
        stability: 0.8 + i * 0.05,
        emergence: 0
      });

      // Add nodes to each plateau
      let nodeCount = 8 - i;
      for (let j = 0; j < nodeCount; j++) {
        plateaus[i].nodes.push({
          x: 200 + p.cos(j * p.TWO_PI / nodeCount) * (60 - i * 8),
          y: plateaus[i].y + p.sin(j * p.TWO_PI / nodeCount) * 15,
          phase: j * 0.5,
          connection: 0
        });
      }
    }

    // Initialize teaching particles
    for (let i = 0; i < 30; i++) {
      teachings.push({
        x: p.random(400),
        y: p.random(600),
        targetX: 0,
        targetY: 0,
        size: p.random(3, 8),
        phase: p.random(p.TWO_PI),
        level: p.floor(p.random(5)),
        active: false
      });
    }
  };

  p.draw = function() {
    // Deep purple to indigo gradient background
    for (let i = 0; i < p.height; i++) {
      let inter = p.map(i, 0, p.height, 0, 1);
      let c = p.lerpColor(p.color(15, 10, 40), p.color(40, 20, 80), inter);
      p.stroke(c);
      p.line(0, i, 400, i);
    }

    time += 0.02;
    mouseInfluence = p.map(p.mouseY, 0, 600, 1, 0.3);

    // Draw connection lines between plateaus
    p.stroke(150, 100, 255, 80);
    p.strokeWeight(1);
    for (let i = 0; i < plateaus.length - 1; i++) {
      let currentPlateau = plateaus[i];
      let nextPlateau = plateaus[i + 1];

      for (let node of currentPlateau.nodes) {
        for (let nextNode of nextPlateau.nodes) {
          let dist = p.dist(node.x, node.y, nextNode.x, nextNode.y);
          if (dist < 100) {
            let alpha = p.map(dist, 0, 100, 60, 10);
            p.stroke(200, 150, 255, alpha * mouseInfluence);
            p.line(node.x, node.y, nextNode.x, nextNode.y);
          }
        }
      }
    }

    // Draw and animate plateaus
    for (let plateau of plateaus) {
      // Calculate emergence based on mouse proximity
      let mouseDist = p.dist(p.mouseX, p.mouseY, 200, plateau.y);
      plateau.emergence = p.map(mouseDist, 0, 200, 1, 0.2);

      // Draw plateau base
      p.fill(60 + plateau.level * 15, 40 + plateau.level * 10, 120 + plateau.level * 20, 150);
      p.noStroke();
      p.ellipse(200, plateau.y, plateau.width, 20 * plateau.emergence);

      // Draw nodes on plateau
      for (let i = 0; i < plateau.nodes.length; i++) {
        let node = plateau.nodes[i];
        let wobble = p.sin(time * 2 + node.phase) * 3 * plateau.emergence;

        // Node connections within plateau
        if (i < plateau.nodes.length - 1) {
          p.stroke(255, 200, 150, 120 * plateau.emergence);
          p.strokeWeight(2);
          p.line(node.x + wobble, node.y, 
                plateau.nodes[i + 1].x + wobble, plateau.nodes[i + 1].y);
        }

        // Draw node
        p.fill(255, 180 + plateau.level * 15, 100 + plateau.level * 30, 200 * plateau.emergence);
        p.noStroke();
        p.circle(node.x + wobble, node.y, 8 + p.sin(time + node.phase) * 2);
      }
    }

    // Update and draw teaching particles
    for (let teaching of teachings) {
      // Activate teachings based on mouse movement
      if (p.dist(p.mouseX, p.mouseY, teaching.x, teaching.y) < 80) {
        teaching.active = true;
        teaching.targetX = plateaus[teaching.level].nodes[0].x;
        teaching.targetY = plateaus[teaching.level].y;
      }

      if (teaching.active) {
        // Move toward target plateau
        teaching.x = p.lerp(teaching.x, teaching.targetX, 0.05);
        teaching.y = p.lerp(teaching.y, teaching.targetY, 0.05);

        // Draw teaching particle
        let pulse = p.sin(time * 3 + teaching.phase) * 0.5 + 0.5;
        p.fill(255, 220, 100, 150 + pulse * 100);
        p.noStroke();
        p.circle(teaching.x, teaching.y, teaching.size + pulse * 3);

        // Draw teaching trail
        p.stroke(255, 200, 80, 50);
        p.strokeWeight(1);
        p.line(teaching.x, teaching.y, 
              teaching.x + p.sin(time + teaching.phase) * 20,
              teaching.y - 10);
      } else {
        // Dormant state
        p.fill(100, 80, 150, 80);
        p.noStroke();
        p.circle(teaching.x, teaching.y, teaching.size * 0.5);
      }
    }

    // Draw the prophet figure
    let prophetPulse = p.sin(time * 1.5) * 0.1 + 1;

    // Prophet's aura
    p.fill(150, 100, 255, 30);
    p.noStroke();
    p.circle(prophet.x, prophet.y, 120 * prophetPulse * mouseInfluence);

    // Prophet's body
    p.fill(200, 150, 255);
    p.noStroke();
    p.circle(prophet.x, prophet.y + 10, 25);
    p.circle(prophet.x, prophet.y - 10, 20); // head

    // Prophet's emanations (synthesis lines)
    p.stroke(255, 200, 100, 150);
    p.strokeWeight(2);
    for (let i = 0; i < 8; i++) {
      let angle = i * p.PI / 4 + time;
      let startX = prophet.x + p.cos(angle) * 30;
      let startY = prophet.y + p.sin(angle) * 30;
      let endX = prophet.x + p.cos(angle) * (60 + p.sin(time * 2) * 20);
      let endY = prophet.y + p.sin(angle) * (60 + p.sin(time * 2) * 20);
      p.line(startX, startY, endX, endY);
    }

    // Synthesis streams connecting prophet to plateaus
    for (let i = 0; i < plateaus.length; i++) {
      let plateau = plateaus[i];
      let streamAlpha = 50 + p.sin(time + i) * 30;
      p.stroke(255, 180, 120, streamAlpha);
      p.strokeWeight(1);

      // Curved line from prophet to plateau
      let midX = (prophet.x + 200) / 2 + p.sin(time + i * 0.5) * 30;
      let midY = (prophet.y + plateau.y) / 2;

      p.noFill();
      p.beginShape();
      p.vertex(prophet.x, prophet.y);
      p.quadraticVertex(midX, midY, 200, plateau.y);
      p.endShape();
    }
  };

  p.mousePressed = function() {
    // Reset teachings on click
    for (let teaching of teachings) {
      if (teaching.active) {
        teaching.active = false;
        teaching.x = p.random(400);
        teaching.y = p.random(600);
        teaching.level = p.floor(p.random(5));
      }
    }
  };
}
